230→static void extract_content(const char *path, char *out, size_t cap)
231→{
232→  FILE *f;
233→  char *buf;
234→  long sz;
235→  char *p;
236→  char *q;
237→
238→  out[0] = '\0';
239→  f = fopen(path, "rb");
240→  if (!f)
241→    {
242→      return;
243→    }
244→  fseek(f, 0, SEEK_END);
245→  sz = ftell(f);
246→  fseek(f, 0, SEEK_SET);
247→  if (sz <= 0 || sz > 64 * 1024)
248→    {
249→      fclose(f);
250→      return;
251→    }
252→  buf = malloc((size_t)sz + 1);
253→  if (!buf)
254→    {
255→      fclose(f);
256→      return;
257→    }
258→  if (fread(buf, 1, (size_t)sz, f) != (size_t)sz)
259→    {
260→      free(buf);
261→      fclose(f);
262→      return;
263→    }
264→  buf[sz] = '\0';
265→  fclose(f);
266→
267→  p = strstr(buf, "\"content\"");
268→  if (!p)
269→    {
270→      free(buf);
271→      return;
272→    }
273→  p = strchr(p + 9, '"');
274→  if (!p)
275→    {
276→      free(buf);
277→      return;
278→    }
279→  q = strchr(p + 1, '"');
280→  if (!q)
281→    {
282→      free(buf);
283→      return;
284→    }
285→  {
286→    size_t n = (size_t)(q - (p + 1));
287→    if (n >= cap)
288→      {
289→        n = cap - 1;
290→      }
291→    memcpy(out, p + 1, n);
292→    out[n] = '\0';
293→    /* unescape \" and \\ and \n lightly */
294→    {
295→      char *r = out;
296→      char *w = out;
297→      while (*r)
298→        {
299→          if (r[0] == '\\' && r[1] == 'n')
300→            {
301→              *w++ = ' ';
302→              r += 2;
303→            }
304→          else if (r[0] == '\\' && r[1] == '"')
305→            {
306→              *w++ = '"';
307→              r += 2;
308→            }
309→          else if (r[0] == '\\' && r[1] == '\\')
310→            {
311→              *w++ = '\\';
312→              r += 2;
313→            }
314→          else
315→            {
316→              *w++ = *r++;
317→            }
318→        }
319→      *w = '\0';
320→    }
321→  }
322→  free(buf);
323→}
