 84→static struct nxrecorder_s *s_rec;
 85→
 86→static void *rec_auto_stop(void *arg)
 87→{
 88→  int max_sec = (int)(intptr_t)arg;
 89→
 90→  sleep(max_sec > 0 ? max_sec : REC_MAX_SEC);
 91→  (void)dm_voice_rec_stop();
 92→  return NULL;
