397→static int asr_wav(const char *wav, char *text, int cap)
398→{
399→  FILE *f;
400→  unsigned char *raw;
401→  char *b64;
402→  char *body;
403→  long sz;
404→  int n;
405→  char *p;
406→  char *q;
407→
408→  text[0] = '\0';
409→  f = fopen(wav, "rb");
410→  if (!f)
411→    {
412→      return -1;
413→    }
414→  fseek(f, 0, SEEK_END);
415→  sz = ftell(f);
416→  fseek(f, 0, SEEK_SET);
417→  if (sz <= 44 || sz > 2 * 1024 * 1024)
418→    {
419→      fclose(f);
420→      return -1;
421→    }
422→  raw = malloc((size_t)sz);
423→  b64 = malloc((size_t)sz * 2 + 8);
424→  body = malloc((size_t)sz * 2 + 256);
425→  if (!raw || !b64 || !body)
426→    {
427→      free(raw); free(b64); free(body); fclose(f);
428→      return -1;
429→    }
430→  if (fread(raw, 1, (size_t)sz, f) != (size_t)sz)
431→    {
432→      free(raw); free(b64); free(body); fclose(f);
433→      return -1;
434→    }
435→  fclose(f);
436→  b64_encode(raw, (size_t)sz, b64, (size_t)sz * 2 + 8);
437→  free(raw);
438→
439→  /* chat/completions ASR: input_audio */
440→  n = snprintf(body, (size_t)sz * 2 + 256,
441→               "{\"model\":\"%s\",\"messages\":[{\"role\":\"user\",\"content\":"
442→               "[{\"type\":\"input_audio\",\"input_audio\":{\"data\":\"%s\","
443→               "\"format\":\"wav\"}}]}]}",
444→               ASR_MODEL, b64);
445→  free(b64);
446→  if (n <= 0)
447→    {
448→      free(body);
449→      return -1;
450→    }
451→  if (http_post_json("/chat/completions", body, TXT_ASR) != 0)
452→    {
453→      free(body);
454→      return -1;
455→    }
456→  free(body);
457→
458→  f = fopen(TXT_ASR, "rb");
459→  if (!f)
460→    {
461→      return -1;
462→    }
463→  fseek(f, 0, SEEK_END);
464→  sz = ftell(f);
465→  fseek(f, 0, SEEK_SET);
466→  if (sz <= 0 || sz > 256 * 1024)
467→    {
468→      fclose(f);
469→      return -1;
470→    }
471→  body = malloc((size_t)sz + 1);
472→  if (!body)
473→    {
474→      fclose(f);
475→      return -1;
476→    }
477→  if (fread(body, 1, (size_t)sz, f) != (size_t)sz)
478→    {
479→      free(body);
480→      fclose(f);
481→      return -1;
482→    }
483→  body[sz] = '\0';
484→  fclose(f);
485→
486→  p = strstr(body, "\"content\"");
487→  if (p)
488→    {
489→      p = strchr(p + 9, '"');
490→      if (p)
491→        {
492→          q = strchr(p + 1, '"');
493→          if (q)
494→            {
495→              size_t ln = (size_t)(q - p - 1);
496→              if (ln >= (size_t)cap)
497→                {
498→                  ln = (size_t)cap - 1;
499→                }
500→              memcpy(text, p + 1, ln);
501→              text[ln] = '\0';
502→            }
503→        }
504→    }
505→  free(body);
506→  return text[0] ? 0 : -1;
507→}
