 184→/* NSH-safe single-quote wrap; reject embedded single quotes */
 185→static int shell_quote(const char *in, char *out, size_t outsz)
 186→{
 187→  size_t n;
 188→  size_t o = 0;
 189→
 190→  if (!in || !out || outsz < 3)
 191→    {
 192→      return -1;
 193→    }
 194→  if (strchr(in, '\'') != NULL)
 195→    {
 196→      return -1;
 197→    }
 198→  n = strlen(in);
 199→  if (n + 3 > outsz)
 200→    {
 201→      return -1;
 202→    }
 203→  out[o++] = '\'';
 204→  memcpy(out + o, in, n);
 205→  o += n;
 206→  out[o++] = '\'';
 207→  out[o] = 0;
 208→  return 0;
 209→}
