 454→static int wifi_cred_load_cfg(char *ssid, size_t slen, char *pass,
 455→                              size_t plen)
 456→{
 457→  FILE *f = fopen("/data/wifi.cfg", "r");
 458→  char line[96];
 459→  int got_ssid = 0;
 460→  int got_pass = 0;
 461→
 462→  if (!f)
 463→    {
 464→      return -1;
 465→    }
 466→  while (fgets(line, sizeof(line), f))
 467→    {
 468→      line[strcspn(line, "\r\n")] = 0;
 469→      if (strncmp(line, "SSID=", 5) == 0)
 470→        {
 471→          snprintf(ssid, slen, "%s", line + 5);
 472→          wifi_unquote(ssid);
 473→          got_ssid = 1;
 474→        }
 475→      else if (strncmp(line, "PASSWORD=", 9) == 0)
 476→        {
 477→          snprintf(pass, plen, "%s", line + 9);
 478→          wifi_unquote(pass);
 479→          got_pass = 1;
 480→        }
 481→    }
 482→  fclose(f);
 483→
 484→  if (!got_ssid || !ssid[0])
 485→    {
 486→      return -1;
 487→    }
 488→  if (!got_pass)
 489→    {
 490→      pass[0] = 0;
 491→    }
 492→  syslog(LOG_INFO, "[deskmate-wifi] creds from /data/wifi.cfg ssid=%s\n",
 493→         ssid);
 494→  return 0;
 495→}
