 531→static int ensure_driver_wait(int attempts_100ms)
 532→{
 533→  int i;
 534→
 535→  if (s_drv_ready && if_nametoindex(DM_WIFI_IF) != 0)
 536→    {
 537→      return 0;
 538→    }
 539→
 540→  for (i = 0; i < attempts_100ms; i++)
 541→    {
 542→      if (if_nametoindex(DM_WIFI_IF) != 0)
 543→        {
 544→          s_drv_ready = 1;
 545→          syslog(LOG_INFO, "[deskmate-wifi] %s ready\n", DM_WIFI_IF);
 546→          return 0;
 547→        }
 548→      usleep(100 * 1000);
 549→    }
 550→
 551→  s_drv_ready = 0;
 552→  syslog(LOG_ERR,
 553→         "[deskmate-wifi] %s missing — board bringup not ready yet\n",
 554→         DM_WIFI_IF);
 555→  return -1;
 556→}
