 84→/* worker thread — NO LVGL calls here */
 85→static void *voice_worker(void *arg)
 86→{
 87→  char reply[CHAT_LINE_MAX];
 88→
 89→  (void)arg;
 90→
 91→  if (s_job == 1)
 92→    {
 93→      snprintf(s_out_sub, sizeof(s_out_sub), "%s",
 94→               dm_t("ASR → 模型 → 喇叭播报", "ASR → LLM → speaker"));
 95→      if (dm_voice_asr_chat_tts("/tmp/dm_voice_in.wav", reply,
 96→                                sizeof(reply)) == 0)
 97→        {
 98→          snprintf(s_out_ans, sizeof(s_out_ans), "%s", reply);
 99→          snprintf(s_out_sub, sizeof(s_out_sub), "%s",
100→                   dm_t("已通过喇叭播放回复", "Reply played on speaker"));
101→          s_out_ready = 1;
102→        }
103→      else
104→        {
105→          /* ASR 404 on this gateway — fall back to text chat */
106→          const char *r = dm_chat_ai_ask(s_pending[0] ? s_pending
107→                                                      : dm_t("陪我聊聊天",
108→                                                             "chat with me"));
109→          if (r && r[0])
110→            {
111→              snprintf(s_out_ans, sizeof(s_out_ans), "%s", r);
112→              snprintf(s_out_sub, sizeof(s_out_sub), "%s",
113→                       dm_t("语音识别不可用，已用文字对话",
114→                            "ASR unavailable, text chat used"));
115→            }
116→          else
117→            {
118→              snprintf(s_out_ans, sizeof(s_out_ans), "%s",
119→                       dm_t("网络或服务异常，稍后再试",
120→                            "Network error, try again"));
121→              snprintf(s_out_sub, sizeof(s_out_sub), "%s",
122→                       dm_t("WiFi 需已连接", "WiFi must be connected"));
123→            }
124→          s_out_ready = 1;
125→        }
126→    }
127→  else if (s_job == 2)
128→    {
129→      const char *r = dm_chat_ai_ask(s_pending);
130→      snprintf(s_out_ans, sizeof(s_out_ans), "%s", r ? r : "……");
131→      if (r && r[0])
132→        {
133→          (void)dm_voice_tts_play(r);
134→          snprintf(s_out_sub, sizeof(s_out_sub), "%s",
135→                   dm_t("已通过喇叭播放回复", "Reply played on speaker"));
136→        }
137→      else
138→        {
139→          s_out_sub[0] = '\0';
140→        }
141→      s_out_ready = 1;
142→    }
143→  return NULL;
144→}
