 76→
 77→/****************************************************************************
 78→ * Name: curl4nx_easy_perform()
 79→ *
 80→ * Description:
 81→ *  Resolve the hostname to an IP address. There are 3 cases:
 82→ *  - direct IP: inet_aton is used
 83→ *  - using internal curl4nx resolution
 84→ *  - DNS resolution, if available
 85→ ****************************************************************************/
 86→
 87→/****************************************************************************
 88→ * Name: curl4nx_resolve
 89→ * Description:
 90→ *   Translate a host name to an IP address (V4 only for the moment)
 91→ *   - either the host is a string with an IP
 92→ *   - either the known hosts were defined by CURL4NXOPT_
 93→ ****************************************************************************/
 94→
 95→static int curl4nx_resolve(FAR struct curl4nx_s *handle, FAR char *hostname,
 96→                          FAR struct in_addr *ip)
 97→{
 98→  int ret = inet_aton(hostname, ip);
 99→  if (ret != 0)
100→    {
101→      return CURL4NXE_OK; /* IP address is valid */
102→    }
103→
104→  curl4nx_warn("Not a valid IP address, trying hostname resolution\n");
105→  return CURL4NXE_COULDNT_RESOLVE_HOST;
106→}
107→
108→/****************************************************************************
109→ * Name: curl4nx_is_header
110→ * Description:
111→ *   Return TRUE if buf contains header, then update off to point at the
112→ *   beginning of header value
113→ ****************************************************************************/
114→
115→static int curl4nx_is_header(FAR char *buf, int len,
116→                            FAR const char *header, FAR int *off)
117→{
118→  if (strncasecmp(buf, header, strlen(header)))
119→    {
120→      return false;
121→    }
122→
123→  *off = strlen(header);
124→  while ((*off) < len && buf[*off] == ' ')
125→    {
126→      (*off)++;
127→    }
128→
129→  return true;
130→}
