133→ * Public Functions
134→ ****************************************************************************/
135→
136→/****************************************************************************
137→ * Name: curl4nx_easy_perform()
138→ ****************************************************************************/
139→
140→int curl4nx_easy_perform(FAR struct curl4nx_s *handle)
141→{
142→  struct sockaddr_in server;
143→  FAR FILE          *stream;     /* IOSTREAM used to printf in the socket TODO avoid */
144→  int                rxoff;      /* Current offset within RX buffer */
145→  char               tmpbuf[16]; /* Buffer to hold small strings */
146→  int                tmplen;     /* Number of bytes used in tmpbuffer */
147→  int                state;      /* Current state of the parser */
148→  int                ret;        /* Return value from internal calls */
149→  FAR char          *headerbuf;
150→  int                headerlen;
151→  FAR char          *end;
152→  int                cret = CURL4NXE_OK; /* Public return value */
153→  bool               redirected = false; /* Boolean to manage HTTP redirections */
154→  bool               chunked = false;
155→  unsigned long long done = 0;
156→  int                redircount = 0;
157→
158→  curl4nx_info("started\n");
159→
160→  stream = NULL;
161→  headerbuf = malloc(CONFIG_LIBCURL4NX_MAXHEADERLINE);
162→  if (!headerbuf)
163→    {
164→      cret = CURL4NXE_OUT_OF_MEMORY;
165→      goto abort;
166→    }
167→
168→  if (handle->host[0] == 0 || handle->port == 0)
169→    {
170→      /* URL has not been set */
171→
172→      cret = CURL4NXE_URL_MALFORMAT;
173→      goto freebuf;
174→    }
175→
176→  /* TODO: check that host and port have changed or are the same, so we can
177→   * recycle the socket for the next request.
178→   */
179→
180→  do
181→    {
182→      handle->sockfd = socket(AF_INET, SOCK_STREAM, 0);
183→      if (handle->sockfd < 0)
184→        {
185→          /* socket failed.  It will set the errno appropriately */
186→
187→          curl4nx_err("ERROR: socket failed: %d\n", errno);
188→          cret = CURL4NXE_COULDNT_CONNECT;
189→          goto freebuf;
190→        }
191→
192→      /* TODO: timeouts */
193→
194→      server.sin_family = AF_INET;
195→      server.sin_port   = htons(handle->port);
196→      cret = curl4nx_resolve(handle, handle->host, &server.sin_addr);
197→      if (cret != CURL4NXE_OK)
198→        {
199→          /* Could not resolve host (or malformed IP address) */
200→
201→          curl4nx_err("ERROR: Failed to resolve hostname\n");
202→          cret = CURL4NXE_COULDNT_RESOLVE_HOST;
203→          goto freebuf;
204→        }
205→
206→      /* Connect to server.  First we have to set some fields in the
207→       * 'server' address structure.  The system will assign me an arbitrary
208→       * local port that is not in use.
209→       */
210→
211→      ret = connect(handle->sockfd,
212→                    (struct sockaddr *)&server, sizeof(struct sockaddr_in));
213→      if (ret < 0)
214→        {
215→          curl4nx_err("ERROR: connect failed: %d\n", errno);
216→          cret = CURL4NXE_COULDNT_CONNECT;
217→          goto close;
218→        }
219→
220→      curl4nx_info("Connected...\n");
221→
222→      stream = fdopen(handle->sockfd, "wb");
223→
224→      /* Send request */
225→
226→      fprintf(stream, "%s %s HTTP/%d.%d\r\n",
227→                      handle->method,
228→                      handle->path,
229→                      handle->version >> 4,
230→                      handle->version & 0x0f);
231→
232→      /* Send headers */
233→
234→      fprintf(stream, "Host: %s\r\n", handle->host);
235→
236→      /* For the moment we do not support compression */
237→
238→      fprintf(stream, "Content-encoding: identity\r\n");
239→
240→      /* Send more headers */
241→
242→      /* End of headers */
243→
244→      fprintf(stream, "\r\n");
245→
246→      /* TODO send data */
247→
248→      fflush(stream);
249→      curl4nx_info("Request sent\n");
250→
251→      /* Now wait for the result */
252→
253→      redirected = false; /* for now */
254→      state      = CURL4NX_STATE_STATUSLINE;
255→      tmplen     = 0;
256→
257→      while (1)
258→        {
259→          ret = recv(handle->sockfd, handle->rxbuf, handle->rxbufsize, 0);
260→          if (ret < 0)
261→            {
262→              curl4nx_err("RECV failed, errno=%d\n", errno);
263→              cret = CURL4NXE_RECV_ERROR;
264→              goto close;
265→            }
266→          else if (ret == 0)
267→            {
268→              curl4nx_err("Connection lost\n");
269→              cret = CURL4NXE_GOT_NOTHING;
270→              goto close;
271→            }
272→
273→          curl4nx_info("Received %d bytes\n", ret);
274→          rxoff = 0;
275→
276→          if (state == CURL4NX_STATE_STATUSLINE)
277→            {
278→              /* Accumulate HTTP/x.y until space */
279→
280→              while ((tmplen < sizeof(tmpbuf)) && (rxoff < ret))
281→                {
282→                  if (handle->rxbuf[rxoff] == ' ')
283→                    {
284→                      /* found space after http version */
285→
286→                      tmpbuf[tmplen] = 0; /* Finish pending string */
287→                      rxoff++;
288→                      curl4nx_info("received version: [%s]\n", tmpbuf);
289→                      tmplen = 0; /* reset buffer to look at code */
290→                      state = CURL4NX_STATE_STATUSCODE;
291→                      break;
292→                    }
293→
294→                  /* Not a space: accumulate chars */
295→
296→                  tmpbuf[tmplen] = handle->rxbuf[rxoff];
297→                  tmplen++;
298→                  rxoff++;
299→                }
300→
301→              /* Check for overflow,
302→               * version code should not fill the tmpbuf
303→               */
304→
305→              if (tmplen == sizeof(tmpbuf))
306→                {
307→                  /* extremely long http version -> invalid response */
308→
309→                  curl4nx_err("Buffer overflow while reading version\n");
310→                  cret = CURL4NXE_RECV_ERROR;
311→                  goto close;
312→                }
313→
314→              /* No overflow and no space found: wait for next buffer */
315→            }
316→
317→          /* NO ELSE HERE, state may have changed and require new management
318→           * for the same rx buffer.
319→           */
320→
321→          if (state == CURL4NX_STATE_STATUSCODE)
322→            {
323→              /* Accumulate response code until space */
324→
325→              while ((tmplen < sizeof(tmpbuf)) && (rxoff < ret))
326→                {
327→                  if (handle->rxbuf[rxoff] == ' ')
328→                    {
329→                      /* Found space after http version */
330→
331→                      tmpbuf[tmplen] = 0; /* Finish pending string */
332→                      rxoff++;
333→                      curl4nx_info("received code: [%s]\n", tmpbuf);
334→                      handle->status = strtol(tmpbuf, &end, 10);
335→
336→                      if (*end != 0)
337→                        {
338→                          curl4nx_err("Bad status code [%s]\n", tmpbuf);
339→                          cret = CURL4NXE_RECV_ERROR;
340→                          goto close;
341→                        }
342→
343→                      tmplen = 0; /* reset buffer to look at code */
344→                      state = CURL4NX_STATE_STATUSREASON;
345→                      break;
346→                    }
347→
348→                  /* Not a space: accumulate chars */
349→
350→                  tmpbuf[tmplen] = handle->rxbuf[rxoff];
351→                  tmplen++;
352→                  rxoff++;
353→                }
354→
355→              /* Check for overflow,
356→               * version code should not fill the tmpbuf
357→               */
358→
359→              if (tmplen == sizeof(tmpbuf))
360→                {
361→                  /* Extremely long http code -> invalid response */
362→
363→                  curl4nx_err("Buffer overflow while reading code\n");
364→                  cret = CURL4NXE_RECV_ERROR;
365→                  goto close;
366→                }
367→
368→              /* No overflow and no space found: wait for next buffer */
369→            }
370→
371→          if (state == CURL4NX_STATE_STATUSREASON)
372→            {
373→              /* Accumulate response code until CRLF */
374→
375→              while (rxoff < ret)
376→                {
377→                  if (handle->rxbuf[rxoff] == 0x0d ||
378→                     handle->rxbuf[rxoff] == 0x0a)
379→                    {
380→                      /* Accumulate all contiguous CR and LF in any order */
381→
382→                      tmpbuf[tmplen] = handle->rxbuf[rxoff];
383→                      tmplen++;
384→                      if (tmplen == 2)
385→                        {
386→                          if (tmpbuf[0] == 0x0d && tmpbuf[1] == 0x0a)
387→                            {
388→                              headerlen = 0;
389→                              handle->content_length = 0;
390→                              state = CURL4NX_STATE_HEADERS;
391→                              break;
392→                            }
393→                          else
394→                            {
395→                              tmplen = 0; /* Reset search for CRLF */
396→                            }
397→                        }
398→                    }
399→                  else
400→                    {
401→                      /* This char is not interesting: reset storage */
402→
403→                      tmplen = 0;
404→
405→                      /* curl4nx_info("-> %c\n", handle->rxbuf[rxoff]); */
406→                    }
407→
408→                  rxoff++;
409→                }
410→            }
411→
412→          if (state == CURL4NX_STATE_HEADERS)
413→            {
414→              while (rxoff < ret)
415→                {
416→                  if (handle->rxbuf[rxoff] == 0x0d ||
417→                     handle->rxbuf[rxoff] == 0x0a)
418→                    {
419→                      /* Accumulate all contiguous CR and LF in any order */
420→
421→                      tmpbuf[tmplen] = handle->rxbuf[rxoff];
422→                      tmplen++;
423→                      if (tmplen == 2)
424→                        {
425→                          if (tmpbuf[0] == 0x0d && tmpbuf[1] == 0x0a)
426→                            {
427→                              if (headerlen == 0) /* Found an empty header */
428→                                {
429→                                  curl4nx_info("<End of headers>\n");
430→                                  rxoff++; /* Skip this char */
431→                                  state = chunked ?
432→                                           CURL4NX_STATE_DATA_CHUNKED :
433→                                           CURL4NX_STATE_DATA_NORMAL;
434→                                  break;
435→                                }
436→                              else
437→                                {
438→                                  int off;
439→                                  curl4nx_iofunc_f func;
440→                                  headerbuf[headerlen] = 0;
441→                                  func = handle->headerfunc;
442→                                  if (func == NULL)
443→                                    {
444→                                      func = handle->writefunc;
445→                                    }
446→
447→                                  func(headerbuf, headerlen, 1,
448→                                       handle->headerdata);
449→
450→                                  /* Find the content-length */
451→
452→                                  if (curl4nx_is_header(headerbuf, headerlen,
453→                                                        "content-length:",
454→                                                        &off))
455→                                    {
456→                                      handle->content_length =
457→                                        strtoull(headerbuf + off, &end, 10);
458→                                      if (*end != 0)
459→                                        {
460→                                          curl4nx_err("Stray chars after "
461→                                                      "content length!\n");
462→                                          cret = CURL4NXE_RECV_ERROR;
463→                                          goto close;
464→                                        }
465→
466→                                      curl4nx_info("Found content length: "
467→                                                   "%llu\n",
468→                                                   handle->content_length);
469→                                    }
470→
471→                                  /* Find the transfer encoding */
472→
473→                                  if (curl4nx_is_header(headerbuf, headerlen,
474→                                                        "transfer-encoding:",
475→                                                        &off))
476→                                    {
477→                                      chunked = !strncasecmp(headerbuf + off,
478→                                                             "chunked", 7);
479→                                      if (chunked)
480→                                        {
481→                                          curl4nx_info("Transfer using "
482→                                                       "chunked format\n");
483→                                        }
484→                                    }
485→
486→                                  /* Find the location */
487→
488→                                  if (curl4nx_is_header(headerbuf, headerlen,
489→                                                        "location:",
490→                                                        &off))
491→                                    {
492→                                      /* Parse the new URL if we get a
493→                                       * redirection code.
494→                                       */
495→
496→                                      if (handle->status >= 300 &&
497→                                          handle->status < 400)
498→                                        {
499→                                          if (handle->flags &
500→                                             CURL4NX_FLAGS_FOLLOWLOCATION)
501→                                            {
502→                                              if ((handle->max_redirs > 0) &&
503→                                                  (redircount >=
504→                                                   handle->max_redirs))
505→                                                {
506→                                                  curl4nx_info(
507→                                                  "Too many redirections\n");
508→                                                  cret =
509→                                                 CURL4NXE_TOO_MANY_REDIRECTS;
510→                                                  goto close;
511→                                                }
512→
513→                                              cret =
514→                                                curl4nx_easy_setopt(
515→                                                        handle,
516→                                                        CURL4NXOPT_URL,
517→                                                        headerbuf + off);
518→                                              if (cret != CURL4NXE_OK)
519→                                                {
520→                                                  goto close;
521→                                                }
522→
523→                                              redirected = true;
524→                                              redircount += 1;
525→                                              curl4nx_info("\
526→                                                REDIRECTION (%d) -> %s\n",
527→                                                redircount,
528→                                                headerbuf + off);
529→                                            }
530→                                        }
531→                                    }
532→
533→                                  /* Prepare for next header */
534→
535→                                  headerlen = 0;
536→                                  tmplen    = 0; /* Reset search for CRLF */
537→                                }
538→                            }
539→                          else
540→                            {
541→                              tmplen = 0; /* Reset search for CRLF */
542→                            }
543→                        }
544→                    }
545→                  else
546→                    {
547→                      tmplen = 0; /* Reset CRLF detection */
548→
549→                      /* Plus one for final zero */
550→
551→                      if (headerlen < (CONFIG_LIBCURL4NX_MAXHEADERLINE - 1))
552→                        {
553→                          headerbuf[headerlen] = handle->rxbuf[rxoff];
554→                          headerlen++;
555→                        }
556→                      else
557→                        {
558→                          curl4nx_warn("prevented header overload\n");
559→                        }
560→                    }
561→
562→                  rxoff++;
563→                }
564→            }
565→
566→          if (state == CURL4NX_STATE_DATA_NORMAL)
567→            {
568→              if ((handle->flags & CURL4NX_FLAGS_FAILONERROR) &&
569→                   handle->status >= 400)
570→                {
571→                  cret = CURL4NXE_HTTP_RETURNED_ERROR;
572→                  goto close;
573→                }
574→
575→              curl4nx_info("now in normal data state, rxoff=%d rxlen=%d\n",
576→                           rxoff, ret);
577→              done += (ret - rxoff);
578→
579→              handle->writefunc(handle->rxbuf + rxoff, ret - rxoff, 1,
580→                                handle->writedata);
581→              if (handle->content_length != 0)
582→                {
583→                  curl4nx_info("Done %llu of %llu\n",
584→                               done, handle->content_length);
585→
586→                  if (handle->progressfunc)
587→                    {
588→                      handle->progressfunc(handle->progressdata,
589→                                           handle->content_length,
590→                                           done, 0, 0);
591→                    }
592→
593→                  if (handle->content_length == done)
594→                    {
595→                      /* Transfer is complete */
596→
597→                      goto close;
598→                    }
599→                }
600→            }
601→
602→          if (state == CURL4NX_STATE_DATA_CHUNKED)
603→            {
604→              if ((handle->flags & CURL4NX_FLAGS_FAILONERROR) &&
605→                  handle->status >= 400)
606→                {
607→                  cret = CURL4NXE_HTTP_RETURNED_ERROR;
608→                  goto close;
609→                }
610→
611→              curl4nx_info("now in chunked data state, rxoff=%d rxlen=%d\n",
612→                           rxoff, ret);
613→              curl4nx_err("Not supported yet.\n");
614→              goto close;
615→            }
616→        }
617→
618→      /* Done with this connection - this will also close the socket */
619→
620→close:
621→      curl4nx_info("Closing\n");
622→      if (stream)
623→        {
624→          fclose(stream);
625→        }
626→    }
627→  while (redirected);
628→
629→freebuf:
630→  free(headerbuf);
631→
632→abort:
633→  curl4nx_info("done\n");
634→  return cret;
635→}
