208→/* nxplayer treats .wav as raw PCM and never reads the WAV header
209→ * (its PCM ops->pre_parse is NULL), so the fmt chunk is parsed here and
210→ * the payload is fed via nxplayer_playraw() with explicit parameters. */
211→static int play_wav(const char *path)
212→{
213→  const char *src = (path && path[0]) ? path : WAV_TTS;
214→  struct nxplayer_s *p;
215→  FILE *f;
216→  FILE *o;
217→  uint8_t hdr[44];
218→  char buf[1024];
219→  size_t n;
220→

190→
191→/* ---- player: nxplayer (buffer-queue API) ---- */
192→
193→static struct nxplayer_s *s_play;
194→
195→static struct nxplayer_s *player_get(void)
196→{
197→  if (!s_play)
198→    {
199→      s_play = nxplayer_create();
200→      if (s_play)
201→        {
202→          (void)nxplayer_setdevice(s_play, "/dev/audio/pcm0p");
203→        }
204→    }
205→  return s_play;
206→}
207→
208→/* nxplayer treats .wav as raw PCM and never reads the WAV header
209→ * (its PCM ops->pre_parse is NULL), so the fmt chunk is parsed here and
210→ * the payload is fed via nxplayer_playraw() with explicit parameters. */
211→static int play_wav(const char *path)
212→{
213→  const char *src = (path && path[0]) ? path : WAV_TTS;
214→  struct nxplayer_s *p;
215→  FILE *f;
216→  FILE *o;
217→  uint8_t hdr[44];
218→  char buf[1024];
219→  size_t n;
220→  uint32_t rate;
221→  uint16_t ch;
222→  uint16_t bits;
223→
224→  p = player_get();
225→  if (!p)
226→    {
227→      return -1;
228→    }
229→
230→  f = fopen(src, "rb");
231→  if (!f)
232→    {
233→      return -1;
234→    }
235→  if (fread(hdr, 1, 44, f) != 44 || memcmp(hdr, "RIFF", 4) != 0)
236→    {
237→      fclose(f);
238→      return -1;
239→    }
240→  ch = (uint16_t)(hdr[22] | (hdr[23] << 8));
241→  rate = (uint32_t)(hdr[24] | (hdr[25] << 8) | (hdr[26] << 16) |
242→                    ((uint32_t)hdr[27] << 24));
243→  bits = (uint16_t)(hdr[34] | (hdr[35] << 8));
244→  if (rate < 8000 || rate > 48000)
245→    {
246→      rate = 24000;
247→    }
248→  if (ch < 1 || ch > 2)
249→    {
250→      ch = 1;
251→    }
252→  if (bits != 8 && bits != 16)
253→    {
254→      bits = 16;
255→    }
256→
257→  o = fopen(PCM_RAW, "wb");
258→  if (!o)
259→    {
260→      fclose(f);
261→      return -1;
262→    }
263→  while ((n = fread(buf, 1, sizeof(buf), f)) > 0)
264→    {
265→      fwrite(buf, 1, n, o);
266→    }
267→  fclose(o);
268→  fclose(f);
269→
270→  (void)nxplayer_stop(p); /* ignore error when idle */
271→  return (nxplayer_playraw(p, PCM_RAW, AUDIO_FMT_PCM, 0, (uint8_t)ch,
272→                           (uint8_t)bits, rate, 1) == OK) ? 0 : -1;
273→}
274→
275→/* 1s 440Hz tone, generated by nxplayer itself — no file parsing needed,
276→ * used by the volume page test button as the hardware sanity check. */
277→int dm_voice_beep(void)
278→{
279→  struct nxplayer_s *p = player_get();
280→
281→  if (!p)
282→    {
283→      return -1;
284→    }
285→  (void)nxplayer_stop(p);
286→  return (nxplayer_playtone(p, 16000, 440, 1) == OK) ? 0 : -1;
287→}
