305→static void json_escape(const char *in, char *out, size_t cap)
306→{
307→  size_t o = 0;
308→  size_t i;
309→  if (!in || !out || cap < 2)
310→    {
311→      if (out && cap)
312→        {
313→          out[0] = '\0';
314→        }
315→      return;
316→    }
317→  for (i = 0; in[i] && o + 8 < cap; i++)
318→    {
319→      unsigned char ch = (unsigned char)in[i];
320→      if (ch == '"' || ch == '\\')
321→        {
322→          out[o++] = '\\';
323→          out[o++] = (char)ch;
324→        }
325→      else if (ch == '\n')
326→        {
327→          out[o++] = '\\';
328→          out[o++] = 'n';
329→        }
330→      else if (ch >= 0x20)
331→        {
332→          out[o++] = (char)ch;
333→        }
334→    }
335→  out[o] = '\0';
336→}
