656→static int tts_synth(const char *text, const char *wav_path)
657→{
658→  char esc[400];
659→  char *body;
660→  char *rsp;
661→  FILE *f;
662→  long sz;
663→  int n;
664→  char *p;
665→  unsigned char *raw;
666→  int rawlen;
667→
668→  json_escape(text, esc, sizeof(esc));
669→  body = malloc(700);
670→  if (!body)
671→    {
672→      return -1;
673→    }
674→  /* chat/completions TTS: assistant content is spoken */
675→  n = snprintf(body, 700,
676→               "{\"model\":\"%s\",\"messages\":["
677→               "{\"role\":\"user\",\"content\":\"请朗读\"},"
678→               "{\"role\":\"assistant\",\"content\":\"%s\"}]}",
679→               TTS_MODEL, esc);
680→  if (n <= 0 || n >= 700)
681→    {
682→      free(body);
683→      return -1;
684→    }
685→  if (http_post_json("/chat/completions", body, TXT_CHAT) != 0)
686→    {
687→      free(body);
688→      return -1;
689→    }
690→  free(body);
691→
692→  f = fopen(TXT_CHAT, "rb");
693→  if (!f)
694→    {
695→      return -1;
696→    }
697→  fseek(f, 0, SEEK_END);
698→  sz = ftell(f);
699→  fseek(f, 0, SEEK_SET);
700→  if (sz <= 0 || sz > 4 * 1024 * 1024)
701→    {
702→      fclose(f);
703→      return -1;
704→    }
705→  rsp = malloc((size_t)sz + 1);
706→  if (!rsp)
707→    {
708→      fclose(f);
709→      return -1;
710→    }
711→  if (fread(rsp, 1, (size_t)sz, f) != (size_t)sz)
712→    {
713→      free(rsp);
714→      fclose(f);
715→      return -1;
716→    }
717→  rsp[sz] = '\0';
718→  fclose(f);
719→
720→  p = strstr(rsp, "\"data\"");
721→  if (!p)
722→    {
723→      free(rsp);
724→      return -1;
725→    }
726→  p = strchr(p + 6, '"');
727→  if (!p)
728→    {
729→      free(rsp);
730→      return -1;
731→    }
732→  {
733→    char *q = strchr(p + 1, '"');
734→    if (!q)
735→      {
736→        free(rsp);
737→        return -1;
738→      }
739→    *q = '\0';
740→  }
741→  raw = malloc((size_t)sz);
742→  if (!raw)
743→    {
744→      free(rsp);
745→      return -1;
746→    }
747→  rawlen = b64_decode(p + 1, raw, (size_t)sz);
748→  free(rsp);
749→  if (rawlen <= 0)
750→    {
751→      free(raw);
752→      return -1;
753→    }
754→  f = fopen(wav_path, "wb");
755→  if (!f)
756→    {
757→      free(raw);
758→      return -1;
759→    }
760→  fwrite(raw, 1, (size_t)rawlen, f);
761→  fclose(f);
762→  free(raw);
763→  return 0;
764→}
