484→
485→static void nxrecorder_jointhread(FAR struct nxrecorder_s *precorder)
486→{
487→  FAR void *value;
488→  int id = 0;
489→
490→  if (gettid() == precorder->record_id)
491→    {
492→      return;
493→    }
494→
495→  pthread_mutex_lock(&precorder->mutex);
496→
497→  if (precorder->record_id > 0)
498→    {
499→      id = precorder->record_id;
500→      precorder->record_id = 0;
501→    }
502→
503→  pthread_mutex_unlock(&precorder->mutex);
504→
505→  if (id > 0)
506→    {
507→      pthread_join(id, &value);
508→    }
509→}
