 24→/* play local wav via same path as TTS output */
 25→static void say_offline(const char *wav_rel, const char *text)
 26→{
 27→  char path[64];
 28→  FILE *f;
 29→
 30→  snprintf(path, sizeof(path), "/resource/audio/%s", wav_rel);
 31→  f = fopen(path, "rb");
 32→  if (!f)
 33→    {
 34→      snprintf(path, sizeof(path), "/data/audio/%s", wav_rel);
 35→      f = fopen(path, "rb");
 36→    }
 37→  if (f)
 38→    {
 39→      fclose(f);
 40→      extern int dm_voice_play_file(const char *path);
 41→      if (dm_voice_play_file(path) == 0)
 42→        {
 43→          if (text)
 44→            {
 45→              dm_say(text, text);
 46→            }
 47→          return;
 48→        }
 49→    }
 50→
 51→  /* last resort: short beep */
 52→  (void)dm_vol_test_beep();
 53→  if (text)
 54→    {
 55→      dm_say(text, text);
 56→    }
 57→}
