209→/* ---- player: nxplayer (buffer-queue API) ---- */
210→
211→/* The audio driver owns a small number of DMA channels.  Serialize all
212→ * playback and recording setup/teardown so the app never starts a new stream
213→ * while an earlier stream is still releasing its buffers. */
214→
215→/* nxplayer treats .wav as raw PCM and never reads the WAV header
216→ * (its PCM ops->pre_parse is NULL), so the fmt chunk is parsed here and
217→ * the payload is fed via nxplayer_playraw() with explicit parameters. */
218→static int play_wav(const char *path)
219→{
220→  const char *src = (path && path[0]) ? path : WAV_TTS;
221→  struct nxplayer_s *p = NULL;
222→  FILE *f = NULL;
223→  FILE *o = NULL;
224→  uint8_t hdr[44];
225→  char buf[1024];
226→  size_t n;
227→  size_t raw_len = 0;
228→  uint32_t rate;
229→  uint16_t ch;
230→  uint16_t bits;
231→  uint64_t bytes_per_sec;
232→  uint64_t play_ms;
233→  int rc = -1;
234→
235→  if (pthread_mutex_trylock(&s_audio_lock) != 0)
236→    {
237→      return -EBUSY;
238→    }
239→  if (s_rec_active)
240→    {
241→      pthread_mutex_unlock(&s_audio_lock);
242→      return -EBUSY;
243→    }
244→
245→  p = nxplayer_create();
246→  if (!p || nxplayer_setdevice(p, "/dev/audio/pcm0p") != OK)
247→    {
248→      goto out;
249→    }
250→
251→  f = fopen(src, "rb");
252→  if (!f)
253→    {
254→      goto out;
255→    }
256→  if (fread(hdr, 1, 44, f) != 44 || memcmp(hdr, "RIFF", 4) != 0)
257→    {
258→      goto out;
259→    }
260→  ch = (uint16_t)(hdr[22] | (hdr[23] << 8));
261→  rate = (uint32_t)(hdr[24] | (hdr[25] << 8) | (hdr[26] << 16) |
262→                    ((uint32_t)hdr[27] << 24));
263→  bits = (uint16_t)(hdr[34] | (hdr[35] << 8));
264→  if (rate < 8000 || rate > 48000)
265→    {
266→      rate = 24000;
267→    }
268→  if (ch < 1 || ch > 2)
269→    {
270→      ch = 1;
271→    }
272→  if (bits != 8 && bits != 16)
273→    {
274→      bits = 16;
275→    }
276→
277→  o = fopen(PCM_RAW, "wb");
278→  if (!o)
279→    {
280→      goto out;
281→    }
282→  while ((n = fread(buf, 1, sizeof(buf), f)) > 0)
283→    {
284→      if (fwrite(buf, 1, n, o) != n)
285→        {
286→          goto out;
287→        }
288→      raw_len += n;
289→    }
290→  if (ferror(f) || raw_len == 0)
291→    {
292→      goto out;
293→    }
294→  fclose(o);
295→  o = NULL;
296→  fclose(f);
297→  f = NULL;
298→
299→  if (nxplayer_playraw(p, PCM_RAW, AUDIO_FMT_PCM, 0, (uint8_t)ch,
300→                       (uint8_t)bits, rate, 1) != OK)
301→    {
302→      goto out;
303→    }
304→
305→  /* nxplayer_playraw() returns as soon as its worker is started.  Keep the
306→   * audio gate until the PCM duration elapses and stop/join the worker, so a
307→   * following capture/playback cannot race the previous DMA release. */
308→  bytes_per_sec = (uint64_t)rate * ch * bits / 8;
309→  play_ms = bytes_per_sec ? ((uint64_t)raw_len * 1000 / bytes_per_sec) : 1000;
310→  play_ms += 150;
311→  if (play_ms > 30000)
312→    {
313→      play_ms = 30000;
314→    }
315→  while (play_ms >= 1000)
316→    {
317→      sleep(1);
318→      play_ms -= 1000;
319→    }
320→  if (play_ms > 0)
321→    {
322→      usleep((useconds_t)(play_ms * 1000));
323→    }
324→
325→  (void)nxplayer_stop(p);
326→  rc = 0;
327→
328→out:
329→  if (o)
330→    {
331→      fclose(o);
332→    }
333→  if (f)
334→    {
335→      fclose(f);
336→    }
337→  if (p)
338→    {
339→      nxplayer_release(p);
340→    }
341→  pthread_mutex_unlock(&s_audio_lock);
342→  return rc;
343→}
