345→/* Play one short 440Hz test tone.  This is synchronous by design; callers
346→ * run it on a worker so neither LVGL nor the recorder UI can block. */
347→int dm_voice_beep(void)
348→{
349→  struct nxplayer_s *p = NULL;
350→  int rc = -1;
351→
352→  if (pthread_mutex_trylock(&s_audio_lock) != 0)
353→    {
354→      return -EBUSY;
355→    }
356→  if (s_rec_active)
357→    {
358→      pthread_mutex_unlock(&s_audio_lock);
359→      return -EBUSY;
360→    }
361→
362→  p = nxplayer_create();
363→  if (!p || nxplayer_setdevice(p, "/dev/audio/pcm0p") != OK)
364→    {
365→      goto out;
366→    }
367→
368→  if (nxplayer_playtone(p, 16000, 440, 1) != OK)
369→    {
370→      goto out;
371→    }
372→
373→  /* Tone playback is asynchronous; wait slightly beyond its duration and
374→   * join it before allowing the next audio operation. */
375→  usleep(1150 * 1000);
376→  (void)nxplayer_stop(p);
377→  rc = 0;
378→
379→out:
380→  if (p)
381→    {
382→      nxplayer_release(p);
383→    }
384→  pthread_mutex_unlock(&s_audio_lock);
385→  return rc;
386→}
