866→{
867→  char text[256];
868→  int play_rc = -1;
869→
870→  if (!wav_path || !reply || cap < 8)
871→    {
872→      return -1;
873→    }
874→  reply[0] = '\0';
875→
876→  s_st = DM_VOICE_ASR;
877→  if (asr_wav(wav_path, text, sizeof(text)) != 0)
