2240→/****************************************************************************
2241→ * Name: nxplayer_playtone
2242→ *
2243→ *   Plays the generated tone data using the Audio system.
2244→ *   If a preferred device has been set, that device will be used for
2245→ *   the playback, otherwise the first suitable device found in
2246→ *   the /dev/audio directory will be used.
2247→ *
2248→ * Input Parameters:
2249→ *   pplayer   - Pointer to the context to initialize
2250→ *   samprate  - sample rate
2251→ *   pitchfreq - pitch frequency‌
2252→ *   duration  - duration of the generated tone
2253→ *
2254→ *
2255→ * Returned Value:
2256→ *   OK if device found, and playback started.
2257→ *
2258→ ****************************************************************************/
2259→
2260→int nxplayer_playtone(FAR struct nxplayer_s *pplayer, uint32_t samprate,
2261→                      uint32_t pitchfreq, uint32_t duration)
2262→{
2263→  DEBUGASSERT(pplayer != NULL);
2264→
2265→  if (pplayer->state != NXPLAYER_STATE_IDLE)
2266→    {
2267→      return -EBUSY;
2268→    }
2269→
2270→  pplayer->tone.sample_rate = samprate ? samprate : 48000;
2271→  pplayer->tone.pitch_freq  = pitchfreq ? pitchfreq : 440;
2272→  pplayer->tone.total_samps = (duration ? duration : 10) *
2273→                               pplayer->tone.sample_rate;
2274→
2275→  audinfo("==============================\n");
2276→  audinfo("Playing tone : samprate:%" PRIu32 " HZ pitchfreq:%" PRIu32 " HZ \
2277→          duration:%" PRIu32 " s\n",
2278→          pplayer->tone.sample_rate, pplayer->tone.pitch_freq,
2279→          pplayer->tone.total_samps / pplayer->tone.sample_rate);
2280→  audinfo("==============================\n");
2281→
2282→  return nxplayer_playinternal(pplayer, AUDIO_FMT_PCM, AUDIO_FMT_UNDEF,
2283→                               2, 16, pplayer->tone.sample_rate, 0);
2284→}
