271→int dm_wifi_wait_time_sync(int timeout_sec)
272→{
273→  int i;
274→
275→  if (timeout_sec < 0)
276→    {
277→      timeout_sec = 0;
278→    }
279→  if (timeout_sec > 90)
280→    {
281→      timeout_sec = 90;
282→    }
283→
284→  for (i = 0; i <= timeout_sec; i++)
285→    {
286→      if (wifi_clock_synced())
287→        {
288→          return 0;
289→        }
290→      if (!dm_wifi_connected())
291→        {
292→          return -ENETDOWN;
