 44→/* "-", uint64_t, ".", 9 digits fraction part, NUL */
 45→
 46→#define NTP_TIME_STR_MAX_LEN (1 + 21 + 1 + 9 + 1)
 47→
 48→static void
 49→format_ntptimestamp(int64_t ts, FAR char *buf, size_t len)
 50→{
 51→  FAR const char *sign;
 52→  uint64_t absts;
 53→
 54→  if (ts < 0)
 55→    {
 56→      sign = "-";
 57→      absts = -ts;
 58→    }
 59→  else
 60→    {
 61→      sign = "";
 62→      absts = ts;
 63→    }
 64→
 65→  snprintf(buf, len, "%s%" PRIu64 ".%09" PRIu64,
 66→           sign, absts >> 32,
 67→           ((absts & 0xffffffff) * NSEC_PER_SEC) >> 32);
 68→}
