1378→static void wifi_request_reconnect(void)
1379→{
1380→  pthread_t th;
1381→  pthread_attr_t attr;
1382→
1383→  if (!s_wifi_enabled || s_manual_override || dm_wifi_connected() ||
1384→      s_reconnect_running)
1385→    {
1386→      return;
1387→    }
1388→
1389→  s_reconnect_running = 1;
1390→  pthread_attr_init(&attr);
1391→  pthread_attr_setstacksize(&attr, DM_WIFI_STACK);
1392→  if (pthread_create(&th, &attr, reconnect_thread, NULL) == 0)
1393→    {
1394→      pthread_detach(th);
1395→    }
1396→  else
1397→    {
1398→      s_reconnect_running = 0;
1399→    }
1400→  pthread_attr_destroy(&attr);
1401→}
