 100→int dm_voice_rec_start(int max_seconds)
 101→{
 102→  pthread_t th;
 103→  pthread_attr_t attr;
 104→
 105→  pthread_mutex_lock(&s_rec_lock);
 106→  if (s_rec_active)
 107→    {
 108→      pthread_mutex_unlock(&s_rec_lock);
 109→      return 0;
 110→    }
 111→
 112→  /* Do not contend for the audio DMA while playback is active.  Use
 113→   * trylock so a UI click never waits behind a long speaker operation. */
 114→  if (pthread_mutex_trylock(&s_audio_lock) != 0)
 115→    {
 116→      pthread_mutex_unlock(&s_rec_lock);
 117→      return -EBUSY;
 118→    }
 119→
 120→  unlink(WAV_REC);
 121→  s_rec = nxrecorder_create();
 122→  if (!s_rec)
 123→    {
 124→      pthread_mutex_unlock(&s_audio_lock);
 125→      pthread_mutex_unlock(&s_rec_lock);
 126→      s_st = DM_VOICE_ERR;
 127→      return -1;
 128→    }
 129→  (void)nxrecorder_setdevice(s_rec, "/dev/audio/pcm0c");
 130→  if (nxrecorder_recordinternal(s_rec, WAV_REC, AUDIO_FMT_PCM,
 131→                                REC_CH, REC_BITS, REC_RATE, 1) != OK)
 132→    {
 133→      nxrecorder_release(s_rec);
 134→      s_rec = NULL;
 135→      pthread_mutex_unlock(&s_audio_lock);
 136→      pthread_mutex_unlock(&s_rec_lock);
 137→      s_st = DM_VOICE_ERR;
 138→      return -1;
 139→    }
 140→
 141→  s_rec_active = 1;
 142→  s_st = DM_VOICE_REC;
 143→  pthread_mutex_unlock(&s_audio_lock);
 144→  pthread_mutex_unlock(&s_rec_lock);
 145→
 146→  pthread_attr_init(&attr);
 147→  pthread_attr_setstacksize(&attr, 4096);
 148→  if (pthread_create(&th, &attr, rec_auto_stop,
 149→                     (void *)(intptr_t)(max_seconds > 0 ? max_seconds
 150→                                                        : REC_MAX_SEC)) == 0)
 151→    {
 152→      pthread_detach(th);
 153→    }
 154→  pthread_attr_destroy(&attr);
 155→  return 0;
 156→}
