 211→/* ---- player: nxplayer (buffer-queue API) ---- */
 212→
 213→/* The audio driver owns a small number of DMA channels.  Serialize all
 214→ * playback and recording setup/teardown so the app never starts a new stream
 215→ * while an earlier stream is still releasing its buffers. */
 216→
 217→/* nxplayer treats .wav as raw PCM and never reads the WAV header
 218→ * (its PCM ops->pre_parse is NULL), so the fmt chunk is parsed here and
 219→ * the payload is fed via nxplayer_playraw() with explicit parameters. */
 220→static int play_wav(const char *path)
 221→{
 222→  const char *src = (path && path[0]) ? path : WAV_TTS;
 223→  struct nxplayer_s *p = NULL;
 224→  FILE *f = NULL;
 225→  FILE *o = NULL;
 226→  uint8_t hdr[44];
 227→  char buf[1024];
 228→  size_t n;
 229→  size_t raw_len = 0;
 230→  uint32_t rate;
 231→  uint16_t ch;
 232→  uint16_t bits;
 233→  uint64_t bytes_per_sec;
 234→  uint64_t play_ms;
 235→  int rc = -1;
 236→
 237→  if (pthread_mutex_trylock(&s_audio_lock) != 0)
 238→    {
 239→      return -EBUSY;
 240→    }
 241→  if (s_rec_active)
 242→    {
 243→      pthread_mutex_unlock(&s_audio_lock);
 244→      return -EBUSY;
 245→    }
 246→
 247→  p = nxplayer_create();
 248→  if (!p || nxplayer_setdevice(p, "/dev/audio/pcm0p") != OK)
 249→    {
 250→      goto out;
 251→    }
 252→
 253→  f = fopen(src, "rb");
 254→  if (!f)
 255→    {
 256→      goto out;
 257→    }
 258→  if (fread(hdr, 1, 44, f) != 44 || memcmp(hdr, "RIFF", 4) != 0)
 259→    {
 260→      goto out;
 261→    }
 262→  ch = (uint16_t)(hdr[22] | (hdr[23] << 8));
 263→  rate = (uint32_t)(hdr[24] | (hdr[25] << 8) | (hdr[26] << 16) |
 264→                    ((uint32_t)hdr[27] << 24));
 265→  bits = (uint16_t)(hdr[34] | (hdr[35] << 8));
 266→  if (rate < 8000 || rate > 48000)
 267→    {
 268→      rate = 24000;
 269→    }
 270→  if (ch < 1 || ch > 2)
 271→    {
 272→      ch = 1;
 273→    }
 274→  if (bits != 8 && bits != 16)
 275→    {
 276→      bits = 16;
 277→    }
 278→
 279→  o = fopen(PCM_RAW, "wb");
 280→  if (!o)
 281→    {
 282→      goto out;
 283→    }
 284→  while ((n = fread(buf, 1, sizeof(buf), f)) > 0)
 285→    {
 286→      if (fwrite(buf, 1, n, o) != n)
 287→        {
 288→          goto out;
 289→        }
 290→      raw_len += n;
 291→    }
 292→  if (ferror(f) || raw_len == 0)
 293→    {
 294→      goto out;
 295→    }
 296→  fclose(o);
 297→  o = NULL;
 298→  fclose(f);
 299→  f = NULL;
 300→
 301→  if (nxplayer_playraw(p, PCM_RAW, AUDIO_FMT_PCM, 0, (uint8_t)ch,
 302→                       (uint8_t)bits, rate, 1) != OK)
 303→    {
 304→      goto out;
 305→    }
 306→
 307→  /* nxplayer_playraw() returns as soon as its worker is started.  Keep the
 308→   * audio gate until the PCM duration elapses and stop/join the worker, so a
 309→   * following capture/playback cannot race the previous DMA release. */
 310→  bytes_per_sec = (uint64_t)rate * ch * bits / 8;
 311→  play_ms = bytes_per_sec ? ((uint64_t)raw_len * 1000 / bytes_per_sec) : 1000;
 312→  play_ms += 150;
 313→  if (play_ms > 30000)
 314→    {
 315→      play_ms = 30000;
 316→    }
 317→  while (play_ms >= 1000)
 318→    {
 319→      sleep(1);
 320→      play_ms -= 1000;
 321→    }
 322→  if (play_ms > 0)
 323→    {
 324→      usleep((useconds_t)(play_ms * 1000));
 325→    }
 326→
 327→  (void)nxplayer_stop(p);
 328→  rc = 0;
 329→
 330→out:
 331→  if (o)
 332→    {
 333→      fclose(o);
 334→    }
 335→  if (f)
 336→    {
 337→      fclose(f);
 338→    }
 339→  if (p)
 340→    {
 341→      nxplayer_release(p);
 342→    }
 343→  pthread_mutex_unlock(&s_audio_lock);
 344→  return rc;
 345→}
