 439→/* Run curl from a script so nsh cannot strip quoted header arguments. */
 440→static int run_curl_script(const char *line)
 441→{
 442→  FILE *f = fopen(VOICE_CURL_SCRIPT, "w");
 443→  int write_ok;
 444→  int close_rc;
 445→  int rc;
 446→
 447→  if (!f)
 448→    {
 449→      syslog(LOG_ERR, "[dm-voice] cannot create curl script\n");
 450→      return -1;
 451→    }
 452→
 453→  write_ok = fputs("#!/bin/sh\n", f) != EOF &&
 454→             fputs(line, f) != EOF && fputc('\n', f) != EOF;
 455→  close_rc = fclose(f);
 456→  if (!write_ok || close_rc != 0)
 457→    {
 458→      syslog(LOG_ERR, "[dm-voice] cannot write curl script\n");
 459→      return -1;
 460→    }
 461→
 462→  rc = system("sh " VOICE_CURL_SCRIPT);
 463→  if (rc != 0)
 464→    {
 465→      syslog(LOG_ERR, "[dm-voice] curl script failed status=%d\n", rc);
 466→      return -1;
 467→    }
 468→  return 0;
 469→}
