248→static void extract_content(const char *path, char *out, size_t cap)
249→{
250→  FILE *f;
251→  char *buf;
252→  long sz;
253→  char *p;
254→  char *q;
255→
256→  out[0] = '\0';
257→  f = fopen(path, "rb");
258→  if (!f)
259→    {
260→      return;
261→    }
262→  fseek(f, 0, SEEK_END);
263→  sz = ftell(f);
264→  fseek(f, 0, SEEK_SET);
265→  if (sz <= 0 || sz > 64 * 1024)
266→    {
267→      fclose(f);
268→      return;
269→    }
270→  buf = malloc((size_t)sz + 1);
271→  if (!buf)
272→    {
273→      fclose(f);
274→      return;
275→    }
276→  if (fread(buf, 1, (size_t)sz, f) != (size_t)sz)
277→    {
278→      free(buf);
279→      fclose(f);
280→      return;
281→    }
282→  buf[sz] = '\0';
283→  fclose(f);
284→
285→  p = strstr(buf, "\"content\"");
286→  if (!p)
287→    {
288→      free(buf);
289→      return;
290→    }
291→  p = strchr(p + 9, '"');
292→  if (!p)
293→    {
294→      free(buf);
295→      return;
296→    }
297→  q = strchr(p + 1, '"');
298→  if (!q)
299→    {
300→      free(buf);
301→      return;
302→    }
303→  {
304→    size_t n = (size_t)(q - (p + 1));
305→    if (n >= cap)
306→      {
307→        n = cap - 1;
308→      }
309→    memcpy(out, p + 1, n);
310→    out[n] = '\0';
311→    /* unescape \" and \\ and \n lightly */
312→    {
313→      char *r = out;
314→      char *w = out;
315→      while (*r)
316→        {
317→          if (r[0] == '\\' && r[1] == 'n')
318→            {
319→              *w++ = ' ';
320→              r += 2;
321→            }
322→          else if (r[0] == '\\' && r[1] == '"')
323→            {
324→              *w++ = '"';
325→              r += 2;
326→            }
327→          else if (r[0] == '\\' && r[1] == '\\')
328→            {
329→              *w++ = '\\';
330→              r += 2;
331→            }
332→          else
333→            {
334→              *w++ = *r++;
335→            }
336→        }
337→      *w = '\0';
338→    }
339→  }
340→  free(buf);
341→}
