 321→static int wifi_is_associated(char *assoc_ssid, size_t ssid_len)
 322→{
 323→  FILE *fp;
 324→  char buf[256];
 325→  int associated = 1;
 326→
 327→  if (assoc_ssid && ssid_len > 0)
 328→    {
 329→      assoc_ssid[0] = 0;
 330→    }
 331→
 332→  (void)system("wapi show wlan0 > /tmp/wifi_status.txt");
 333→  fp = fopen("/tmp/wifi_status.txt", "r");
 334→  if (!fp)
 335→    {
 336→      return 0;
 337→    }
 338→
 339→  while (fgets(buf, sizeof(buf), fp) != NULL)
 340→    {
 341→      buf[strcspn(buf, "\r\n")] = 0;
 342→      if (strstr(buf, "AP: 00:00:00:00:00:00") != NULL)
 343→        {
 344→          associated = 0;
 345→        }
 346→      if (assoc_ssid && ssid_len > 0)
 347→        {
 348→          char *p = strstr(buf, "ESSID:");
 349→          if (p)
 350→            {
 351→              p += 6;
 352→              while (*p == ' ' || *p == '"')
 353→                {
 354→                  p++;
 355→                }
 356→              snprintf(assoc_ssid, ssid_len, "%s", p);
 357→              assoc_ssid[strcspn(assoc_ssid, "\"\r\n")] = 0;
 358→            }
 359→        }
 360→    }
 361→
 362→  fclose(fp);
 363→  return associated;
 364→}
