 387→/* Port of 9.5 wifi_manager.c:get_wifi_status().
 388→ * 1 = associated, 0 = not associated (AP is all-zero), -1 = cannot read.
 389→ * "wapi show" returns early when there is no IPv4 yet, so it is only used as
 390→ * an EXTRA check after an address was obtained. */
 391→static int wifi_is_link_up(void)
 392→{
 393→  FILE *fp;
 394→  char buf[256];
 395→  int associated = 1;
 396→
 397→  (void)system("wapi show wlan0 > /tmp/wifi_status.txt 2>&1");
 398→  fp = fopen("/tmp/wifi_status.txt", "r");
 399→  if (!fp)
 400→    {
 401→      return -1;
 402→    }
 403→
 404→  while (fgets(buf, sizeof(buf), fp) != NULL)
 405→    {
 406→      if (strstr(buf, "AP: 00:00:00:00:00:00") != NULL)
 407→        {
 408→          associated = 0;
 409→          break;
 410→        }
 411→    }
 412→
 413→  fclose(fp);
 414→  return associated;
 415→}
