 594→static int wifi_cred_load_wapi_json(char *ssid, size_t slen, char *pass,
 595→                                    size_t plen)
 596→{
 597→  FILE *f;
 598→  cJSON *root;
 599→  cJSON *ifobj;
 600→  cJSON *ssid_item;
 601→  cJSON *psk_item;
 602→  char *buf;
 603→  long size;
 604→  int ret = -1;
 605→
 606→  f = fopen(DM_WIFI_WAPI_CONFIG_PATH, "rb");
 607→  if (!f)
 608→    {
 609→      return -1;
 610→    }
 611→
 612→  if (fseek(f, 0, SEEK_END) != 0 || (size = ftell(f)) <= 0 || size > 4096 ||
 613→      fseek(f, 0, SEEK_SET) != 0)
 614→    {
 615→      fclose(f);
 616→      return -1;
 617→    }
 618→
 619→  buf = malloc((size_t)size + 1);
 620→  if (!buf)
 621→    {
 622→      fclose(f);
 623→      return -1;
 624→    }
 625→  if (fread(buf, 1, (size_t)size, f) != (size_t)size)
 626→    {
 627→      free(buf);
 628→      fclose(f);
 629→      return -1;
 630→    }
 631→  fclose(f);
 632→  buf[size] = '\0';
 633→
 634→  root = cJSON_Parse(buf);
 635→  free(buf);
 636→  if (!root)
 637→    {
 638→      return -1;
 639→    }
 640→
 641→  /* WAPI save_config writes {"wlan0":{"ssid":...,"psk":...}}.  Accept
 642→   * the older flat shape as a compatibility fallback. */
 643→  ifobj = cJSON_GetObjectItem(root, DM_WIFI_IF);
 644→  if (!ifobj)
 645→    {
 646→      ifobj = root;
 647→    }
 648→  ssid_item = cJSON_GetObjectItem(ifobj, "ssid");
 649→  psk_item = cJSON_GetObjectItem(ifobj, "psk");
 650→  if (ssid_item && cJSON_IsString(ssid_item) && ssid_item->valuestring &&
 651→      ssid_item->valuestring[0])
 652→    {
 653→      snprintf(ssid, slen, "%s", ssid_item->valuestring);
 654→      if (psk_item && cJSON_IsString(psk_item) && psk_item->valuestring)
 655→        {
 656→          snprintf(pass, plen, "%s", psk_item->valuestring);
 657→        }
 658→      else
 659→        {
 660→          pass[0] = '\0';
 661→        }
 662→      ret = 0;
 663→    }
 664→
 665→  cJSON_Delete(root);
 666→  if (ret == 0)
 667→    {
 668→      syslog(LOG_INFO, "[deskmate-wifi] loaded credentials from WAPI config\n");
 669→    }
 670→  return ret;
 671→}
