183→static void kick_job(int job)
184→{
185→  pthread_t th;
186→  pthread_attr_t attr;
187→
188→  if (s_busy)
189→    {
190→      return;
191→    }
192→  s_busy = true;
193→  s_job = job;
194→  s_ui_rec = false;
195→  s_rec_sec = 0;
196→  s_out_ready = 0;
197→  s_out_ans[0] = '\0';
198→  s_out_sub[0] = '\0';
199→
200→  dm_face_set(FACE_THINK, EYE_DECOR_NONE, 10);
201→  set_ans(job == 1 ? dm_t("识别中…", "Recognizing…")
202→                   : dm_t("思考中…", "Thinking…"));
203→  set_ptt("处理中…", "Working…", C_BTN_HI);
204→
205→  pthread_attr_init(&attr);
206→  pthread_attr_setstacksize(&attr, 24576);
207→  if (pthread_create(&th, &attr, voice_worker, NULL) == 0)
208→    {
209→      pthread_detach(th);
210→    }
211→  else
212→    {
213→      s_busy = false;
214→      if (job == 1 && dm_voice_rec_active())
215→        {
216→          /* Keep the recording controllable if worker creation failed. */
217→          s_ui_rec = true;
218→          set_ans(dm_t("正在录音，稍后再点结束",
219→                       "Recording; tap stop again"));
220→          set_ptt("结束并发送", "Stop & send", C_HEART);
221→        }
222→      else
223→        {
224→          set_ptt("开始说话", "Start talk", C_BTN);
225→        }
226→    }
227→  pthread_attr_destroy(&attr);
228→}
