1476→
1477→/****************************************************************************
1478→ * Name: ntpc_start_with_list
1479→ *
1480→ * Description:
1481→ *   Start the NTP daemon
1482→ *
1483→ * Returned Value:
1484→ *   On success, the non-negative task ID of the NTPC daemon is returned;
1485→ *   On failure, a negated errno value is returned.
1486→ *
1487→ ****************************************************************************/
1488→
1489→int ntpc_start_with_list(FAR const char *ntp_server_list)
1490→{
1491→  FAR char *task_argv[] =
1492→    {
1493→      (FAR char *)ntp_server_list,
1494→      NULL
1495→    };
1496→
1497→  /* Is the NTP in a non-running state? */
1498→
1499→  sem_wait(&g_ntpc_daemon.lock);
1500→  if (g_ntpc_daemon.state == NTP_NOT_RUNNING ||
1501→      g_ntpc_daemon.state == NTP_STOPPED)
1502→    {
1503→      /* Start the NTP daemon */
1504→
1505→      g_ntpc_daemon.state = NTP_STARTED;
1506→      g_ntpc_daemon.pid =
1507→        task_create("NTP daemon", CONFIG_NETUTILS_NTPCLIENT_SERVERPRIO,
1508→                    CONFIG_NETUTILS_NTPCLIENT_STACKSIZE, ntpc_daemon,
1509→                    task_argv);
1510→
1511→      /* Handle failures to start the NTP daemon */
1512→
1513→      if (g_ntpc_daemon.pid < 0)
1514→        {
1515→          int errval = errno;
1516→          DEBUGASSERT(errval > 0);
1517→
1518→          g_ntpc_daemon.state = NTP_STOPPED;
1519→          nerr("ERROR: Failed to start the NTP daemon: %d\n", errval);
1520→          sem_post(&g_ntpc_daemon.lock);
1521→          return -errval;
1522→        }
1523→
1524→      /* Wait for any daemon state change */
1525→
1526→      do
1527→        {
1528→          sem_wait(&g_ntpc_daemon.sync);
1529→        }
1530→      while (g_ntpc_daemon.state == NTP_STARTED);
1531→    }
1532→
1533→  sem_post(&g_ntpc_daemon.lock);
1534→  return g_ntpc_daemon.pid;
1535→}
1536→
1537→/****************************************************************************
1538→ * Name: ntpc_start
1539→ *
1540→ * Description:
1541→ *   Start the NTP daemon
1542→ *
1543→ * Returned Value:
1544→ *   On success, the non-negative task ID of the NTPC daemon is returned;
1545→ *   On failure, a negated errno value is returned.
1546→ *
1547→ ****************************************************************************/
1548→
1549→int ntpc_start(void)
1550→{
1551→  return ntpc_start_with_list(CONFIG_NETUTILS_NTPCLIENT_SERVER);
1552→}
1553→
1554→/****************************************************************************
1555→ * Name: ntpc_stop
1556→ *
1557→ * Description:
1558→ *   Stop the NTP daemon
1559→ *
1560→ * Returned Value:
1561→ *   Zero on success; a negated errno value on failure.  The current
1562→ *   implementation only returns success.
1563→ *
1564→ ****************************************************************************/
1565→
1566→int ntpc_stop(void)
1567→{
1568→  int ret;
1569→
1570→  /* Is the NTP in a running state? */
1571→
1572→  sem_wait(&g_ntpc_daemon.lock);
1573→  if (g_ntpc_daemon.state == NTP_STARTED ||
1574→      g_ntpc_daemon.state == NTP_RUNNING)
1575→    {
1576→      /* Yes.. request that the daemon stop. */
1577→
1578→      g_ntpc_daemon.state = NTP_STOP_REQUESTED;
1579→
1580→      /* Wait for any daemon state change */
1581→
1582→      do
1583→        {
1584→          /* Signal the NTP client */
1585→
1586→          ret = kill(g_ntpc_daemon.pid,
1587→                     CONFIG_NETUTILS_NTPCLIENT_SIGWAKEUP);
1588→
1589→          if (ret < 0)
1590→            {
1591→              nerr("ERROR: kill pid %d failed: %d\n",
1592→                   g_ntpc_daemon.pid, errno);
1593→              break;
1594→            }
1595→
1596→          /* Wait for the NTP client to respond to the stop request */
1597→
1598→          sem_wait(&g_ntpc_daemon.sync);
1599→        }
1600→      while (g_ntpc_daemon.state == NTP_STOP_REQUESTED);
1601→    }
1602→
1603→  sem_post(&g_ntpc_daemon.lock);
1604→  return OK;
1605→}
