1246→                   CONFIG_NETUTILS_NTPCLIENT_NUM_SAMPLES);
1247→  if (samples == NULL)
1248→    {
1249→      return EXIT_FAILURE;
1250→    }
1251→
1252→  srvs = calloc(1, sizeof(*srvs));
1253→  if (srvs == NULL)
