277→static void wifi_restart_ntp_after_link(void)
278→{
279→  int stop_rc;
280→  int start_rc;
281→  uint64_t now_ms;
282→
283→  if (wifi_clock_synced())
284→    {
285→      return;
286→    }
287→
288→  pthread_mutex_lock(&s_ntp_lock);
289→  now_ms = wifi_monotonic_ms();
290→  if (s_ntp_retry_after_ms != 0 && now_ms < s_ntp_retry_after_ms)
291→    {
292→      pthread_mutex_unlock(&s_ntp_lock);
293→      return;
294→    }
295→
296→  /* The stock pool may be unreachable from some WLANs. Refresh only from an
297→   * app worker and provide several DNS-resolved public NTP endpoints. */
298→  stop_rc = ntpc_stop();
299→  start_rc = ntpc_start_with_list(DM_WIFI_NTP_SERVERS);
300→  s_ntp_retry_after_ms = now_ms +
301→      (uint64_t)DM_WIFI_NTP_RETRY_SEC * 1000;
302→  syslog(start_rc < 0 ? LOG_WARNING : LOG_INFO,
303→         "[deskmate-wifi] NTP refresh stop=%d start=%d\n",
304→         stop_rc, start_rc);
305→  pthread_mutex_unlock(&s_ntp_lock);
306→}
