static int b64_encode(const unsigned char *in, size_t inlen, char *out, size_t outcap)
{
  size_t i = 0, o = 0;
  while (i < inlen && o + 4 < outcap)
    {
      unsigned int v = in[i++] << 16;
      if (i < inlen) v |= in[i++] << 8;
      if (i < inlen) v |= in[i++];
      out[o++] = b64tab[(v >> 18) & 63];
      out[o++] = b64tab[(v >> 12) & 63];
      out[o++] = b64tab[(v >> 6) & 63];
      out[o++] = b64tab[v & 63];
    }
  out[o] = '\0';
  return (int)o;
}

