 936→void dm_wifi_tick(void)
 937→{
 938→  dm_wifi_poll();
 939→
 940→  if (dm_wifi_link_lost())
 941→    {
 942→      dm_wifi_clear_link_lost();
 943→      refresh_wifi_header();
 944→      refresh_ap_list();
 945→      if (g_dm.page == PAGE_WIFI)
 946→        {
 947→          set_tip("Wi-Fi 连接已断开，请重新连接",
 948→                  "Connection lost, reconnect");
 949→        }
 950→    }
 951→
 952→  if (g_dm.page == PAGE_SETTINGS || g_dm.page == PAGE_WIFI)
 953→    {
 954→      refresh_wifi_header();
 955→    }
 956→
 957→  if (g_dm.page == PAGE_WIFI)
 958→    {
 959→      if (dm_wifi_scan_ready())
 960→        {
 961→          dm_wifi_clear_scan_ready();
 962→          refresh_ap_list();
 963→          if (dm_wifi_ap_count() > 0)
 964→            {
 965→              char b[48];
 966→              lv_snprintf(b, sizeof(b), "%s %d %s",
 967→                          dm_t("找到", "Found"), dm_wifi_ap_count(),
 968→                          dm_t("个热点，点选后连接", "APs, tap to select"));
 969→              set_tip(b, b);
 970→            }
 971→          else
 972→            {
 973→              set_tip("未找到热点，可再点「扫描」", "No APs, tap Scan again");
 974→            }
 975→        }
 976→    }
 977→
 978→  if (g_dm.page == PAGE_WIFI_CONN)
 979→    {
 980→      if (dm_wifi_conn_ok())
 981→        {
 982→          dm_wifi_clear_conn_flags();
 983→          refresh_wifi_header();
 984→          if (s_done_title)
 985→            {
 986→              lv_label_set_text(s_done_title, dm_t("已连接", "Connected"));
 987→              lv_obj_set_style_text_color(s_done_title, lv_color_hex(C_OK),
 988→                                          LV_PART_MAIN);
 989→            }
 990→          if (s_done_icon)
 991→            {
 992→              lv_label_set_text(s_done_icon, "OK");
 993→              lv_obj_set_style_text_color(s_done_icon, lv_color_hex(C_OK),
 994→                                          LV_PART_MAIN);
 995→            }
 996→          if (s_done_sub)
 997→            {
 998→              lv_label_set_text(s_done_sub, dm_wifi_cur_ip());
 999→            }
1000→          dm_show(PAGE_WIFI_DONE);
1001→        }
1002→      else if (dm_wifi_conn_fail())
1003→        {
1004→          dm_wifi_clear_conn_flags();
1005→          refresh_wifi_header();
1006→          if (s_done_title)
1007→            {
1008→              lv_label_set_text(s_done_title,
1009→                                dm_t("连接失败", "Failed"));
1010→              lv_obj_set_style_text_color(s_done_title, lv_color_hex(C_HEART),
1011→                                          LV_PART_MAIN);
1012→            }
1013→          if (s_done_icon)
1014→            {
1015→              lv_label_set_text(s_done_icon, "X");
1016→              lv_obj_set_style_text_color(s_done_icon, lv_color_hex(C_HEART),
1017→                                          LV_PART_MAIN);
1018→            }
1019→          if (s_done_sub)
1020→            {
1021→              lv_label_set_text(s_done_sub,
1022→                                dm_t("请检查密码或重试", "Check password"));
1023→            }
1024→          dm_show(PAGE_WIFI_DONE);
1025→        }
1026→    }
1027→}
