 70→  lv_obj_set_style_radius(g_dm_root, 0, LV_PART_MAIN);
 71→  lv_obj_set_style_pad_all(g_dm_root, 0, LV_PART_MAIN);
 72→  lv_obj_clear_flag(g_dm_root, LV_OBJ_FLAG_SCROLLABLE);
 73→
