628→static int time_days_in_month(int year, int month)
629→{
630→  static const int days[] = { 31, 28, 31, 30, 31, 30,
631→                              31, 31, 30, 31, 30, 31 };
632→  int leap;
633→
634→  if (month < 1 || month > 12)
635→    {
636→      return 31;
637→    }
638→  leap = ((year % 4 == 0 && year % 100 != 0) || year % 400 == 0);
639→  if (month == 2 && leap)
640→    {
641→      return 29;
642→    }
643→  return days[month - 1];
644→}
