646→static void time_seed_from_build(void)
647→{
648→  static const char *const months[] =
649→    { "Jan", "Feb", "Mar", "Apr", "May", "Jun",
650→      "Jul", "Aug", "Sep", "Oct", "Nov", "Dec" };
651→  char mon[4] = { 0 };
652→  int day = 1;
653→  int year = 2026;
654→  int hour = 12;
655→  int minute = 0;
656→  int second = 0;
657→  int i;
658→
659→  if (sscanf(__DATE__, "%3s %d %d", mon, &day, &year) == 3)
660→    {
661→      for (i = 0; i < 12; i++)
662→        {
663→          if (strcmp(mon, months[i]) == 0)
664→            {
665→              s_time_value[1] = i + 1;
666→              break;
667→            }
668→        }
669→      s_time_value[0] = year;
670→      s_time_value[2] = day;
671→    }
672→  else
673→    {
674→      s_time_value[0] = year;
675→      s_time_value[1] = 1;
676→      s_time_value[2] = 1;
677→    }
678→
679→  if (sscanf(__TIME__, "%d:%d:%d", &hour, &minute, &second) != 3)
680→    {
681→      hour = 12;
682→      minute = 0;
683→    }
684→  s_time_value[3] = hour;
685→  s_time_value[4] = minute;
686→}
