694→      current.tm_year + 1900 >= 2024)
695→    {
696→      s_time_value[0] = current.tm_year + 1900;
697→      s_time_value[1] = current.tm_mon + 1;
698→      s_time_value[2] = current.tm_mday;
699→      s_time_value[3] = current.tm_hour;
700→      s_time_value[4] = current.tm_min;
701→    }
702→  else
703→    {
704→      time_seed_from_build();
705→    }
