752→static void time_step_cb(lv_event_t *e)
753→{
754→  int action = (int)(intptr_t)lv_event_get_user_data(e);
755→  int field = action >> 1;
756→  int delta = (action & 1) ? 1 : -1;
757→
758→  if (field < 0 || field >= 5)
759→    {
760→      return;
761→    }
762→
763→  switch (field)
764→    {
765→      case 0:
766→        s_time_value[0] += delta;
767→        if (s_time_value[0] < 2024) s_time_value[0] = 2024;
768→        if (s_time_value[0] > 2099) s_time_value[0] = 2099;
769→        break;
770→      case 1:
771→        s_time_value[1] += delta;
772→        if (s_time_value[1] < 1) s_time_value[1] = 12;
773→        if (s_time_value[1] > 12) s_time_value[1] = 1;
774→        if (s_time_value[2] > time_days_in_month(s_time_value[0],
775→                                                   s_time_value[1]))
776→          {
777→            s_time_value[2] = time_days_in_month(s_time_value[0],
778→                                                  s_time_value[1]);
779→          }
780→        break;
781→      case 2:
782→        s_time_value[2] += delta;
783→        if (s_time_value[2] < 1)
784→          {
785→            s_time_value[2] = time_days_in_month(s_time_value[0],
786→                                                  s_time_value[1]);
787→          }
788→        if (s_time_value[2] > time_days_in_month(s_time_value[0],
789→                                                  s_time_value[1]))
790→          {
791→            s_time_value[2] = 1;
792→          }
793→        break;
794→      case 3:
795→        s_time_value[3] = (s_time_value[3] + delta + 24) % 24;
796→        break;
797→      case 4:
798→        s_time_value[4] = (s_time_value[4] + delta + 60) % 60;
799→        break;
800→    }
801→  time_refresh_labels();
802→}
