836→static void time_apply_cb(lv_event_t *e)
837→{
838→  struct tm requested;
839→  struct tm verify;
840→  struct timeval tv;
841→  time_t epoch;
842→
843→  (void)e;
844→  if (s_time_value[0] < 2024 || s_time_value[0] > 2099 ||
845→      s_time_value[1] < 1 || s_time_value[1] > 12 ||
846→      s_time_value[2] < 1 ||
847→      s_time_value[2] > time_days_in_month(s_time_value[0],
848→                                            s_time_value[1]) ||
849→      s_time_value[3] < 0 || s_time_value[3] > 23 ||
850→      s_time_value[4] < 0 || s_time_value[4] > 59)
851→    {
852→      if (s_time_hint_l)
853→        {
854→          lv_label_set_text(s_time_hint_l,
855→                            dm_t("日期或时间超出范围", "Date/time out of range"));
856→        }
857→      return;
858→    }
859→
860→  memset(&requested, 0, sizeof(requested));
861→  requested.tm_year = s_time_value[0] - 1900;
862→  requested.tm_mon = s_time_value[1] - 1;
863→  requested.tm_mday = s_time_value[2];
864→  requested.tm_hour = s_time_value[3];
865→  requested.tm_min = s_time_value[4];
866→  requested.tm_isdst = -1;
867→  epoch = mktime(&requested);
868→  if (epoch == (time_t)-1 || localtime_r(&epoch, &verify) == NULL ||
869→      verify.tm_year != requested.tm_year ||
870→      verify.tm_mon != requested.tm_mon ||
871→      verify.tm_mday != requested.tm_mday ||
872→      verify.tm_hour != requested.tm_hour ||
873→      verify.tm_min != requested.tm_min)
874→    {
875→      if (s_time_hint_l)
876→        {
877→          lv_label_set_text(s_time_hint_l,
878→                            dm_t("系统无法识别该日期", "Invalid local date"));
879→        }
880→      return;
881→    }
882→
883→  tv.tv_sec = epoch;
884→  tv.tv_usec = 0;
885→  if (settimeofday(&tv, NULL) != 0)
886→    {
887→      if (s_time_hint_l)
888→        {
889→          lv_label_set_text(s_time_hint_l,
890→                            dm_t("设置失败，请确认系统允许改时钟",
891→                                 "Set failed; clock change may be restricted"));
892→        }
893→      return;
894→    }
895→
896→  dm_wifi_manual_time_mark();
897→  time_refresh_labels();
898→  if (s_time_hint_l)
899→    {
900→      lv_label_set_text(s_time_hint_l,
901→                        dm_t("已设置；网络 NTP 同步后会自动校正",
902→                             "Set; NTP will correct it when available"));
903→    }
904→}
