 631→static int time_days_in_month(int year, int month)
 632→{
 633→  static const int days[] = { 31, 28, 31, 30, 31, 30,
 634→                              31, 31, 30, 31, 30, 31 };
 635→  int leap;
 636→
 637→  if (month < 1 || month > 12)
 638→    {
 639→      return 31;
 640→    }
 641→  leap = ((year % 4 == 0 && year % 100 != 0) || year % 400 == 0);
 642→  if (month == 2 && leap)
 643→    {
 644→      return 29;
 645→    }
 646→  return days[month - 1];
 647→}
