 652→    { "Jan", "Feb", "Mar", "Apr", "May", "Jun",
 653→      "Jul", "Aug", "Sep", "Oct", "Nov", "Dec" };
 654→  char mon[4] = { 0 };
 655→  int day = 1;
 656→  int year = 2026;
 657→  int hour = 12;
 658→  int minute = 0;
 659→  int second = 0;
