 754→static void time_step_cb(lv_event_t *e)
 755→{
 756→  int action = (int)(intptr_t)lv_event_get_user_data(e);
 757→  int field = action >> 1;
 758→  int delta = (action & 1) ? 1 : -1;
 759→
 760→  if (field < 0 || field >= 5)
 761→    {
 762→      return;
 763→    }
 764→
 765→  switch (field)
 766→    {
 767→      case 0:
 768→        s_time_value[0] += delta;
 769→        if (s_time_value[0] < 2024) s_time_value[0] = 2024;
 770→        if (s_time_value[0] > 2099) s_time_value[0] = 2099;
 771→        if (s_time_value[2] > time_days_in_month(s_time_value[0],
 772→                                                  s_time_value[1]))
 773→          {
 774→            s_time_value[2] = time_days_in_month(s_time_value[0],
 775→                                                  s_time_value[1]);
 776→          }
 777→        break;
 778→      case 1:
 779→        s_time_value[1] += delta;
 780→        if (s_time_value[1] < 1) s_time_value[1] = 12;
 781→        if (s_time_value[1] > 12) s_time_value[1] = 1;
 782→        if (s_time_value[2] > time_days_in_month(s_time_value[0],
 783→                                                   s_time_value[1]))
 784→          {
 785→            s_time_value[2] = time_days_in_month(s_time_value[0],
 786→                                                  s_time_value[1]);
 787→          }
 788→        break;
 789→      case 2:
 790→        s_time_value[2] += delta;
 791→        if (s_time_value[2] < 1)
 792→          {
 793→            s_time_value[2] = time_days_in_month(s_time_value[0],
 794→                                                  s_time_value[1]);
 795→          }
 796→        if (s_time_value[2] > time_days_in_month(s_time_value[0],
 797→                                                  s_time_value[1]))
 798→          {
 799→            s_time_value[2] = 1;
 800→          }
 801→        break;
 802→      case 3:
 803→        s_time_value[3] = (s_time_value[3] + delta + 24) % 24;
 804→        break;
 805→      case 4:
 806→        s_time_value[4] = (s_time_value[4] + delta + 60) % 60;
 807→        break;
 808→    }
 809→  time_refresh_labels();
 810→}
