 844→static void time_apply_cb(lv_event_t *e)
 845→{
 846→  struct tm requested;
 847→  struct tm verify;
 848→  struct timeval tv;
 849→  time_t epoch;
 850→
 851→  (void)e;
 852→  if (s_time_value[0] < 2024 || s_time_value[0] > 2099 ||
 853→      s_time_value[1] < 1 || s_time_value[1] > 12 ||
 854→      s_time_value[2] < 1 ||
 855→      s_time_value[2] > time_days_in_month(s_time_value[0],
 856→                                            s_time_value[1]) ||
 857→      s_time_value[3] < 0 || s_time_value[3] > 23 ||
 858→      s_time_value[4] < 0 || s_time_value[4] > 59)
 859→    {
 860→      if (s_time_hint_l)
 861→        {
 862→          lv_label_set_text(s_time_hint_l,
 863→                            dm_t("日期或时间超出范围", "Date/time out of range"));
 864→        }
 865→      return;
 866→    }
 867→
 868→  memset(&requested, 0, sizeof(requested));
 869→  requested.tm_year = s_time_value[0] - 1900;
 870→  requested.tm_mon = s_time_value[1] - 1;
 871→  requested.tm_mday = s_time_value[2];
 872→  requested.tm_hour = s_time_value[3];
 873→  requested.tm_min = s_time_value[4];
 874→  requested.tm_isdst = -1;
 875→  epoch = mktime(&requested);
 876→  if (epoch == (time_t)-1 || localtime_r(&epoch, &verify) == NULL ||
 877→      verify.tm_year != requested.tm_year ||
 878→      verify.tm_mon != requested.tm_mon ||
 879→      verify.tm_mday != requested.tm_mday ||
 880→      verify.tm_hour != requested.tm_hour ||
 881→      verify.tm_min != requested.tm_min)
 882→    {
 883→      if (s_time_hint_l)
 884→        {
 885→          lv_label_set_text(s_time_hint_l,
 886→                            dm_t("系统无法识别该日期", "Invalid local date"));
 887→        }
 888→      return;
 889→    }
 890→
 891→  tv.tv_sec = epoch;
 892→  tv.tv_usec = 0;
 893→  if (settimeofday(&tv, NULL) != 0)
 894→    {
 895→      if (s_time_hint_l)
 896→        {
 897→          lv_label_set_text(s_time_hint_l,
 898→                            dm_t("设置失败，请确认系统允许改时钟",
 899→                                 "Set failed; clock change may be restricted"));
 900→        }
 901→      return;
 902→    }
 903→
 904→  dm_wifi_manual_time_mark();
 905→  time_refresh_labels();
 906→  if (s_time_hint_l)
 907→    {
 908→      lv_label_set_text(s_time_hint_l,
 909→                        dm_t("已设置；网络 NTP 同步后会自动校正",
 910→                             "Set; NTP will correct it when available"));
 911→    }
 912→}
