546→static int chat_reply(const char *user, char *out, int cap)
547→{
548→  char esc[400];
549→  char body[900];
550→  char *rsp;
551→  FILE *f;
552→  long sz;
553→  int n;
554→  char *p;
555→  char *q;
556→
557→  out[0] = '\0';
558→  json_escape(user, esc, sizeof(esc));
559→
560→  n = snprintf(body, sizeof(body),
561→               "{\"model\":\"%s\",\"messages\":["
562→               "{\"role\":\"system\",\"content\":\"你是openvela语音小助手，口语化简短回答，不超过60字。\"},"
563→               "{\"role\":\"user\",\"content\":\"%s\"}],"
564→               "\"temperature\":0.7,\"max_tokens\":120}",
565→               CHAT_MODEL, esc);
566→  if (n <= 0 || n >= (int)sizeof(body))
567→    {
568→      return -1;
569→    }
570→  if (http_post_json("/chat/completions", body, TXT_CHAT) != 0)
571→    {
572→      return -1;
573→    }
574→
575→  f = fopen(TXT_CHAT, "rb");
576→  if (!f)
577→    {
578→      return -1;
579→    }
580→  fseek(f, 0, SEEK_END);
581→  sz = ftell(f);
582→  fseek(f, 0, SEEK_SET);
583→  if (sz <= 0 || sz > 64 * 1024)
584→    {
585→      fclose(f);
586→      return -1;
587→    }
588→  rsp = malloc((size_t)sz + 1);
589→  if (!rsp)
590→    {
591→      fclose(f);
592→      return -1;
593→    }
594→  if (fread(rsp, 1, (size_t)sz, f) != (size_t)sz)
595→    {
596→      free(rsp);
597→      fclose(f);
598→      return -1;
599→    }
600→  rsp[sz] = '\0';
601→  fclose(f);
602→
603→  p = strstr(rsp, "\"content\"");
604→  if (p)
605→    {
606→      p = strchr(p + 9, '"');
607→      if (p)
608→        {
609→          q = strchr(p + 1, '"');
610→          if (q)
611→            {
612→              size_t ln = (size_t)(q - p - 1);
613→              if (ln >= (size_t)cap)
614→                {
615→                  ln = (size_t)cap - 1;
616→                }
617→              memcpy(out, p + 1, ln);
618→              out[ln] = '\0';
619→            }
620→        }
621→    }
622→  free(rsp);
623→  return out[0] ? 0 : -1;
624→}
