272→  if (json_escape(user_text, esc, sizeof(esc)) < 0)
273→    {
274→      return local_reply(user_text);
275→    }
276→
277→  n = snprintf(body, sizeof(body),
278→               "{\"model\":\"%s\",\"messages\":["
