 231→/* Check wapi show wlan0 like 9.5 wifi_manager.c get_wifi_status() */
 232→static int wifi_is_associated(char *assoc_ssid, size_t ssid_len)
 233→{
 234→  FILE *fp;
 235→  char buf[256];
 236→  int associated = 1;
 237→
 238→  if (assoc_ssid && ssid_len > 0)
 239→    {
 240→      assoc_ssid[0] = 0;
 241→    }
 242→
 243→  (void)system("wapi show wlan0 > /tmp/wifi_status.txt");
 244→  fp = fopen("/tmp/wifi_status.txt", "r");
 245→  if (!fp)
 246→    {
 247→      return 0;
 248→    }
 249→
 250→  while (fgets(buf, sizeof(buf), fp) != NULL)
 251→    {
 252→      buf[strcspn(buf, "\r\n")] = 0;
 253→      if (strstr(buf, "AP: 00:00:00:00:00:00") != NULL)
 254→        {
 255→          associated = 0;
 256→        }
 257→      if (assoc_ssid && ssid_len > 0)
 258→        {
 259→          char *p = strstr(buf, "ESSID:");
 260→          if (p)
 261→            {
 262→              p += 6;
 263→              while (*p == ' ' || *p == '"')
 264→                {
 265→                  p++;
 266→                }
 267→              snprintf(assoc_ssid, ssid_len, "%s", p);
 268→              assoc_ssid[strcspn(assoc_ssid, "\"\r\n")] = 0;
 269→            }
 270→        }
 271→    }
 272→
 273→  fclose(fp);
 274→  return associated;
 275→}
 276→
 277→/* Verify the current association is really the expected SSID.
 278→ * Returns 1 = match, 0 = mismatch / not associated, -1 = cannot read. */
 279→static int wifi_verify_assoc(const char *expected)
 280→{
 281→  char assoc[33];
 282→
 283→  if (!expected || !expected[0])
 284→    {
 285→      return -1;
 286→    }
 287→  if (!wifi_is_associated(assoc, sizeof(assoc)))
 288→    {
 289→      return 0;
 290→    }
 291→  if (!assoc[0])
 292→    {
 293→      return -1;
 294→    }
 295→  return strcmp(assoc, expected) == 0 ? 1 : 0;
 296→}
 297→
 298→/* Port of 9.5 wifi_manager.c:get_wifi_status().
 299→ * 1 = associated, 0 = not associated (AP is all-zero), -1 = cannot read.
 300→ * "wapi show" returns early when there is no IPv4 yet, so it is only used as
 301→ * an EXTRA check after an address was obtained. */
 302→static int wifi_is_link_up(void)
 303→{
 304→  FILE *fp;
 305→  char buf[256];
 306→  int associated = 1;
 307→
 308→  (void)system("wapi show wlan0 > /tmp/wifi_status.txt 2>&1");
 309→  fp = fopen("/tmp/wifi_status.txt", "r");
 310→  if (!fp)
 311→    {
 312→      return -1;
 313→    }
 314→
 315→  while (fgets(buf, sizeof(buf), fp) != NULL)
 316→    {
 317→      if (strstr(buf, "AP: 00:00:00:00:00:00") != NULL)
 318→        {
 319→          associated = 0;
 320→          break;
 321→        }
 322→    }
 323→
 324→  fclose(fp);
 325→  return associated;
 326→}
