 562→
 563→/* Parse /tmp/wifi_scan_result.txt:
 564→ *   bssid / frequency / signal level / encode / ssid
 565→ *   74:39:89:f8:f0:ae       5240    -59     0803    Programmers7
 566→ *   d2:ad:08:f8:eb:71       2462    -88     0803    DIRECT-71-HP Smart Tank 750
 567→ *
 568→ * Preserves spaces inside SSIDs, skips hidden (empty) SSIDs and non-MAC lines,
 569→ * deduplicates same-SSID entries (keeping strongest RSSI), and sorts by RSSI.
 570→ */
 571→static int collect_aps_from_txt(void)
 572→{
 573→  FILE *fp;
 574→  char line[256];
 575→  int n = 0;
 576→  int i;
 577→  int j;
 578→
 579→  fp = fopen("/tmp/wifi_scan_result.txt", "r");
 580→  if (!fp)
 581→    {
 582→      return -1;
 583→    }
 584→
 585→  pthread_mutex_lock(&s_lock);
 586→  s_ap_n = 0;
 587→
 588→  while (fgets(line, sizeof(line), fp) && n < DM_WIFI_AP_MAX)
 589→    {
 590→      char *p = line;
 591→      char *tok_bssid;
 592→      char *tok_freq;
 593→      char *tok_rssi;
 594→      char *tok_enc;
 595→      char *ssid_start;
 596→      size_t ssid_len;
 597→      int rssi;
 598→      bool is_open;
 599→      int dup_idx = -1;
 600→
 601→      line[strcspn(line, "\r\n")] = 0;
 602→
 603→      while (*p == ' ' || *p == '\t')
 604→        {
 605→          p++;
 606→        }
 607→      if (!*p || strncmp(p, "bssid", 5) == 0)
 608→        {
 609→          continue;
 610→        }
 611→
 612→      /* Field 0: BSSID (must contain ':') */
 613→      tok_bssid = p;
 614→      while (*p && *p != ' ' && *p != '\t')
 615→        {
 616→          p++;
 617→        }
 618→      if (!*p)
 619→        {
 620→          continue;
 621→        }
 622→      *p++ = 0;
 623→      if (strchr(tok_bssid, ':') == NULL)
 624→        {
 625→          continue;
 626→        }
 627→
 628→      /* Field 1: frequency */
 629→      while (*p == ' ' || *p == '\t')
 630→        {
 631→          p++;
 632→        }
 633→      tok_freq = p;
 634→      while (*p && *p != ' ' && *p != '\t')
 635→        {
 636→          p++;
 637→        }
 638→      if (!*p || !*tok_freq)
 639→        {
 640→          continue;
 641→        }
 642→      *p++ = 0;
 643→
 644→      /* Field 2: signal level (RSSI) */
 645→      while (*p == ' ' || *p == '\t')
 646→        {
 647→          p++;
 648→        }
 649→      tok_rssi = p;
 650→      while (*p && *p != ' ' && *p != '\t')
 651→        {
 652→          p++;
 653→        }
 654→      if (!*p || !*tok_rssi)
 655→        {
 656→          continue;
 657→        }
 658→      *p++ = 0;
 659→      rssi = atoi(tok_rssi);
 660→
 661→      /* Field 3: encode (0000 = open, otherwise encrypted) */
 662→      while (*p == ' ' || *p == '\t')
 663→        {
 664→          p++;
 665→        }
 666→      tok_enc = p;
 667→      while (*p && *p != ' ' && *p != '\t')
 668→        {
 669→          p++;
 670→        }
 671→      if (*p)
 672→        {
 673→          *p++ = 0;
 674→        }
 675→      if (!*tok_enc)
 676→        {
 677→          continue;
 678→        }
 679→      is_open = (strcmp(tok_enc, "0000") == 0);
 680→
 681→      /* Field 4+: entire remainder of line is SSID (may contain spaces) */
 682→      while (*p == ' ' || *p == '\t')
 683→        {
 684→          p++;
 685→        }
 686→      ssid_start = p;
 687→      ssid_len = strlen(ssid_start);
 688→      while (ssid_len > 0 &&
 689→             (ssid_start[ssid_len - 1] == ' ' ||
 690→              ssid_start[ssid_len - 1] == '\t'))
 691→        {
 692→          ssid_start[--ssid_len] = 0;
 693→        }
 694→      if (ssid_len == 0)
 695→        {
 696→          /* Hidden AP with blank SSID */
 697→          continue;
 698→        }
 699→
 700→      /* Deduplicate by SSID: keep strongest RSSI */
 701→      for (i = 0; i < n; i++)
 702→        {
 703→          if (strncmp(s_aps[i].ssid, ssid_start, sizeof(s_aps[i].ssid) - 1) == 0)
 704→            {
 705→              dup_idx = i;
 706→              break;
 707→            }
 708→        }
 709→      if (dup_idx >= 0)
 710→        {
 711→          if (rssi > s_aps[dup_idx].rssi)
 712→            {
 713→              s_aps[dup_idx].rssi = rssi;
 714→              s_aps[dup_idx].open = is_open;
 715→            }
 716→          continue;
 717→        }
 718→
 719→      strncpy(s_aps[n].ssid, ssid_start, sizeof(s_aps[n].ssid) - 1);
 720→      s_aps[n].ssid[sizeof(s_aps[n].ssid) - 1] = 0;
 721→      s_aps[n].rssi = rssi;
 722→      s_aps[n].open = is_open;
 723→      n++;
 724→    }
 725→
 726→  /* Sort APs by RSSI descending (strongest signal first) */
 727→  for (i = 0; i < n - 1; i++)
 728→    {
 729→      for (j = i + 1; j < n; j++)
 730→        {
 731→          if (s_aps[j].rssi > s_aps[i].rssi)
 732→            {
 733→              dm_ap_t tmp = s_aps[i];
 734→              s_aps[i] = s_aps[j];
 735→              s_aps[j] = tmp;
 736→            }
 737→        }
 738→    }
 739→
 740→  s_ap_n = n;
 741→  if (s_sel >= s_ap_n)
 742→    {
 743→      s_sel = (s_ap_n > 0) ? 0 : -1;
 744→    }
 745→  pthread_mutex_unlock(&s_lock);
 746→  fclose(fp);
 747→  return n;
 748→}
 749→
 750→static void *scan_thread(void *arg)
 751→{
 752→  int i;
 753→  int n;
 754→
 755→  (void)arg;
 756→
 757→  if (!s_wifi_enabled)
 758→    {
 759→      s_scan_busy = 0;
 760→      s_scan_ready = 1;
 761→      return NULL;
 762→    }
 763→
 764→  /* Wait briefly if an auto-connect thread is yielding */
 765→  for (i = 0; i < 50 && s_conn_busy; i++)
 766→    {
 767→      usleep(100 * 1000);
 768→    }
 769→
 770→  if (ensure_driver() < 0)
 771→    {
 772→      s_scan_busy = 0;
 773→      s_scan_ready = 1;
 774→      return NULL;
 775→    }
 776→
 777→  /* Only bring interface up in STA mode if not already connected */
 778→  if (!dm_wifi_connected())
 779→    {
 780→      cli_sta_up();
 781→      usleep(200 * 1000);
 782→    }
 783→
 784→  /* Match 9.5 demo get_wifi.sh: wapi scan wlan0 > /tmp/wifi_scan_result.txt */
 785→  (void)system("wapi scan wlan0 > /tmp/wifi_scan_result.txt");
 786→  usleep(300 * 1000);
 787→
 788→  n = collect_aps_from_txt();
 789→  if (n <= 0)
 790→    {
 791→      usleep(500 * 1000);
 792→      (void)system("wapi scan wlan0 > /tmp/wifi_scan_result.txt");
 793→      usleep(300 * 1000);
 794→      n = collect_aps_from_txt();
 795→    }
 796→
 797→  syslog(LOG_INFO, "[deskmate-wifi] wapi scan -> %d aps\n", n);
 798→  for (i = 0; i < s_ap_n; i++)
 799→    {
 800→      syslog(LOG_INFO, "[deskmate-wifi]  ap %s rssi=%d open=%d\n",
 801→             s_aps[i].ssid, s_aps[i].rssi, (int)s_aps[i].open);
 802→    }
 803→
 804→  s_scan_busy = 0;
 805→  s_scan_ready = 1;
 806→  return NULL;
 807→}
 808→
 809→int dm_wifi_start_scan(void)
 810→{
 811→  pthread_t th;
 812→  pthread_attr_t attr;
 813→  int ret;
 814→
 815→  if (!s_wifi_enabled)
 816→    {
 817→      return -1;
 818→    }
 819→
 820→  if (s_scan_busy)
 821→    {
 822→      return 0;
 823→    }
 824→
 825→  /* Interrupt any background boot auto-connect so manual scan is never blocked */
 826→  s_manual_override = 1;
 827→  if (s_conn_busy && !s_conn_is_auto)
 828→    {
 829→      return -1;
 830→    }
 831→
 832→  s_scan_ready = 0;
 833→  s_scan_busy = 1;
 834→  pthread_attr_init(&attr);
 835→  pthread_attr_setstacksize(&attr, DM_WIFI_STACK);
 836→  ret = pthread_create(&th, &attr, scan_thread, NULL);
 837→  pthread_attr_destroy(&attr);
 838→  if (ret != 0)
 839→    {
 840→      s_scan_busy = 0;
 841→      return -1;
 842→    }
 843→  pthread_detach(th);
 844→  return 0;
 845→}
 846→
 847→/* Official connect — ifup → mode 2 → psk(3 2) → essid(1) → wait → renew */
 848→static void *conn_thread(void *arg)
 849→{
 850→  char cmd[192];
 851→  char qssid[80];
 852→  char qpass[160];
 853→  int i;
 854→  int attempt;
 855→  int got_ip = 0;
 856→  int is_auto = s_conn_is_auto;
 857→  struct in_addr addr;
 858→  char try_ssid[33];
 859→  char try_pass[64];
 860→  bool try_open;
 861→
 862→  (void)arg;
 863→
 864→  if (!s_wifi_enabled)
 865→    {
 866→      s_conn_busy = 0;
 867→      s_conn_fail = 1;
 868→      return NULL;
 869→    }
 870→
 871→  strncpy(try_ssid, s_pending_ssid, sizeof(try_ssid) - 1);
 872→  try_ssid[sizeof(try_ssid) - 1] = 0;
 873→  strncpy(try_pass, s_pending_pass, sizeof(try_pass) - 1);
 874→  try_pass[sizeof(try_pass) - 1] = 0;
 875→  try_open = s_pending_open;
 876→
 877→  if (try_ssid[0] == 0 || if_nametoindex(DM_WIFI_IF) == 0)
 878→    {
 879→      syslog(LOG_ERR, "[deskmate-wifi] connect abort: no ssid/wlan0\n");
 880→      s_conn_busy = 0;
 881→      s_conn_fail = 1;
 882→      return NULL;
 883→    }
 884→
 885→  if (ensure_driver() < 0)
 886→    {
 887→      s_conn_busy = 0;
 888→      s_conn_fail = 1;
 889→      return NULL;
 890→    }
 891→
 892→  if (is_auto && s_manual_override)
 893→    {
 894→      s_conn_busy = 0;
 895→      return NULL;
 896→    }
 897→
 898→  /* NOTE: credentials are persisted only after a verified connection (below).
 899→
 900→   * 9) The 9.5 wifi_manager retries the whole sequence every 5s until it is
 901→   * associated. Port that behaviour here: up to DM_WIFI_CONN_ROUNDS tries. */
 902→  for (attempt = 0; attempt < DM_WIFI_CONN_ROUNDS; attempt++)
 903→    {
 904→      if (attempt > 0)
 905→        {
 906→          syslog(LOG_INFO, "[deskmate-wifi] retry %d/%d in %ds\n",
 907→                 attempt + 1, DM_WIFI_CONN_ROUNDS, DM_WIFI_CONN_RETRY_SEC);
 908→          sleep(DM_WIFI_CONN_RETRY_SEC);
 909→        }
 910→
 911→      got_ip = 0;
 912→
 913→      /* 1) ifup + STA mode */
 914→      cli_sta_up();
 915→
 916→  /* 1.5) Drop the previous association so switching between networks
 917→   *      (WPA2 <-> open) always starts from a clean driver state. */
 918→  syslog(LOG_INFO, "[deskmate-wifi] wapi disconnect %s\n", DM_WIFI_IF);
 919→  (void)system("wapi disconnect wlan0");
 920→  usleep(100 * 1000);
 921→
 922→  /* 2) psk — WPA_ALG_CCMP = 3, WPA2 = 2 */
 923→  if (!try_open && try_pass[0])
 924→    {
 925→      if (shell_quote(try_pass, qpass, sizeof(qpass)) < 0)
 926→        {
 927→          s_conn_busy = 0;
 928→          s_conn_fail = 1;
 929→          return NULL;
 930→        }
 931→      snprintf(cmd, sizeof(cmd), "wapi psk %s %s 3 2", DM_WIFI_IF, qpass);
 932→      syslog(LOG_INFO, "[deskmate-wifi] %s\n", cmd);
 933→      if (system(cmd) != 0)
 934→        {
 935→          syslog(LOG_ERR, "[deskmate-wifi] psk failed (passphrase must be 8-63 chars)\n");
 936→          s_conn_busy = 0;
 937→          s_conn_fail = 1;
 938→          return NULL;
 939→        }
 940→    }
 941→  else
 942→    {
 943→      /* Open AP: clear any leftover WPA key (alg 0 = WPA_ALG_NONE), otherwise
 944→       * the driver keeps the previous CCMP key and cannot join open networks. */
 945→      syslog(LOG_INFO, "[deskmate-wifi] open AP: clear psk\n");
 946→      (void)system("wapi psk wlan0 00000000 0");
 947→    }
 948→
 949→  /* 3) essid — flag 1 = connect */
 950→  if (shell_quote(try_ssid, qssid, sizeof(qssid)) < 0)
 951→    {
 952→      s_conn_busy = 0;
 953→      s_conn_fail = 1;
 954→      return NULL;
 955→    }
 956→  snprintf(cmd, sizeof(cmd), "wapi essid %s %s 1", DM_WIFI_IF, qssid);
 957→  syslog(LOG_INFO, "[deskmate-wifi] %s\n", cmd);
 958→  if (system(cmd) != 0)
 959→    {
 960→      syslog(LOG_ERR, "[deskmate-wifi] essid join failed\n");
 961→      s_conn_busy = 0;
 962→      s_conn_fail = 1;
 963→      return NULL;
 964→    }
 965→
 966→  /* 4) Wait for WPA2 4-way handshake / association (interruptible if auto) */
 967→  for (i = 0; i < 25; i++)
 968→    {
 969→      if (!s_wifi_enabled)
 970→        {
 971→          s_conn_busy = 0;
 972→          return NULL;
 973→        }
 974→      if (is_auto && s_manual_override)
 975→        {
 976→          s_conn_busy = 0;
 977→          return NULL;
 978→        }
 979→      usleep(100 * 1000);
 980→    }
 981→
 982→  /* 5) DHCP renew — single DHCP call per attempt */
 983→  for (i = 0; i < 4; i++)
 984→    {
 985→      if (is_auto && s_manual_override)
 986→        {
 987→          s_conn_busy = 0;
 988→          return NULL;
 989→        }
 990→
 991→      (void)system("renew wlan0");
 992→      if (wifi_get_valid_ip(&addr) == 0)
 993→        {
 994→          got_ip = 1;
 995→          break;
 996→        }
 997→
 998→      if (is_auto && s_manual_override)
 999→        {
1000→          s_conn_busy = 0;
1001→          return NULL;
1002→        }
1003→
1004→      if (netlib_obtain_ipv4addr(DM_WIFI_IF) >= 0 &&
1005→          wifi_get_valid_ip(&addr) == 0)
1006→        {
1007→          got_ip = 1;
1008→          break;
1009→        }
1010→
1011→      syslog(LOG_WARNING, "[deskmate-wifi] renew retry %d\n", i + 1);
1012→      sleep(1);
1013→    }
1014→
1015→  /* Verify we are really associated with the intended SSID (an old IPv4
1016→   * address may still be configured while switching networks). */
1017→  if (got_ip)
1018→    {
1019→      int assoc = wifi_verify_assoc(try_ssid);
1020→      if (assoc == 0)
1021→        {
1022→          syslog(LOG_ERR,
1023→                 "[deskmate-wifi] associated to another SSID, treat as failure\n");
1024→          got_ip = 0;
1025→        }
1026→      else if (assoc < 0)
1027→        {
1028→          syslog(LOG_WARNING,
1029→                 "[deskmate-wifi] cannot verify ESSID, assume connected\n");
1030→        }
1031→    }
1032→
1033→      /* Ported check: "wapi show" reports AP all-zero when not associated. */
1034→      if (got_ip && wifi_is_link_up() == 0)
1035→        {
1036→          syslog(LOG_WARNING, "[deskmate-wifi] wapi show: not associated yet\n");
1037→          got_ip = 0;
1038→        }
1039→
1040→      if (got_ip)
1041→        {
1042→          break;
1043→        }
1044→
1045→      syslog(LOG_WARNING, "[deskmate-wifi] attempt %d/%d failed\n",
1046→             attempt + 1, DM_WIFI_CONN_ROUNDS);
1047→    }
1048→
1049→  if (got_ip && !s_wifi_enabled)
1050→    {
1051→      got_ip = 0;
1052→    }
1053→
1054→  /* Fix: Only set s_cur_ssid when got_ip is true! */
1055→  pthread_mutex_lock(&s_lock);
1056→  if (got_ip)
1057→    {
1058→      strncpy(s_cur_ssid, try_ssid, sizeof(s_cur_ssid) - 1);
1059→      s_cur_ssid[sizeof(s_cur_ssid) - 1] = 0;
1060→      strncpy(s_cur_ip, inet_ntoa(addr), sizeof(s_cur_ip) - 1);
1061→      s_cur_ip[sizeof(s_cur_ip) - 1] = 0;
1062→    }
1063→  else
1064→    {
1065→      s_cur_ssid[0] = 0;
1066→      s_cur_ip[0] = 0;
1067→    }
1068→  pthread_mutex_unlock(&s_lock);
1069→
1070→  if (!got_ip)
1071→    {
1072→      syslog(LOG_ERR,
1073→             "[deskmate-wifi] connect fail after %d attempts "
1074→             "(ssid=%s wlan0=%d)\n",
1075→             DM_WIFI_CONN_ROUNDS, try_ssid,
1076→             (int)if_nametoindex(DM_WIFI_IF));
1077→      s_conn_busy = 0;
1078→      s_conn_fail = 1;
1079→      return NULL;
1080→    }
1081→
1082→  syslog(LOG_INFO, "[deskmate-wifi] connected ssid=%s ip=%s\n",
1083→         s_cur_ssid, s_cur_ip);
1084→
1085→  if (system("wapi save_config wlan0") != 0)
1086→    {
1087→      syslog(LOG_WARNING, "[deskmate-wifi] wapi save_config failed\n");
1088→    }
1089→  wifi_cred_save(try_ssid, try_pass);
1090→
1091→  s_conn_busy = 0;
1092→  s_conn_ok = 1;
1093→  return NULL;
1094→}
1095→
1096→static int wifi_start_connect_internal(const char *ssid, const char *pass,
1097→                                       int is_auto)
1098→{
1099→  pthread_t th;
1100→  pthread_attr_t attr;
1101→  int ret;
1102→  int i;
1103→
1104→  if (!ssid || !ssid[0])
1105→    {
1106→      return -1;
1107→    }
1108→
1109→  if (!is_auto)
1110→    {
1111→      s_manual_override = 1;
1112→      for (i = 0; i < 50 && (s_scan_busy || (s_conn_busy && s_conn_is_auto)); i++)
1113→        {
1114→          usleep(100 * 1000);
1115→        }
1116→    }
1117→
1118→  if (s_scan_busy || s_conn_busy)
1119→    {
1120→      return -1;
1121→    }
1122→
1123→  strncpy(s_pending_ssid, ssid, sizeof(s_pending_ssid) - 1);
1124→  s_pending_ssid[sizeof(s_pending_ssid) - 1] = 0;
1125→  if (pass)
1126→    {
1127→      strncpy(s_pending_pass, pass, sizeof(s_pending_pass) - 1);
1128→      s_pending_pass[sizeof(s_pending_pass) - 1] = 0;
1129→    }
1130→  else
1131→    {
1132→      s_pending_pass[0] = 0;
1133→    }
1134→  s_pending_open = (pass == NULL || s_pending_pass[0] == 0);
1135→
1136→  s_conn_ok = 0;
1137→  s_conn_fail = 0;
1138→  s_conn_is_auto = is_auto;
1139→  s_conn_busy = 1;
1140→
1141→  pthread_attr_init(&attr);
1142→  pthread_attr_setstacksize(&attr, DM_WIFI_STACK);
1143→  ret = pthread_create(&th, &attr, conn_thread, NULL);
1144→  pthread_attr_destroy(&attr);
1145→  if (ret != 0)
1146→    {
1147→      s_conn_busy = 0;
1148→      return -1;
1149→    }
1150→  pthread_detach(th);
1151→  return 0;
1152→}
1153→
1154→int dm_wifi_connect(const char *ssid, const char *pass)
1155→{
1156→  return wifi_start_connect_internal(ssid, pass, 0);
1157→}
1158→
1159→/* Boot auto-connect: checks if already connected, otherwise tries saved
1160→ * credentials once or twice and immediately yields if user opens manual scan. */
1161→static void *auto_thread(void *arg)
1162→{
1163→  char ssid[33];
1164→  char pass[64];
1165→  struct in_addr addr;
1166→  int round;
1167→  int i;
1168→
1169→  (void)arg;
1170→
1171→  ssid[0] = 0;
1172→  pass[0] = 0;
1173→  if (wifi_cred_load(ssid, sizeof(ssid), pass, sizeof(pass)) != 0 ||
1174→      !ssid[0])
1175→    {
1176→      if (DM_WIFI_AUTO_SSID[0] == 0)
1177→        {
1178→          syslog(LOG_INFO,
1179→                 "[deskmate-wifi] no saved credentials; skip auto-connect\n");
1180→          return NULL;
1181→        }
1182→      snprintf(ssid, sizeof(ssid), "%s", DM_WIFI_AUTO_SSID);
1183→      snprintf(pass, sizeof(pass), "%s", DM_WIFI_AUTO_PSK);
1184→    }
1185→
1186→  syslog(LOG_INFO,
1187→         "[deskmate-wifi] auto-connect ssid=%s — wait wlan0 first\n", ssid);
1188→
1189→  for (round = 0; round < 2 && !s_manual_override; round++)
1190→    {
1191→      if (ensure_driver_wait(300) < 0)
1192→        {
1193→          if (s_manual_override)
1194→            {
1195→              return NULL;
1196→            }
1197→          sleep(2);
1198→          continue;
1199→        }
1200→
1201→      /* If board or wifi_manager already obtained an IP, adopt it directly */
1202→      if (wifi_get_valid_ip(&addr) == 0)
1203→        {
1204→          char assoc_ssid[33];
1205→          wifi_is_associated(assoc_ssid, sizeof(assoc_ssid));
1206→          pthread_mutex_lock(&s_lock);
1207→          snprintf(s_cur_ssid, sizeof(s_cur_ssid), "%s",
1208→                   assoc_ssid[0] ? assoc_ssid : ssid);
1209→          snprintf(s_cur_ip, sizeof(s_cur_ip), "%s", inet_ntoa(addr));
1210→          pthread_mutex_unlock(&s_lock);
1211→          syslog(LOG_INFO, "[deskmate-wifi] already connected ssid=%s ip=%s\n",
1212→                 s_cur_ssid, s_cur_ip);
1213→          return NULL;
1214→        }
1215→
1216→      if (dm_wifi_connected() || s_manual_override)
1217→        {
1218→          return NULL;
1219→        }
1220→
1221→      dm_wifi_clear_conn_flags();
1222→      if (wifi_start_connect_internal(ssid, pass, 1) != 0)
1223→        {
1224→          sleep(2);
1225→          continue;
1226→        }
1227→
1228→      /* Wait for conn_thread to finish or manual override */
1229→      for (i = 0; i < 180 && s_conn_busy && !s_manual_override; i++)
1230→        {
1231→          usleep(100 * 1000);
1232→        }
1233→
1234→      if (dm_wifi_connected())
1235→        {
1236→          syslog(LOG_INFO, "[deskmate-wifi] auto connected ssid=%s ip=%s\n",
1237→                 dm_wifi_cur_ssid(), dm_wifi_cur_ip());
1238→          dm_wifi_clear_conn_flags();
1239→          return NULL;
1240→        }
1241→
1242→      dm_wifi_clear_conn_flags();
1243→      if (s_manual_override)
1244→        {
1245→          return NULL;
1246→        }
1247→      sleep(2);
1248→    }
1249→
1250→  syslog(LOG_INFO,
1251→         "[deskmate-wifi] auto-connect finished; manual UI ready\n");
1252→  return NULL;
1253→}
1254→
1255→/* DEPRECATED / DISABLED: boot auto-connect is no longer used.
1256→ * The app is manual-only now (Settings > Wi-Fi). Kept for reference or for
1257→ * a future opt-in, but dm_wifi_auto_start() is not called anywhere. */
1258→void dm_wifi_auto_start(void)
1259→{
1260→  pthread_t th;
1261→  pthread_attr_t attr;
1262→
1263→  if (s_auto_started)
1264→    {
1265→      return;
1266→    }
1267→  s_auto_started = 1;
1268→
1269→  pthread_attr_init(&attr);
1270→  pthread_attr_setstacksize(&attr, DM_WIFI_STACK);
1271→  if (pthread_create(&th, &attr, auto_thread, NULL) == 0)
1272→    {
1273→      pthread_detach(th);
1274→    }
1275→  pthread_attr_destroy(&attr);
1276→}
