  96→ * plain read() on /dev/audio/pcm0c is a no-op on this driver (no .read
  97→ * op), only the nxrecorder buffer-queue path actually captures audio.
  98→ */
  99→
 100→static struct nxrecorder_s *s_rec;
 101→
 102→static void *rec_auto_stop(void *arg)
 103→{
 104→  int max_sec = (int)(intptr_t)arg;
 105→
 106→  sleep(max_sec > 0 ? max_sec : REC_MAX_SEC);
 107→  (void)dm_voice_rec_stop();
 108→  return NULL;
 109→}
 110→
 111→int dm_voice_rec_start(int max_seconds)
 112→{
 113→  pthread_t th;
 114→  pthread_attr_t attr;
 115→
 116→  pthread_mutex_lock(&s_rec_lock);
 117→  if (s_rec_active)
 118→    {
 119→      pthread_mutex_unlock(&s_rec_lock);
 120→      return 0;
 121→    }
 122→
 123→  /* Do not contend for the audio DMA while playback is active.  Use
 124→   * trylock so a UI click never waits behind a long speaker operation. */
 125→  if (pthread_mutex_trylock(&s_audio_lock) != 0)
 126→    {
 127→      pthread_mutex_unlock(&s_rec_lock);
 128→      return -EBUSY;
 129→    }
 130→
 131→  unlink(WAV_REC);
 132→  s_rec = nxrecorder_create();
 133→  if (!s_rec)
 134→    {
 135→      pthread_mutex_unlock(&s_audio_lock);
 136→      pthread_mutex_unlock(&s_rec_lock);
 137→      s_st = DM_VOICE_ERR;
 138→      return -1;
 139→    }
 140→  (void)nxrecorder_setdevice(s_rec, "/dev/audio/pcm0c");
 141→  if (nxrecorder_recordinternal(s_rec, WAV_REC, AUDIO_FMT_PCM,
 142→                                REC_CH, REC_BITS, REC_RATE, 1) != OK)
 143→    {
 144→      nxrecorder_release(s_rec);
 145→      s_rec = NULL;
 146→      pthread_mutex_unlock(&s_audio_lock);
 147→      pthread_mutex_unlock(&s_rec_lock);
 148→      s_st = DM_VOICE_ERR;
 149→      return -1;
 150→    }
 151→
 152→  s_rec_active = 1;
 153→  s_st = DM_VOICE_REC;
 154→  pthread_mutex_unlock(&s_audio_lock);
 155→  pthread_mutex_unlock(&s_rec_lock);
 156→
 157→  pthread_attr_init(&attr);
 158→  pthread_attr_setstacksize(&attr, 4096);
 159→  if (pthread_create(&th, &attr, rec_auto_stop,
 160→                     (void *)(intptr_t)(max_seconds > 0 ? max_seconds
 161→                                                        : REC_MAX_SEC)) == 0)
 162→    {
 163→      pthread_detach(th);
 164→    }
 165→  pthread_attr_destroy(&attr);
 166→  return 0;
 167→}
 168→
 169→int dm_voice_rec_stop(void)
 170→{
 171→  FILE *f;
 172→  long size;
 173→
 174→  pthread_mutex_lock(&s_rec_lock);
 175→  if (s_rec_active)
 176→    {
 177→      /* Stop/join can wait for the NuttX audio worker.  Keep this off the
 178→       * LVGL event thread and hold the audio gate until the recorder releases
 179→       * its DMA/session resources. */
 180→      pthread_mutex_lock(&s_audio_lock);
 181→      if (s_rec)
 182→        {
 183→          nxrecorder_stop(s_rec);
 184→          nxrecorder_release(s_rec);
 185→          s_rec = NULL;
 186→        }
 187→      s_rec_active = 0;
 188→      s_st = DM_VOICE_IDLE;
 189→      pthread_mutex_unlock(&s_audio_lock);
 190→    }
 191→  pthread_mutex_unlock(&s_rec_lock);
 192→
 193→  f = fopen(WAV_REC, "rb");
 194→  if (!f)
 195→    {
 196→      syslog(LOG_ERR, "[dm-voice] recording file missing\n");
 197→      s_st = DM_VOICE_ERR;
 198→      return -1;
 199→    }
 200→
 201→  if (fseek(f, 0, SEEK_END) != 0)
 202→    {
 203→      fclose(f);
 204→      s_st = DM_VOICE_ERR;
 205→      return -1;
 206→    }
 207→
 208→  size = ftell(f);
 209→  fclose(f);
 210→  if (size <= 44)
 211→    {
 212→      syslog(LOG_ERR, "[dm-voice] recording has no audio payload\n");
 213→      s_st = DM_VOICE_ERR;
 214→      return -1;
 215→    }
 216→
 217→  return 0;
 218→}
