 222→/* ---- player: nxplayer (buffer-queue API) ---- */
 223→
 224→/* The audio driver owns a small number of DMA channels.  Serialize all
 225→ * playback and recording setup/teardown so the app never starts a new stream
 226→ * while an earlier stream is still releasing its buffers. */
 227→
 228→/* nxplayer treats .wav as raw PCM and never reads the WAV header
 229→ * (its PCM ops->pre_parse is NULL), so the fmt chunk is parsed here and
 230→ * the payload is fed via nxplayer_playraw() with explicit parameters. */
 231→static int play_wav(const char *path)
 232→{
 233→  const char *src = (path && path[0]) ? path : WAV_TTS;
 234→  struct nxplayer_s *p = NULL;
 235→  FILE *f = NULL;
 236→  FILE *o = NULL;
 237→  uint8_t hdr[44];
 238→  char buf[1024];
 239→  size_t n;
 240→  size_t raw_len = 0;
 241→  uint32_t rate;
 242→  uint16_t ch;
 243→  uint16_t bits;
 244→  uint64_t bytes_per_sec;
 245→  uint64_t play_ms;
 246→  int rc = -1;
 247→
 248→  if (pthread_mutex_trylock(&s_audio_lock) != 0)
 249→    {
 250→      return -EBUSY;
 251→    }
 252→  if (s_rec_active)
 253→    {
 254→      pthread_mutex_unlock(&s_audio_lock);
 255→      return -EBUSY;
 256→    }
 257→
 258→  p = nxplayer_create();
 259→  if (!p || nxplayer_setdevice(p, "/dev/audio/pcm0p") != OK)
 260→    {
 261→      goto out;
 262→    }
 263→
 264→  f = fopen(src, "rb");
 265→  if (!f)
 266→    {
 267→      goto out;
 268→    }
 269→  if (fread(hdr, 1, 44, f) != 44 || memcmp(hdr, "RIFF", 4) != 0)
 270→    {
 271→      goto out;
 272→    }
 273→  ch = (uint16_t)(hdr[22] | (hdr[23] << 8));
 274→  rate = (uint32_t)(hdr[24] | (hdr[25] << 8) | (hdr[26] << 16) |
 275→                    ((uint32_t)hdr[27] << 24));
 276→  bits = (uint16_t)(hdr[34] | (hdr[35] << 8));
 277→  if (rate < 8000 || rate > 48000)
 278→    {
 279→      rate = 24000;
 280→    }
 281→  if (ch < 1 || ch > 2)
 282→    {
 283→      ch = 1;
 284→    }
 285→  if (bits != 8 && bits != 16)
 286→    {
 287→      bits = 16;
 288→    }
 289→
 290→  o = fopen(PCM_RAW, "wb");
 291→  if (!o)
 292→    {
 293→      goto out;
 294→    }
 295→  while ((n = fread(buf, 1, sizeof(buf), f)) > 0)
 296→    {
 297→      if (fwrite(buf, 1, n, o) != n)
 298→        {
 299→          goto out;
 300→        }
 301→      raw_len += n;
 302→    }
 303→  if (ferror(f) || raw_len == 0)
 304→    {
 305→      goto out;
 306→    }
 307→  fclose(o);
 308→  o = NULL;
 309→  fclose(f);
 310→  f = NULL;
 311→
 312→  if (nxplayer_playraw(p, PCM_RAW, AUDIO_FMT_PCM, 0, (uint8_t)ch,
 313→                       (uint8_t)bits, rate, 1) != OK)
 314→    {
 315→      goto out;
 316→    }
 317→
 318→  /* nxplayer_playraw() returns as soon as its worker is started.  Keep the
 319→   * audio gate until the PCM duration elapses and stop/join the worker, so a
 320→   * following capture/playback cannot race the previous DMA release. */
 321→  bytes_per_sec = (uint64_t)rate * ch * bits / 8;
 322→  play_ms = bytes_per_sec ? ((uint64_t)raw_len * 1000 / bytes_per_sec) : 1000;
 323→  play_ms += 150;
 324→  if (play_ms > 30000)
 325→    {
 326→      play_ms = 30000;
 327→    }
 328→  while (play_ms >= 1000)
 329→    {
 330→      sleep(1);
 331→      play_ms -= 1000;
 332→    }
 333→  if (play_ms > 0)
 334→    {
 335→      usleep((useconds_t)(play_ms * 1000));
 336→    }
 337→
 338→  (void)nxplayer_stop(p);
 339→  rc = 0;
 340→
 341→out:
 342→  if (o)
 343→    {
 344→      fclose(o);
 345→    }
 346→  if (f)
 347→    {
 348→      fclose(f);
 349→    }
 350→  if (p)
 351→    {
 352→      nxplayer_release(p);
 353→    }
 354→  pthread_mutex_unlock(&s_audio_lock);
 355→  return rc;
 356→}
 357→
 358→/* Play one short 440Hz test tone.  This is synchronous by design; callers
 359→ * run it on a worker so neither LVGL nor the recorder UI can block. */
 360→int dm_voice_beep(void)
 361→{
 362→  struct nxplayer_s *p = NULL;
 363→  int rc = -1;
 364→
 365→  if (pthread_mutex_trylock(&s_audio_lock) != 0)
 366→    {
 367→      return -EBUSY;
 368→    }
 369→  if (s_rec_active)
 370→    {
 371→      pthread_mutex_unlock(&s_audio_lock);
 372→      return -EBUSY;
 373→    }
 374→
 375→  p = nxplayer_create();
 376→  if (!p || nxplayer_setdevice(p, "/dev/audio/pcm0p") != OK)
 377→    {
 378→      goto out;
 379→    }
 380→
 381→  if (nxplayer_playtone(p, 16000, 440, 1) != OK)
 382→    {
 383→      goto out;
 384→    }
 385→
 386→  /* Tone playback is asynchronous; wait slightly beyond its duration and
 387→   * join it before allowing the next audio operation. */
 388→  usleep(1150 * 1000);
 389→  (void)nxplayer_stop(p);
 390→  rc = 0;
 391→
 392→out:
 393→  if (p)
 394→    {
 395→      nxplayer_release(p);
 396→    }
 397→  pthread_mutex_unlock(&s_audio_lock);
 398→  return rc;
 399→}
