 461→/* Load and validate the key supplied at runtime. Never log or compile it. */
 462→static int voice_key_load(char *key, size_t key_cap)
 463→{
 464→  FILE *f;
 465→  size_t i;
 466→  size_t n;
 467→  int valid = 0;
 468→
 469→  if (!key || key_cap < 16)
 470→    {
 471→      return 0;
 472→    }
 473→  key[0] = '\0';
 474→  f = fopen(MIMO_KEY_PATH, "rb");
 475→  if (!f)
 476→    {
 477→      snprintf(key, key_cap, "%s", MIMO_EMBEDDED_KEY);
 478→      return key[0] != '\0';
 479→    }
 480→
 481→  if (fgets(key, (int)key_cap, f))
 482→    {
 483→      n = strlen(key);
 484→      while (n > 0 && (key[n - 1] == '\r' || key[n - 1] == '\n' ||
 485→                       key[n - 1] == ' ' || key[n - 1] == '\t'))
 486→        {
 487→          key[--n] = '\0';
 488→        }
 489→      valid = n > 8 && n < key_cap - 1;
 490→      for (i = 0; valid && i < n; i++)
 491→        {
 492→          unsigned char ch = (unsigned char)key[i];
 493→          if (!((ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') ||
 494→                (ch >= '0' && ch <= '9') || ch == '-' || ch == '_' ||
 495→                ch == '.'))
 496→            {
 497→              valid = 0;
 498→            }
 499→        }
 500→    }
 501→
 502→  fclose(f);
 503→  if (!valid)
 504→    {
 505→      memset(key, 0, key_cap);
 506→      snprintf(key, key_cap, "%s", MIMO_EMBEDDED_KEY);
 507→      valid = key[0] != '\0';
 508→    }
 509→  return valid;
 510→}
