 512→/* Curl reads a short-lived, owner-only config file. The shell script itself
 513→ * never contains the key and does not depend on NSH command substitution. */
 514→static int run_curl_script(const char *line)
 515→{
 516→  char key[128];
 517→  FILE *kf;
 518→  FILE *sf;
 519→  int key_write_ok;
 520→  int key_close_rc;
 521→  int script_write_ok;
 522→  int script_close_rc;
 523→  int rc;
 524→
 525→  if (!voice_key_load(key, sizeof(key)))
 526→    {
 527→      s_last_failure = DM_VOICE_FAILURE_API_KEY;
 528→      syslog(LOG_ERR, "[dm-voice] runtime API key missing or invalid\n");
 529→      return -1;
 530→    }
 531→
 532→  kf = fopen(MIMO_CURL_CONFIG, "w");
 533→  if (!kf || chmod(MIMO_CURL_CONFIG, S_IRUSR | S_IWUSR) != 0)
 534→    {
 535→      if (kf)
 536→        {
 537→          fclose(kf);
 538→        }
 539→      memset(key, 0, sizeof(key));
 540→      unlink(MIMO_CURL_CONFIG);
 541→      return -1;
 542→    }
 543→  key_write_ok = fprintf(kf, "header = \"Authorization: Bearer %s\"\n",
 544→                         key) > 0;
 545→  key_close_rc = fclose(kf);
 546→  memset(key, 0, sizeof(key));
 547→  if (!key_write_ok || key_close_rc != 0)
 548→    {
 549→      unlink(MIMO_CURL_CONFIG);
 550→      return -1;
 551→    }
 552→
 553→  sf = fopen(VOICE_CURL_SCRIPT, "w");
 554→  if (!sf)
 555→    {
 556→      unlink(MIMO_CURL_CONFIG);
 557→      syslog(LOG_ERR, "[dm-voice] cannot create curl script\n");
 558→      return -1;
 559→    }
 560→
 561→  script_write_ok = fputs("#!/bin/sh\n", sf) != EOF &&
 562→                    fputs(line, sf) != EOF && fputc('\n', sf) != EOF;
 563→  script_close_rc = fclose(sf);
 564→  if (!script_write_ok || script_close_rc != 0)
 565→    {
 566→      unlink(MIMO_CURL_CONFIG);
 567→      syslog(LOG_ERR, "[dm-voice] cannot write curl script\n");
 568→      return -1;
 569→    }
 570→
 571→  rc = system("sh " VOICE_CURL_SCRIPT);
 572→  unlink(MIMO_CURL_CONFIG);
 573→  if (rc != 0)
 574→    {
 575→      syslog(LOG_ERR, "[dm-voice] curl script failed status=%d\n", rc);
 576→      return -1;
 577→    }
 578→  return 0;
 579→}
