 582→static const char b64tab[] =
 583→    "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
 584→
 585→static int b64_encode(const unsigned char *in, size_t inlen, char *out,
 586→                      size_t outcap)
 587→{
 588→  size_t i = 0;
 589→  size_t o = 0;
 590→
 591→  if (!in || !out || outcap < 2 || inlen > (outcap - 1) / 4 * 3)
 592→    {
 593→      return -1;
 594→    }
 595→
 596→  while (i < inlen)
 597→    {
 598→      size_t remain = inlen - i;
 599→      unsigned int v = (unsigned int)in[i++] << 16;
 600→      if (remain > 1)
 601→        {
 602→          v |= (unsigned int)in[i++] << 8;
 603→        }
 604→      if (remain > 2)
 605→        {
 606→          v |= (unsigned int)in[i++];
 607→        }
 608→      out[o++] = b64tab[(v >> 18) & 63];
 609→      out[o++] = b64tab[(v >> 12) & 63];
 610→      out[o++] = remain > 1 ? b64tab[(v >> 6) & 63] : '=';
 611→      out[o++] = remain > 2 ? b64tab[v & 63] : '=';
 612→    }
 613→  out[o] = '\0';
 614→  return (int)o;
 615→}
 616→
 617→static int b64_decode(const char *in, unsigned char *out, size_t outcap)
 618→{
 619→  uint32_t val = 0;
 620→  int valb = -8;
 621→  size_t o = 0;
 622→  for (; *in && *in != '=' && o < outcap; in++)
 623→    {
 624→      const char *p = strchr(b64tab, *in);
 625→      if (!p) continue;
 626→      val = (val << 6) + (int)(p - b64tab);
 627→      valb += 6;
 628→      if (valb >= 0)
 629→        {
 630→          out[o++] = (unsigned char)((val >> valb) & 255);
 631→          valb -= 8;
 632→        }
 633→    }
 634→  return (int)o;
 635→}
