 637→static int http_post_json(const char *path, const char *json_body,
 638→                          const char *out_path)
 639→{
 640→  char cmd[1400];
 641→  FILE *f;
 642→  size_t body_len;
 643→  int write_ok;
 644→  int close_rc;
 645→  int rc;
 646→
 647→  if (!dm_wifi_connected())
 648→    {
 649→      s_last_failure = DM_VOICE_FAILURE_CHAT;
 650→      return -1;
 651→    }
 652→  if (dm_wifi_wait_time_sync(40) != 0)
 653→    {
 654→      s_last_failure = DM_VOICE_FAILURE_TIME;
 655→      syslog(LOG_WARNING, "[dm-voice] secure request deferred: clock not ready\n");
 656→      return -1;
 657→    }
 658→
 659→  f = fopen(JSON_REQ, "w");
 660→  if (!f)
 661→    {
 662→      s_last_failure = DM_VOICE_FAILURE_CHAT;
 663→      return -1;
 664→    }
 665→  body_len = strlen(json_body);
 666→  write_ok = fwrite(json_body, 1, body_len, f) == body_len;
 667→  close_rc = fclose(f);
 668→  if (!write_ok || close_rc != 0)
 669→    {
 670→      s_last_failure = DM_VOICE_FAILURE_CHAT;
 671→      return -1;
 672→    }
 673→  unlink(out_path);
 674→  /* Use short curl options supported by the board build.  The runtime key is
 675→   * expanded by the shell and is not written into this script. */
 676→  snprintf(cmd, sizeof(cmd),
 677→           "curl -K " MIMO_CURL_CONFIG " -s -S -f -m 25 -X POST %s%s "
 678→           "-H 'Content-Type: application/json' "
 679→           "-d @%s -o %s",
 680→           VOICE_BASE, path, JSON_REQ, out_path);
 681→  rc = run_curl_script(cmd);
 682→  if (rc != 0 && s_last_failure == DM_VOICE_FAILURE_NONE)
 683→    {
 684→      s_last_failure = DM_VOICE_FAILURE_CHAT;
 685→    }
 686→  return rc;
 687→}
