 689→static cJSON *voice_json_load(const char *path, long max_size)
 690→{
 691→  FILE *f;
 692→  char *buf;
 693→  long size;
 694→  cJSON *root;
 695→
 696→  f = fopen(path, "rb");
 697→  if (!f)
 698→    {
 699→      return NULL;
 700→    }
 701→  if (fseek(f, 0, SEEK_END) != 0 || (size = ftell(f)) <= 0 ||
 702→      size > max_size || fseek(f, 0, SEEK_SET) != 0)
 703→    {
 704→      fclose(f);
 705→      return NULL;
 706→    }
 707→  buf = malloc((size_t)size + 1);
 708→  if (!buf)
 709→    {
 710→      fclose(f);
 711→      return NULL;
 712→    }
 713→  if (fread(buf, 1, (size_t)size, f) != (size_t)size)
 714→    {
 715→      free(buf);
 716→      fclose(f);
 717→      return NULL;
 718→    }
 719→  fclose(f);
 720→  buf[size] = '\0';
 721→  root = cJSON_Parse(buf);
 722→  free(buf);
 723→  return root;
 724→}
