 758→/* nxrecorder's AUDIO_FMT_PCM encoder writes headerless PCM even when the
 759→ * filename ends in .wav.  Wrap that payload in a standards-compliant WAV
 760→ * header before sending `format: wav` to the MiMo chat-completions ASR API. */
 761→static int voice_prepare_wav(const char *src, const char **wav_out)
 762→{
 763→  FILE *in;
 764→  FILE *out;
 765→  uint8_t header[44];
 766→  char buf[1024];
 767→  long size;
 768→  size_t n;
 769→  uint32_t data_size;
 770→  unsigned int byte_rate = REC_RATE * REC_CH * REC_BITS / 8;
 771→  int rc = -1;
 772→
 773→  if (!src || !wav_out)
 774→    {
 775→      return -1;
 776→    }
 777→
 778→  *wav_out = src;
 779→  in = fopen(src, "rb");
 780→  if (!in)
 781→    {
 782→      return -1;
 783→    }
 784→
 785→  if (fread(header, 1, 12, in) == 12 &&
 786→      memcmp(header, "RIFF", 4) == 0 && memcmp(header + 8, "WAVE", 4) == 0)
 787→    {
 788→      fclose(in);
 789→      return 0;
 790→    }
 791→
 792→  if (fseek(in, 0, SEEK_END) != 0 || (size = ftell(in)) <= 0 ||
 793→      size > 2 * 1024 * 1024 - 44 || fseek(in, 0, SEEK_SET) != 0)
 794→    {
 795→      fclose(in);
 796→      return -1;
 797→    }
 798→
 799→  data_size = (uint32_t)size;
 800→  memset(header, 0, sizeof(header));
 801→  memcpy(header, "RIFF", 4);
 802→  put_le32(header + 4, data_size + 36);
 803→  memcpy(header + 8, "WAVEfmt ", 8);
 804→  put_le32(header + 16, 16);
 805→  put_le16(header + 20, 1);
 806→  put_le16(header + 22, REC_CH);
 807→  put_le32(header + 24, REC_RATE);
 808→  put_le32(header + 28, byte_rate);
 809→  put_le16(header + 32, REC_CH * REC_BITS / 8);
 810→  put_le16(header + 34, REC_BITS);
 811→  memcpy(header + 36, "data", 4);
 812→  put_le32(header + 40, data_size);
 813→
 814→  out = fopen(WAV_ASR, "wb");
 815→  if (!out)
 816→    {
 817→      fclose(in);
 818→      return -1;
 819→    }
 820→
 821→  if (fwrite(header, 1, sizeof(header), out) == sizeof(header))
 822→    {
 823→      rc = 0;
 824→      while ((n = fread(buf, 1, sizeof(buf), in)) > 0)
 825→        {
 826→          if (fwrite(buf, 1, n, out) != n)
 827→            {
 828→              rc = -1;
 829→              break;
 830→            }
 831→        }
 832→      if (ferror(in))
 833→        {
 834→          rc = -1;
 835→        }
 836→    }
 837→
 838→  if (fclose(out) != 0)
 839→    {
 840→      rc = -1;
 841→    }
 842→  fclose(in);
 843→  if (rc == 0)
 844→    {
 845→      *wav_out = WAV_ASR;
 846→    }
 847→  else
 848→    {
 849→      unlink(WAV_ASR);
 850→    }
 851→  return rc;
 852→}
