 854→static int asr_wav(const char *wav, char *text, int cap)
 855→{
 856→  FILE *f;
 857→  unsigned char *raw;
 858→  char *b64;
 859→  char *body;
 860→  size_t body_cap;
 861→  long sz;
 862→  int n;
 863→  cJSON *root;
 864→  cJSON *message;
 865→  cJSON *content;
 866→
 867→  if (!wav || !text || cap < 2)
 868→    {
 869→      return -1;
 870→    }
 871→  text[0] = '\0';
 872→  f = fopen(wav, "rb");
 873→  if (!f)
 874→    {
 875→      return -1;
 876→    }
 877→  if (fseek(f, 0, SEEK_END) != 0 || (sz = ftell(f)) <= 44 ||
 878→      sz > 2 * 1024 * 1024 || fseek(f, 0, SEEK_SET) != 0)
 879→    {
 880→      fclose(f);
 881→      return -1;
 882→    }
 883→  raw = malloc((size_t)sz);
 884→  b64 = malloc((size_t)sz * 2 + 8);
 885→  body_cap = (size_t)sz * 2 + 512;
 886→  body = malloc(body_cap);
 887→  if (!raw || !b64 || !body)
 888→    {
 889→      free(raw);
 890→      free(b64);
 891→      free(body);
 892→      fclose(f);
 893→      return -1;
 894→    }
 895→  if (fread(raw, 1, (size_t)sz, f) != (size_t)sz)
 896→    {
 897→      free(raw);
 898→      free(b64);
 899→      free(body);
 900→      fclose(f);
 901→      return -1;
 902→    }
 903→  fclose(f);
 904→  if (b64_encode(raw, (size_t)sz, b64, (size_t)sz * 2 + 8) <= 0)
 905→    {
 906→      free(raw);
 907→      free(b64);
 908→      free(body);
 909→      return -1;
 910→    }
 911→  free(raw);
 912→
 913→  /* Official MiMo ASR schema: data URL + one input_audio content part. */
 914→  n = snprintf(body, body_cap,
 915→               "{\"model\":\"%s\",\"messages\":[{\"role\":\"user\",\"content\":"
 916→               "[{\"type\":\"input_audio\",\"input_audio\":{\"data\":"
 917→               "\"data:audio/wav;base64,%s\"}}]}],"
 918→               "\"asr_options\":{\"language\":\"auto\"}}",
 919→               ASR_MODEL, b64);
 920→  free(b64);
 921→  if (n <= 0 || (size_t)n >= body_cap)
 922→    {
 923→      free(body);
 924→      return -1;
 925→    }
 926→  if (http_post_json("/chat/completions", body, TXT_ASR) != 0)
 927→    {
 928→      free(body);
 929→      return -1;
 930→    }
 931→  free(body);
 932→
 933→  root = voice_json_load(TXT_ASR, 256 * 1024);
 934→  if (!root)
 935→    {
 936→      return -1;
 937→    }
 938→  message = voice_first_message(root);
 939→  content = message ? cJSON_GetObjectItem(message, "content") : NULL;
 940→  if (content && cJSON_IsString(content) && content->valuestring)
 941→    {
 942→      snprintf(text, (size_t)cap, "%s", content->valuestring);
 943→    }
 944→  cJSON_Delete(root);
 945→  return text[0] ? 0 : -1;
 946→}
