1006→static int tts_synth(const char *text, const char *wav_path,
1007→                     const char *voice_id)
1008→{
1009→  char esc[400];
1010→  char voice_esc[64];
1011→  char body[1000];
1012→  unsigned char *raw = NULL;
1013→  FILE *f = NULL;
1014→  long sz;
1015→  int n;
1016→  int rawlen;
1017→  int write_ok;
1018→  int close_rc;
1019→  int rc = -1;
1020→  cJSON *root = NULL;
1021→  cJSON *message;
1022→  cJSON *audio;
1023→  cJSON *data;
1024→
1025→  if (!text || !text[0] || !wav_path || !voice_id || !voice_id[0])
1026→    {
1027→      return -1;
1028→    }
1029→  if (json_escape(text, esc, sizeof(esc)) < 0 ||
1030→      json_escape(voice_id, voice_esc, sizeof(voice_esc)) < 0)
1031→    {
1032→      return -1;
1033→    }
1034→  n = snprintf(body, sizeof(body),
1035→               "{\"model\":\"%s\",\"messages\":["
1036→               "{\"role\":\"user\",\"content\":\"请使用指定音色，以自然清晰的语气朗读。\"},"
1037→               "{\"role\":\"assistant\",\"content\":\"%s\"}],"
1038→               "\"audio\":{\"format\":\"wav\",\"voice\":\"%s\"}}",
1039→               TTS_MODEL, esc, voice_esc);
1040→  if (n <= 0 || n >= (int)sizeof(body))
1041→    {
1042→      return -1;
1043→    }
1044→  if (http_post_json("/chat/completions", body, TXT_CHAT) != 0)
1045→    {
1046→      return -1;
1047→    }
1048→
1049→  root = voice_json_load(TXT_CHAT, 4 * 1024 * 1024);
1050→  if (!root)
1051→    {
1052→      goto out;
1053→    }
1054→  message = voice_first_message(root);
1055→  audio = message ? cJSON_GetObjectItem(message, "audio") : NULL;
1056→  data = audio ? cJSON_GetObjectItem(audio, "data") : NULL;
1057→  if (!data || !cJSON_IsString(data) || !data->valuestring)
1058→    {
1059→      goto out;
1060→    }
1061→
1062→  sz = (long)strlen(data->valuestring);
1063→  if (sz <= 0 || sz > 4 * 1024 * 1024)
1064→    {
1065→      goto out;
1066→    }
1067→  raw = malloc((size_t)sz);
1068→  if (!raw)
1069→    {
1070→      goto out;
1071→    }
1072→  rawlen = b64_decode(data->valuestring, raw, (size_t)sz);
1073→  if (rawlen < 44 || memcmp(raw, "RIFF", 4) != 0 ||
1074→      memcmp(raw + 8, "WAVE", 4) != 0)
1075→    {
1076→      goto out;
1077→    }
1078→
1079→  f = fopen(wav_path, "wb");
1080→  if (!f)
1081→    {
1082→      goto out;
1083→    }
1084→  write_ok = fwrite(raw, 1, (size_t)rawlen, f) == (size_t)rawlen;
1085→  close_rc = fclose(f);
1086→  f = NULL;
1087→  if (write_ok && close_rc == 0)
1088→    {
1089→      rc = 0;
1090→    }
1091→
1092→out:
1093→  if (f)
1094→    {
1095→      fclose(f);
1096→    }
1097→  free(raw);
1098→  if (root)
1099→    {
1100→      cJSON_Delete(root);
1101→    }
1102→  if (rc != 0)
1103→    {
1104→      unlink(wav_path);
1105→      if (s_last_failure == DM_VOICE_FAILURE_NONE)
1106→        {
1107→          s_last_failure = DM_VOICE_FAILURE_TTS;
1108→        }
1109→    }
1110→  return rc;
1111→}
