1113→static int voice_asr_chat_tts_unlocked(const char *wav_path, char *reply,
1114→                                       int cap)
1115→{
1116→  char text[256];
1117→  const char *asr_path;
1118→  int play_rc = -1;
1119→
1120→  if (!wav_path || !reply || cap < 8)
1121→    {
1122→      return -1;
1123→    }
1124→  s_last_failure = DM_VOICE_FAILURE_NONE;
1125→  reply[0] = '\0';
1126→
1127→  if (voice_prepare_wav(wav_path, &asr_path) != 0)
1128→    {
1129→      s_last_failure = DM_VOICE_FAILURE_ASR;
1130→      s_st = DM_VOICE_ERR;
1131→      return -1;
1132→    }
1133→
1134→  s_st = DM_VOICE_ASR;
1135→  if (asr_wav(asr_path, text, sizeof(text)) != 0)
1136→    {
1137→      if (s_last_failure == DM_VOICE_FAILURE_NONE)
1138→        {
1139→          s_last_failure = DM_VOICE_FAILURE_ASR;
1140→        }
1141→      s_st = DM_VOICE_ERR;
1142→      return -1;
1143→    }
1144→
1145→  s_st = DM_VOICE_CHAT;
1146→  if (chat_reply(text, reply, cap) != 0)
1147→    {
1148→      if (s_last_failure == DM_VOICE_FAILURE_NONE)
1149→        {
1150→          s_last_failure = DM_VOICE_FAILURE_CHAT;
1151→        }
1152→      strncpy(reply, "（网络忙，没听清）", (size_t)cap - 1);
1153→      reply[cap - 1] = '\0';
1154→      s_st = DM_VOICE_ERR;
1155→      return -1;
1156→    }
1157→
1158→  /* Preserve the text answer even if playback fails; the caller can show
1159→   * that the reply is text-only rather than pretending the speaker worked. */
1160→  s_st = DM_VOICE_TTS;
1161→  if (tts_synth(reply, WAV_TTS, dm_voice_profile_api_id()) == 0)
1162→    {
1163→      s_st = DM_VOICE_PLAY;
1164→      play_rc = play_wav(WAV_TTS);
1165→    }
1166→  else if (s_last_failure == DM_VOICE_FAILURE_NONE)
1167→    {
1168→      s_last_failure = DM_VOICE_FAILURE_TTS;
1169→    }
1170→  s_st = DM_VOICE_IDLE;
1171→  return play_rc == 0 ? 0 : 1;
1172→}
