333→static void extract_content(const char *path, char *out, size_t cap)
334→{
335→  FILE *f;
336→  char *buf;
337→  long sz;
338→  cJSON *root;
339→  cJSON *choices;
340→  cJSON *choice;
341→  cJSON *message;
342→  cJSON *content;
343→
344→  if (!out || cap < 2)
345→    {
346→      return;
347→    }
348→  out[0] = '\0';
349→  f = fopen(path, "rb");
350→  if (!f)
351→    {
352→      return;
353→    }
354→  if (fseek(f, 0, SEEK_END) != 0 || (sz = ftell(f)) <= 0 ||
355→      sz > 64 * 1024 || fseek(f, 0, SEEK_SET) != 0)
356→    {
357→      fclose(f);
358→      return;
359→    }
360→  buf = malloc((size_t)sz + 1);
361→  if (!buf)
362→    {
363→      fclose(f);
364→      return;
365→    }
366→  if (fread(buf, 1, (size_t)sz, f) != (size_t)sz)
367→    {
368→      free(buf);
369→      fclose(f);
370→      return;
371→    }
372→  buf[sz] = '\0';
373→  fclose(f);
374→
375→  root = cJSON_Parse(buf);
376→  free(buf);
377→  if (!root)
378→    {
379→      return;
380→    }
381→  choices = cJSON_GetObjectItem(root, "choices");
382→  choice = choices && cJSON_IsArray(choices)
383→             ? cJSON_GetArrayItem(choices, 0) : NULL;
384→  message = choice ? cJSON_GetObjectItem(choice, "message") : NULL;
385→  content = message ? cJSON_GetObjectItem(message, "content") : NULL;
386→  if (content && cJSON_IsString(content) && content->valuestring)
387→    {
388→      snprintf(out, cap, "%s", content->valuestring);
389→    }
390→  cJSON_Delete(root);
391→}
