 991→/****************************************************************************
 992→ * Name: nxrecorder_stop
 993→ *
 994→ *   nxrecorder_stop() stops the current recordback and closes the file and
 995→ *   the associated device.
 996→ *
 997→ * Input:
 998→ *   precorder    Pointer to the initialized MRecorder context
 999→ *
1000→ ****************************************************************************/
1001→
1002→#ifndef CONFIG_AUDIO_EXCLUDE_STOP
1003→int nxrecorder_stop(FAR struct nxrecorder_s *precorder)
1004→{
1005→  struct audio_msg_s term_msg;
1006→
1007→  DEBUGASSERT(precorder != NULL);
1008→
1009→  /* Validate we are not in IDLE state */
1010→
1011→  pthread_mutex_lock(&precorder->mutex);
1012→  if (precorder->state == NXRECORDER_STATE_IDLE)
1013→    {
1014→      pthread_mutex_unlock(&precorder->mutex);
1015→      return OK;
1016→    }
1017→
1018→  pthread_mutex_unlock(&precorder->mutex);
1019→
1020→  /* Notify the recordback thread that it needs to cancel the recordback */
1021→
1022→  term_msg.msg_id = AUDIO_MSG_STOP;
1023→  term_msg.u.data = 0;
1024→  mq_send(precorder->mq, (FAR const char *)&term_msg, sizeof(term_msg),
1025→          CONFIG_NXRECORDER_MSG_PRIO);
1026→
1027→  /* Join the thread.  The thread will do all the cleanup. */
1028→
1029→  nxrecorder_jointhread(precorder);
1030→
1031→  return OK;
1032→}
