1221→static int voice_asr_chat_tts_unlocked(const char *wav_path, char *reply,
1222→                                       int cap)
1223→{
1224→  char text[256];
1225→  const char *asr_path;
1226→  int play_rc = -1;
1227→
1228→  if (!wav_path || !reply || cap < 8)
1229→    {
1230→      return -1;
1231→    }
1232→  s_last_failure = DM_VOICE_FAILURE_NONE;
1233→  reply[0] = '\0';
1234→
1235→  if (voice_prepare_wav(wav_path, &asr_path) != 0)
1236→    {
1237→      s_last_failure = DM_VOICE_FAILURE_ASR;
1238→      s_st = DM_VOICE_ERR;
1239→      return -1;
1240→    }
1241→
1242→  s_st = DM_VOICE_ASR;
1243→  if (asr_wav(asr_path, text, sizeof(text)) != 0)
1244→    {
1245→      if (s_last_failure == DM_VOICE_FAILURE_NONE)
1246→        {
1247→          s_last_failure = DM_VOICE_FAILURE_ASR;
1248→        }
1249→      s_st = DM_VOICE_ERR;
1250→      return -1;
1251→    }
1252→
1253→  s_st = DM_VOICE_CHAT;
1254→  if (chat_reply(text, reply, cap) != 0)
1255→    {
1256→      if (s_last_failure == DM_VOICE_FAILURE_NONE)
1257→        {
1258→          s_last_failure = DM_VOICE_FAILURE_CHAT;
1259→        }
1260→      strncpy(reply, "（网络忙，没听清）", (size_t)cap - 1);
1261→      reply[cap - 1] = '\0';
1262→      s_st = DM_VOICE_ERR;
1263→      return -1;
1264→    }
1265→
1266→  /* Preserve the text answer even if playback fails; the caller can show
1267→   * that the reply is text-only rather than pretending the speaker worked. */
1268→  s_st = DM_VOICE_TTS;
1269→  if (tts_synth(reply, WAV_TTS, dm_voice_profile_api_id()) == 0)
1270→    {
1271→      s_st = DM_VOICE_PLAY;
1272→      play_rc = play_wav(WAV_TTS);
1273→    }
1274→  else if (s_last_failure == DM_VOICE_FAILURE_NONE)
1275→    {
1276→      s_last_failure = DM_VOICE_FAILURE_TTS;
1277→    }
1278→  s_st = DM_VOICE_IDLE;
1279→  return play_rc == 0 ? 0 : 1;
