 383→/* Play one short 440Hz test tone.  This is synchronous by design; callers
 384→ * run it on a worker so neither LVGL nor the recorder UI can block. */
 385→int dm_voice_beep(void)
 386→{
 387→  struct nxplayer_s *p = NULL;
 388→  int rc = -1;
 389→
 390→  if (pthread_mutex_trylock(&s_audio_lock) != 0)
 391→    {
 392→      return -EBUSY;
 393→    }
 394→  if (s_rec_active)
 395→    {
 396→      pthread_mutex_unlock(&s_audio_lock);
 397→      return -EBUSY;
 398→    }
 399→
 400→  p = nxplayer_create();
 401→  if (!p || nxplayer_setdevice(p, "/dev/audio/pcm0p") != OK)
 402→    {
 403→      goto out;
 404→    }
 405→
 406→  if (nxplayer_playtone(p, 16000, 440, 1) != OK)
 407→    {
 408→      goto out;
 409→    }
 410→
 411→  /* Tone playback is asynchronous; wait slightly beyond its duration and
 412→   * join it before allowing the next audio operation. */
 413→  usleep(1150 * 1000);
 414→  (void)nxplayer_stop(p);
 415→  rc = 0;
 416→
 417→out:
 418→  if (p)
 419→    {
 420→      nxplayer_release(p);
 421→    }
 422→  pthread_mutex_unlock(&s_audio_lock);
 423→  return rc;
 424→}
