 442→static int json_escape(const char *in, char *out, size_t cap)
 443→{
 444→  size_t o = 0;
 445→  size_t i;
 446→
 447→  if (!in || !out || cap < 2)
 448→    {
 449→      if (out && cap)
 450→        {
 451→          out[0] = '\0';
 452→        }
 453→      return -1;
 454→    }
 455→
 456→  for (i = 0; in[i]; i++)
 457→    {
 458→      unsigned char ch = (unsigned char)in[i];
 459→      size_t need = (ch == '"' || ch == '\\' || ch == '\n') ? 2 :
 460→                    (ch >= 0x20 ? 1 : 0);
 461→
 462→      if (o + need >= cap)
 463→        {
 464→          out[o] = '\0';
 465→          return -1;
 466→        }
 467→      if (ch == '"' || ch == '\\')
 468→        {
 469→          out[o++] = '\\';
 470→          out[o++] = (char)ch;
 471→        }
 472→      else if (ch == '\n')
 473→        {
 474→          out[o++] = '\\';
 475→          out[o++] = 'n';
 476→        }
 477→      else if (ch >= 0x20)
 478→        {
 479→          out[o++] = (char)ch;
 480→        }
 481→    }
 482→  out[o] = '\0';
 483→  return (int)o;
 484→}
