 486→/* Load and validate the key supplied at runtime. Never log or compile it. */
 487→static int voice_key_load(char *key, size_t key_cap)
 488→{
 489→  FILE *f;
 490→  size_t i;
 491→  size_t n;
 492→  int valid = 0;
 493→
 494→  if (!key || key_cap < 16)
 495→    {
 496→      return 0;
 497→    }
 498→  key[0] = '\0';
 499→  f = fopen(MIMO_KEY_PATH, "rb");
 500→  if (!f)
 501→    {
 502→      snprintf(key, key_cap, "%s", MIMO_EMBEDDED_KEY);
 503→      return key[0] != '\0';
 504→    }
 505→
 506→  if (fgets(key, (int)key_cap, f))
 507→    {
 508→      n = strlen(key);
 509→      while (n > 0 && (key[n - 1] == '\r' || key[n - 1] == '\n' ||
 510→                       key[n - 1] == ' ' || key[n - 1] == '\t'))
 511→        {
 512→          key[--n] = '\0';
 513→        }
 514→      valid = n > 8 && n < key_cap - 1;
 515→      for (i = 0; valid && i < n; i++)
 516→        {
 517→          unsigned char ch = (unsigned char)key[i];
 518→          if (!((ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') ||
 519→                (ch >= '0' && ch <= '9') || ch == '-' || ch == '_' ||
 520→                ch == '.'))
 521→            {
 522→              valid = 0;
 523→            }
 524→        }
 525→    }
 526→
 527→  fclose(f);
 528→  if (!valid)
 529→    {
 530→      memset(key, 0, key_cap);
 531→      snprintf(key, key_cap, "%s", MIMO_EMBEDDED_KEY);
 532→      valid = key[0] != '\0';
 533→    }
 534→  return valid;
 535→}
