 844→
 845→/* nxrecorder's AUDIO_FMT_PCM encoder writes headerless PCM even when the
 846→ * filename ends in .wav.  Wrap that payload in a standards-compliant WAV
 847→ * header before sending `format: wav` to the MiMo chat-completions ASR API. */
 848→static int voice_prepare_wav(const char *src, const char **wav_out)
 849→{
 850→  FILE *in;
 851→  FILE *out;
 852→  uint8_t header[44];
 853→  char buf[1024];
 854→  long size;
 855→  size_t n;
 856→  uint32_t data_size;
 857→  unsigned int byte_rate = REC_RATE * REC_CH * REC_BITS / 8;
 858→  int rc = -1;
 859→
 860→  if (!src || !wav_out)
 861→    {
 862→      return -1;
 863→    }
 864→
 865→  *wav_out = src;
 866→  in = fopen(src, "rb");
 867→  if (!in)
 868→    {
 869→      return -1;
 870→    }
 871→
 872→  if (fread(header, 1, 12, in) == 12 &&
 873→      memcmp(header, "RIFF", 4) == 0 && memcmp(header + 8, "WAVE", 4) == 0)
 874→    {
 875→      fclose(in);
 876→      return 0;
 877→    }
 878→
 879→  if (fseek(in, 0, SEEK_END) != 0 || (size = ftell(in)) <= 0 ||
 880→      size > 2 * 1024 * 1024 - 44 || fseek(in, 0, SEEK_SET) != 0)
 881→    {
 882→      fclose(in);
 883→      return -1;
 884→    }
 885→
 886→  data_size = (uint32_t)size;
 887→  memset(header, 0, sizeof(header));
 888→  memcpy(header, "RIFF", 4);
 889→  put_le32(header + 4, data_size + 36);
 890→  memcpy(header + 8, "WAVEfmt ", 8);
 891→  put_le32(header + 16, 16);
 892→  put_le16(header + 20, 1);
 893→  put_le16(header + 22, REC_CH);
 894→  put_le32(header + 24, REC_RATE);
 895→  put_le32(header + 28, byte_rate);
 896→  put_le16(header + 32, REC_CH * REC_BITS / 8);
 897→  put_le16(header + 34, REC_BITS);
 898→  memcpy(header + 36, "data", 4);
 899→  put_le32(header + 40, data_size);
 900→
 901→  out = fopen(WAV_ASR, "wb");
 902→  if (!out)
 903→    {
 904→      fclose(in);
 905→      return -1;
 906→    }
 907→
 908→  if (fwrite(header, 1, sizeof(header), out) == sizeof(header))
 909→    {
 910→      rc = 0;
 911→      while ((n = fread(buf, 1, sizeof(buf), in)) > 0)
 912→        {
 913→          if (fwrite(buf, 1, n, out) != n)
 914→            {
 915→              rc = -1;
 916→              break;
 917→            }
 918→        }
 919→      if (ferror(in))
 920→        {
 921→          rc = -1;
 922→        }
 923→    }
 924→
 925→  if (fclose(out) != 0)
 926→    {
 927→      rc = -1;
 928→    }
 929→  fclose(in);
 930→  if (rc == 0)
 931→    {
 932→      *wav_out = WAV_ASR;
 933→    }
 934→  else
 935→    {
 936→      unlink(WAV_ASR);
 937→    }
 938→  return rc;
 939→}
