 941→static int asr_wav(const char *wav, char *text, int cap)
 942→{
 943→  FILE *f;
 944→  unsigned char *raw;
 945→  char *b64;
 946→  char *body;
 947→  size_t body_cap;
 948→  long sz;
 949→  int n;
 950→  cJSON *root;
 951→  cJSON *message;
 952→  cJSON *content;
 953→
 954→  if (!wav || !text || cap < 2)
 955→    {
 956→      return -1;
 957→    }
 958→  text[0] = '\0';
 959→  f = fopen(wav, "rb");
 960→  if (!f)
 961→    {
 962→      return -1;
 963→    }
 964→  if (fseek(f, 0, SEEK_END) != 0 || (sz = ftell(f)) <= 44 ||
 965→      sz > 2 * 1024 * 1024 || fseek(f, 0, SEEK_SET) != 0)
 966→    {
 967→      fclose(f);
 968→      syslog(LOG_ERR, "[dm-voice] ASR WAV size/seek invalid\n");
 969→      return -1;
 970→    }
 971→  syslog(LOG_INFO, "[dm-voice] ASR WAV bytes=%ld\n", sz);
 972→  raw = malloc((size_t)sz);
 973→  b64 = malloc((size_t)sz * 2 + 8);
 974→  body_cap = (size_t)sz * 2 + 512;
 975→  body = malloc(body_cap);
 976→  if (!raw || !b64 || !body)
 977→    {
 978→      free(raw);
 979→      free(b64);
 980→      free(body);
 981→      fclose(f);
 982→      return -1;
 983→    }
 984→  if (fread(raw, 1, (size_t)sz, f) != (size_t)sz)
 985→    {
 986→      free(raw);
 987→      free(b64);
 988→      free(body);
 989→      fclose(f);
 990→      return -1;
 991→    }
 992→  fclose(f);
 993→  if (b64_encode(raw, (size_t)sz, b64, (size_t)sz * 2 + 8) <= 0)
 994→    {
 995→      free(raw);
 996→      free(b64);
 997→      free(body);
 998→      return -1;
 999→    }
1000→  free(raw);
1001→
1002→  /* Official MiMo ASR schema: data URL + one input_audio content part. */
1003→  n = snprintf(body, body_cap,
1004→               "{\"model\":\"%s\",\"messages\":[{\"role\":\"user\",\"content\":"
1005→               "[{\"type\":\"input_audio\",\"input_audio\":{\"data\":"
1006→               "\"data:audio/wav;base64,%s\"}}]}],"
1007→               "\"asr_options\":{\"language\":\"auto\"}}",
1008→               ASR_MODEL, b64);
1009→  free(b64);
1010→  if (n <= 0 || (size_t)n >= body_cap)
1011→    {
1012→      free(body);
1013→      return -1;
1014→    }
1015→  syslog(LOG_INFO, "[dm-voice] ASR request start\n");
1016→  if (http_post_json("/chat/completions", body, TXT_ASR) != 0)
1017→    {
1018→      free(body);
1019→      syslog(LOG_ERR, "[dm-voice] ASR HTTP request failed\n");
1020→      return -1;
1021→    }
1022→  free(body);
1023→
1024→  root = voice_json_load(TXT_ASR, 256 * 1024);
1025→  if (!root)
1026→    {
1027→      syslog(LOG_ERR, "[dm-voice] ASR response is not valid JSON\n");
1028→      return -1;
1029→    }
1030→  message = voice_first_message(root);
1031→  content = message ? cJSON_GetObjectItem(message, "content") : NULL;
1032→  if (content && cJSON_IsString(content) && content->valuestring)
1033→    {
1034→      snprintf(text, (size_t)cap, "%s", content->valuestring);
1035→    }
1036→  cJSON_Delete(root);
1037→  if (!text[0])
1038→    {
1039→      syslog(LOG_ERR,
1040→             "[dm-voice] ASR response has no choices[0].message.content text\n");
1041→      return -1;
1042→    }
1043→  syslog(LOG_INFO, "[dm-voice] ASR success text_bytes=%u\n",
1044→         (unsigned int)strlen(text));
1045→  return 0;
1046→}
