1224→static int voice_asr_chat_tts_unlocked(const char *wav_path, char *reply,
1225→                                       int cap)
1226→{
1227→  char text[256];
1228→  const char *asr_path;
1229→  int play_rc = -1;
1230→
1231→  if (!wav_path || !reply || cap < 8)
1232→    {
1233→      return -1;
1234→    }
1235→  s_last_failure = DM_VOICE_FAILURE_NONE;
1236→  reply[0] = '\0';
1237→
1238→  if (voice_prepare_wav(wav_path, &asr_path) != 0)
1239→    {
1240→      s_last_failure = DM_VOICE_FAILURE_ASR;
1241→      s_st = DM_VOICE_ERR;
1242→      return -1;
1243→    }
1244→
1245→  s_st = DM_VOICE_ASR;
1246→  if (asr_wav(asr_path, text, sizeof(text)) != 0)
1247→    {
1248→      if (s_last_failure == DM_VOICE_FAILURE_NONE)
1249→        {
1250→          s_last_failure = DM_VOICE_FAILURE_ASR;
1251→        }
1252→      s_st = DM_VOICE_ERR;
1253→      return -1;
1254→    }
1255→
1256→  s_st = DM_VOICE_CHAT;
1257→  if (chat_reply(text, reply, cap) != 0)
1258→    {
1259→      if (s_last_failure == DM_VOICE_FAILURE_NONE)
1260→        {
1261→          s_last_failure = DM_VOICE_FAILURE_CHAT;
1262→        }
1263→      strncpy(reply, "（网络忙，没听清）", (size_t)cap - 1);
1264→      reply[cap - 1] = '\0';
1265→      s_st = DM_VOICE_ERR;
1266→      return -1;
1267→    }
1268→
1269→  /* Preserve the text answer even if playback fails; the caller can show
1270→   * that the reply is text-only rather than pretending the speaker worked. */
1271→  s_st = DM_VOICE_TTS;
1272→  if (tts_synth(reply, WAV_TTS, dm_voice_profile_api_id()) == 0)
1273→    {
1274→      s_st = DM_VOICE_PLAY;
1275→      play_rc = play_wav(WAV_TTS);
1276→    }
1277→  else if (s_last_failure == DM_VOICE_FAILURE_NONE)
1278→    {
1279→      s_last_failure = DM_VOICE_FAILURE_TTS;
1280→    }
1281→  s_st = DM_VOICE_IDLE;
1282→  return play_rc == 0 ? 0 : 1;
1283→}
