1496→/* Play local alert files away from the LVGL timer thread. */
1497→struct voice_file_job_s
1498→{
1499→  char path[128];
1500→};
1501→
1502→static void *play_file_worker(void *arg)
1503→{
1504→  struct voice_file_job_s *job = arg;
1505→  char path[sizeof(job->path)];
1506→
1507→  snprintf(path, sizeof(path), "%s", job->path);
1508→  free(job);
1509→  (void)play_wav(path);
1510→  return NULL;
1511→}
1512→
1513→int dm_voice_play_file(const char *wav_path)
1514→{
1515→  struct voice_file_job_s *job;
1516→  pthread_t th;
1517→  pthread_attr_t attr;
1518→  int ret;
1519→
1520→  if (!wav_path || !wav_path[0])
1521→    {
1522→      return -1;
1523→    }
1524→
1525→  job = malloc(sizeof(*job));
1526→  if (!job)
1527→    {
1528→      return -1;
1529→    }
1530→  snprintf(job->path, sizeof(job->path), "%s", wav_path);
1531→
1532→  pthread_attr_init(&attr);
1533→  pthread_attr_setstacksize(&attr, 16384);
1534→  ret = pthread_create(&th, &attr, play_file_worker, job);
1535→  pthread_attr_destroy(&attr);
1536→  if (ret != 0)
1537→    {
1538→      free(job);
1539→      return -1;
1540→    }
1541→
1542→  pthread_detach(th);
1543→  return 0;
1544→}
