  1→/*
  2→ * dm_audio_vol.c — volume control for 4R 3W speaker
  3→ * Uses NuttX audio FEATURE/VOLUME ioctl (see nxplayer_setvolume),
  4→ * value range 0..1000 on device, 0..100% in UI.
  5→ * Persist to /data/deskmate_vol.txt
  6→ */
  7→
  8→#include "deskmate.h"
  9→#include "dm_audio_vol.h"
 10→
 11→#ifdef CONFIG_DESKMATE_APP
 12→
 13→#include <stdio.h>
 14→#include <string.h>
 15→#include <unistd.h>
 16→#include <fcntl.h>
 17→#include <errno.h>
 18→#include <syslog.h>
 19→#include <sys/ioctl.h>
 20→#include <nuttx/audio/audio.h>
 21→#include <aw-alsa-lib/control.h>
 22→#include "dm_voice.h"
 23→
 24→#define VOL_PATH "/data/deskmate_vol.txt"
 25→#define VOL_DEFAULT 80
 26→#define CODEC_CARD "audiocodec"
 27→#define DAC_VOL_MAX 160
 28→
 29→static int s_vol = VOL_DEFAULT;
 30→static int s_mute;
 31→
 32→/* Perceptual slider mapping: lift the quiet half of the range, while
 33→ * reserving headroom at the top to avoid the previous full-scale loudness. */
 34→static unsigned int vol_percent_to_reg(int percent)
 35→{
 36→  static const struct
 37→  {
 38→    unsigned char percent;
 39→    unsigned char reg;
 40→  } points[] =
 41→  {
 42→    { 0,   0 },
 43→    { 10, 48 },
 44→    { 25, 88 },
 45→    { 50, 124 },
 46→    { 75, 148 },
 47→    { 100, DAC_VOL_MAX }
 48→  };
 49→  unsigned int i;
 50→
 51→  if (percent <= 0)
 52→    {
 53→      return 0;
 54→    }
 55→  if (percent >= 100)
 56→    {
 57→      return DAC_VOL_MAX;
 58→    }
 59→
 60→  for (i = 1; i < sizeof(points) / sizeof(points[0]); i++)
 61→    {
 62→      if (percent <= points[i].percent)
 63→        {
 64→          unsigned int span = points[i].percent - points[i - 1].percent;
 65→          unsigned int value_span = points[i].reg - points[i - 1].reg;
 66→          unsigned int offset = (unsigned int)percent - points[i - 1].percent;
 67→          return points[i - 1].reg + (value_span * offset + span / 2) / span;
 68→        }
 69→    }
 70→
 71→  return DAC_VOL_MAX;
 72→}
 73→
 74→static void vol_save(void)
 75→{
 76→  FILE *f = fopen(VOL_PATH, "w");
 77→  if (!f)
 78→    {
 79→      return;
 80→    }
 81→  fprintf(f, "%d %d\n", s_vol, s_mute);
 82→  fclose(f);
 83→}
 84→
 85→void dm_vol_init(void)
 86→{
 87→  FILE *f = fopen(VOL_PATH, "r");
 88→  int v = VOL_DEFAULT;
 89→  int m = 0;
 90→
 91→  if (f)
 92→    {
 93→      if (fscanf(f, "%d %d", &v, &m) >= 1)
 94→        {
 95→          if (v < 0)
 96→            {
 97→              v = 0;
 98→            }
 99→          if (v > 100)
100→            {
101→              v = 100;
102→            }
103→          s_vol = v;
104→          s_mute = m ? 1 : 0;
105→        }
106→      fclose(f);
107→    }
108→  dm_vol_apply();
109→}
110→
111→int dm_vol_get(void)
112→{
113→  return s_vol;
114→}
115→
116→int dm_vol_is_mute(void)
117→{
118→  return s_mute;
119→}
120→
121→int dm_vol_set_mute(int on)
122→{
123→  s_mute = on ? 1 : 0;
124→  dm_vol_apply();
125→  vol_save();
126→  return s_mute;
127→}
128→
129→void dm_vol_apply(void)
130→{
131→  unsigned int reg;
132→  int r1, r2;
133→
134→  /* CONFIG_AUDIO_EXCLUDE_VOLUME=y strips the AUDIO_FU_VOLUME ioctl path,
135→     so drive DACL/R digital volume through aw-alsa-lib controls instead. */
136→
137→  reg = s_mute ? 0 : vol_percent_to_reg(s_vol);
138→  r1 = snd_ctl_set(CODEC_CARD, "DACL digital volume", reg);
139→  r2 = snd_ctl_set(CODEC_CARD, "DACR digital volume", reg);
140→  syslog(LOG_INFO, "[dm-vol] dac vol reg=%u (dACL=%d dACR=%d)\n", reg, r1, r2);
141→
142→  /* also keep TTS helper in sync (percent, 0 when mute) */
143→  dm_voice_set_speaker_volume(s_mute ? 0 : s_vol);
144→}
145→
146→int dm_vol_set(int percent)
147→{
148→  if (percent < 0)
149→    {
150→      percent = 0;
151→    }
152→  if (percent > 100)
153→    {
154→      percent = 100;
155→    }
156→  s_vol = percent;
157→  if (s_vol > 0)
158→    {
159→      s_mute = 0;
160→    }
161→  dm_vol_apply();
162→  vol_save();
163→  return s_vol;
164→}
165→
166→/* Short 440Hz tone for offline proactive fallback. */
167→int dm_vol_test_beep(void)
168→{
169→  if (s_mute)
170→    {
171→      return -1;
172→    }
173→  return dm_voice_beep();
174→}
175→
176→/* Spoken sample for the Volume settings page. */
177→int dm_vol_test_sample(void)
178→{
179→  if (s_mute)
180→    {
181→      return -1;
182→    }
183→  return dm_voice_volume_test();
184→}
