 19→#define CHAT_LINE_MAX 96
 20→#define CHAT_FACE_SZ 76
 21→
 22→static lv_obj_t *s_ans;
 23→static lv_obj_t *s_sub;
 24→static lv_obj_t *s_ptt_btn;
 25→static volatile bool s_busy;
 26→static volatile bool s_ui_rec;
 27→static volatile int s_job;
 28→static volatile int s_rec_sec;
 29→static uint64_t s_rec_started_ms;
 30→static volatile int s_mic_err;
 31→static volatile int s_out_ready; /* 1=text 2=microphone error */
 32→
 33→static char s_pending[CHAT_LINE_MAX];
 34→static char s_last_ans[CHAT_LINE_MAX];
 35→static char s_out_ans[CHAT_LINE_MAX];
 36→static char s_out_sub[80];
