 56→  s_last_ans[sizeof(s_last_ans) - 1] = '\0';
 57→  if (s_ans)
 58→    {
 59→      lv_label_set_text(s_ans, s_last_ans[0] ? s_last_ans
 60→                                             : dm_t("点按钮开始说话",
 61→                                                    "Tap button to talk"));
 62→    }
 63→}
