 89→static void reset_to_idle(void)
 90→{
 91→  s_ui_rec = false;
 92→  s_rec_sec = 0;
 93→  s_rec_started_ms = 0;
 94→  s_busy = false;
 95→  s_job = 0;
 96→  set_ptt("开始说话", "Start talk", C_BTN);
 97→}
 98→
 99→/* worker thread — NO LVGL calls here */
100→static void *voice_worker(void *arg)
101→{
102→  char reply[CHAT_LINE_MAX];
103→  int voice_rc;
104→
105→  (void)arg;
106→
107→  if (s_job == 1)
108→    {
109→      /* nxrecorder_stop() joins its audio worker.  Never call it from the
110→       * LVGL click callback: a slow/failed PCM read must not freeze the UI. */
111→      if (dm_voice_rec_stop() != 0)
112→        {
113→          snprintf(s_out_ans, sizeof(s_out_ans), "%s",
114→                   dm_t("录音失败，未采集到有效音频",
115→                        "Recording failed; no audio captured"));
116→          snprintf(s_out_sub, sizeof(s_out_sub), "%s",
117→                   dm_t("检查麦克风和 /dev/audio/pcm0c",
118→                        "Check the microphone and /dev/audio/pcm0c"));
119→          s_out_ready = 1;
120→          return NULL;
121→        }
122→
123→      snprintf(s_out_sub, sizeof(s_out_sub), "%s",
124→               dm_t("ASR → 模型 → 喇叭播报", "ASR → LLM → speaker"));
125→      voice_rc = dm_voice_asr_chat_tts("/tmp/dm_voice_in.wav", reply,
126→                                       sizeof(reply));
127→      if (voice_rc >= 0)
128→        {
129→          snprintf(s_out_ans, sizeof(s_out_ans), "%s", reply);
130→          snprintf(s_out_sub, sizeof(s_out_sub), "%s",
131→                   voice_rc == 0
132→                     ? dm_t("已通过喇叭播放回复", "Reply played on speaker")
133→                     : dm_t("文字回复已显示，语音播报失败",
134→                            "Text reply shown; speech playback failed"));
135→          s_out_ready = 1;
136→        }
137→      else
138→        {
139→          /* Report the actual blocking condition instead of masking it as a
140→           * generic recognition failure. */
141→          switch (dm_voice_last_failure())
142→            {
143→              case DM_VOICE_FAILURE_TIME:
144→                snprintf(s_out_ans, sizeof(s_out_ans), "%s",
145→                         dm_t("设备时间尚未同步", "Device time is not synced"));
146→                snprintf(s_out_sub, sizeof(s_out_sub), "%s",
147→                         dm_t("网络时间就绪后再试，TLS证书校验未关闭",
148→                              "Retry after network time sync; TLS validation remains on"));
149→                break;
150→
151→              case DM_VOICE_FAILURE_API_KEY:
152→                snprintf(s_out_ans, sizeof(s_out_ans), "%s",
153→                         dm_t("MiMo API密钥未配置", "MiMo API key is not configured"));
154→                snprintf(s_out_sub, sizeof(s_out_sub), "%s",
155→                         dm_t("将新密钥保存到 /data/deskmate_mimo.key",
156→                              "Save a rotated key to /data/deskmate_mimo.key"));
157→                break;
158→
159→              case DM_VOICE_FAILURE_CHAT:
160→                snprintf(s_out_ans, sizeof(s_out_ans), "%s",
161→                         dm_t("语音对话请求失败", "Voice chat request failed"));
162→                snprintf(s_out_sub, sizeof(s_out_sub), "%s",
163→                         dm_t("检查网络/API状态，或点脸使用文字聊天",
164→                              "Check network/API status or tap the face for text chat"));
165→                break;
166→
167→              default:
168→                snprintf(s_out_ans, sizeof(s_out_ans), "%s",
169→                         dm_t("语音识别失败，请重试", "Speech recognition failed"));
170→                snprintf(s_out_sub, sizeof(s_out_sub), "%s",
171→                         dm_t("检查录音和麦克风，或点脸使用文字聊天",
172→                              "Check recording/mic or tap the face for text chat"));
173→                break;
174→            }
175→          s_out_ready = 1;
176→        }
177→    }
178→  else if (s_job == 2)
179→    {
180→      const char *r = dm_chat_ai_ask(s_pending);
181→      snprintf(s_out_ans, sizeof(s_out_ans), "%s", r ? r : "……");
182→      if (r && r[0] && dm_chat_ai_remote_ok())
183→        {
184→          if (dm_voice_tts_play(r) == 0)
185→            {
186→              snprintf(s_out_sub, sizeof(s_out_sub), "%s",
187→                       dm_t("已通过喇叭播放回复", "Reply played on speaker"));
188→            }
189→          else
190→            {
191→              snprintf(s_out_sub, sizeof(s_out_sub), "%s",
192→                       dm_t("文字回复已显示，语音播报失败",
193→                            "Text reply shown; speech playback failed"));
194→            }
195→        }
196→      else if (r && r[0])
197→        {
198→          snprintf(s_out_sub, sizeof(s_out_sub), "%s",
199→                   dm_t("云端连接失败，当前显示离线回复",
200→                        "Cloud unavailable; showing offline reply"));
201→        }
202→      else
203→        {
204→          s_out_sub[0] = '\0';
205→        }
206→      s_out_ready = 1;
207→    }
208→  return NULL;
209→}
210→
211→static void kick_job(int job)
212→{
213→  pthread_t th;
214→  pthread_attr_t attr;
215→
216→  if (s_busy)
217→    {
218→      return;
219→    }
220→  s_busy = true;
221→  s_job = job;
222→  s_ui_rec = false;
223→  s_rec_sec = 0;
224→  s_out_ready = 0;
225→  s_out_ans[0] = '\0';
226→  s_out_sub[0] = '\0';
227→
228→  dm_face_set(FACE_THINK, EYE_DECOR_NONE, 10);
229→  set_ans(job == 1 ? dm_t("识别中…", "Recognizing…")
230→                   : dm_t("思考中…", "Thinking…"));
231→  set_ptt("处理中…", "Working…", C_BTN_HI);
232→
233→  pthread_attr_init(&attr);
234→  pthread_attr_setstacksize(&attr, 24576);
235→  if (pthread_create(&th, &attr, voice_worker, NULL) == 0)
236→    {
237→      pthread_detach(th);
238→    }
239→  else
240→    {
241→      s_busy = false;
242→      if (job == 1 && dm_voice_rec_active())
243→        {
244→          /* Keep the recording controllable if worker creation failed. */
245→          s_ui_rec = true;
246→          set_ans(dm_t("正在录音，稍后再点结束",
247→                       "Recording; tap stop again"));
248→          set_ptt("结束并发送", "Stop & send", C_HEART);
249→        }
250→      else
251→        {
252→          set_ptt("开始说话", "Start talk", C_BTN);
253→        }
254→    }
255→  pthread_attr_destroy(&attr);
256→}
257→
258→static void face_click(lv_event_t *e)
259→{
260→  (void)e;
261→  if (s_busy || s_ui_rec)
262→    {
263→      return;
264→    }
265→  dm_face_set(FACE_HAPPY, EYE_DECOR_HEART, 8);
266→  strncpy(s_pending, dm_t("陪我聊聊天", "Chat with me"), sizeof(s_pending) - 1);
267→  s_pending[sizeof(s_pending) - 1] = '\0';
268→  kick_job(2);
269→}
270→
271→static void ptt_click(lv_event_t *e)
272→{
273→  int rec_rc;
274→
275→  (void)e;
276→
277→  if (s_busy)
278→    {
279→      return;
280→    }
281→
282→  if (!s_ui_rec)
283→    {
284→      s_mic_err = 0;
285→      dm_voice_set_speaker_volume(80);
286→      rec_rc = dm_voice_rec_start(6);
287→      if (rec_rc != 0)
288→        {
289→          if (rec_rc == -EBUSY)
290→            {
291→              set_ans(dm_t("喇叭正在播放，请稍后再录",
292→                           "Speaker is busy; try recording again"));
293→              set_sub(dm_t("等待音频播放结束", "Wait for audio to finish"));
294→            }
295→          else
296→            {
297→              set_ans(dm_t("麦克风不可用", "Mic unavailable"));
298→              set_sub(dm_t("检查 /dev/audio/pcm0c",
299→                           "Check /dev/audio/pcm0c"));
300→            }
301→          set_ptt("开始说话", "Start talk", C_BTN);
302→          return;
303→        }
304→      s_ui_rec = true;
305→      s_rec_sec = 0;
306→      s_rec_started_ms = chat_monotonic_ms();
307→      dm_face_set(FACE_THINK, EYE_DECOR_NONE, 10);
308→      set_ans(dm_t("● 录音中… 再点一下结束并发送",
309→                   "● Recording… tap again to send"));
310→      set_sub(dm_t("再点一下结束", "Tap again to stop"));
311→      set_ptt("结束并发送", "Stop & send", C_HEART);
312→    }
313→  else
314→    {
315→      s_ui_rec = false;
316→      s_rec_sec = 0;
317→      set_ptt("发送中…", "Sending…", C_BTN_HI);
318→      set_ans(dm_t("正在结束录音…", "Stopping mic…"));
319→
320→      if (s_mic_err)
321→        {
322→          set_ans(dm_t("麦克风故障，无法录音", "Mic failed"));
323→          set_sub(dm_t("检查 /dev/audio/pcm0c", "Check mic device"));
324→          reset_to_idle();
325→          return;
326→        }
327→
328→      /* Stop/join and network work run in voice_worker, not this LVGL event. */
329→      kick_job(1);
330→    }
331→}
