 84→  int rc;
 85→
 86→  if (!chat_key_load(key, sizeof(key)))
 87→    {
 88→      syslog(LOG_ERR, "[dm-chat] runtime API key missing or invalid\n");
 89→      return -1;
 90→    }
 91→
 92→  kf = fopen(MIMO_CURL_CONFIG, "w");
 93→  if (!kf || chmod(MIMO_CURL_CONFIG, S_IRUSR | S_IWUSR) != 0)
 94→    {
 95→      if (kf)
 96→        {
 97→          fclose(kf);
 98→        }
 99→      memset(key, 0, sizeof(key));
100→      unlink(MIMO_CURL_CONFIG);
101→      return -1;
102→    }
103→  key_write_ok = fprintf(kf, "header = \"Authorization: Bearer %s\"\n",
104→                         key) > 0;
105→  key_close_rc = fclose(kf);
106→  memset(key, 0, sizeof(key));
107→  if (!key_write_ok || key_close_rc != 0)
108→    {
109→      unlink(MIMO_CURL_CONFIG);
110→      return -1;
111→    }
112→
113→  sf = fopen(CHAT_CURL_SCRIPT, "w");
114→  if (!sf)
115→    {
116→      unlink(MIMO_CURL_CONFIG);
117→      syslog(LOG_ERR, "[dm-chat] cannot create curl script\n");
118→      return -1;
119→    }
120→  script_write_ok = fputs("#!/bin/sh\n", sf) != EOF &&
121→                    fputs(line, sf) != EOF && fputc('\n', sf) != EOF;
122→  script_close_rc = fclose(sf);
123→  if (!script_write_ok || script_close_rc != 0)
124→    {
125→      unlink(MIMO_CURL_CONFIG);
126→      syslog(LOG_ERR, "[dm-chat] cannot write curl script\n");
127→      return -1;
128→    }
129→
130→  rc = system("sh " CHAT_CURL_SCRIPT);
131→  unlink(MIMO_CURL_CONFIG);
132→  if (rc != 0)
133→    {
134→      syslog(LOG_ERR, "[dm-chat] curl script failed status=%d\n", rc);
135→      return -1;
136→    }
137→  return 0;
138→}
