150→/* ---------- 24 点 ---------- */
151→
152→typedef struct
153→{
154→  double v;
155→  char s[48];
156→} n24_t;
157→
158→static int s_n4[4];
159→static lv_obj_t *s_n4_lbl[4];
160→static lv_obj_t *s_n4_hint;
161→
162→static void n24_fmt(double v, char *out, size_t n)
163→{
164→  if (fabs(v - floor(v + 0.5)) < 1e-9 && fabs(v) < 1e9)
165→    {
166→      snprintf(out, n, "%d", (int)floor(v + 0.5));
167→    }
168→  else
169→    {
170→      snprintf(out, n, "%.4g", v);
171→    }
172→}
173→
174→static int n24_try(const n24_t *a, int n, char *out, size_t outn)
175→{
176→  int i;
177→  int j;
178→  int k;
179→  n24_t next[4];
180→  static const char ops[4] = { '+', '-', '*', '/' };
181→
182→  if (n == 1)
183→    {
184→      if (fabs(a[0].v - 24.0) < 1e-6)
185→        {
186→          snprintf(out, outn, "%s", a[0].s);
187→          return 1;
188→        }
189→      return 0;
190→    }
191→
192→  for (i = 0; i < n; i++)
193→    {
194→      for (j = 0; j < n; j++)
195→        {
196→          if (i == j)
197→            {
198→              continue;
199→            }
200→          for (k = 0; k < 4; k++)
201→            {
202→              double r;
203→              int m = 0;
204→              int p;
205→              char tmp[48];
206→
207→              if (ops[k] == '+')
208→                {
209→                  r = a[i].v + a[j].v;
210→                }
211→              else if (ops[k] == '-')
212→                {
213→                  r = a[i].v - a[j].v;
214→                }
215→              else if (ops[k] == '*')
216→                {
217→                  r = a[i].v * a[j].v;
218→                }
219→              else
220→                {
221→                  if (fabs(a[j].v) < 1e-9)
222→                    {
223→                      continue;
224→                    }
225→                  r = a[i].v / a[j].v;
226→                }
227→              snprintf(tmp, sizeof(tmp), "(%s%c%s)", a[i].s, ops[k],
228→                       a[j].s);
229→              for (p = 0; p < n; p++)
230→                {
231→                  if (p != i && p != j)
232→                    {
233→                      next[m++] = a[p];
234→                    }
235→                }
236→              n24_fmt(r, next[m].s, sizeof(next[m].s));
237→              /* keep expression not just number for leaf display */
238→              snprintf(next[m].s, sizeof(next[m].s), "%s", tmp);
239→              next[m].v = r;
240→              if (n24_try(next, m + 1, out, outn))
241→                {
242→                  return 1;
243→                }
244→            }
245→        }
246→    }
247→  return 0;
248→}
249→
250→static void n24_deal(void)
251→{
252→  char buf[8];
253→  int i;
254→  for (i = 0; i < 4; i++)
255→    {
256→      s_n4[i] = 1 + (int)(rand() % 13);
257→      snprintf(buf, sizeof(buf), "%d", s_n4[i]);
258→      if (s_n4_lbl[i])
259→        {
260→          lv_label_set_text(s_n4_lbl[i], buf);
261→        }
262→    }
263→  if (s_n4_hint)
264→    {
265→      lv_label_set_text(s_n4_hint, "用 + − × ÷ 把四个数凑成 24");
266→    }
267→}
268→
269→static void n24_next_cb(lv_event_t *e)
270→{
271→  (void)e;
272→  n24_deal();
273→}
274→
275→static void n24_hint_cb(lv_event_t *e)
276→{
277→  n24_t a[4];
278→  char out[96];
279→  int i;
280→  (void)e;
281→
282→  for (i = 0; i < 4; i++)
283→    {
284→      a[i].v = (double)s_n4[i];
285→      snprintf(a[i].s, sizeof(a[i].s), "%d", s_n4[i]);
286→    }
287→  out[0] = 0;
288→  if (n24_try(a, 4, out, sizeof(out)))
289→    {
290→      if (s_n4_hint)
291→        {
292→          lv_label_set_text(s_n4_hint, out);
293→        }
294→    }
295→  else if (s_n4_hint)
296→    {
297→      lv_label_set_text(s_n4_hint, "这组无解，下一局吧");
298→    }
299→}
