251→ * playback and recording setup/teardown so the app never starts a new stream
252→ * while an earlier stream is still releasing its buffers. */
253→
254→/* nxplayer treats .wav as raw PCM and never reads the WAV header
255→ * (its PCM ops->pre_parse is NULL), so the fmt chunk is parsed here and
256→ * the payload is fed via nxplayer_playraw() with explicit parameters. */
257→static int play_wav(const char *path)
258→{
259→  const char *src = (path && path[0]) ? path : WAV_TTS;
260→  struct nxplayer_s *p = NULL;
261→  FILE *f = NULL;
262→  FILE *o = NULL;
263→  uint8_t hdr[44];
264→  char buf[1024];
265→  size_t n;
266→  size_t raw_len = 0;
267→  uint32_t rate;
268→  uint16_t ch;
269→  uint16_t bits;
270→  uint64_t bytes_per_sec;
271→  uint64_t play_ms;
272→  int rc = -1;
273→
274→  if (pthread_mutex_trylock(&s_audio_lock) != 0)
275→    {
276→      return -EBUSY;
277→    }
278→  if (s_rec_active)
279→    {
280→      pthread_mutex_unlock(&s_audio_lock);
281→      return -EBUSY;
282→    }
283→
284→  p = nxplayer_create();
285→  if (!p || nxplayer_setdevice(p, "/dev/audio/pcm0p") != OK)
286→    {
287→      goto out;
288→    }
289→
290→  f = fopen(src, "rb");
291→  if (!f)
292→    {
293→      goto out;
294→    }
295→  if (fread(hdr, 1, 44, f) != 44 || memcmp(hdr, "RIFF", 4) != 0)
296→    {
297→      goto out;
298→    }
299→  ch = (uint16_t)(hdr[22] | (hdr[23] << 8));
300→  rate = (uint32_t)(hdr[24] | (hdr[25] << 8) | (hdr[26] << 16) |
301→                    ((uint32_t)hdr[27] << 24));
302→  bits = (uint16_t)(hdr[34] | (hdr[35] << 8));
303→  if (rate < 8000 || rate > 48000)
304→    {
305→      rate = 24000;
306→    }
307→  if (ch < 1 || ch > 2)
308→    {
309→      ch = 1;
310→    }
311→  if (bits != 8 && bits != 16)
312→    {
313→      bits = 16;
314→    }
315→
316→  o = fopen(PCM_RAW, "wb");
317→  if (!o)
318→    {
319→      goto out;
320→    }
321→  while ((n = fread(buf, 1, sizeof(buf), f)) > 0)
322→    {
323→      if (fwrite(buf, 1, n, o) != n)
324→        {
325→          goto out;
326→        }
327→      raw_len += n;
328→    }
329→  if (ferror(f) || raw_len == 0)
330→    {
331→      goto out;
332→    }
333→  fclose(o);
334→  o = NULL;
335→  fclose(f);
336→  f = NULL;
337→
338→  if (nxplayer_playraw(p, PCM_RAW, AUDIO_FMT_PCM, 0, (uint8_t)ch,
339→                       (uint8_t)bits, rate, 1) != OK)
340→    {
341→      goto out;
342→    }
343→
344→  /* nxplayer_playraw() returns as soon as its worker is started.  Keep the
345→   * audio gate until the PCM duration elapses and stop/join the worker, so a
346→   * following capture/playback cannot race the previous DMA release. */
347→  bytes_per_sec = (uint64_t)rate * ch * bits / 8;
348→  play_ms = bytes_per_sec ? ((uint64_t)raw_len * 1000 / bytes_per_sec) : 1000;
349→  play_ms += 150;
350→  if (play_ms > 30000)
351→    {
352→      play_ms = 30000;
353→    }
354→  while (play_ms >= 1000)
355→    {
356→      sleep(1);
357→      play_ms -= 1000;
358→    }
359→  if (play_ms > 0)
360→    {
361→      usleep((useconds_t)(play_ms * 1000));
362→    }
363→
364→  (void)nxplayer_stop(p);
365→  rc = 0;
366→
367→out:
368→  if (o)
369→    {
370→      fclose(o);
371→    }
372→  if (f)
373→    {
374→      fclose(f);
375→    }
376→  if (p)
377→    {
378→      nxplayer_release(p);
379→    }
380→  pthread_mutex_unlock(&s_audio_lock);
381→  return rc;
382→}
