125→static void *recorder_worker(void *arg)
126→{
127→  recorder_job_t job = (recorder_job_t)(intptr_t)arg;
128→  int rc;
129→
130→  switch (job)
131→    {
132→      case REC_JOB_START:
133→        rc = dm_voice_rec_start(RECORDER_MAX_SEC);
134→        break;
135→
136→      case REC_JOB_STOP_SAVE:
137→        rc = dm_voice_rec_stop();
138→        if (rc == 0)
139→          {
140→            rc = dm_voice_record_save(DM_VOICE_RECORD_PATH);
141→          }
142→        break;
143→
144→      case REC_JOB_PLAY:
145→        rc = dm_voice_play_file_sync(DM_VOICE_RECORD_PATH);
146→        break;
147→
148→      default:
149→        rc = -EINVAL;
150→        break;
151→    }
152→
153→  s_job_result = rc;
154→  s_job_done = 1;
155→  return NULL;
156→}
157→
158→static int recorder_start_job(recorder_job_t job)
159→{
160→  pthread_t th;
161→  pthread_attr_t attr;
162→  int ret;
163→
164→  if (s_busy)
165→    {
166→      return -EBUSY;
167→    }
168→
169→  s_busy = 1;
170→  s_job = job;
171→  s_job_done = 0;
172→  recorder_refresh();
173→
174→  pthread_attr_init(&attr);
175→  pthread_attr_setstacksize(&attr, 16384);
176→  ret = pthread_create(&th, &attr, recorder_worker, (void *)(intptr_t)job);
177→  pthread_attr_destroy(&attr);
178→  if (ret != 0)
179→    {
180→      s_busy = 0;
181→      s_job = REC_JOB_NONE;
182→      return -ret;
183→    }
184→
185→  pthread_detach(th);
186→  return 0;
187→}
