297→void dm_recorder_tick(void)
298→{
299→  if (s_job_done)
300→    {
301→      recorder_job_t completed = s_job;
302→      int rc = s_job_result;
303→
304→      s_job_done = 0;
305→      s_busy = 0;
306→      s_job = REC_JOB_NONE;
307→
308→      if (completed == REC_JOB_START)
309→        {
310→          if (rc == 0)
311→            {
312→              s_recording = 1;
313→              s_record_started_ms = recorder_monotonic_ms();
314→              if (s_status)
315→                {
316→                  lv_label_set_text(s_status,
317→                                    dm_t("正在录音…结束后自动保存",
318→                                         "Recording… save when stopped"));
319→                }
320→            }
321→          else if (s_status)
322→            {
323→              lv_label_set_text(s_status,
324→                                dm_t("无法启动录音，请稍后重试",
325→                                     "Could not start recording"));
326→            }
327→        }
328→      else if (completed == REC_JOB_STOP_SAVE)
329→        {
330→          s_recording = 0;
331→          s_record_started_ms = 0;
332→          if (rc == 0)
333→            {
334→              s_has_saved = 1;
335→              if (s_status)
336→                {
337→                  lv_label_set_text(s_status,
338→                                    dm_t("录音已保存，可通过喇叭播放",
339→                                         "Saved; ready to play on speaker"));
340→                }
341→            }
342→          else if (s_status)
343→            {
344→              lv_label_set_text(s_status,
345→                                dm_t("录音保存失败，请重新录制",
346→                                     "Save failed; please record again"));
347→            }
348→        }
349→      else if (completed == REC_JOB_PLAY && s_status)
350→        {
351→          lv_label_set_text(s_status,
352→                            rc == 0
353→                              ? dm_t("正在喇叭播放录音", "Playing on speaker")
354→                              : dm_t("播放失败，请先录制一段", "Playback failed"));
355→        }
356→      recorder_refresh();
357→    }
358→
359→  if (s_recording && !s_busy)
360→    {
361→      uint64_t now_ms = recorder_monotonic_ms();
362→      if (s_record_started_ms != 0 && now_ms >= s_record_started_ms)
363→        {
364→          char elapsed[48];
365→          unsigned int seconds =
366→              (unsigned int)((now_ms - s_record_started_ms) / 1000);
367→          snprintf(elapsed, sizeof(elapsed),
368→                   dm_t("已录 %u / %u 秒", "%u / %u sec"),
369→                   seconds, RECORDER_MAX_SEC);
370→          if (s_elapsed)
371→            {
372→              lv_label_set_text(s_elapsed, elapsed);
373→            }
374→        }
375→
376→      /* nxrecorder has an automatic time limit. Save its completed capture
377→       * instead of leaving it in /tmp when the limit is reached. */
378→      if (!dm_voice_rec_active())
379→        {
380→          if (recorder_start_job(REC_JOB_STOP_SAVE) != 0 && s_status)
381→            {
382→              lv_label_set_text(s_status,
383→                                dm_t("自动结束，正在等待保存", "Stopped; retrying save"));
384→            }
385→        }
386→    }
387→}
