309→void dm_recorder_tick(void)
310→{
311→  int job_done;
312→  int rc = 0;
313→  recorder_job_t completed = REC_JOB_NONE;
314→
315→  pthread_mutex_lock(&s_job_lock);
316→  job_done = s_job_done;
317→  if (job_done)
318→    {
319→      completed = s_job;
320→      rc = s_job_result;
321→      s_job_done = 0;
322→    }
323→  pthread_mutex_unlock(&s_job_lock);
324→
325→  if (job_done)
326→    {
327→      s_busy = 0;
328→      s_job = REC_JOB_NONE;
329→
330→      if (completed == REC_JOB_START)
331→        {
332→          if (rc == 0)
333→            {
334→              s_recording = 1;
335→              s_record_started_ms = recorder_monotonic_ms();
336→              if (s_elapsed)
337→                {
338→                  char elapsed[48];
339→                  snprintf(elapsed, sizeof(elapsed),
340→                           dm_t("已录 0 / %u 秒", "0 / %u sec"),
341→                           RECORDER_MAX_SEC);
342→                  lv_label_set_text(s_elapsed, elapsed);
343→                }
344→              if (s_status)
345→                {
346→                  lv_label_set_text(s_status,
347→                                    dm_t("正在录音…结束后自动保存",
348→                                         "Recording… save when stopped"));
349→                }
350→            }
351→          else if (s_status)
352→            {
353→              lv_label_set_text(s_status,
354→                                dm_t("无法启动录音，请稍后重试",
355→                                     "Could not start recording"));
356→            }
357→        }
358→      else if (completed == REC_JOB_STOP_SAVE)
359→        {
360→          s_recording = 0;
361→          s_record_started_ms = 0;
362→          if (rc == 0)
363→            {
364→              s_has_saved = 1;
365→              if (s_status)
366→                {
367→                  lv_label_set_text(s_status,
368→                                    dm_t("录音已保存，可通过喇叭播放",
369→                                         "Saved; ready to play on speaker"));
370→                }
371→            }
372→          else if (s_status)
373→            {
374→              lv_label_set_text(s_status,
375→                                dm_t("录音保存失败，请重新录制",
376→                                     "Save failed; please record again"));
377→            }
378→        }
379→      else if (completed == REC_JOB_PLAY && s_status)
380→        {
381→          lv_label_set_text(s_status,
382→                            rc == 0
383→                              ? dm_t("录音播放完成", "Playback complete")
384→                              : dm_t("播放失败，请先录制一段", "Playback failed"));
385→        }
386→      recorder_refresh();
387→    }
388→
389→  if (s_recording && !s_busy)
390→    {
391→      uint64_t now_ms = recorder_monotonic_ms();
392→      if (s_record_started_ms != 0 && now_ms >= s_record_started_ms)
393→        {
394→          char elapsed[48];
395→          unsigned int seconds =
396→              (unsigned int)((now_ms - s_record_started_ms) / 1000);
397→          snprintf(elapsed, sizeof(elapsed),
398→                   dm_t("已录 %u / %u 秒", "%u / %u sec"),
399→                   seconds, RECORDER_MAX_SEC);
400→          if (s_elapsed)
401→            {
402→              lv_label_set_text(s_elapsed, elapsed);
403→            }
404→        }
405→
406→      /* nxrecorder has an automatic time limit. Save its completed capture
407→       * instead of leaving it in /tmp when the limit is reached. */
408→      if (!dm_voice_rec_active())
409→        {
410→          if (recorder_start_job(REC_JOB_STOP_SAVE) != 0 && s_status)
411→            {
412→              lv_label_set_text(s_status,
413→                                dm_t("自动结束，正在等待保存", "Stopped; retrying save"));
414→            }
415→        }
416→    }
417→}
