 269→static int wifi_clock_synced(void)
 270→{
 271→  struct tm utc;
 272→  time_t now = time(NULL);
 273→
 274→  if (now <= 0 || gmtime_r(&now, &utc) == NULL || utc.tm_year + 1900 < 2024)
 275→    {
 276→      return 0;
 277→    }
 278→
 279→  /* A saved/manual clock is usable for TLS while NTP is being retried; an
 280→   * actual NTP sample remains the authoritative source when available. */
 281→  return wifi_ntp_has_samples() || s_manual_time_set;
 282→}
 283→
 284→void dm_wifi_manual_time_mark(void)
 285→{
 286→  FILE *f;
 287→  time_t now = time(NULL);
 288→
 289→  pthread_mutex_lock(&s_ntp_lock);
 290→  s_manual_time_set = 1;
 291→  s_ntp_retry_after_ms = 0;
 292→  pthread_mutex_unlock(&s_ntp_lock);
 293→
 294→  f = fopen(DM_WIFI_MANUAL_TIME_PATH, "w");
 295→  if (f)
 296→    {
 297→      fprintf(f, "%lld\n", (long long)now);
 298→      fclose(f);
 299→    }
 300→  syslog(LOG_INFO,
 301→         "[deskmate-wifi] manual system time set; saved local clock seed\n");
 302→}
 303→
 304→void dm_wifi_manual_time_restore(void)
 305→{
 306→  FILE *f;
 307→  long long saved_epoch;
 308→  time_t saved_time;
 309→  time_t current_time = time(NULL);
 310→  struct tm utc;
 311→  struct timeval tv;
 312→
 313→  /* Never replace a valid RTC or an NTP time that arrived early at boot. */
 314→  if (current_time > 0 && gmtime_r(&current_time, &utc) != NULL &&
 315→      utc.tm_year + 1900 >= 2024)
 316→    {
 317→      return;
 318→    }
 319→
 320→  f = fopen(DM_WIFI_MANUAL_TIME_PATH, "r");
 321→  if (!f)
 322→    {
 323→      return;
 324→    }
 325→  if (fscanf(f, "%lld", &saved_epoch) != 1)
 326→    {
 327→      fclose(f);
 328→      return;
 329→    }
 330→  fclose(f);
 331→
 332→  saved_time = (time_t)saved_epoch;
 333→  if ((long long)saved_time != saved_epoch || saved_time <= 0 ||
 334→      gmtime_r(&saved_time, &utc) == NULL || utc.tm_year + 1900 < 2024 ||
 335→      utc.tm_year + 1900 > 2099)
 336→    {
 337→      return;
 338→    }
 339→
 340→  tv.tv_sec = saved_time;
 341→  tv.tv_usec = 0;
 342→  if (settimeofday(&tv, NULL) == 0)
 343→    {
 344→      pthread_mutex_lock(&s_ntp_lock);
 345→      s_manual_time_set = 1;
 346→      s_ntp_retry_after_ms = 0;
 347→      pthread_mutex_unlock(&s_ntp_lock);
 348→      syslog(LOG_INFO,
 349→             "[deskmate-wifi] restored saved local clock seed; NTP may correct it\n");
 350→    }
 351→}
 352→
 353→static void wifi_restart_ntp_after_link(void)
 354→{
 355→  int stop_rc;
 356→  int start_rc;
 357→  uint64_t now_ms;
 358→
 359→  if (wifi_ntp_has_samples())
 360→    {
 361→      return;
 362→    }
 363→
 364→  pthread_mutex_lock(&s_ntp_lock);
 365→  now_ms = wifi_monotonic_ms();
 366→  if (s_ntp_retry_after_ms != 0 && now_ms < s_ntp_retry_after_ms)
 367→    {
 368→      pthread_mutex_unlock(&s_ntp_lock);
 369→      return;
 370→    }
 371→
 372→  /* The stock pool may be unreachable from some WLANs. Refresh only from an
 373→   * app worker and provide several DNS-resolved public NTP endpoints. */
 374→  stop_rc = ntpc_stop();
 375→  start_rc = ntpc_start_with_list(DM_WIFI_NTP_SERVERS);
 376→  s_ntp_retry_after_ms = now_ms +
 377→      (uint64_t)DM_WIFI_NTP_RETRY_SEC * 1000;
 378→  syslog(start_rc < 0 ? LOG_WARNING : LOG_INFO,
 379→         "[deskmate-wifi] NTP refresh stop=%d start=%d\n",
 380→         stop_rc, start_rc);
 381→  pthread_mutex_unlock(&s_ntp_lock);
 382→}
 383→
 384→int dm_wifi_wait_time_sync(int timeout_sec)
 385→{
 386→  struct ntpc_status_s status;
 387→  struct tm utc;
 388→  time_t now;
 389→  int year = 0;
 390→  int status_rc;
 391→  int i;
 392→
 393→  if (timeout_sec < 0)
 394→    {
 395→      timeout_sec = 0;
 396→    }
 397→  if (timeout_sec > 90)
 398→    {
 399→      timeout_sec = 90;
 400→    }
 401→
 402→  for (i = 0; i <= timeout_sec; i++)
 403→    {
 404→      if (wifi_clock_synced())
 405→        {
 406→          return 0;
 407→        }
 408→      if (!dm_wifi_connected())
 409→        {
 410→          return -ENETDOWN;
 411→        }
 412→      if (i == 0 || (i > 0 && (i % DM_WIFI_NTP_RETRY_SEC) == 0))
 413→        {
 414→          wifi_restart_ntp_after_link();
 415→        }
 416→      if (i < timeout_sec)
 417→        {
 418→          sleep(1);
 419→        }
 420→    }
 421→
 422→  memset(&status, 0, sizeof(status));
 423→  status_rc = ntpc_status(&status);
 424→  now = time(NULL);
 425→  if (now > 0 && gmtime_r(&now, &utc) != NULL)
 426→    {
 427→      year = utc.tm_year + 1900;
 428→    }
 429→  syslog(LOG_WARNING,
 430→         "[deskmate-wifi] NTP not ready; status=%d samples=%u year=%d; HTTPS deferred\n",
 431→         status_rc, status.nsamples, year);
 432→  return -ETIMEDOUT;
 433→}
