 435→/* Check wapi show wlan0 like 9.5 wifi_manager.c get_wifi_status() */
 436→static int wifi_is_associated(char *assoc_ssid, size_t ssid_len)
 437→{
 438→  FILE *fp;
 439→  char buf[256];
 440→  int associated = 1;
 441→
 442→  if (assoc_ssid && ssid_len > 0)
 443→    {
 444→      assoc_ssid[0] = 0;
 445→    }
 446→
 447→  (void)system("wapi show wlan0 > /tmp/wifi_status.txt");
 448→  fp = fopen("/tmp/wifi_status.txt", "r");
 449→  if (!fp)
 450→    {
 451→      return 0;
 452→    }
 453→
 454→  while (fgets(buf, sizeof(buf), fp) != NULL)
 455→    {
 456→      buf[strcspn(buf, "\r\n")] = 0;
 457→      if (strstr(buf, "AP: 00:00:00:00:00:00") != NULL)
 458→        {
 459→          associated = 0;
 460→        }
 461→      if (assoc_ssid && ssid_len > 0)
 462→        {
 463→          char *p = strstr(buf, "ESSID:");
 464→          if (p)
 465→            {
 466→              p += 6;
 467→              while (*p == ' ' || *p == '"')
 468→                {
 469→                  p++;
 470→                }
 471→              snprintf(assoc_ssid, ssid_len, "%s", p);
 472→              assoc_ssid[strcspn(assoc_ssid, "\"\r\n")] = 0;
 473→            }
 474→        }
 475→    }
 476→
 477→  fclose(fp);
 478→  return associated;
 479→}
