 666→static int wifi_cred_load_cfg(char *ssid, size_t slen, char *pass,
 667→                              size_t plen)
 668→{
 669→  FILE *f = fopen("/data/wifi.cfg", "r");
 670→  char line[96];
 671→  int got_ssid = 0;
 672→  int got_pass = 0;
 673→
 674→  if (!f)
 675→    {
 676→      return -1;
 677→    }
 678→  while (fgets(line, sizeof(line), f))
 679→    {
 680→      line[strcspn(line, "\r\n")] = 0;
 681→      if (strncmp(line, "SSID=", 5) == 0)
 682→        {
 683→          snprintf(ssid, slen, "%s", line + 5);
 684→          wifi_unquote(ssid);
 685→          got_ssid = 1;
 686→        }
 687→      else if (strncmp(line, "PASSWORD=", 9) == 0)
 688→        {
 689→          snprintf(pass, plen, "%s", line + 9);
 690→          wifi_unquote(pass);
 691→          got_pass = 1;
 692→        }
 693→    }
 694→  fclose(f);
 695→
 696→  if (!got_ssid || !ssid[0])
 697→    {
 698→      return -1;
 699→    }
 700→  if (!got_pass)
 701→    {
 702→      pass[0] = 0;
 703→    }
 704→  syslog(LOG_INFO, "[deskmate-wifi] creds from /data/wifi.cfg ssid=%s\n",
 705→         ssid);
 706→  return 0;
 707→}
 708→
 709→static int wifi_cred_load_wapi_json(char *ssid, size_t slen, char *pass,
 710→                                    size_t plen)
 711→{
 712→  FILE *f;
 713→  cJSON *root;
 714→  cJSON *ifobj;
 715→  cJSON *ssid_item;
 716→  cJSON *psk_item;
 717→  char *buf;
 718→  long size;
 719→  int ret = -1;
 720→
 721→  f = fopen(DM_WIFI_WAPI_CONFIG_PATH, "rb");
 722→  if (!f)
 723→    {
 724→      return -1;
 725→    }
 726→
 727→  if (fseek(f, 0, SEEK_END) != 0 || (size = ftell(f)) <= 0 || size > 4096 ||
 728→      fseek(f, 0, SEEK_SET) != 0)
 729→    {
 730→      fclose(f);
 731→      return -1;
 732→    }
 733→
 734→  buf = malloc((size_t)size + 1);
 735→  if (!buf)
 736→    {
 737→      fclose(f);
 738→      return -1;
 739→    }
 740→  if (fread(buf, 1, (size_t)size, f) != (size_t)size)
 741→    {
 742→      free(buf);
 743→      fclose(f);
 744→      return -1;
 745→    }
 746→  fclose(f);
 747→  buf[size] = '\0';
 748→
 749→  root = cJSON_Parse(buf);
 750→  free(buf);
 751→  if (!root)
 752→    {
 753→      return -1;
 754→    }
 755→
 756→  /* WAPI save_config writes {"wlan0":{"ssid":...,"psk":...}}.  Accept
 757→   * the older flat shape as a compatibility fallback. */
 758→  ifobj = cJSON_GetObjectItem(root, DM_WIFI_IF);
 759→  if (!ifobj)
 760→    {
 761→      ifobj = root;
 762→    }
 763→  ssid_item = cJSON_GetObjectItem(ifobj, "ssid");
 764→  psk_item = cJSON_GetObjectItem(ifobj, "psk");
 765→  if (ssid_item && cJSON_IsString(ssid_item) && ssid_item->valuestring &&
 766→      ssid_item->valuestring[0])
 767→    {
 768→      snprintf(ssid, slen, "%s", ssid_item->valuestring);
 769→      if (psk_item && cJSON_IsString(psk_item) && psk_item->valuestring)
 770→        {
 771→          snprintf(pass, plen, "%s", psk_item->valuestring);
 772→        }
 773→      else
 774→        {
 775→          pass[0] = '\0';
 776→        }
 777→      ret = 0;
 778→    }
 779→
 780→  cJSON_Delete(root);
 781→  if (ret == 0)
 782→    {
 783→      syslog(LOG_INFO, "[deskmate-wifi] loaded credentials from WAPI config\n");
 784→    }
 785→  return ret;
 786→}
