 788→static int wifi_cred_load(char *ssid, size_t slen, char *pass, size_t plen)
 789→{
 790→  FILE *f = fopen(DM_WIFI_SAVE_PATH, "r");
 791→  char line[96];
 792→
 793→  if (f)
 794→    {
 795→      if (fgets(line, sizeof(line), f))
 796→        {
 797→          line[strcspn(line, "\r\n")] = 0;
 798→          if (line[0])
 799→            {
 800→              snprintf(ssid, slen, "%s", line);
 801→              if (fgets(line, sizeof(line), f))
 802→                {
 803→                  line[strcspn(line, "\r\n")] = 0;
 804→                  snprintf(pass, plen, "%s", line);
 805→                }
 806→              else
 807→                {
