1458→static void *reconnect_thread(void *arg)
1459→{
1460→  char ssid[33];
1461→  char pass[64];
1462→  int attempt;
1463→  int i;
1464→
1465→  (void)arg;
1466→  ssid[0] = '\0';
1467→  pass[0] = '\0';
1468→  if (wifi_cred_load(ssid, sizeof(ssid), pass, sizeof(pass)) != 0 ||
1469→      !ssid[0])
1470→    {
1471→      syslog(LOG_WARNING, "[deskmate-wifi] reconnect skipped: no saved credentials\n");
1472→      goto done;
1473→    }
1474→
1475→  for (attempt = 0; attempt < 4 && s_wifi_enabled; attempt++)
1476→    {
1477→      if (dm_wifi_connected() || s_manual_override)
1478→        {
1479→          break;
1480→        }
1481→
1482→      if (attempt > 0)
1483→        {
1484→          sleep(DM_WIFI_CONN_RETRY_SEC);
1485→        }
1486→      if (s_scan_busy || s_conn_busy)
1487→        {
1488→          continue;
1489→        }
1490→
1491→      syslog(LOG_INFO, "[deskmate-wifi] saved-network reconnect attempt %d\n",
1492→             attempt + 1);
1493→      if (wifi_start_connect_internal(ssid, pass, 1) != 0)
1494→        {
1495→          continue;
1496→        }
1497→
1498→      for (i = 0; i < 600 && s_conn_busy && s_wifi_enabled &&
1499→                  !s_manual_override; i++)
1500→        {
1501→          usleep(100 * 1000);
1502→        }
1503→      if (dm_wifi_connected())
1504→        {
1505→          break;
1506→        }
1507→    }
1508→
1509→done:
1510→  s_reconnect_running = 0;
1511→  s_reconnect_retry_after_ms = wifi_monotonic_ms() + 30000;
1512→  return NULL;
1513→}
1514→
1515→static void wifi_request_reconnect(void)
1516→{
1517→  pthread_t th;
1518→  pthread_attr_t attr;
1519→
1520→  uint64_t now_ms = wifi_monotonic_ms();
1521→
1522→  if (!s_wifi_enabled || s_manual_override || dm_wifi_connected() ||
1523→      s_reconnect_running || s_auto_thread_active || s_scan_busy || s_conn_busy ||
1524→      (s_reconnect_retry_after_ms != 0 &&
1525→       now_ms < s_reconnect_retry_after_ms))
1526→    {
1527→      return;
1528→    }
1529→
1530→  s_reconnect_running = 1;
1531→  pthread_attr_init(&attr);
1532→  pthread_attr_setstacksize(&attr, DM_WIFI_STACK);
1533→  if (pthread_create(&th, &attr, reconnect_thread, NULL) == 0)
1534→    {
1535→      pthread_detach(th);
1536→    }
1537→  else
1538→    {
1539→      s_reconnect_running = 0;
1540→    }
1541→  pthread_attr_destroy(&attr);
1542→}
