1544→/* Boot auto-connect: checks if already connected, otherwise tries saved
1545→ * credentials once or twice and immediately yields if user opens manual scan. */
1546→static void *auto_thread(void *arg)
1547→{
1548→  char ssid[33];
1549→  char pass[64];
1550→  struct in_addr addr;
1551→  int round;
1552→  int i;
1553→
1554→  (void)arg;
1555→
1556→  ssid[0] = 0;
1557→  pass[0] = 0;
1558→  if (wifi_cred_load(ssid, sizeof(ssid), pass, sizeof(pass)) != 0 ||
1559→      !ssid[0])
1560→    {
1561→      if (DM_WIFI_AUTO_SSID[0] == 0)
1562→        {
1563→          syslog(LOG_INFO,
1564→                 "[deskmate-wifi] no saved credentials; skip boot connect\n");
1565→          goto done;
1566→        }
1567→      snprintf(ssid, sizeof(ssid), "%s", DM_WIFI_AUTO_SSID);
1568→      snprintf(pass, sizeof(pass), "%s", DM_WIFI_AUTO_PSK);
1569→    }
1570→
1571→  syslog(LOG_INFO,
1572→         "[deskmate-wifi] auto-connect ssid=%s — wait wlan0 first\n", ssid);
1573→
1574→  for (round = 0; round < 2 && !s_manual_override; round++)
1575→    {
1576→      if (ensure_driver_wait(300) < 0)
1577→        {
1578→          if (s_manual_override)
1579→            {
1580→              goto done;
1581→            }
1582→          sleep(2);
1583→          continue;
1584→        }
1585→
1586→      /* Ignore placeholder addresses unless association to the saved AP is
1587→       * verified; wlan0 may report 10.0.0.2 while its AP MAC is still zero. */
1588→      if (wifi_get_valid_ip(&addr) == 0 &&
1589→          wifi_verify_assoc(ssid) == 1 && wifi_is_link_up() == 1)
1590→        {
1591→          pthread_mutex_lock(&s_lock);
1592→          snprintf(s_cur_ssid, sizeof(s_cur_ssid), "%s", ssid);
1593→          snprintf(s_cur_ip, sizeof(s_cur_ip), "%s", inet_ntoa(addr));
1594→          pthread_mutex_unlock(&s_lock);
1595→          syslog(LOG_INFO, "[deskmate-wifi] already connected ssid=%s ip=%s\n",
1596→                 s_cur_ssid, s_cur_ip);
1597→          wifi_cred_save(ssid, pass);
1598→          if (!wifi_ntp_has_samples())
1599→            {
1600→              wifi_restart_ntp_after_link();
1601→            }
1602→          goto done;
1603→        }
1604→
1605→      if (dm_wifi_connected() || s_manual_override)
1606→        {
1607→          goto done;
1608→        }
1609→
1610→      dm_wifi_clear_conn_flags();
1611→      if (wifi_start_connect_internal(ssid, pass, 1) != 0)
1612→        {
1613→          sleep(2);
1614→          continue;
1615→        }
1616→
1617→      /* Wait for conn_thread to finish or manual override */
1618→      for (i = 0; i < 600 && s_conn_busy && !s_manual_override; i++)
1619→        {
1620→          usleep(100 * 1000);
1621→        }
1622→
1623→      if (dm_wifi_connected())
1624→        {
1625→          syslog(LOG_INFO, "[deskmate-wifi] auto connected ssid=%s ip=%s\n",
1626→                 dm_wifi_cur_ssid(), dm_wifi_cur_ip());
1627→          dm_wifi_clear_conn_flags();
1628→          goto done;
1629→        }
1630→
1631→      dm_wifi_clear_conn_flags();
1632→      if (s_manual_override)
1633→        {
1634→          goto done;
1635→        }
1636→      sleep(2);
1637→    }
1638→
1639→  syslog(LOG_INFO,
1640→         "[deskmate-wifi] auto-connect finished; manual UI ready\n");
1641→done:
1642→  s_auto_thread_active = 0;
1643→  return NULL;
1644→}
1645→
1646→/* Boot auto-connect: reads saved credentials (/data/deskmate_wifi.txt or
1647→ * /data/wifi.cfg) and reconnects, yielding to the manual UI if the user
1648→ * starts a scan/connect first.  Called once from deskmate_main.c. */
1649→void dm_wifi_auto_start(void)
1650→{
1651→  pthread_t th;
1652→  pthread_attr_t attr;
1653→
1654→  if (s_auto_started)
1655→    {
1656→      return;
1657→    }
1658→  s_auto_started = 1;
1659→  s_auto_thread_active = 1;
1660→
1661→  pthread_attr_init(&attr);
1662→  pthread_attr_setstacksize(&attr, DM_WIFI_STACK);
1663→  if (pthread_create(&th, &attr, auto_thread, NULL) == 0)
1664→    {
1665→      pthread_detach(th);
1666→    }
1667→  else
1668→    {
1669→      s_auto_thread_active = 0;
1670→    }
1671→  pthread_attr_destroy(&attr);
1672→}
