243→/* ---- multi-turn conversation memory (shared with voice chat) ---- */
244→#define HIST_TURN_MAX 3
245→#define HIST_LINE     128
246→
247→static struct
248→{
249→  char user[HIST_LINE];
250→  char bot[HIST_LINE];
251→} s_hist[HIST_TURN_MAX];
252→static int s_hist_n;
253→
254→void dm_chat_hist_reset(void)
255→{
256→  s_hist_n = 0;
257→}
258→
259→void dm_chat_hist_push(const char *user, const char *assistant)
260→{
261→  int i;
262→
263→  if (!user || !user[0])
264→    {
265→      return;
266→    }
267→  if (s_hist_n == HIST_TURN_MAX)
268→    {
269→      for (i = 1; i < HIST_TURN_MAX; i++)
270→        {
271→          s_hist[i - 1] = s_hist[i];
272→        }
273→      s_hist_n = HIST_TURN_MAX - 1;
274→    }
275→  strncpy(s_hist[s_hist_n].user, user, HIST_LINE - 1);
276→  s_hist[s_hist_n].user[HIST_LINE - 1] = '\0';
277→  if (assistant)
278→    {
279→      strncpy(s_hist[s_hist_n].bot, assistant, HIST_LINE - 1);
280→      s_hist[s_hist_n].bot[HIST_LINE - 1] = '\0';
281→    }
282→  else
283→    {
284→      s_hist[s_hist_n].bot[0] = '\0';
285→    }
286→  s_hist_n++;
287→}
288→
289→/* emit {"role":..,"content":..}, entries (each with trailing comma) */
290→int dm_chat_hist_json(char *out, int cap)
291→{
292→  char esc[HIST_LINE * 2];
293→  int o = 0;
294→  int i;
295→
296→  if (!out || cap < 2)
297→    {
298→      return -1;
299→    }
300→  out[0] = '\0';
301→  for (i = 0; i < s_hist_n; i++)
302→    {
303→      int n;
304→
305→      if (s_hist[i].user[0])
306→        {
307→          json_escape(s_hist[i].user, esc, sizeof(esc));
308→          n = snprintf(out + o, (size_t)(cap - o),
309→                       "{\"role\":\"user\",\"content\":\"%s\"},", esc);
310→          if (n < 0 || n >= cap - o)
311→            {
312→              out[o] = '\0';
313→              return -1;
314→            }
315→          o += n;
316→        }
317→      if (s_hist[i].bot[0])
318→        {
319→          json_escape(s_hist[i].bot, esc, sizeof(esc));
320→          n = snprintf(out + o, (size_t)(cap - o),
321→                       "{\"role\":\"assistant\",\"content\":\"%s\"},", esc);
322→          if (n < 0 || n >= cap - o)
323→            {
324→              out[o] = '\0';
325→              return -1;
326→            }
327→          o += n;
328→        }
329→    }
330→  return o;
331→}
