 99→/* worker thread — NO LVGL calls here */
100→static void *voice_worker(void *arg)
101→{
102→  char reply[CHAT_LINE_MAX];
103→  int voice_rc;
104→
105→  (void)arg;
106→
107→  if (s_job == 1)
108→    {
109→      /* nxrecorder_stop() joins its audio worker.  Never call it from the
110→       * LVGL click callback: a slow/failed PCM read must not freeze the UI. */
111→      if (dm_voice_rec_stop() != 0)
112→        {
113→          snprintf(s_out_ans, sizeof(s_out_ans), "%s",
114→                   dm_t("录音失败，未采集到有效音频",
115→                        "Recording failed; no audio captured"));
116→          snprintf(s_out_sub, sizeof(s_out_sub), "%s",
117→                   dm_t("检查麦克风和 /dev/audio/pcm0c",
118→                        "Check the microphone and /dev/audio/pcm0c"));
119→          s_out_ready = 1;
120→          return NULL;
121→        }
122→
123→      snprintf(s_out_sub, sizeof(s_out_sub), "%s",
124→               dm_t("ASR → 模型 → 喇叭播报", "ASR → LLM → speaker"));
125→      voice_rc = dm_voice_asr_chat_tts("/tmp/dm_voice_in.wav", reply,
126→                                       sizeof(reply));
127→      if (voice_rc >= 0)
128→        {
129→          snprintf(s_out_ans, sizeof(s_out_ans), "%s", reply);
130→          snprintf(s_out_sub, sizeof(s_out_sub), "%s",
131→                   voice_rc == 0
132→                     ? dm_t("已通过喇叭播放回复", "Reply played on speaker")
133→                     : dm_t("文字回复已显示，语音播报失败",
134→                            "Text reply shown; speech playback failed"));
135→          s_out_ready = 1;
136→        }
137→      else
138→        {
139→          /* Report the actual blocking condition instead of masking it as a
140→           * generic recognition failure. */
141→          switch (dm_voice_last_failure())
142→            {
143→              case DM_VOICE_FAILURE_WIFI:
144→                snprintf(s_out_ans, sizeof(s_out_ans), "%s",
145→                         dm_t("Wi-Fi 尚未连接", "Wi-Fi is not connected"));
146→                snprintf(s_out_sub, sizeof(s_out_sub), "%s",
147→                         dm_t("正在等待网络；连接后再试", "Wait for Wi-Fi, then try again"));
148→                break;
149→
150→              case DM_VOICE_FAILURE_TIME:
151→                snprintf(s_out_ans, sizeof(s_out_ans), "%s",
152→                         dm_t("设备时间尚未同步", "Device time is not synced"));
153→                snprintf(s_out_sub, sizeof(s_out_sub), "%s",
154→                         dm_t("网络时间就绪后再试，TLS证书校验未关闭",
155→                              "Retry after network time sync; TLS validation remains on"));
156→                break;
157→
158→              case DM_VOICE_FAILURE_API_KEY:
159→                snprintf(s_out_ans, sizeof(s_out_ans), "%s",
160→                         dm_t("MiMo API密钥未配置", "MiMo API key is not configured"));
161→                snprintf(s_out_sub, sizeof(s_out_sub), "%s",
162→                         dm_t("将新密钥保存到 /data/deskmate_mimo.key",
163→                              "Save a rotated key to /data/deskmate_mimo.key"));
164→                break;
165→
166→              case DM_VOICE_FAILURE_CHAT:
167→                snprintf(s_out_ans, sizeof(s_out_ans), "%s",
168→                         dm_t("语音对话请求失败", "Voice chat request failed"));
169→                snprintf(s_out_sub, sizeof(s_out_sub), "%s",
170→                         dm_t("检查网络/API状态，或点脸使用文字聊天",
171→                              "Check network/API status or tap the face for text chat"));
172→                break;
173→
174→              default:
175→                snprintf(s_out_ans, sizeof(s_out_ans), "%s",
176→                         dm_t("语音识别失败，请重试", "Speech recognition failed"));
177→                snprintf(s_out_sub, sizeof(s_out_sub), "%s",
178→                         dm_t("检查录音和麦克风，或点脸使用文字聊天",
179→                              "Check recording/mic or tap the face for text chat"));
180→                break;
181→            }
182→          s_out_ready = 1;
183→        }
184→    }
185→  else if (s_job == 2)
186→    {
187→      const char *r = dm_chat_ai_ask(s_pending);
188→      snprintf(s_out_ans, sizeof(s_out_ans), "%s", r ? r : "……");
189→      if (r && r[0] && dm_chat_ai_remote_ok())
190→        {
191→          if (dm_voice_tts_play(r) == 0)
192→            {
193→              snprintf(s_out_sub, sizeof(s_out_sub), "%s",
194→                       dm_t("已通过喇叭播放回复", "Reply played on speaker"));
195→            }
196→          else
197→            {
198→              snprintf(s_out_sub, sizeof(s_out_sub), "%s",
199→                       dm_t("文字回复已显示，语音播报失败",
200→                            "Text reply shown; speech playback failed"));
201→            }
202→        }
203→      else if (r && r[0])
204→        {
205→          snprintf(s_out_sub, sizeof(s_out_sub), "%s",
206→                   dm_t("云端连接失败，当前显示离线回复",
207→                        "Cloud unavailable; showing offline reply"));
208→        }
209→      else
210→        {
211→          s_out_sub[0] = '\0';
212→        }
213→      s_out_ready = 1;
214→    }
215→  return NULL;
216→}
