218→static void kick_job(int job)
219→{
220→  pthread_t th;
221→  pthread_attr_t attr;
222→
223→  if (s_busy)
224→    {
225→      return;
226→    }
227→  s_busy = true;
228→  s_job = job;
229→  s_ui_rec = false;
230→  s_rec_sec = 0;
231→  s_out_ready = 0;
232→  s_out_ans[0] = '\0';
233→  s_out_sub[0] = '\0';
234→
235→  dm_face_set(FACE_THINK, EYE_DECOR_NONE, 10);
236→  set_ans(job == 1 ? dm_t("识别中…", "Recognizing…")
237→                   : dm_t("思考中…", "Thinking…"));
238→  set_ptt("处理中…", "Working…", C_BTN_HI);
239→
240→  pthread_attr_init(&attr);
241→  pthread_attr_setstacksize(&attr, DM_VOICE_NET_WORKER_STACK);
242→  if (pthread_create(&th, &attr, voice_worker, NULL) == 0)
243→    {
244→      pthread_detach(th);
245→    }
246→  else
247→    {
248→      s_busy = false;
249→      if (job == 1 && dm_voice_rec_active())
250→        {
251→          /* Keep the recording controllable if worker creation failed. */
252→          s_ui_rec = true;
253→          set_ans(dm_t("正在录音，稍后再点结束",
254→                       "Recording; tap stop again"));
255→          set_ptt("结束并发送", "Stop & send", C_HEART);
256→        }
257→      else
258→        {
259→          set_ptt("开始说话", "Start talk", C_BTN);
260→        }
261→    }
262→  pthread_attr_destroy(&attr);
263→}
