272→  dm_face_set(FACE_HAPPY, EYE_DECOR_HEART, 8);
273→  strncpy(s_pending, dm_t("陪我聊聊天", "Chat with me"), sizeof(s_pending) - 1);
274→  s_pending[sizeof(s_pending) - 1] = '\0';
275→  kick_job(2);
