331→static int voice_wav_find_data(FILE *f, uint16_t *channels, uint32_t *rate,
332→                               uint16_t *bits, long *data_offset,
333→                               uint32_t *data_size)
334→{
335→  uint8_t riff[12];
336→  uint8_t chunk[8];
337→  uint8_t fmt[16];
338→  long file_size;
339→  long offset = 12;
340→  int have_fmt = 0;
341→  int have_data = 0;
342→
343→  if (fread(riff, 1, sizeof(riff), f) != sizeof(riff) ||
344→      memcmp(riff, "RIFF", 4) != 0 || memcmp(riff + 8, "WAVE", 4) != 0 ||
345→      fseek(f, 0, SEEK_END) != 0 || (file_size = ftell(f)) < 44)
346→    {
347→      return -1;
348→    }
349→
350→  while (offset <= file_size - 8)
351→    {
352→      uint32_t chunk_size;
353→      long payload_offset;
354→
355→      if (fseek(f, offset, SEEK_SET) != 0 ||
356→          fread(chunk, 1, sizeof(chunk), f) != sizeof(chunk))
357→        {
358→          return -1;
359→        }
360→      chunk_size = voice_get_le32(chunk + 4);
361→      payload_offset = offset + 8;
362→      if ((long)chunk_size > file_size - payload_offset)
363→        {
364→          return -1;
365→        }
366→
367→      if (memcmp(chunk, "fmt ", 4) == 0)
368→        {
369→          if (chunk_size < sizeof(fmt) ||
370→              fseek(f, payload_offset, SEEK_SET) != 0 ||
371→              fread(fmt, 1, sizeof(fmt), f) != sizeof(fmt) ||
372→              voice_get_le16(fmt) != 1)
373→            {
374→              return -1;
375→            }
376→          *channels = voice_get_le16(fmt + 2);
377→          *rate = voice_get_le32(fmt + 4);
378→          *bits = voice_get_le16(fmt + 14);
379→          have_fmt = 1;
380→        }
381→      else if (memcmp(chunk, "data", 4) == 0)
382→        {
383→          *data_offset = payload_offset;
384→          *data_size = chunk_size;
385→          have_data = 1;
386→        }
387→
388→      if (have_fmt && have_data)
389→        {
390→          return 0;
391→        }
392→
393→      offset = payload_offset + (long)chunk_size + (chunk_size & 1u);
394→    }
395→
396→  return -1;
397→}
