724→/* Load and validate the key supplied at runtime. Never log or compile it. */
725→static int voice_key_load(char *key, size_t key_cap)
726→{
727→  FILE *f;
728→  size_t i;
729→  size_t n;
730→  int valid = 0;
731→
732→  if (!key || key_cap < 16)
733→    {
734→      return 0;
735→    }
736→  key[0] = '\0';
737→  f = fopen(MIMO_KEY_PATH, "rb");
738→  if (!f)
739→    {
740→      snprintf(key, key_cap, "%s", MIMO_EMBEDDED_KEY);
741→      return key[0] != '\0';
742→    }
743→
744→  if (fgets(key, (int)key_cap, f))
745→    {
746→      n = strlen(key);
747→      while (n > 0 && (key[n - 1] == '\r' || key[n - 1] == '\n' ||
748→                       key[n - 1] == ' ' || key[n - 1] == '\t'))
749→        {
750→          key[--n] = '\0';
751→        }
752→      valid = n > 8 && n < key_cap - 1;
753→      for (i = 0; valid && i < n; i++)
754→        {
755→          unsigned char ch = (unsigned char)key[i];
756→          if (!((ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') ||
757→                (ch >= '0' && ch <= '9') || ch == '-' || ch == '_' ||
758→                ch == '.'))
759→            {
760→              valid = 0;
761→            }
762→        }
763→    }
764→
765→  fclose(f);
766→  if (!valid)
767→    {
768→      memset(key, 0, key_cap);
769→      snprintf(key, key_cap, "%s", MIMO_EMBEDDED_KEY);
770→      valid = key[0] != '\0';
771→    }
772→  return valid;
773→}
