775→/* Curl reads a short-lived, owner-only config file. Invoke the command
776→ * directly through NuttX system() rather than nesting a generated script
777→ * through NSH's limited sh parser. The API key never enters the command line. */
778→static int run_curl_command(const char *line)
779→{
780→  char key[128];
781→  FILE *kf;
782→  int key_write_ok;
783→  int key_close_rc;
784→  int rc;
785→  int saved_errno;
786→
787→  if (!line || !line[0] || !voice_key_load(key, sizeof(key)))
788→    {
789→      s_last_failure = DM_VOICE_FAILURE_API_KEY;
790→      syslog(LOG_ERR, "[dm-voice] runtime API key or curl command unavailable\n");
791→      return -1;
792→    }
793→
794→  kf = fopen(MIMO_CURL_CONFIG, "w");
795→  if (!kf)
796→    {
797→      syslog(LOG_ERR, "[dm-voice] cannot create curl config errno=%d\n", errno);
798→      memset(key, 0, sizeof(key));
799→      return -1;
800→    }
801→  if (chmod(MIMO_CURL_CONFIG, S_IRUSR | S_IWUSR) != 0)
802→    {
803→      syslog(LOG_ERR, "[dm-voice] cannot protect curl config errno=%d\n", errno);
804→      fclose(kf);
805→      memset(key, 0, sizeof(key));
806→      unlink(MIMO_CURL_CONFIG);
807→      return -1;
808→    }
809→  key_write_ok = fprintf(kf, "header = \"Authorization: Bearer %s\"\n",
810→                         key) > 0;
811→  key_close_rc = fclose(kf);
812→  memset(key, 0, sizeof(key));
813→  if (!key_write_ok || key_close_rc != 0)
814→    {
815→      syslog(LOG_ERR, "[dm-voice] cannot write curl config\n");
816→      unlink(MIMO_CURL_CONFIG);
817→      return -1;
818→    }
819→
820→  errno = 0;
821→  rc = system(line);
822→  saved_errno = errno;
823→  unlink(MIMO_CURL_CONFIG);
824→  if (rc != 0)
825→    {
826→      syslog(LOG_ERR,
827→             "[dm-voice] curl command failed system_status=%d errno=%d\n",
828→             rc, saved_errno);
829→      return -1;
830→    }
831→  return 0;
832→}
