835→static const char b64tab[] =
836→    "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
837→
838→static int b64_encode(const unsigned char *in, size_t inlen, char *out,
839→                      size_t outcap)
840→{
841→  size_t i = 0;
842→  size_t o = 0;
843→
844→  if (!in || !out || outcap < 2 || inlen > (outcap - 1) / 4 * 3)
845→    {
846→      return -1;
847→    }
848→
849→  while (i < inlen)
850→    {
851→      size_t remain = inlen - i;
852→      unsigned int v = (unsigned int)in[i++] << 16;
853→      if (remain > 1)
854→        {
855→          v |= (unsigned int)in[i++] << 8;
856→        }
857→      if (remain > 2)
858→        {
859→          v |= (unsigned int)in[i++];
860→        }
861→      out[o++] = b64tab[(v >> 18) & 63];
862→      out[o++] = b64tab[(v >> 12) & 63];
863→      out[o++] = remain > 1 ? b64tab[(v >> 6) & 63] : '=';
864→      out[o++] = remain > 2 ? b64tab[v & 63] : '=';
865→    }
866→  out[o] = '\0';
867→  return (int)o;
868→}
