324→void dm_recorder_tick(void)
325→{
326→  int job_done;
327→  int rc = 0;
328→  recorder_job_t completed = REC_JOB_NONE;
329→
330→  pthread_mutex_lock(&s_job_lock);
331→  job_done = s_job_done;
332→  if (job_done)
333→    {
334→      completed = s_job;
335→      rc = s_job_result;
336→      s_job_done = 0;
337→    }
338→  pthread_mutex_unlock(&s_job_lock);
339→
340→  if (job_done)
341→    {
342→      s_busy = 0;
343→      s_job = REC_JOB_NONE;
344→
345→      if (completed == REC_JOB_START)
346→        {
347→          if (rc == 0)
348→            {
349→              s_recording = 1;
350→              s_record_started_ms = recorder_monotonic_ms();
351→              if (s_elapsed)
352→                {
353→                  char elapsed[48];
354→                  snprintf(elapsed, sizeof(elapsed),
355→                           dm_t("已录 0 / %u 秒", "0 / %u sec"),
356→                           RECORDER_MAX_SEC);
357→                  lv_label_set_text(s_elapsed, elapsed);
358→                }
359→              if (s_status)
360→                {
361→                  lv_label_set_text(s_status,
362→                                    dm_t("正在录音…结束后自动保存",
363→                                         "Recording… save when stopped"));
364→                }
365→            }
366→          else if (s_status)
367→            {
368→              lv_label_set_text(s_status,
369→                                dm_t("无法启动录音，请稍后重试",
370→                                     "Could not start recording"));
371→            }
372→        }
373→      else if (completed == REC_JOB_STOP_SAVE)
374→        {
375→          s_recording = 0;
376→          s_record_started_ms = 0;
377→          if (rc == 0)
378→            {
379→              s_has_saved = 1;
380→              if (s_status)
381→                {
382→                  lv_label_set_text(s_status,
383→                                    dm_t("录音已保存，可通过喇叭播放",
384→                                         "Saved; ready to play on speaker"));
385→                }
386→            }
387→          else if (s_status)
388→            {
389→              lv_label_set_text(s_status,
390→                                dm_t("录音保存失败，请重新录制",
391→                                     "Save failed; please record again"));
392→            }
393→        }
394→      else if (completed == REC_JOB_PLAY && s_status)
395→        {
396→          lv_label_set_text(s_status,
397→                            rc == 0
398→                              ? dm_t("录音播放完成", "Playback complete")
399→                              : dm_t("播放失败，请先录制一段", "Playback failed"));
400→        }
401→      recorder_refresh();
402→    }
403→
404→  if (s_recording && !s_busy)
405→    {
406→      uint64_t now_ms = recorder_monotonic_ms();
407→      if (s_record_started_ms != 0 && now_ms >= s_record_started_ms)
408→        {
409→          char elapsed[48];
410→          unsigned int seconds =
411→              (unsigned int)((now_ms - s_record_started_ms) / 1000);
412→          snprintf(elapsed, sizeof(elapsed),
413→                   dm_t("已录 %u / %u 秒", "%u / %u sec"),
414→                   seconds, RECORDER_MAX_SEC);
415→          if (s_elapsed)
416→            {
417→              lv_label_set_text(s_elapsed, elapsed);
418→            }
419→        }
420→
421→      /* nxrecorder has an automatic time limit. Save its completed capture
422→       * instead of leaving it in /tmp when the limit is reached. */
423→      if (!dm_voice_rec_active())
424→        {
425→          if (recorder_start_job(REC_JOB_STOP_SAVE) != 0 && s_status)
426→            {
427→              lv_label_set_text(s_status,
428→                                dm_t("自动结束，正在等待保存", "Stopped; retrying save"));
429→            }
430→        }
431→    }
432→}
