382→static void *recorder_worker(void *arg)
383→{
384→  recorder_job_t job = s_job;
385→  int slot = (int)(intptr_t)arg;
386→  char path[64];
387→  int rc;
388→
389→  switch (job)
390→    {
391→      case REC_JOB_START:
392→        rc = dm_voice_rec_start(RECORDER_MAX_SEC);
393→        break;
394→
395→      case REC_JOB_STOP_SAVE:
396→        rc = dm_voice_rec_stop();
397→        if (rc == 0 && recorder_slot_path(slot, path, sizeof(path)) == 0)
398→          {
399→            rc = dm_voice_record_save(path);
400→            if (rc == 0)
401→              {
402→                recorder_state_save((slot + 1) % RECORDER_SLOT_COUNT);
403→              }
404→          }
405→        else if (rc == 0)
406→          {
407→            rc = -EINVAL;
408→          }
409→        break;
410→
411→      case REC_JOB_PLAY:
412→        rc = recorder_slot_path(slot, path, sizeof(path));
413→        if (rc == 0)
414→          {
415→            rc = dm_voice_play_file_sync(path);
416→          }
417→        break;
418→
419→      default:
420→        rc = -EINVAL;
421→        break;
422→    }
423→
424→  pthread_mutex_lock(&s_job_lock);
425→  s_job_result = rc;
426→  s_job_completed_slot = slot;
427→  s_job_done = 1;
428→  pthread_mutex_unlock(&s_job_lock);
429→  return NULL;
430→}
431→
432→static int recorder_start_job(recorder_job_t job, int slot)
433→{
434→  pthread_t th;
435→  pthread_attr_t attr;
436→  int ret;
437→
438→  if (s_busy)
439→    {
440→      return -EBUSY;
441→    }
442→
443→  s_busy = 1;
444→  s_job = job;
445→  s_job_slot = slot;
446→  pthread_mutex_lock(&s_job_lock);
447→  s_job_done = 0;
448→  pthread_mutex_unlock(&s_job_lock);
449→  recorder_refresh();
450→
451→  pthread_attr_init(&attr);
452→  pthread_attr_setstacksize(&attr, 16384);
453→  ret = pthread_create(&th, &attr, recorder_worker, (void *)(intptr_t)slot);
454→  pthread_attr_destroy(&attr);
455→  if (ret != 0)
456→    {
457→      s_busy = 0;
458→      s_job = REC_JOB_NONE;
459→      if (s_status)
460→        {
461→          lv_label_set_text(s_status,
462→                            dm_t("无法启动录音任务", "Could not start recorder task"));
463→        }
464→      recorder_refresh();
465→      return -ret;
466→    }
467→
468→  pthread_detach(th);
469→  return 0;
470→}
