658→void dm_recorder_tick(void)
659→{
660→  int job_done;
661→  int rc = 0;
662→  int completed_slot = -1;
663→  recorder_job_t completed = REC_JOB_NONE;
664→
665→  pthread_mutex_lock(&s_job_lock);
666→  job_done = s_job_done;
667→  if (job_done)
668→    {
669→      completed = s_job;
670→      rc = s_job_result;
671→      completed_slot = s_job_completed_slot;
672→      s_job_done = 0;
673→    }
674→  pthread_mutex_unlock(&s_job_lock);
675→
676→  if (job_done)
677→    {
678→      s_busy = 0;
679→      s_job = REC_JOB_NONE;
680→
681→      if (completed == REC_JOB_START)
682→        {
683→          if (rc == 0)
684→            {
685→              s_recording = 1;
686→              s_record_started_ms = recorder_monotonic_ms();
687→              if (s_elapsed)
688→                {
689→                  char elapsed[48];
690→                  snprintf(elapsed, sizeof(elapsed),
691→                           dm_t("已录 0 / %u 秒", "0 / %u sec"),
692→                           RECORDER_MAX_SEC);
693→                  lv_label_set_text(s_elapsed, elapsed);
694→                }
695→              if (s_status)
696→                {
697→                  char status[48];
698→                  snprintf(status, sizeof(status),
699→                           dm_t("正在录制第 %02d 条…", "Recording #%02d…"),
700→                           s_record_slot + 1);
701→                  lv_label_set_text(s_status, status);
702→                }
703→            }
704→          else if (s_status)
705→            {
706→              lv_label_set_text(s_status,
707→                                dm_t("无法启动录音，请稍后重试",
708→                                     "Could not start recording"));
709→            }
710→        }
711→      else if (completed == REC_JOB_STOP_SAVE)
712→        {
713→          s_recording = 0;
714→          s_record_started_ms = 0;
715→          if (rc == 0 && completed_slot >= 0 &&
716→              completed_slot < RECORDER_SLOT_COUNT)
717→            {
718→              if (!s_slot_exists[completed_slot])
719→                {
720→                  s_slot_count++;
721→                }
722→              s_slot_exists[completed_slot] = 1;
723→              s_selected_slot = completed_slot;
724→              s_next_slot = (completed_slot + 1) % RECORDER_SLOT_COUNT;
