399→static void *recorder_worker(void *arg)
400→{
401→  recorder_job_t job = s_job;
402→  int slot = (int)(intptr_t)arg;
403→  char path[64];
404→  int rc;
405→
406→  switch (job)
407→    {
408→      case REC_JOB_START:
409→        rc = dm_voice_rec_start(RECORDER_MAX_SEC);
410→        break;
411→
412→      case REC_JOB_STOP_SAVE:
413→        rc = dm_voice_rec_stop();
414→        if (rc == 0 && recorder_slot_path(slot, path, sizeof(path)) == 0)
415→          {
416→            rc = dm_voice_record_save(path);
417→            if (rc == 0)
418→              {
419→                recorder_state_save((slot + 1) % RECORDER_SLOT_COUNT);
420→              }
421→          }
422→        else if (rc == 0)
423→          {
424→            rc = -EINVAL;
425→          }
426→        break;
427→
428→      case REC_JOB_PLAY:
429→        rc = recorder_slot_path(slot, path, sizeof(path));
430→        if (rc == 0)
431→          {
432→            rc = dm_voice_play_file_sync(path);
433→          }
434→        break;
435→
436→      default:
437→        rc = -EINVAL;
438→        break;
439→    }
440→
441→  pthread_mutex_lock(&s_job_lock);
442→  s_job_result = rc;
443→  s_job_completed_slot = slot;
444→  s_job_done = 1;
445→  pthread_mutex_unlock(&s_job_lock);
446→  return NULL;
447→}
