449→static int recorder_start_job(recorder_job_t job, int slot)
450→{
451→  pthread_t th;
452→  pthread_attr_t attr;
453→  int ret;
454→
455→  if (s_busy)
456→    {
457→      return -EBUSY;
458→    }
459→
460→  s_busy = 1;
461→  s_job = job;
462→  pthread_mutex_lock(&s_job_lock);
463→  s_job_done = 0;
464→  pthread_mutex_unlock(&s_job_lock);
465→  recorder_refresh();
466→
467→  pthread_attr_init(&attr);
468→  pthread_attr_setstacksize(&attr, 16384);
469→  ret = pthread_create(&th, &attr, recorder_worker, (void *)(intptr_t)slot);
470→  pthread_attr_destroy(&attr);
471→  if (ret != 0)
472→    {
473→      s_busy = 0;
474→      s_job = REC_JOB_NONE;
475→      if (s_status)
476→        {
477→          lv_label_set_text(s_status,
478→                            dm_t("无法启动录音任务", "Could not start recorder task"));
479→        }
480→      recorder_refresh();
481→      return -ret;
482→    }
483→
484→  pthread_detach(th);
485→  return 0;
486→}
