221→static int json_escape(const char *in, char *out, size_t cap)
222→{
223→  size_t o = 0;
224→  size_t i;
225→
226→  if (!in || !out || cap < 2)
227→    {
228→      return -1;
229→    }
230→  for (i = 0; in[i] && o + 8 < cap; i++)
231→    {
232→      unsigned char ch = (unsigned char)in[i];
233→      if (ch == '"' || ch == '\\')
234→        {
235→          out[o++] = '\\';
236→          out[o++] = (char)ch;
237→        }
238→      else if (ch == '\n')
239→        {
240→          out[o++] = '\\';
241→          out[o++] = 'n';
242→        }
243→      else if (ch < 0x20)
244→        {
245→          /* skip control chars */
246→        }
247→      else
248→        {
249→          out[o++] = (char)ch;
250→        }
251→    }
252→  out[o] = '\0';
253→  return (int)o;
254→}
