256→/* ---- multi-turn conversation memory (shared with voice chat) ---- */
257→#define HIST_TURN_MAX 3
258→#define HIST_LINE     128
259→
260→static struct
261→{
262→  char user[HIST_LINE];
263→  char bot[HIST_LINE];
264→} s_hist[HIST_TURN_MAX];
265→static int s_hist_n;
266→
267→void dm_chat_hist_reset(void)
268→{
269→  s_hist_n = 0;
270→}
271→
272→void dm_chat_hist_push(const char *user, const char *assistant)
273→{
274→  int i;
275→
276→  if (!user || !user[0])
277→    {
278→      return;
279→    }
280→  if (s_hist_n == HIST_TURN_MAX)
281→    {
282→      for (i = 1; i < HIST_TURN_MAX; i++)
283→        {
284→          s_hist[i - 1] = s_hist[i];
285→        }
286→      s_hist_n = HIST_TURN_MAX - 1;
287→    }
288→  strncpy(s_hist[s_hist_n].user, user, HIST_LINE - 1);
289→  s_hist[s_hist_n].user[HIST_LINE - 1] = '\0';
290→  if (assistant)
291→    {
292→      strncpy(s_hist[s_hist_n].bot, assistant, HIST_LINE - 1);
293→      s_hist[s_hist_n].bot[HIST_LINE - 1] = '\0';
294→    }
295→  else
296→    {
297→      s_hist[s_hist_n].bot[0] = '\0';
298→    }
299→  s_hist_n++;
300→}
301→
302→/* emit {"role":..,"content":..}, entries (each with trailing comma) */
303→int dm_chat_hist_json(char *out, int cap)
304→{
305→  char esc[HIST_LINE * 2];
306→  int o = 0;
307→  int i;
308→
309→  if (!out || cap < 2)
310→    {
311→      return -1;
312→    }
313→  out[0] = '\0';
314→  for (i = 0; i < s_hist_n; i++)
315→    {
316→      int n;
317→
318→      if (s_hist[i].user[0])
319→        {
320→          json_escape(s_hist[i].user, esc, sizeof(esc));
321→          n = snprintf(out + o, (size_t)(cap - o),
322→                       "{\"role\":\"user\",\"content\":\"%s\"},", esc);
323→          if (n < 0 || n >= cap - o)
324→            {
325→              out[o] = '\0';
326→              return -1;
327→            }
328→          o += n;
329→        }
330→      if (s_hist[i].bot[0])
331→        {
332→          json_escape(s_hist[i].bot, esc, sizeof(esc));
333→          n = snprintf(out + o, (size_t)(cap - o),
334→                       "{\"role\":\"assistant\",\"content\":\"%s\"},", esc);
335→          if (n < 0 || n >= cap - o)
336→            {
337→              out[o] = '\0';
338→              return -1;
339→            }
340→          o += n;
341→        }
342→    }
343→  return o;
344→}
