428→const char *dm_chat_ai_ask(const char *user_text)
429→{
430→  char esc[400];
431→  char persona[1024];
432→  char hist[1400];
433→  char body[2400];
434→  char cmd[1200];
435→  char http_status[48] = "";
436→  char curl_error[160] = "";
437→  const char *persona_src;
438→  FILE *f;
439→  int n;
440→  int cmd_len;
441→  int write_ok;
442→  int close_rc;
443→  int curl_rc;
444→
445→  s_last_reply[0] = '\0';
446→  s_last_request_remote_ok = 0;
447→  if (!user_text || !user_text[0])
448→    {
449→      return local_reply("");
450→    }
451→
452→  if (!dm_wifi_connected())
453→    {
454→      strncpy(s_last_reply, local_reply(user_text), sizeof(s_last_reply) - 1);
455→      s_last_reply[sizeof(s_last_reply) - 1] = '\0';
456→      return s_last_reply;
457→    }
458→
459→  /* Do not send HTTPS while the board clock is still at its boot epoch;
460→   * this causes mbedTLS to reject valid certificates as not-yet-valid. */
461→  if (dm_wifi_wait_time_sync(40) != 0)
462→    {
463→      syslog(LOG_WARNING, "[dm-chat] system clock not synchronized\n");
464→      strncpy(s_last_reply, local_reply(user_text), sizeof(s_last_reply) - 1);
465→      s_last_reply[sizeof(s_last_reply) - 1] = '\0';
466→      return s_last_reply;
467→    }
468→
469→  if (json_escape(user_text, esc, sizeof(esc)) < 0)
470→    {
471→      return local_reply(user_text);
472→    }
473→
474→  persona_src = s_persona_ctx[0] ? s_persona_ctx
475→                                 : "你是openvela小助手，桌边陪伴助手，回答简洁温暖，不超过80字，用中文。";
476→  if (json_escape(persona_src, persona, sizeof(persona)) < 0)
477→    {
478→      return local_reply(user_text);
479→    }
480→
481→  dm_chat_hist_json(hist, sizeof(hist));
482→  n = snprintf(body, sizeof(body),
483→               "{\"model\":\"%s\",\"messages\":["
484→               "{\"role\":\"system\",\"content\":\"%s\"},"
485→               "%s"
486→               "{\"role\":\"user\",\"content\":\"%s\"}],"
487→               "\"max_completion_tokens\":400,\"thinking\":{\"type\":\"disabled\"}}",
488→               MIMO_MODEL, persona, hist, esc);
489→  if (n <= 0 || n >= (int)sizeof(body))
490→    {
491→      return local_reply(user_text);
492→    }
493→
494→  f = fopen(CHAT_REQ_PATH, "w");
495→  if (!f)
496→    {
497→      syslog(LOG_ERR, "[dm-chat] cannot create request body errno=%d\n", errno);
498→      return local_reply(user_text);
499→    }
500→  write_ok = fwrite(body, 1, (size_t)n, f) == (size_t)n;
501→  close_rc = fclose(f);
502→  if (!write_ok || close_rc != 0)
503→    {
504→      syslog(LOG_ERR, "[dm-chat] cannot write request body\n");
505→      return local_reply(user_text);
506→    }
507→
508→  unlink(CHAT_RSP_PATH);
509→  unlink(CHAT_HTTP_STATUS);
510→  unlink(CHAT_CURL_ERROR);
511→  /* Emit a status line and curl stderr separately; neither contains the key
512→   * or request body, and both let the user distinguish TLS/network/API errors. */
513→  cmd_len = snprintf(cmd, sizeof(cmd),
514→                     "curl -K " MIMO_CURL_CONFIG " "
515→                     "--cacert /resource/etc/ssl/curl/ca-certificates.crt "
516→                     "-s -S -f -m 20 -w 'HTTP_STATUS:%%{http_code}\\n' "
517→                     "-X POST %s/chat/completions "
518→                     "-H 'Content-Type: application/json' "
519→                     "-d @%s -o %s > %s 2> %s",
520→                     MIMO_BASE, CHAT_REQ_PATH, CHAT_RSP_PATH,
521→                     CHAT_HTTP_STATUS, CHAT_CURL_ERROR);
522→  if (cmd_len <= 0 || cmd_len >= (int)sizeof(cmd))
523→    {
524→      syslog(LOG_ERR, "[dm-chat] curl command buffer too small\n");
525→      return local_reply(user_text);
526→    }
527→
528→  curl_rc = run_curl_command(cmd);
529→  chat_read_diag(CHAT_HTTP_STATUS, http_status, sizeof(http_status));
530→  chat_read_diag(CHAT_CURL_ERROR, curl_error, sizeof(curl_error));
531→  unlink(CHAT_HTTP_STATUS);
532→  unlink(CHAT_CURL_ERROR);
533→  if (curl_rc != 0)
534→    {
535→      syslog(LOG_WARNING, "[dm-chat] HTTP failure status=%s curl=%s\n",
536→             http_status[0] ? http_status : "unavailable",
537→             curl_error[0] ? curl_error : "no curl diagnostic");
538→      strncpy(s_last_reply, local_reply(user_text),
539→              sizeof(s_last_reply) - 1);
540→      s_last_reply[sizeof(s_last_reply) - 1] = '\0';
541→      return s_last_reply;
542→    }
543→  syslog(LOG_INFO, "[dm-chat] HTTP success status=%s\n",
544→         http_status[0] ? http_status : "unavailable");
545→
546→  extract_content(CHAT_RSP_PATH, s_last_reply, sizeof(s_last_reply));
547→  if (s_last_reply[0])
548→    {
549→      s_last_request_remote_ok = 1;
550→      dm_chat_hist_push(user_text, s_last_reply);
551→    }
552→  else
553→    {
554→      strncpy(s_last_reply, local_reply(user_text),
555→              sizeof(s_last_reply) - 1);
556→      s_last_reply[sizeof(s_last_reply) - 1] = '\0';
557→    }
558→  return s_last_reply;
559→}
