 856→static const char b64tab[] =
 857→    "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
 858→
 859→static int b64_encode(const unsigned char *in, size_t inlen, char *out,
 860→                      size_t outcap)
 861→{
 862→  size_t i = 0;
 863→  size_t o = 0;
 864→
 865→  if (!in || !out || outcap < 2 || inlen > (outcap - 1) / 4 * 3)
 866→    {
 867→      return -1;
 868→    }
 869→
 870→  while (i < inlen)
 871→    {
 872→      size_t remain = inlen - i;
 873→      unsigned int v = (unsigned int)in[i++] << 16;
 874→      if (remain > 1)
 875→        {
 876→          v |= (unsigned int)in[i++] << 8;
 877→        }
 878→      if (remain > 2)
 879→        {
 880→          v |= (unsigned int)in[i++];
 881→        }
 882→      out[o++] = b64tab[(v >> 18) & 63];
 883→      out[o++] = b64tab[(v >> 12) & 63];
 884→      out[o++] = remain > 1 ? b64tab[(v >> 6) & 63] : '=';
 885→      out[o++] = remain > 2 ? b64tab[v & 63] : '=';
 886→    }
 887→  out[o] = '\0';
 888→  return (int)o;
 889→}
 890→
 891→static int b64_decode(const char *in, unsigned char *out, size_t outcap)
 892→{
 893→  const char *p;
 894→  unsigned int val = 0;
 895→  int bits = 0;
 896→  size_t o = 0;
 897→  size_t symbols = 0;
 898→  size_t padding = 0;
 899→  int ended = 0;
 900→
 901→  if (!in || !out)
 902→    {
 903→      return -1;
 904→    }
 905→
 906→  /* Some compatible gateways return a data URL instead of bare Base64. */
 907→  if (strncmp(in, "data:", 5) == 0)
 908→    {
 909→      const char *comma = strchr(in, ',');
 910→      const char *base64 = strstr(in, ";base64");
 911→      if (!comma || !base64 || base64 > comma)
 912→        {
 913→          return -1;
 914→        }
 915→      in = comma + 1;
 916→    }
 917→
 918→  for (; *in; in++)
 919→    {
 920→      unsigned char ch = (unsigned char)*in;
 921→      if (ch == ' ' || ch == '\t' || ch == '\r' || ch == '\n')
 922→        {
 923→          continue;
 924→        }
 925→      if (ch == '=')
 926→        {
 927→          ended = 1;
 928→          padding++;
 929→          if (padding > 2)
 930→            {
 931→              return -1;
 932→            }
 933→          continue;
 934→        }
 935→      if (ended)
 936→        {
 937→          return -1;
 938→        }
 939→
 940→      p = strchr(b64tab, ch);
 941→      if (!p)
 942→        {
 943→          return -1;
 944→        }
 945→      symbols++;
 946→      val = (val << 6) | (unsigned int)(p - b64tab);
 947→      bits += 6;
 948→      if (bits >= 8)
 949→        {
 950→          bits -= 8;
 951→          if (o >= outcap)
 952→            {
 953→              return -1;
 954→            }
 955→          out[o++] = (unsigned char)((val >> bits) & 0xff);
 956→          val &= bits ? ((1u << bits) - 1u) : 0u;
 957→        }
 958→    }
 959→
 960→  if (symbols == 0 || symbols % 4 == 1 ||
 961→      (padding == 1 && symbols % 4 != 3) ||
 962→      (padding == 2 && symbols % 4 != 2) ||
 963→      (padding > 0 && (symbols + padding) % 4 != 0) ||
 964→      (bits != 0 && bits != 2 && bits != 4) || val != 0)
 965→    {
 966→      return -1;
 967→    }
 968→  return (int)o;
 969→}
