523→    {
524→      strncpy(s_last_reply, local_reply(user_text),
525→              sizeof(s_last_reply) - 1);
526→      s_last_reply[sizeof(s_last_reply) - 1] = '\0';
527→    }
528→  return s_last_reply;
529→}
