1607→static int voice_asr_chat_tts_unlocked(const char *wav_path, char *reply,
1608→                                       int cap)
1609→{
1610→  char text[256];
1611→  const char *asr_path;
1612→  int play_rc = -1;
1613→
1614→  if (!wav_path || !reply || cap < 8)
1615→    {
1616→      return -1;
1617→    }
1618→  s_last_failure = DM_VOICE_FAILURE_NONE;
1619→  reply[0] = '\0';
1620→
1621→  if (voice_prepare_wav(wav_path, &asr_path) != 0)
1622→    {
1623→      s_last_failure = DM_VOICE_FAILURE_ASR;
1624→      s_st = DM_VOICE_ERR;
1625→      return -1;
1626→    }
1627→
1628→  s_st = DM_VOICE_ASR;
1629→  if (asr_wav(asr_path, text, sizeof(text)) != 0)
1630→    {
1631→      if (s_last_failure == DM_VOICE_FAILURE_NONE)
1632→        {
1633→          s_last_failure = DM_VOICE_FAILURE_ASR;
1634→        }
1635→      s_st = DM_VOICE_ERR;
1636→      return -1;
1637→    }
1638→
1639→  s_st = DM_VOICE_CHAT;
1640→  if (chat_reply(text, reply, cap) != 0)
1641→    {
1642→      if (s_last_failure == DM_VOICE_FAILURE_NONE)
1643→        {
1644→          s_last_failure = DM_VOICE_FAILURE_CHAT;
1645→        }
1646→      strncpy(reply, "（网络忙，没听清）", (size_t)cap - 1);
1647→      reply[cap - 1] = '\0';
1648→      s_st = DM_VOICE_ERR;
1649→      return -1;
1650→    }
1651→
1652→  /* Preserve the text answer even if playback fails; the caller can show
1653→   * that the reply is text-only rather than pretending the speaker worked. */
1654→  s_st = DM_VOICE_TTS;
1655→  if (tts_synth(reply, WAV_TTS, dm_voice_profile_api_id()) == 0)
1656→    {
1657→      s_st = DM_VOICE_PLAY;
1658→      play_rc = play_wav(WAV_TTS);
1659→    }
1660→  else if (s_last_failure == DM_VOICE_FAILURE_NONE)
1661→    {
1662→      s_last_failure = DM_VOICE_FAILURE_TTS;
1663→    }
1664→  s_st = DM_VOICE_IDLE;
1665→  return play_rc == 0 ? 0 : 1;
1666→}
1667→
1668→int dm_voice_asr_chat_tts(const char *wav_path, char *reply, int cap)
1669→{
1670→  int rc;
1671→
1672→  pthread_mutex_lock(&s_voice_api_lock);
1673→  rc = voice_asr_chat_tts_unlocked(wav_path, reply, cap);
1674→  pthread_mutex_unlock(&s_voice_api_lock);
1675→  return rc;
1676→}
