329→static void note_kb_confirm_cb(lv_event_t *e)
330→{
331→  const char *w = (const char *)lv_event_get_user_data(e);
332→
333→  if (w && w[0])
334→    {
335→      /* Append one CJK character (3 bytes UTF-8) to draft */
336→      size_t cur = s_draft_len;
337→      if (cur + 3 < NOTE_LEN_MAX - 1)
338→        {
339→          memcpy(s_draft + cur, w, 3);
340→          s_draft_len = (int)(cur + 3);
341→          s_draft[s_draft_len] = 0;
342→        }
343→      /* Clear pinyin input after selecting a character */
344→      s_pin_len = 0;
345→      s_pin[0] = 0;
346→    }
347→  note_paint();
348→  note_paint_cands();
349→}
