 51→#define WATER_GOAL 8
 52→
 53→static int s_w_cups;
 54→static int s_w_interval = 45;
 55→static int s_w_left;
 56→static int s_w_day;
 57→static time_t s_w_due;
 58→static bool s_w_alert_on;
 59→static lv_obj_t *s_w_big;
 60→static lv_obj_t *s_w_next;
 61→static lv_obj_t *s_w_tip;
 62→static lv_obj_t *s_w_iv_lab;
