 64→
 65→#define WATER_IV_MIN 5
 66→#define WATER_IV_MAX 60
 67→#define WATER_IV_STEP 5
 68→
 69→static int water_iv_clamp(int iv)
 70→{
 71→  if (iv < WATER_IV_MIN)
 72→    {
 73→      iv = WATER_IV_MIN;
 74→    }
 75→  if (iv > WATER_IV_MAX)
 76→    {
 77→      iv = WATER_IV_MAX;
 78→    }
 79→  iv = (iv / WATER_IV_STEP) * WATER_IV_STEP;
 80→  if (iv < WATER_IV_MIN)
 81→    {
 82→      iv = WATER_IV_MIN;
 83→    }
 84→  return iv;
 85→}
 86→
 87→static int today_yday(void)
 88→{
 89→  time_t t = time(NULL);
 90→  struct tm tmv;
 91→  localtime_r(&t, &tmv);
 92→  return tmv.tm_yday + tmv.tm_year * 1000;
 93→}
 94→
 95→static void water_save(void)
 96→{
 97→  FILE *f;
 98→
 99→  if (s_w_left > 0)
100→    {
101→      s_w_due = time(NULL) + s_w_left;
102→    }
103→  else if (!s_w_alert_on)
104→    {
105→      s_w_due = time(NULL) + s_w_interval * 60;
106→      s_w_left = s_w_interval * 60;
107→    }
108→  /* when alert is on, keep due in the past until user taps 好滴 */
109→
110→  f = fopen(WATER_PATH, "w");
111→  if (!f)
112→    {
113→      return;
114→    }
115→  fprintf(f, "%d %d %ld %d\n", s_w_cups, s_w_interval, (long)s_w_due,
116→          s_w_day);
117→  fclose(f);
118→}
119→
120→static void water_load(void)
121→{
122→  FILE *f = fopen(WATER_PATH, "r");
123→  int c = 0;
124→  int iv = 45;
125→  long due = 0;
126→  int day = today_yday();
127→  time_t now = time(NULL);
128→
129→  if (f)
130→    {
131→      if (fscanf(f, "%d %d %ld %d", &c, &iv, &due, &day) != 4)
132→        {
133→          day = today_yday();
134→          due = 0;
135→        }
136→      fclose(f);
137→    }
138→  iv = water_iv_clamp(iv);
139→  if (iv < WATER_IV_MIN || iv > WATER_IV_MAX)
140→    {
141→      iv = 45;
142→    }
143→  s_w_cups = c < 0 ? 0 : c;
144→  s_w_interval = iv;
145→  s_w_day = today_yday();
146→
147→  if (day != today_yday())
148→    {
149→      s_w_cups = 0;
150→      s_w_due = now + iv * 60;
151→    }
152→  else if (due <= 0)
153→    {
154→      s_w_due = now + iv * 60;
155→    }
156→  else
157→    {
158→      s_w_due = (time_t)due;
159→    }
160→
161→  s_w_left = (int)(s_w_due - now);
162→  if (s_w_left < 0)
163→    {
164→      s_w_left = 0; /* overdue → tick will raise full-screen alert */
165→    }
166→}
