240→static float clampf(float v, float lo, float hi)
241→{
242→  if (v < lo)
243→    {
244→      return lo;
245→    }
246→  if (v > hi)
247→    {
248→      return hi;
249→    }
250→  return v;
251→}
252→
253→static float mf_trapezoid(float x, float lo, float opt_lo, float opt_hi,
254→                          float hi)
255→{
256→  if (x < lo || x > hi)
257→    {
258→      return 0.0f;
259→    }
260→  if (x < opt_lo)
261→    {
262→      return (x - lo) / (opt_lo - lo);
263→    }
264→  if (x <= opt_hi)
265→    {
266→      return 1.0f;
267→    }
268→  return (hi - x) / (hi - opt_hi);
269→}
270→
271→static float mf_env_score(float t, float h, int has_t, int has_h)
272→{
273→  float st = 0.0f;
274→  float sh = 0.0f;
275→  int nt = 0;
276→  int nh = 0;
277→
278→  if (has_t)
279→    {
280→      st = mf_trapezoid(t, 10.0f, 20.0f, 26.0f, 35.0f);
281→      nt = 1;
282→    }
283→  if (has_h)
284→    {
285→      sh = mf_trapezoid(h, 20.0f, 40.0f, 60.0f, 85.0f);
286→      nh = 1;
287→    }
288→  if (nt && nh)
289→    {
290→      return 0.6f * st + 0.4f * sh;
291→    }
292→  if (nt)
293→    {
294→      return st;
295→    }
296→  if (nh)
297→    {
298→      return sh;
299→    }
300→  return -1.0f;
301→}
302→
303→static float mf_game_score(int game_ms)
304→{
305→  float g = (float)game_ms / 1000.0f / 60.0f; /* minutes */
306→
307→  if (game_ms < 0)
308→    {
309→      return -1.0f; /* missing */
310→    }
311→  if (g <= 0.0f)
312→    {
313→      return 0.55f; /* neutral if tracked as 0 */
314→    }
315→  if (g <= 30.0f)
316→    {
317→      return 0.55f + 0.45f * (g / 30.0f);
318→    }
319→  if (g <= 60.0f)
320→    {
321→      return 1.0f;
322→    }
323→  if (g <= 120.0f)
324→    {
325→      return 1.0f - 0.45f * ((g - 60.0f) / 60.0f);
326→    }
327→  if (g <= 180.0f)
328→    {
329→      return 0.55f - 0.35f * ((g - 120.0f) / 60.0f);
330→    }
331→  {
332→    float v = 0.20f - 0.15f * ((g - 180.0f) / 60.0f);
333→    return v < 0.05f ? 0.05f : v;
334→  }
335→}
