745→  s_last_behavior = beh_v;
746→  s_last_cov = cov;
747→  s_last_nf = nf;
748→  s_last_has_mood = (mood_v >= 0) ? 1 : 0;
749→  s_last_has_beh = (beh_v >= 0) ? 1 : 0;
750→
751→  /* blend: mood algorithm (静心轨迹) + board behavior factors */
752→  if (mood_v >= 0 && beh_v >= 0)
753→    {
754→      return (mood_v * 6 + beh_v * 4) / 10;
755→    }
756→  if (mood_v >= 0)
757→    {
758→      return mood_v;
759→    }
760→  if (beh_v >= 0)
761→    {
762→      return beh_v;
763→    }
764→  return 50;
765→}
