456→static void cd_save(void)
457→{
458→  FILE *f = fopen(COUNTDOWN_PATH, "w");
459→  int i;
460→  if (!f)
461→    {
462→      return;
463→    }
464→  for (i = 0; i < s_cd_n; i++)
465→    {
466→      fprintf(f, "%04d-%02d-%02d %s\n", s_cd[i].y, s_cd[i].m, s_cd[i].d,
467→              s_cd[i].name);
468→    }
469→  fclose(f);
470→}
471→
472→static void cd_load(void)
473→{
474→  FILE *f = fopen(COUNTDOWN_PATH, "r");
475→  char line[64];
476→  s_cd_n = 0;
477→  s_cd_sel = 0;
478→  if (!f)
479→    {
480→      /* seed demo */
481→      time_t t = time(NULL);
482→      struct tm tmv;
483→      localtime_r(&t, &tmv);
484→      s_cd[0].y = tmv.tm_year + 1900;
485→      s_cd[0].m = 10;
486→      s_cd[0].d = 1;
487→      snprintf(s_cd[0].name, CD_NAME_MAX, "生日");
488→      s_cd[1].y = tmv.tm_year + 1900;
489→      s_cd[1].m = 12;
490→      s_cd[1].d = 20;
491→      snprintf(s_cd[1].name, CD_NAME_MAX, "考试");
492→      s_cd_n = 2;
493→      return;
494→    }
495→  while (s_cd_n < CD_MAX && fgets(line, sizeof(line), f))
496→    {
497→      int y;
498→      int m;
499→      int d;
500→      char name[CD_NAME_MAX];
501→      if (sscanf(line, "%d-%d-%d %15s", &y, &m, &d, name) == 4)
502→        {
503→          s_cd[s_cd_n].y = y;
504→          s_cd[s_cd_n].m = m;
505→          s_cd[s_cd_n].d = d;
506→          snprintf(s_cd[s_cd_n].name, CD_NAME_MAX, "%s", name);
507→          s_cd_n++;
508→        }
509→    }
510→  fclose(f);
511→}
512→
513→static int cd_days(const cd_item_t *it)
514→{
515→  time_t now = time(NULL);
516→  struct tm tmv;
517→  struct tm t2;
518→  time_t target;
519→
520→  localtime_r(&now, &tmv);
521→  memset(&t2, 0, sizeof(t2));
522→  t2.tm_year = it->y - 1900;
523→  t2.tm_mon = it->m - 1;
524→  t2.tm_mday = it->d;
525→  t2.tm_hour = 12;
526→  target = mktime(&t2);
527→  if (target == (time_t)-1)
528→    {
529→      return 0;
530→    }
531→  {
532→    struct tm a;
533→    struct tm b;
534→    localtime_r(&target, &a);
535→    localtime_r(&now, &b);
536→    a.tm_hour = a.tm_min = a.tm_sec = 0;
537→    b.tm_hour = b.tm_min = b.tm_sec = 0;
538→    return (int)difftime(mktime(&a), mktime(&b)) / 86400;
539→  }
540→}
