468→static void clean_reminder_name(const char *text, size_t date_start,
469→                                size_t date_end, size_t time_start,
470→                                size_t time_end, char *out, size_t cap)
471→{
472→  char tmp[INTENT_TEXT_MAX];
473→  size_t len = strlen(text);
474→  size_t start = date_start;
475→  size_t end = date_end;
476→  size_t tstart = time_start;
477→  size_t tend = time_end;
478→  size_t out_len = 0;
479→  static const char *const leading[] = {
480→    "帮我设置提醒", "提醒一下", "提醒我", "倒数日", "记一个", "计一个",
481→    "记一下", "在", "请", "把", "到时候", "我"
482→  };
483→  size_t i;
484→
485→  if (len >= sizeof(tmp))
486→    {
487→      len = sizeof(tmp) - 1;
488→    }
489→  memcpy(tmp, text, len);
490→  tmp[len] = '\0';
491→
492→  if (tstart >= end)
493→    {
494→      memmove(tmp + tstart, tmp + tend, len - tend + 1);
495→      len -= tend - tstart;
496→      memmove(tmp + start, tmp + end, len - end + 1);
497→      len -= end - start;
498→    }
499→  else if (start >= tend)
500→    {
501→      memmove(tmp + start, tmp + end, len - end + 1);
502→      len -= end - start;
503→      memmove(tmp + tstart, tmp + tend, len - tend + 1);
504→      len -= tend - tstart;
505→    }
506→  else
507→    {
508→      memmove(tmp + start, tmp + end, len - end + 1);
509→      len -= end - start;
510→      if (tstart > end)
511→        {
512→          tstart -= end - start;
513→          tend -= end - start;
514→        }
515→      memmove(tmp + tstart, tmp + tend, len - tend + 1);
516→      len -= tend - tstart;
517→    }
518→
519→  while (len > 0)
520→    {
521→      int changed = 0;
522→      while (len > 0 && (tmp[0] == ' ' || tmp[0] == '\t' || tmp[0] == ',' ||
523→                         tmp[0] == ':' || tmp[0] == '-'))
524→        {
525→          memmove(tmp, tmp + 1, len);
526→          len--;
527→        }
528→      for (i = 0; i < sizeof(leading) / sizeof(leading[0]); i++)
529→        {
530→          size_t n = strlen(leading[i]);
531→          if (len >= n && memcmp(tmp, leading[i], n) == 0)
532→            {
533→              memmove(tmp, tmp + n, len - n + 1);
534→              len -= n;
535→              changed = 1;
536→              break;
537→            }
538→        }
539→      if (!changed)
540→        {
541→          break;
542→        }
543→    }
544→  while (len > 0 && (tmp[len - 1] == ' ' || tmp[len - 1] == '\t' ||
545→                      tmp[len - 1] == ',' || tmp[len - 1] == ':' ||
546→                      tmp[len - 1] == '-' || tmp[len - 1] == '.' ||
547→                      tmp[len - 1] == '。' || tmp[len - 1] == '，'))
548→    {
549→      tmp[--len] = '\0';
550→    }
551→
552→  if (len == 0)
553→    {
554→      snprintf(out, cap, "%s", "提醒事项");
555→      return;
556→    }
557→  out_len = len < cap - 1 ? len : cap - 1;
558→  if (out_len < len)
559→    {
560→      while (out_len > 0 && ((unsigned char)tmp[out_len] & 0xc0u) == 0x80u)
561→        {
562→          out_len--;
563→        }
564→    }
565→  memcpy(out, tmp, out_len);
566→  out[out_len] = '\0';
567→}
