673→          }
674→        snprintf(reply, cap, "已有专注计时正在进行，我没有重置它。先结束当前专注再试。\n");
675→        return -1;
676→
677→      case INTENT_COUNTDOWN:
678→        rc = dm_countdown_add_voice(intent->text, intent->year, intent->month,
679→                                    intent->day, intent->hour,
680→                                    intent->minute);
681→        if (rc == 0)
682→          {
683→            snprintf(reply, cap, "记好了：%s，%d月%d日%02d:%02d提醒你。",
684→                     intent->text, intent->month, intent->day, intent->hour,
685→                     intent->minute);
686→            return 0;
687→          }
688→        if (rc == -2)
689→          {
690→            snprintf(reply, cap, "倒数日列表已满，暂时不能添加。请先删除一项。\n");
691→          }
692→        else if (rc == -4)
693→          {
694→            snprintf(reply, cap, "设备日期时间还没校准，无法设置准确提醒。\n");
695→          }
696→        else
697→          {
698→            snprintf(reply, cap, "提醒没有保存成功，请检查日期后再试。\n");
699→          }
700→        return -1;
701→
702→      case INTENT_NOTE:
703→        rc = dm_note_add_voice(intent->text);
704→        if (rc == 0)
705→          {
706→            snprintf(reply, cap, "记下了：%s。已经保存到备忘。", intent->text);
707→            return 0;
708→          }
709→        if (rc == -2)
710→          {
711→            snprintf(reply, cap, "备忘已满，暂时不能添加。请先删除一条。\n");
712→          }
713→        else
714→          {
715→            snprintf(reply, cap, "这条备忘没有保存成功，请再说短一点。\n");
716→          }
717→        return -1;
718→
719→      case INTENT_MOOD:
720→        dm_health_voice_advice(intent->text, reply, (int)cap);
721→        return 0;
722→
723→      default:
724→        return -1;
725→    }
726→}
