static void trim_reminder_punctuation(char *text, size_t *len)
{
  int changed = 1;
  while (*len > 0 && changed)
    {
      changed = 0;
      if (text[*len - 1] == ' ' || text[*len - 1] == '\t' ||
          text[*len - 1] == ',' || text[*len - 1] == ':' ||
          text[*len - 1] == '-' || text[*len - 1] == '.')
        {
          text[--(*len)] = '\0';
          changed = 1;
        }
      else if (*len >= 3 &&
               (memcmp(text + *len - 3, "。", 3) == 0 ||
                memcmp(text + *len - 3, "，", 3) == 0 ||
                memcmp(text + *len - 3, "！", 3) == 0 ||
                memcmp(text + *len - 3, "？", 3) == 0 ||
                memcmp(text + *len - 3, "；", 3) == 0 ||
                memcmp(text + *len - 3, "：", 3) == 0))
        {
          *len -= 3;
          text[*len] = '\0';
          changed = 1;
        }
    }
}

