 61→static int chinese_digit(const char *p, size_t left, int *value)
 62→{
 63→  static const struct
 64→  {
 65→    const char *text;
 66→    int value;
 67→  } digits[] = {
 68→    {"零", 0}, {"〇", 0}, {"一", 1}, {"二", 2}, {"两", 2},
 69→    {"三", 3}, {"四", 4}, {"五", 5}, {"六", 6}, {"七", 7},
 70→    {"八", 8}, {"九", 9}
 71→  };
 72→  size_t i;
 73→
 74→  if (left < 3)
 75→    {
 76→      return 0;
 77→    }
 78→  for (i = 0; i < sizeof(digits) / sizeof(digits[0]); i++)
 79→    {
 80→      if (memcmp(p, digits[i].text, 3) == 0)
 81→        {
 82→          *value = digits[i].value;
 83→          return 1;
 84→        }
 85→    }
 86→  return 0;
 87→}
 88→
 89→static int chinese_unit(const char *p, size_t left, int *unit)
 90→{
 91→  if (left < 3)
 92→    {
 93→      return 0;
 94→    }
 95→  if (memcmp(p, "十", 3) == 0)
 96→    {
 97→      *unit = 10;
 98→      return 1;
 99→    }
100→  if (memcmp(p, "百", 3) == 0)
101→    {
102→      *unit = 100;
103→      return 1;
104→    }
105→  if (memcmp(p, "千", 3) == 0)
106→    {
107→      *unit = 1000;
108→      return 1;
109→    }
110→  return 0;
111→}
112→
113→static int parse_number_slice(const char *text, size_t begin, size_t end,
114→                              int *value)
115→{
116→  size_t i;
117→  int ascii_only = 1;
118→  int total = 0;
119→  int section = 0;
120→  int number = -1;
121→  int saw = 0;
122→
123→  if (!text || !value || begin >= end)
124→    {
125→      return 0;
126→    }
127→  for (i = begin; i < end; i++)
128→    {
129→      if (!isdigit((unsigned char)text[i]))
130→        {
131→          ascii_only = 0;
132→          break;
133→        }
134→    }
135→  if (ascii_only)
136→    {
137→      long parsed = 0;
138→      for (i = begin; i < end; i++)
139→        {
140→          parsed = parsed * 10 + (text[i] - '0');
141→          if (parsed > 10000)
142→            {
143→              return 0;
144→            }
145→        }
146→      *value = (int)parsed;
147→      return 1;
148→    }
149→
150→  i = begin;
151→  while (i < end)
152→    {
153→      int digit;
154→      int unit;
155→      if (chinese_digit(text + i, end - i, &digit))
156→        {
157→          number = digit;
158→          i += 3;
159→          saw = 1;
160→        }
161→      else if (chinese_unit(text + i, end - i, &unit))
162→        {
163→          int multiplier = number >= 0 ? number : 1;
164→          section += multiplier * unit;
165→          number = -1;
166→          i += 3;
167→          saw = 1;
168→        }
169→      else
170→        {
171→          return 0;
172→        }
173→    }
174→  if (!saw)
175→    {
176→      return 0;
177→    }
178→  if (number >= 0)
179→    {
180→      section += number;
181→    }
182→  total += section;
183→  if (total > 10000)
184→    {
185→      return 0;
186→    }
187→  *value = total;
188→  return 1;
189→}
190→
191→static int parse_number_before(const char *text, size_t end, size_t *start,
192→                               int *value)
193→{
194→  size_t begin = end;
195→  size_t cursor;
196→
197→  while (begin > 0)
198→    {
199→      int ignored;
200→      if (isdigit((unsigned char)text[begin - 1]))
201→        {
202→          begin--;
203→          continue;
204→        }
205→      if (begin >= 3 &&
206→          (chinese_digit(text + begin - 3, 3, &ignored) ||
207→           chinese_unit(text + begin - 3, 3, &ignored)))
208→        {
209→          begin -= 3;
210→          continue;
211→        }
212→      break;
213→    }
214→  cursor = begin;
215→  if (!parse_number_slice(text, begin, end, value))
216→    {
217→      return 0;
218→    }
219→  if (start)
220→    {
221→      *start = cursor;
222→    }
223→  return 1;
224→}
