241→static int parse_duration_minutes(const char *text, int *minutes)
242→{
243→  const char *hour_word = strstr(text, "小时");
244→  const char *minute_word = strstr(text, "分钟");
245→  const char *short_minute = strstr(text, "分");
246→  const char *unit;
247→  size_t start;
248→  int number;
249→  int multiplier;
250→
251→  if (strstr(text, "半小时"))
252→    {
253→      *minutes = 30;
254→      return 1;
255→    }
256→  if (hour_word && (!minute_word || hour_word < minute_word))
257→    {
258→      unit = hour_word;
259→      multiplier = 60;
260→    }
261→  else
262→    {
263→      unit = minute_word ? minute_word : short_minute;
264→      multiplier = 1;
265→    }
266→  if (!unit)
267→    {
268→      return 0;
269→    }
270→  if (!parse_number_before(text, (size_t)(unit - text), &start, &number))
271→    {
272→      /* Accept the natural Mandarin form "一个小时". */
273→      if (multiplier == 60 && unit >= text + 3 &&
274→          memcmp(unit - 3, "个", 3) == 0 &&
275→          parse_number_before(text, (size_t)(unit - text - 3), &start,
276→                              &number))
277→        {
278→          /* parsed the number before 个 */
279→        }
280→      else
281→        {
282→          return 0;
283→        }
284→    }
285→  if (number < 1 || number > 120)
286→    {
287→      return 0;
288→    }
289→  *minutes = number * multiplier;
290→  if (*minutes > 120)
291→    {
292→      return 0;
293→    }
294→  return 1;
295→}
