297→static int parse_datetime(const char *text, int *year, int *month, int *day,
298→                          int *hour, int *minute, size_t *date_start,
299→                          size_t *date_end, size_t *time_start,
300→                          size_t *time_end)
301→{
302→  const char *day_mark = first_of(text, "号", "日");
303→  const char *month_mark = strstr(text, "月");
304→  const char *time_mark;
305→  const char *minute_mark;
306→  const char *year_mark;
307→  size_t year_start = 0;
308→  size_t day_start;
309→  size_t hour_start;
310→  size_t month_start = 0;
311→  int explicit_month = 0;
312→  int explicit_year = 0;
313→  int month_value = 0;
314→  int year_value = 0;
315→  int day_value;
316→  int hour_value;
317→  int minute_value = 0;
318→  time_t now;
319→  struct tm current;
320→  struct tm target_tm;
321→  time_t target;
322→  struct tm verify;
323→
324→  if (!day_mark || !parse_number_before(text, (size_t)(day_mark - text),
325→                                        &day_start, &day_value) ||
326→      day_value < 1 || day_value > 31)
327→    {
328→      return 0;
329→    }
330→  if (month_mark && month_mark < day_mark &&
331→      parse_number_before(text, (size_t)(month_mark - text), &month_start,
332→                          &month_value) && month_value >= 1 &&
333→      month_value <= 12)
334→    {
335→      explicit_month = 1;
336→    }
337→  else
338→    {
339→      month_mark = NULL;
340→    }
341→
342→  year_mark = month_mark ? strstr(text, "年") : NULL;
343→  if (year_mark && year_mark < month_mark &&
344→      parse_number_before(text, (size_t)(year_mark - text), &year_start,
345→                          &year_value) && year_value >= 2024 &&
346→      year_value <= 2099)
347→    {
348→      explicit_year = 1;
349→    }
350→  time_mark = first_of(day_mark + 3, "点", "时");
351→  if (!time_mark ||
352→      !parse_number_before(text, (size_t)(time_mark - text), &hour_start,
353→                           &hour_value) || hour_value < 0 || hour_value > 23)
354→    {
355→      return 0;
356→    }
357→
358→  minute_value = 0;
359→  minute_mark = strstr(time_mark + 3, "分");
360→  if (minute_mark)
361→    {
362→      size_t minute_start;
363→      int parsed_minute;
364→      if (parse_number_before(text, (size_t)(minute_mark - text),
365→                              &minute_start, &parsed_minute) &&
366→          minute_start >= (size_t)(time_mark + 3 - text) &&
367→          parsed_minute >= 0 && parsed_minute <= 59)
368→        {
369→          minute_value = parsed_minute;
370→        }
371→    }
372→  else if (strncmp(time_mark + 3, "半", 3) == 0)
373→    {
374→      minute_value = 30;
375→    }
376→
377→  now = time(NULL);
378→  localtime_r(&now, &current);
379→  if (current.tm_year + 1900 < 2024)
380→    {
381→      return -1;
382→    }
383→  *year = explicit_year ? year_value : current.tm_year + 1900;
384→  *month = explicit_month ? month_value : current.tm_mon + 1;
385→  *day = day_value;
386→  *hour = hour_value;
387→  *minute = minute_value;
388→
389→  memset(&target_tm, 0, sizeof(target_tm));
390→  target_tm.tm_year = *year - 1900;
391→  target_tm.tm_mon = *month - 1;
392→  target_tm.tm_mday = *day;
393→  target_tm.tm_hour = *hour;
394→  target_tm.tm_min = *minute;
395→  target_tm.tm_isdst = -1;
396→  target = mktime(&target_tm);
397→  if (target == (time_t)-1)
398→    {
399→      return 0;
400→    }
401→  localtime_r(&target, &verify);
402→  if (verify.tm_year != *year - 1900 || verify.tm_mon != *month - 1 ||
403→      verify.tm_mday != *day || verify.tm_hour != *hour ||
404→      verify.tm_min != *minute)
405→    {
406→      return 0;
407→    }
408→
409→  /* An unspecified month/year means the next occurrence; an explicitly
410→   * supplied month but no year also rolls to next year if already past. */
411→  if (target <= now && !explicit_year)
412→    {
413→      if (explicit_month)
414→        {
415→          (*year)++;
416→        }
417→      else
418→        {
419→          (*month)++;
420→          if (*month > 12)
421→            {
422→              *month = 1;
423→              (*year)++;
424→            }
425→        }
426→      memset(&target_tm, 0, sizeof(target_tm));
427→      target_tm.tm_year = *year - 1900;
428→      target_tm.tm_mon = *month - 1;
429→      target_tm.tm_mday = *day;
430→      target_tm.tm_hour = *hour;
431→      target_tm.tm_min = *minute;
432→      target_tm.tm_isdst = -1;
433→      target = mktime(&target_tm);
434→      if (target == (time_t)-1)
435→        {
436→          return 0;
437→        }
438→      localtime_r(&target, &verify);
439→      if (verify.tm_year != *year - 1900 || verify.tm_mon != *month - 1 ||
440→          verify.tm_mday != *day || verify.tm_hour != *hour ||
441→          verify.tm_min != *minute)
442→        {
443→          return 0;
444→        }
445→    }
446→
447→  if (date_start)
448→    {
449→      *date_start = explicit_year ? year_start
450→                                  : (explicit_month ? month_start : day_start);
451→    }
452→  if (date_end)
453→    {
454→      *date_end = (size_t)(day_mark - text) + 3;
455→    }
456→  if (time_start)
457→    {
458→      *time_start = hour_start;
459→    }
460→  if (time_end)
461→    {
462→      *time_end = (minute_mark ? (size_t)(minute_mark - text) + 3
463→                               : (size_t)(time_mark - text) + 3 +
464→                                 (minute_value == 30 ? 3 : 0));
465→    }
466→  return 1;
467→}
