592→static int parse_intent(const char *text, assistant_intent_t *intent)
593→{
594→  static const char *const note_triggers[] = {
595→    "帮我记一下", "记一下", "记下来", "记一个", "记个", "备忘里"
596→  };
597→  static const char *const reminder_triggers[] = {
598→    "提醒", "闹钟", "倒数日", "记一下", "记一个", "计一个", "安排"
599→  };
600→  static const char *const mood_words[] = {
601→    "不开心", "心情不好", "难过", "伤心", "焦虑", "压力大", "很累",
602→    "疲惫", "孤独", "烦躁", "沮丧"
603→  };
604→  size_t date_start = 0;
605→  size_t date_end = 0;
606→  size_t time_start = 0;
607→  size_t time_end = 0;
608→  int has_dt;
609→  int minutes;
610→
611→  memset(intent, 0, sizeof(*intent));
612→
613→  has_dt = parse_datetime(text, &intent->year, &intent->month, &intent->day,
614→                          &intent->hour, &intent->minute, &date_start,
615→                          &date_end, &time_start, &time_end);
616→  if (has_dt == 1 &&
617→      contains_any(text, reminder_triggers,
618→                   sizeof(reminder_triggers) / sizeof(reminder_triggers[0])))
619→    {
620→      intent->type = INTENT_COUNTDOWN;
621→      clean_reminder_name(text, date_start, date_end, time_start, time_end,
622→                          intent->text, sizeof(intent->text));
623→      return 1;
624→    }
625→
626→  if (contains_any(text, note_triggers,
627→                   sizeof(note_triggers) / sizeof(note_triggers[0])))
628→    {
629→      const char *trigger = NULL;
630→      size_t trigger_len = 0;
631→      size_t i;
632→      for (i = 0; i < sizeof(note_triggers) / sizeof(note_triggers[0]); i++)
633→        {
634→          const char *found = strstr(text, note_triggers[i]);
635→          if (found && (!trigger || found < trigger))
636→            {
637→              trigger = found;
638→              trigger_len = strlen(note_triggers[i]);
639→            }
640→        }
641→      if (trigger)
642→        {
643→          const char *content = trigger + trigger_len;
644→          while (*content == ' ' || *content == '\t' || *content == ':' ||
645→                 *content == ',' || *content == '，' || *content == '：')
646→            {
647→              content++;
648→            }
649→          while (strncmp(content, "我", 3) == 0 ||
650→                 strncmp(content, "一下", 6) == 0 ||
651→                 strncmp(content, "记得", 6) == 0)
652→            {
653→              content += strncmp(content, "我", 3) == 0 ? 3 : 6;
654→            }
655→          if (!*content)
656→            {
657→              return 0;
658→            }
659→          intent->type = INTENT_NOTE;
660→          snprintf(intent->text, sizeof(intent->text), "%s", content);
661→          return 1;
662→        }
663→    }
664→
665→  if ((strstr(text, "专注") || strstr(text, "计时") || strstr(text, "番茄钟")) &&
666→      parse_duration_minutes(text, &minutes))
667→    {
668→      intent->type = INTENT_FOCUS;
669→      intent->minutes = minutes;
670→      return 1;
671→    }
672→
673→  if (contains_any(text, mood_words, sizeof(mood_words) / sizeof(mood_words[0])))
674→    {
675→      intent->type = INTENT_MOOD;
676→      snprintf(intent->text, sizeof(intent->text), "%s", text);
677→      return 1;
678→    }
679→
680→  return 0;
681→}
