174→    }
175→  if (!saw)
176→    {
177→      return 0;
178→    }
179→  if (number >= 0)
180→    {
181→      section += number;
182→    }
183→  total += section;
184→  if (total > 10000)
185→    {
186→      return 0;
187→    }
188→  *value = total;
189→  return 1;
190→}
