192→static int parse_number_before(const char *text, size_t end, size_t *start,
193→                               int *value)
194→{
195→  size_t begin = end;
196→  size_t cursor;
197→
198→  while (begin > 0)
199→    {
200→      int ignored;
201→      if (isdigit((unsigned char)text[begin - 1]))
202→        {
203→          begin--;
204→          continue;
205→        }
206→      if (begin >= 3 &&
207→          (chinese_digit(text + begin - 3, 3, &ignored) ||
208→           chinese_unit(text + begin - 3, 3, &ignored)))
209→        {
210→          begin -= 3;
211→          continue;
212→        }
213→      break;
214→    }
215→  cursor = begin;
216→  if (!parse_number_slice(text, begin, end, value))
217→    {
218→      return 0;
219→    }
220→  if (start)
221→    {
222→      *start = cursor;
223→    }
224→  return 1;
225→}
226→
227→static const char *first_of(const char *text, const char *a, const char *b)
228→{
229→  const char *pa = a ? strstr(text, a) : NULL;
230→  const char *pb = b ? strstr(text, b) : NULL;
231→  if (!pa)
232→    {
233→      return pb;
234→    }
235→  if (!pb)
236→    {
237→      return pa;
238→    }
239→  return pa < pb ? pa : pb;
240→}
