520→static void clean_reminder_name(const char *text, size_t date_start,
521→                                size_t date_end, size_t time_start,
522→                                size_t time_end, char *out, size_t cap)
523→{
524→  char tmp[INTENT_TEXT_MAX];
525→  size_t len = strlen(text);
526→  size_t start = date_start;
527→  size_t end = date_end;
528→  size_t tstart = time_start;
529→  size_t tend = time_end;
530→  size_t out_len = 0;
531→  static const char *const leading[] = {
532→    "帮我设置提醒", "帮我", "给我", "提醒一下", "提醒我", "我提醒我", "倒数日",
533→    "记一个", "计一个", "记一下", "记下来", "在", "请", "把", "到时候"
534→  };
535→  size_t i;
536→
537→  if (len >= sizeof(tmp))
538→    {
539→      snprintf(out, cap, "%s", "提醒事项");
540→      return;
541→    }
542→  memcpy(tmp, text, len);
543→  tmp[len] = '\0';
544→
545→  if (tstart >= end)
546→    {
547→      memmove(tmp + tstart, tmp + tend, len - tend + 1);
548→      len -= tend - tstart;
549→      memmove(tmp + start, tmp + end, len - end + 1);
550→      len -= end - start;
551→    }
552→  else if (start >= tend)
553→    {
554→      memmove(tmp + start, tmp + end, len - end + 1);
555→      len -= end - start;
556→      memmove(tmp + tstart, tmp + tend, len - tend + 1);
557→      len -= tend - tstart;
558→    }
559→  else
560→    {
561→      memmove(tmp + start, tmp + end, len - end + 1);
562→      len -= end - start;
563→      if (tstart > end)
564→        {
565→          tstart -= end - start;
566→          tend -= end - start;
567→        }
568→      memmove(tmp + tstart, tmp + tend, len - tend + 1);
569→      len -= tend - tstart;
570→    }
571→
572→  while (len > 0)
573→    {
574→      int changed = 0;
575→      while (len > 0 && (tmp[0] == ' ' || tmp[0] == '\t' || tmp[0] == ',' ||
576→                         tmp[0] == ':' || tmp[0] == '-'))
577→        {
578→          memmove(tmp, tmp + 1, len);
579→          len--;
580→        }
581→      while (len >= 3 &&
582→             (memcmp(tmp, "，", 3) == 0 || memcmp(tmp, "：", 3) == 0 ||
583→              memcmp(tmp, "、", 3) == 0))
584→        {
585→          memmove(tmp, tmp + 3, len - 2);
586→          len -= 3;
587→        }
588→      for (i = 0; i < sizeof(leading) / sizeof(leading[0]); i++)
589→        {
590→          size_t n = strlen(leading[i]);
591→          if (len >= n && memcmp(tmp, leading[i], n) == 0)
592→            {
593→              memmove(tmp, tmp + n, len - n + 1);
594→              len -= n;
595→              changed = 1;
596→              break;
597→            }
598→        }
599→      if (!changed)
600→        {
601→          break;
602→        }
603→    }
604→  trim_reminder_clutter(tmp, &len);
605→  trim_reminder_punctuation(tmp, &len);
606→
607→  if (len == 0)
608→    {
609→      snprintf(out, cap, "%s", "提醒事项");
610→      return;
611→    }
612→  out_len = len < cap - 1 ? len : cap - 1;
613→  if (out_len < len)
614→    {
615→      while (out_len > 0 && ((unsigned char)tmp[out_len] & 0xc0u) == 0x80u)
616→        {
617→          out_len--;
618→        }
619→    }
620→  memcpy(out, tmp, out_len);
621→  out[out_len] = '\0';
622→}
