744→static int run_intent(const assistant_intent_t *intent, char *reply, size_t cap)
745→{
746→  int rc;
747→  switch (intent->type)
748→    {
749→      case INTENT_FOCUS:
750→        rc = dm_focus_start_minutes(intent->minutes);
751→        if (rc == 0)
752→          {
753→            snprintf(reply, cap, "好，%d分钟专注已开始。我陪你。",
754→                     intent->minutes);
755→            return 0;
756→          }
757→        snprintf(reply, cap, "已有专注计时正在进行，我没有重置它。先结束当前专注再试。");
758→        return -1;
759→
760→      case INTENT_COUNTDOWN:
761→        rc = dm_countdown_add_voice(intent->text, intent->year, intent->month,
762→                                    intent->day, intent->hour,
763→                                    intent->minute);
764→        if (rc == 0)
765→          {
766→            snprintf(reply, cap, "记好了：%s，%d月%d日%02d:%02d提醒你。",
767→                     intent->text, intent->month, intent->day, intent->hour,
768→                     intent->minute);
769→            return 0;
770→          }
771→        if (rc == -2)
772→          {
773→            snprintf(reply, cap, "倒数日列表已满，暂时不能添加。请先删除一项。");
774→          }
775→        else if (rc == -4)
776→          {
777→            snprintf(reply, cap, "设备日期时间还没校准，无法设置准确提醒。");
778→          }
779→        else
780→          {
781→            snprintf(reply, cap, "提醒没有保存成功，请检查日期后再试。");
782→          }
783→        return -1;
784→
785→      case INTENT_NOTE:
786→        rc = dm_note_add_voice(intent->text);
787→        if (rc == 0)
788→          {
789→            snprintf(reply, cap, "%s", "记下了，已经保存到备忘。");
790→            return 0;
791→          }
792→        if (rc == -2)
793→          {
794→            snprintf(reply, cap, "备忘已满，暂时不能添加。请先删除一条。");
795→          }
796→        else
797→          {
798→            snprintf(reply, cap, "这条备忘没有保存成功，请再说短一点。");
799→          }
800→        return -1;
801→
802→      case INTENT_MOOD:
803→        dm_health_voice_advice(intent->text, reply, (int)cap);
804→        return 0;
805→
806→      case INTENT_TIME_ERROR:
807→        snprintf(reply, cap, "设备日期时间还没同步或校准，我没有创建提醒。请先在设置中校准时间后再试。");
808→        return -1;
809→
810→      default:
811→        return -1;
812→    }
813→}
