159→static void step_cb(lv_event_t *e)
160→{
161→  int delta = (int)(uintptr_t)lv_event_get_user_data(e);
162→
163→  if (delta > 0)
164→    {
165→      g_dm.focus_custom_min = focus_custom_next(g_dm.focus_custom_min);
166→    }
167→  else
168→    {
169→      g_dm.focus_custom_min = focus_custom_prev(g_dm.focus_custom_min);
170→    }
171→
172→  if (g_dm.focus_custom_min < 1)
173→    {
174→      g_dm.focus_custom_min = 1;
175→    }
176→  if (g_dm.focus_custom_min > 120)
177→    {
178→      g_dm.focus_custom_min = 120;
179→    }
180→  apply_minutes(g_dm.focus_custom_min);
181→  mark_preset(4);
182→}
