1607→static int voice_asr_chat_tts_unlocked(const char *wav_path, char *reply,
1608→                                       int cap)
1609→{
1610→  char text[256];
1611→  const char *asr_path;
1612→  int play_rc = -1;
1613→  int intent_handled;
1614→
1615→  if (!wav_path || !reply || cap < 8)
1616→    {
1617→      return -1;
1618→    }
1619→  s_last_failure = DM_VOICE_FAILURE_NONE;
1620→  reply[0] = '\0';
1621→
1622→  if (voice_prepare_wav(wav_path, &asr_path) != 0)
1623→    {
1624→      s_last_failure = DM_VOICE_FAILURE_ASR;
1625→      s_st = DM_VOICE_ERR;
1626→      return -1;
1627→    }
1628→
1629→  s_st = DM_VOICE_ASR;
1630→  if (asr_wav(asr_path, text, sizeof(text)) != 0)
1631→    {
1632→      if (s_last_failure == DM_VOICE_FAILURE_NONE)
1633→        {
1634→          s_last_failure = DM_VOICE_FAILURE_ASR;
1635→        }
1636→      s_st = DM_VOICE_ERR;
1637→      return -1;
1638→    }
1639→
1640→  s_st = DM_VOICE_CHAT;
1641→  intent_handled = dm_assistant_intent_try(text, reply, cap);
1642→  if (intent_handled > 0)
1643→    {
1644→      dm_chat_hist_push(text, reply);
1645→    }
1646→  else if (chat_reply(text, reply, cap) != 0)
1647→    {
1648→      if (s_last_failure == DM_VOICE_FAILURE_NONE)
1649→        {
1650→          s_last_failure = DM_VOICE_FAILURE_CHAT;
1651→        }
1652→      strncpy(reply, "（网络忙，没听清）", (size_t)cap - 1);
1653→      reply[cap - 1] = '\0';
1654→      s_st = DM_VOICE_ERR;
1655→      return -1;
1656→    }
1657→
1658→  /* Preserve the text answer even if playback fails; the caller can show
1659→   * that the reply is text-only rather than pretending the speaker worked. */
1660→  s_st = DM_VOICE_TTS;
1661→  if (tts_synth(reply, WAV_TTS, dm_voice_profile_api_id()) == 0)
1662→    {
1663→      s_st = DM_VOICE_PLAY;
1664→      play_rc = play_wav(WAV_TTS);
1665→    }
1666→  else if (s_last_failure == DM_VOICE_FAILURE_NONE)
1667→    {
1668→      s_last_failure = DM_VOICE_FAILURE_TTS;
1669→    }
1670→  s_st = DM_VOICE_IDLE;
1671→  return play_rc == 0 ? 0 : 1;
1672→}
1673→
1674→int dm_voice_asr_chat_tts(const char *wav_path, char *reply, int cap)
1675→{
1676→  int rc;
1677→
1678→  pthread_mutex_lock(&s_voice_api_lock);
1679→  rc = voice_asr_chat_tts_unlocked(wav_path, reply, cap);
1680→  pthread_mutex_unlock(&s_voice_api_lock);
1681→  return rc;
1682→}
