415→void dm_chat_tick(void)
416→{
417→  /* apply worker results on LVGL thread */
418→  if (s_out_ready)
419→    {
420→      s_out_ready = 0;
421→      if (s_out_ans[0])
422→        {
423→          set_ans(s_out_ans);
424→        }
425→      if (s_out_sub[0])
426→        {
427→          set_sub(s_out_sub);
428→        }
429→      dm_face_set(FACE_HAPPY, EYE_DECOR_NONE, 8);
430→      reset_to_idle();
431→    }
432→
433→  if (s_ui_rec && !s_busy)
434→    {
435→      char buf[80];
436→      uint64_t now_ms = chat_monotonic_ms();
437→      if (s_rec_started_ms != 0 && now_ms >= s_rec_started_ms)
438→        {
439→          s_rec_sec = (int)((now_ms - s_rec_started_ms) / 1000);
440→        }
441→      if (dm_voice_rec_active())
442→        {
443→          snprintf(buf, sizeof(buf),
444→                   dm_t("● 录音中 %d 秒 · 再点一下结束并发送",
445→                        "● Recording %ds · tap again to send"),
446→                   s_rec_sec);
447→          set_ans(buf);
448→          set_sub((s_rec_sec & 1) ? dm_t("正在听…", "Listening…")
449→                                  : dm_t("对准麦克风说话", "Speak to the mic"));
450→        }
451→      else
452→        {
453→          s_ui_rec = false;
454→          if (s_rec_sec < 2)
455→            {
456→              s_mic_err = 1;
457→              set_ans(dm_t("麦克风故障，无法录音", "Mic failed"));
458→              set_sub(dm_t("检查 /dev/audio/pcm0c", "Check mic device"));
459→              reset_to_idle();
460→            }
461→          else
462→            {
463→              /* Recording auto-stop reached the configured limit.  Send the
464→               * captured WAV instead of silently discarding it. */
465→              kick_job(1);
466→            }
467→        }
468→    }
469→}
