275→static void n24_hint_cb(lv_event_t *e)
276→{
277→  n24_t a[4];
278→  char out[96];
279→  int i;
280→  (void)e;
281→
282→  for (i = 0; i < 4; i++)
283→    {
284→      a[i].v = (double)s_n4[i];
285→      snprintf(a[i].s, sizeof(a[i].s), "%d", s_n4[i]);
286→    }
287→  out[0] = 0;
288→  if (n24_try(a, 4, out, sizeof(out)))
289→    {
290→      if (s_n4_hint)
291→        {
292→          lv_label_set_text(s_n4_hint, out);
293→        }
294→    }
295→  else if (s_n4_hint)
296→    {
297→      lv_label_set_text(s_n4_hint, "这组无解，下一局吧");
298→    }
299→}
