391→static void draw_line(int x0, int y0, int x1, int y1)
392→{
393→  int dx = abs(x1 - x0);
394→  int dy = abs(y1 - y0);
395→  int sx = x0 < x1 ? 1 : -1;
396→  int sy = y0 < y1 ? 1 : -1;
397→  int err = dx - dy;
398→  for (;;)
399→    {
400→      draw_dot(x0, y0);
401→      if (x0 == x1 && y0 == y1)
402→        {
403→          break;
404→        }
405→      {
406→        int e2 = 2 * err;
407→        if (e2 > -dy)
408→          {
409→            err -= dy;
410→            x0 += sx;
411→          }
412→        if (e2 < dx)
413→          {
414→            err += dx;
415→            y0 += sy;
416→          }
417→        }
418→    }
419→}
