223→static void calc_eval(void)
224→{
225→  double r;
226→
227→  if (!s_calc_op)
228→    {
229→      s_calc_just_eq = true;
230→      calc_show();
231→      return;
232→    }
233→
234→  if (s_calc_typing)
235→    {
236→      r = calc_do(s_calc_acc, s_calc_op, atof(s_calc_cur));
237→    }
238→  else
239→    {
240→      r = calc_do(s_calc_acc, s_calc_op, s_calc_acc);
241→    }
242→
243→  calc_fmt(r, s_calc_cur, sizeof(s_calc_cur));
244→  {
245→    size_t n = strlen(s_calc_expr);
246→    snprintf(s_calc_expr + n, sizeof(s_calc_expr) - n, " %s =",
247→             s_calc_cur);
248→  }
249→  s_calc_acc = r;
250→  s_calc_op = 0;
251→  s_calc_typing = false;
252→  s_calc_just_eq = true;
253→  calc_show();
254→}
