282→static void calc_sign(void)
283→{
284→  if (strcmp(s_calc_cur, "0") == 0 || strcmp(s_calc_cur, "ERR") == 0)
285→    {
286→      return;
287→    }
288→  if (s_calc_cur[0] == '-')
289→    {
290→      memmove(s_calc_cur, s_calc_cur + 1, strlen(s_calc_cur));
291→    }
292→  else
293→    {
294→      char tmp[CALC_CUR_MAX];
295→      snprintf(tmp, sizeof(tmp), "-%s", s_calc_cur);
296→      snprintf(s_calc_cur, sizeof(s_calc_cur), "%s", tmp);
297→    }
298→  calc_show();
299→}
