301→static void calc_key_cb(lv_event_t *e)
302→{
303→  const char *k = (const char *)lv_event_get_user_data(e);
304→  if (!k || !k[0])
305→    {
306→      return;
307→    }
308→  if (strcmp(k, "C") == 0)
309→    {
310→      calc_reset();
311→    }
312→  else if (strcmp(k, "BS") == 0)
313→    {
314→      calc_back();
315→    }
316→  else if (strcmp(k, "SG") == 0)
317→    {
318→      calc_sign();
319→    }
320→  else if (strcmp(k, "=") == 0)
321→    {
322→      calc_eval();
323→    }
324→  else if (k[1] == 0 && strchr("+-*/", k[0]))
325→    {
326→      calc_op(k[0]);
327→    }
328→  else if (k[1] == 0 && (k[0] == '.' || (k[0] >= '0' && k[0] <= '9')))
329→    {
330→      calc_digit(k[0]);
331→    }
332→}
