220→static int json_escape(const char *in, char *out, size_t cap)
221→{
222→  size_t o = 0;
223→  size_t i;
224→
225→  if (!in || !out || cap < 2)
226→    {
227→      return -1;
228→    }
229→  for (i = 0; in[i] && o + 8 < cap; i++)
230→    {
231→      unsigned char ch = (unsigned char)in[i];
232→      if (ch == '"' || ch == '\\')
233→        {
234→          out[o++] = '\\';
235→          out[o++] = (char)ch;
236→        }
237→      else if (ch == '\n')
238→        {
239→          out[o++] = '\\';
240→          out[o++] = 'n';
241→        }
242→      else if (ch < 0x20)
243→        {
244→          /* skip control chars */
245→        }
246→      else
247→        {
248→          out[o++] = (char)ch;
249→        }
250→    }
251→  out[o] = '\0';
252→  return (int)o;
253→}
