295→  int parts = 0;
296→  int rc;
297→
298→  if (!minute_word)
299→    {
300→      minute_word = strstr(text, "分");
301→    }
302→  rc = parse_duration_part(text, hour_word, 6, 60 * 60, 1, &total);
303→  if (rc < 0)
304→    {
305→      return 0;
