1027→  int i;
1028→
1029→  if (!text || !text[0] || !reply || reply_cap < 8)
1030→    {
1031→      return 0;
1032→    }
1033→  parsed_ok = parse_intent(text, &parsed);
1034→
1035→  pthread_mutex_lock(&s_intent_lock);
1036→  if (!parsed_ok && s_waiting_game_choice)
1037→    {
1038→      game_page = game_page_from_text(text);
1039→      if (game_page != PAGE_COUNT)
1040→        {
1041→          memset(&parsed, 0, sizeof(parsed));
1042→          parsed.type = INTENT_GAME;
1043→          parsed.game_page = game_page;
1044→          parsed_ok = 1;
1045→        }
1046→      else if (contains_any(text, cancel_game_words,
1047→                            sizeof(cancel_game_words) /
1048→                              sizeof(cancel_game_words[0])))
1049→        {
1050→          memset(&parsed, 0, sizeof(parsed));
1051→          parsed.type = INTENT_GAME_CANCEL;
1052→          parsed_ok = 1;
1053→        }
1054→    }
1055→  if (!parsed_ok)
1056→    {
1057→      pthread_mutex_unlock(&s_intent_lock);
1058→      return 0;
1059→    }
1060→  if (s_intent_active)
1061→    {
1062→      pthread_mutex_unlock(&s_intent_lock);
1063→      return 0;
1064→    }
1065→  s_intent = parsed;
1066→  s_intent_active = 1;
1067→  s_intent_executing = 0;
1068→  s_intent_done = 0;
1069→  s_intent_reply[0] = '\0';
1070→  pthread_mutex_unlock(&s_intent_lock);
1071→
1072→  for (i = 0; i < INTENT_WAIT_STEPS; i++)
1073→    {
1074→      int done;
1075→      usleep(INTENT_WAIT_US);
1076→      pthread_mutex_lock(&s_intent_lock);
1077→      done = s_intent_done;
1078→      if (done)
1079→        {
1080→          snprintf(reply, (size_t)reply_cap, "%s", s_intent_reply);
1081→          s_intent_active = 0;
1082→          s_intent_done = 0;
1083→          pthread_mutex_unlock(&s_intent_lock);
1084→          return 1;
1085→        }
1086→      pthread_mutex_unlock(&s_intent_lock);
1087→    }
1088→
1089→  pthread_mutex_lock(&s_intent_lock);
1090→  if (!s_intent_executing)
1091→    {
1092→      s_intent_active = 0;
1093→      s_intent_done = 0;
1094→      pthread_mutex_unlock(&s_intent_lock);
1095→      return 0;
1096→    }
1097→  pthread_mutex_unlock(&s_intent_lock);
1098→
1099→  /* An operation already started on the LVGL thread; allow it to finish. */
1100→  for (i = 0; i < 40; i++)
1101→    {
1102→      usleep(INTENT_WAIT_US);
1103→      pthread_mutex_lock(&s_intent_lock);
1104→      if (s_intent_done)
1105→        {
1106→          snprintf(reply, (size_t)reply_cap, "%s", s_intent_reply);
1107→          s_intent_active = 0;
1108→          s_intent_done = 0;
1109→          pthread_mutex_unlock(&s_intent_lock);
1110→          return 1;
1111→        }
1112→      pthread_mutex_unlock(&s_intent_lock);
1113→    }
1114→  pthread_mutex_lock(&s_intent_lock);
1115→  s_intent_active = 0;
1116→  s_intent_executing = 0;
1117→  s_intent_done = 0;
1118→  pthread_mutex_unlock(&s_intent_lock);
1119→  return 0;
1120→}
