143→
144→  for (i = 0; i < 4; i++)
145→    {
146→      int dx = (i < 2) ? (i * dw) : (i * dw + gap_colon);
147→      clip_setup(&c->d[i], c->box, dx, 0, dw, h, font);
148→    }
149→
150→  colon_x = 2 * dw + gap_colon / 4;
151→  c->colon = lv_label_create(c->box);
152→  lv_label_set_text(c->colon, ":");
153→  dm_style(c->colon, font, C_DIM);
154→  lv_obj_set_pos(c->colon, colon_x, 0);
155→
156→  /* Durations above 99 minutes use a centered text label instead of clipping
157→   * the three-digit minute value in the four-wheel MM:SS layout. */
158→  c->wide = lv_label_create(c->box);
159→  lv_label_set_text(c->wide, "");
160→  dm_style(c->wide, font, C_INK);
161→  lv_obj_set_width(c->wide, w);
162→  lv_obj_set_style_text_align(c->wide, LV_TEXT_ALIGN_CENTER, LV_PART_MAIN);
163→  lv_obj_center(c->wide);
164→  lv_obj_add_flag(c->wide, LV_OBJ_FLAG_HIDDEN);
