165→        override fun onServicesDiscovered(g: BluetoothGatt, status: Int) {
166→            onMain {
167→                if (status != BluetoothGatt.GATT_SUCCESS) {
168→                    fail("发现服务失败，状态码 " + status)
169→                    closeGatt()
170→                    return@onMain
171→                }
172→                val service = g.getService(BleProtocol.SERVICE_UUID)
173→                if (service == null) {
174→                    fail("没有找到专属 Service UUID，请确认连接的是 Gemini S1")
175→                    closeGatt()
176→                    return@onMain
177→                }
178→                authChar = service.getCharacteristic(BleProtocol.CHAR_AUTH)
179→                cmdChar = service.getCharacteristic(BleProtocol.CHAR_CMD)
180→                statusChar = service.getCharacteristic(BleProtocol.CHAR_STATUS)
181→                if (authChar == null) {
182→                    fail("专属服务缺少 AUTH 特征")
183→                    closeGatt()
184→                    return@onMain
185→                }
186→                queue = GattQueue(g) { message ->
187→                    if (message != null) log("GATT: " + message)
188→                }
189→                enableNotifications(g, authChar)
190→                enableNotifications(g, cmdChar)
191→                enableNotifications(g, statusChar)
192→                _state.update {
193→                    it.copy(
194→                        connState = ConnState.READY,
195→                        statusText = "服务就绪，可以配对",
196→                        hint = "等待板子下发 challenge，或点「配对」主动请求"
197→                    )
198→                }
199→                log("服务发现完成，已订阅配对/状态通知")
200→            }
201→        }
202→
203→        override fun onCharacteristicChanged(
204→            g: BluetoothGatt,
205→            c: BluetoothGattCharacteristic,
206→            value: ByteArray
207→        ) {
208→            onMain { handleNotification(value) }
209→        }
210→
211→        @Deprecated("Deprecated in API 33, kept for Android 12/13 compatibility")
212→        override fun onCharacteristicChanged(g: BluetoothGatt, c: BluetoothGattCharacteristic) {
213→            val value = c.value ?: ByteArray(0)
214→            onMain { handleNotification(value) }
215→        }
216→
217→        override fun onCharacteristicWrite(
218→            g: BluetoothGatt,
219→            c: BluetoothGattCharacteristic,
220→            status: Int
221→        ) {
222→            onMain {
223→                if (pendingPairAck && c.uuid == ackCharUuid) {
224→                    pendingPairAck = false
225→                    handler.removeCallbacks(pairTimeout)
226→                    if (status == BluetoothGatt.GATT_SUCCESS) {
227→                        onPairSuccess()
228→                    } else {
229→                        onPairFailed("ACK 写入失败，状态码 " + status)
230→                    }
231→                }
232→                queue?.onOperationFinished(
233→                    if (status == BluetoothGatt.GATT_SUCCESS) null else "写入失败，状态码 " + status
234→                )
235→            }
236→        }
237→
238→        override fun onDescriptorWrite(
239→            g: BluetoothGatt,
240→            d: BluetoothGattDescriptor,
241→            status: Int
242→        ) {
243→            onMain {
244→                queue?.onOperationFinished(
245→                    if (status == BluetoothGatt.GATT_SUCCESS) null else "订阅失败，状态码 " + status
246→                )
247→            }
248→        }
249→    }
