610→    private fun enableNotifications(g: BluetoothGatt, c: BluetoothGattCharacteristic?) {
611→        if (c == null) return
612→        val props = c.properties
613→        val notify = (props and BluetoothGattCharacteristic.PROPERTY_NOTIFY) != 0
614→        val indicate = (props and BluetoothGattCharacteristic.PROPERTY_INDICATE) != 0
615→        if (!notify && !indicate) return
616→        try {
617→            g.setCharacteristicNotification(c, true)
618→            val cccd = c.getDescriptor(BleProtocol.CCCD_UUID)
619→            if (cccd == null) {
620→                log("特征 " + c.uuid.toString().takeLast(4) + " 没有 CCCD，无法订阅")
621→                return
622→            }
623→            val value = if (notify) {
624→                BluetoothGattDescriptor.ENABLE_NOTIFICATION_VALUE
625→            } else {
626→                BluetoothGattDescriptor.ENABLE_INDICATION_VALUE
627→            }
628→            queue?.enqueue(GattOp.WriteDescriptor(cccd, value, "订阅 " + c.uuid.toString().takeLast(4)))
629→        } catch (e: SecurityException) {
630→            log("订阅通知失败：蓝牙权限被拒绝")
631→        }
632→    }
