634→    private fun writeCharacteristic(c: BluetoothGattCharacteristic, value: ByteArray, label: String) {
635→        if (!hasConnectPermission()) {
636→            log(label + "：缺少蓝牙连接权限")
637→            return
638→        }
639→        val q = queue
640→        if (q == null) {
641→            log(label + "：GATT 队列未就绪")
642→            return
643→        }
644→        q.enqueue(GattOp.WriteCharacteristic(c, value, label))
645→    }
