738→private sealed class GattOp {
739→    abstract val label: String
740→
741→    data class WriteCharacteristic(
742→        val characteristic: BluetoothGattCharacteristic,
743→        val value: ByteArray,
744→        override val label: String,
745→        val writeType: Int = BluetoothGattCharacteristic.WRITE_TYPE_DEFAULT
746→    ) : GattOp()
747→
748→    data class WriteDescriptor(
749→        val descriptor: BluetoothGattDescriptor,
750→        val value: ByteArray,
751→        override val label: String
752→    ) : GattOp()
753→}
754→
755→/** 串行执行 GATT 操作：Android 同一时刻只允许一个 GATT 写操作。 */
756→private class GattQueue(
757→    private val gatt: BluetoothGatt,
758→    private val onMessage: (String?) -> Unit
759→) {
760→    private val pending = ArrayDeque<GattOp>()
761→    private var busy = false
762→
763→    fun enqueue(op: GattOp) {
764→        pending.addLast(op)
765→        pump()
766→    }
767→
768→    fun onOperationFinished(error: String?) {
769→        busy = false
770→        if (error != null) onMessage(error)
771→        pump()
772→    }
773→
774→    private fun pump() {
775→        if (busy) return
776→        val op = pending.removeFirstOrNull() ?: return
777→        busy = true
778→        val ok = when (op) {
779→            is GattOp.WriteCharacteristic -> writeCharacteristic(op)
780→            is GattOp.WriteDescriptor -> writeDescriptor(op)
781→        }
782→        if (!ok) {
783→            busy = false
784→            onMessage(op.label + "：GATT 忙或写入被拒绝")
785→            pump()
786→        }
787→    }
788→
789→    private fun writeCharacteristic(op: GattOp.WriteCharacteristic): Boolean {
790→        return try {
791→            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
792→                gatt.writeCharacteristic(op.characteristic, op.value, op.writeType) == BluetoothStatusCodes.SUCCESS
793→            } else {
794→                @Suppress("DEPRECATION")
795→                op.characteristic.value = op.value
796→                @Suppress("DEPRECATION")
797→                op.characteristic.writeType = op.writeType
798→                @Suppress("DEPRECATION")
799→                gatt.writeCharacteristic(op.characteristic)
800→            }
801→        } catch (e: SecurityException) {
802→            false
803→        }
804→    }
805→
806→    private fun writeDescriptor(op: GattOp.WriteDescriptor): Boolean {
807→        return try {
808→            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
809→                gatt.writeDescriptor(op.descriptor, op.value) == BluetoothStatusCodes.SUCCESS
810→            } else {
811→                @Suppress("DEPRECATION")
812→                op.descriptor.value = op.value
813→                @Suppress("DEPRECATION")
814→                gatt.writeDescriptor(op.descriptor)
815→            }
816→        } catch (e: SecurityException) {
817→            false
818→        }
819→    }
820→}

  1→/*
  2→ * dm_ble_gatt.c — FlowDesk BLE GATT server + LE advertising
  3→ *
  4→ * Service:  12345678-1234-5678-1234-56789abcdef0
  5→ * CHAR_AUTH  ...def1  write (Pair ACK) + notify (Pair Request challenge)
  6→ * CHAR_CMD   ...def2  write (Pair Request / Heartbeat)
  7→ * CHAR_STATUS ...def3 notify (Net On/Off)
  8→ *
  9→ * Frame: [CMD:1][LEN:1][DATA:0..32], multi-byte little-endian.
 10→ * Pairing: response = challenge XOR hash(PAIR_KEY), hash = h*31 + k[i].
 11→ */
