 33→/* 128-bit UUIDs in openvela / BLE wire order (reverse of big-endian string)
 34→ * 12345678-1234-5678-1234-56789abcdef0  ->  f0 de bc 9a 78 56 34 12 ...
 35→ * ...def1 AUTH, ...def2 CMD, ...def3 STATUS */
 36→#define DM_UUID_SVC \
 37→  0xf0, 0xde, 0xbc, 0x9a, 0x78, 0x56, 0x34, 0x12, \
 38→  0x78, 0x56, 0x34, 0x12, 0x78, 0x56, 0x34, 0x12
 39→#define DM_UUID_AUTH \
 40→  0xf1, 0xde, 0xbc, 0x9a, 0x78, 0x56, 0x34, 0x12, \
 41→  0x78, 0x56, 0x34, 0x12, 0x78, 0x56, 0x34, 0x12
 42→#define DM_UUID_CMD \
 43→  0xf2, 0xde, 0xbc, 0x9a, 0x78, 0x56, 0x34, 0x12, \
 44→  0x78, 0x56, 0x34, 0x12, 0x78, 0x56, 0x34, 0x12
 45→#define DM_UUID_STATUS \
 46→  0xf3, 0xde, 0xbc, 0x9a, 0x78, 0x56, 0x34, 0x12, \
 47→  0x78, 0x56, 0x34, 0x12, 0x78, 0x56, 0x34, 0x12
