118→/* ---- protocol helpers (LE) ---- */
119→
120→static void put_u32_le(uint8_t *p, uint32_t v)
121→{
122→  p[0] = (uint8_t)(v & 0xff);
123→  p[1] = (uint8_t)((v >> 8) & 0xff);
124→  p[2] = (uint8_t)((v >> 16) & 0xff);
125→  p[3] = (uint8_t)((v >> 24) & 0xff);
126→}
127→
128→static uint32_t get_u32_le(const uint8_t *p)
129→{
130→  return (uint32_t)p[0] | ((uint32_t)p[1] << 8) |
131→         ((uint32_t)p[2] << 16) | ((uint32_t)p[3] << 24);
132→}
133→
134→static uint32_t key_hash(void)
135→{
136→  uint32_t h = 0;
137→  int i;
138→  for (i = 0; i < DM_BT_PAIR_KEY_LEN; i++)
139→    {
140→      h = h * 31u + (uint8_t)DM_BT_PAIR_KEY[i];
141→    }
142→  return h;
143→}
144→
145→static int send_notify(uint16_t attr, const uint8_t *data, uint16_t len)
146→{
147→  bt_status_t ret;
148→  if (!s_srv || !s_has_peer)
149→    {
150→      return -1;
151→    }
152→  pthread_mutex_lock(&s_lock);
153→  ret = bt_gatts_notify(s_srv, &s_peer, attr, (uint8_t *)data, len);
154→  pthread_mutex_unlock(&s_lock);
155→  return (ret == BT_STATUS_SUCCESS) ? 0 : -1;
156→}
157→
158→static int send_pair_req(uint32_t challenge)
159→{
160→  uint8_t buf[6];
161→  buf[0] = DM_BT_CMD_PAIR_REQ;
162→  buf[1] = 4;
163→  put_u32_le(buf + 2, challenge);
164→  return send_notify(ATTR_AUTH, buf, 6);
165→}
166→
167→static int send_pair_fail(void)
168→{
169→  uint8_t buf[2] = { DM_BT_CMD_PAIR_FAIL, 0 };
170→  return send_notify(ATTR_AUTH, buf, 2);
171→}
172→
173→static void start_pairing(void)
174→{
175→  uint32_t ch = (uint32_t)rand() ^ (uint32_t)(uintptr_t)&s_challenge;
176→  s_challenge = ch;
177→  s_pairing = 1;
178→  s_paired = 0;
179→  set_state(DM_BLE_PAIRING);
180→  if (send_pair_req(ch) != 0)
181→    {
182→      syslog(LOG_WARNING, "[ble-gatt] pair req notify failed\n");
183→    }
184→}
185→
186→/* ---- attr callbacks ---- */
187→
188→static uint16_t auth_on_read(void *srv, bt_address_t *addr, uint16_t attr,
189→                             uint32_t req)
190→{
191→  uint8_t buf[2] = { 0, 0 };
192→  (void)srv;
193→  (void)addr;
194→  (void)attr;
195→  bt_gatts_response(srv, addr, req, buf, 2);
196→  return 0;
197→}
198→
199→static uint16_t auth_on_write(void *srv, bt_address_t *addr, uint16_t attr,
200→                              const uint8_t *value, uint16_t length,
201→                              uint16_t offset)
202→{
203→  (void)srv;
204→  (void)attr;
205→  (void)offset;
206→
207→  if (length >= 2 && value[0] == DM_BT_CMD_PAIR_ACK && value[1] >= 4 &&
208→      length >= 6)
209→    {
210→      uint32_t resp = get_u32_le(value + 2);
211→      uint32_t expect = s_challenge ^ key_hash();
212→      syslog(LOG_INFO, "[ble-gatt] pair ack resp=0x%x expect=0x%x\n",
213→             (unsigned)resp, (unsigned)expect);
214→      if (s_pairing && resp == expect)
215→        {
216→          s_paired = 1;
217→          s_pairing = 0;
218→          pthread_mutex_lock(&s_lock);
219→          if (addr)
220→            {
221→              s_peer = *addr;
222→              s_has_peer = 1;
223→            }
224→          pthread_mutex_unlock(&s_lock);
225→          set_state(DM_BLE_PAIRED);
226→          /* confirm with Pair ACK notify so App side is consistent */
227→          {
228→            uint8_t ack[2] = { DM_BT_CMD_PAIR_ACK, 0 };
229→            send_notify(ATTR_AUTH, ack, 2);
230→          }
231→        }
232→      else
233→        {
234→          s_paired = 0;
235→          s_pairing = 0;
236→          send_pair_fail();
237→          set_state(DM_BLE_CONNECTED);
238→        }
239→      return length;
240→    }
241→
242→  if (length >= 2 && value[0] == DM_BT_CMD_PAIR_REQ)
243→    {
244→      start_pairing();
245→      return length;
246→    }
247→
248→  return length;
249→}
250→
251→static uint16_t cmd_on_write(void *srv, bt_address_t *addr, uint16_t attr,
252→                             const uint8_t *value, uint16_t length,
253→                             uint16_t offset)
254→{
255→  (void)srv;
256→  (void)attr;
257→  (void)offset;
258→
259→  if (addr)
260→    {
261→      pthread_mutex_lock(&s_lock);
262→      s_peer = *addr;
263→      s_has_peer = 1;
264→      pthread_mutex_unlock(&s_lock);
265→    }
266→
267→  if (length >= 1)
268→    {
269→      uint8_t cmd = value[0];
270→      if (cmd == DM_BT_CMD_PAIR_REQ)
271→        {
272→          start_pairing();
273→        }
274→      else if (cmd == DM_BT_CMD_HEARTBEAT)
275→        {
276→          /* keep-alive, ignore */
277→        }
278→      else if (cmd == DM_BT_CMD_PAIR_ACK && length >= 6)
279→        {
280→          /* App may write ACK on AUTH or CMD */
281→          auth_on_write(srv, addr, ATTR_AUTH, value, length, offset);
282→        }
283→    }
284→  return length;
285→}
286→
287→static uint16_t status_on_read(void *srv, bt_address_t *addr, uint16_t attr,
288→                               uint32_t req)
289→{
290→  uint8_t buf[2] = { DM_BT_CMD_NET_OFF, 0 };
291→  (void)attr;
292→  bt_gatts_response(srv, addr, req, buf, 2);
293→  return 0;
294→}
295→
296→static uint16_t cccd_on_write(void *srv, bt_address_t *addr, uint16_t attr,
297→                              const uint8_t *value, uint16_t length,
298→                              uint16_t offset)
299→{
300→  (void)srv;
301→  (void)addr;
302→  (void)offset;
303→  if (length < 1)
304→    {
305→      return length;
306→    }
307→  if (attr == ATTR_AUTH_CCCD)
308→    {
309→      s_auth_cccd = value[0];
310→      if (s_auth_cccd && !s_paired)
311→        {
312→          start_pairing();
313→        }
314→    }
315→  else if (attr == ATTR_CMD_CCCD)
316→    {
317→      s_cmd_cccd = value[0];
318→    }
319→  else if (attr == ATTR_STATUS_CCCD)
320→    {
321→      s_status_cccd = value[0];
322→    }
323→  return length;
324→}
