505→static int start_adv(void)
506→{
507→  ble_adv_params_t params;
508→  advertiser_data_t *adv_data;
509→  advertiser_data_t *scan_rsp;
510→  uint8_t *p_adv;
511→  uint8_t *p_rsp;
512→  uint16_t adv_len = 0;
513→  uint16_t rsp_len = 0;
514→
515→  if (!s_ins)
516→    {
517→      return -1;
518→    }
519→  if (s_adv)
520→    {
521→      return 0;
522→    }
523→
524→  memset(&params, 0, sizeof(params));
525→  params.adv_type = BT_LE_ADV_IND;
526→  params.own_addr_type = BT_LE_ADDR_TYPE_PUBLIC;
527→  params.tx_power = 0;
528→  params.interval = 160; /* 100ms */
529→  params.duration = 0;
530→  params.channel_map = 7;
531→  params.filter_policy = BT_LE_ADV_FILTER_WHITE_LIST_FOR_NONE;
532→
533→  adv_data = advertiser_data_new();
534→  if (!adv_data)
535→    {
536→      return -1;
537→    }
538→  advertiser_data_set_flags(adv_data,
539→                            BT_AD_FLAG_GENERAL_DISCOVERABLE |
540→                            BT_AD_FLAG_BREDR_NOT_SUPPORT);
541→  advertiser_data_add_service_uuid(adv_data, &k_svc_uuid);
542→  p_adv = advertiser_data_build(adv_data, &adv_len);
543→
544→  scan_rsp = advertiser_data_new();
545→  if (scan_rsp)
546→    {
547→      advertiser_data_set_name(scan_rsp, "FlowDesk-S1");
548→      p_rsp = advertiser_data_build(scan_rsp, &rsp_len);
549→    }
550→  else
551→    {
552→      p_rsp = NULL;
553→    }
554→
555→  s_adv = bt_le_start_advertising(s_ins, &params,
556→                                  p_adv, adv_len,
557→                                  p_rsp, rsp_len,
558→                                  &s_adv_cbs);
559→
560→  advertiser_data_free(adv_data);
561→  if (scan_rsp)
562→    {
563→      advertiser_data_free(scan_rsp);
564→    }
565→
566→  if (!s_adv)
567→    {
568→      syslog(LOG_ERR, "[ble-gatt] start advertising failed\n");
569→      set_state(DM_BLE_ERROR);
570→      return -1;
571→    }
572→  set_state(DM_BLE_ADVERTISING);
573→  return 0;
574→}
