251→    fun startScan() {
252→        if (scanning) {
253→            stopScan()
254→            return
255→        }
256→        val bt = adapter
257→        if (bt == null) {
258→            fail("此设备不支持 BLE")
259→            return
260→        }
261→        if (!hasScanPermission()) {
262→            fail("缺少蓝牙扫描权限，请授予「附近的设备」权限")
263→            return
264→        }
265→        if (!hasConnectPermission()) {
266→            fail("缺少蓝牙连接权限，请授予「附近的设备」权限")
267→            return
268→        }
269→        if (!bt.isEnabled) {
270→            promptEnableBluetooth()
271→            return
272→        }
273→        val scanner = try {
274→            bt.bluetoothLeScanner
275→        } catch (e: SecurityException) {
276→            null
277→        }
278→        if (scanner == null) {
279→            fail("无法获取 BLE 扫描器，请确认蓝牙已开启")
280→            return
281→        }
282→        scanResults.clear()
283→        scanning = true
284→        _state.update {
285→            it.copy(
286→                connState = ConnState.SCANNING,
287→                devices = emptyList(),
288→                selectedAddress = null,
289→                statusText = "正在扫描…",
290→                hint = "只显示广播专属 Service UUID 的设备（12 秒）"
291→            )
292→        }
293→        val filters = listOf(
294→            ScanFilter.Builder()
295→                .setServiceUuid(ParcelUuid(BleProtocol.SERVICE_UUID))
296→                .build()
297→        )
298→        val settings = ScanSettings.Builder()
299→            .setScanMode(ScanSettings.SCAN_MODE_LOW_LATENCY)
300→            .build()
301→        try {
302→            scanner.startScan(filters, settings, scanCallback)
303→            log("开始扫描：过滤 Service UUID")
304→        } catch (e: SecurityException) {
305→            scanning = false
306→            fail("扫描失败：蓝牙权限被拒绝")
307→            return
308→        }
309→        handler.postDelayed(scanTimeout, SCAN_TIMEOUT_MS)
310→    }
