312→    fun stopScan() {
313→        if (!scanning) return
314→        stopScanInternal()
315→        val count = _state.value.devices.size
316→        _state.update {
317→            it.copy(
318→                connState = if (it.paired) ConnState.PAIRED else ConnState.IDLE,
319→                statusText = "扫描结束，发现 " + count + " 台专属设备",
320→                hint = if (count > 0) {
321→                    "点选设备后点「连接」"
322→                } else {
323→                    "未发现设备，请确认板子已上电并打开 App 连接页面"
324→                }
325→            )
326→        }
327→        log("停止扫描")
328→    }
