344→    fun connect(address: String) {
345→        val bt = adapter
346→        if (bt == null) {
347→            fail("此设备不支持 BLE")
348→            return
349→        }
350→        if (!hasConnectPermission()) {
351→            fail("缺少蓝牙连接权限，请授予「附近的设备」权限")
352→            return
353→        }
354→        if (!bt.isEnabled) {
355→            promptEnableBluetooth()
356→            return
357→        }
358→        if (scanning) stopScan()
359→        manualDisconnect = false
360→        val device = try {
361→            bt.getRemoteDevice(address)
362→        } catch (e: SecurityException) {
363→            null
364→        } catch (e: IllegalArgumentException) {
365→            null
366→        }
367→        if (device == null) {
368→            fail("无效的设备地址")
369→            return
370→        }
371→        closeGatt()
372→        _state.update {
373→            it.copy(
374→                connState = ConnState.CONNECTING,
375→                statusText = "正在连接…",
376→                hint = address,
377→                connectedAddress = address,
378→                selectedAddress = address,
379→                paired = false,
380→                networkShared = false,
381→                pairingPhase = PairingPhase.NONE
382→            )
383→        }
384→        log("连接 " + address)
385→        gatt = try {
386→            device.connectGatt(appContext, false, gattCallback, BluetoothDevice.TRANSPORT_LE)
387→        } catch (e: SecurityException) {
388→            null
389→        }
390→        if (gatt == null) {
391→            fail("连接失败：请检查蓝牙权限和设备状态")
392→        }
393→    }
