395→    fun requestPair() {
396→        val current = _state.value
397→        if (current.paired) {
398→            log("已经配对，无需重复配对")
399→            return
400→        }
401→        if (gatt == null || authChar == null || queue == null) {
402→            fail("请先连接设备")
403→            return
404→        }
405→        if (!hasConnectPermission()) {
406→            fail("缺少蓝牙连接权限")
407→            return
408→        }
409→        _state.update {
410→            it.copy(
411→                connState = ConnState.PAIRING,
412→                pairingPhase = PairingPhase.PAIRING,
413→                statusText = "正在配对…",
414→                hint = "已向板子发送 Pair Request，等待 challenge"
415→            )
416→        }
417→        handler.removeCallbacks(pairTimeout)
418→        handler.postDelayed(pairTimeout, PAIR_TIMEOUT_MS)
419→        val target = cmdChar ?: authChar
420→        if (target != null) {
421→            writeCharacteristic(target, BleProtocol.buildPairRequest(), "PairRequest")
422→        }
423→        log("发送 Pair Request")
424→    }
