466→    private fun handleNotification(value: ByteArray) {
467→        val msg = BleProtocol.parse(value) ?: return
468→        log("收到 " + BleProtocol.commandName(msg.cmd) + " [" + BleProtocol.hex(value) + "]")
469→        when (msg.cmd) {
470→            BleProtocol.CMD_PAIR_REQ -> handlePairRequest(msg)
471→            BleProtocol.CMD_PAIR_FAIL -> onPairFailed("板子返回配对失败")
472→            BleProtocol.CMD_NET_ON -> {
473→                _state.update {
474→                    it.copy(
475→                        networkShared = true,
476→                        statusText = "网络共享已开启",
477→                        hint = "板子已请求联网，请保持蓝牙网络共享开启"
478→                    )
479→                }
480→                log("板子请求开启网络共享")
481→            }
482→
483→            BleProtocol.CMD_NET_OFF -> {
484→                _state.update {
485→                    it.copy(
486→                        networkShared = false,
487→                        statusText = "网络共享已关闭",
488→                        hint = "可在系统设置中重新开启蓝牙网络共享"
489→                    )
490→                }
491→                log("板子请求关闭网络共享")
492→            }
493→
494→            BleProtocol.CMD_HEARTBEAT -> {
495→                // 板子心跳，保持静默
496→            }
497→
498→            else -> log("未识别命令 " + BleProtocol.commandName(msg.cmd))
499→        }
500→    }
501→
502→    private fun handlePairRequest(msg: BleProtocol.Message) {
503→        val challenge = BleProtocol.readChallenge(msg)
504→        if (challenge == null) {
505→            log("PairRequest 数据长度不足，忽略")
506→            return
507→        }
508→        if (_state.value.paired) {
509→            log("已经配对，忽略重复 PairRequest")
510→            return
511→        }
512→        val target = authChar ?: cmdChar ?: statusChar
513→        if (target == null) {
514→            fail("没有可写入的配对特征")
515→            return
516→        }
517→        log("收到 challenge=0x" + String.format(Locale.US, "%08X", challenge))
518→        _state.update {
519→            it.copy(
520→                connState = ConnState.PAIRING,
521→                pairingPhase = PairingPhase.PAIRING,
522→                statusText = "正在配对…",
523→                hint = "已收到 challenge，正在回复 Pair ACK"
524→            )
525→        }
526→        handler.removeCallbacks(pairTimeout)
527→        handler.postDelayed(pairTimeout, PAIR_TIMEOUT_MS)
528→        pendingPairAck = true
529→        ackCharUuid = target.uuid
530→        writeCharacteristic(target, BleProtocol.buildPairAck(challenge), "PairAck")
531→    }
532→
533→    private fun onPairSuccess() {
534→        pendingPairAck = false
535→        ackCharUuid = null
536→        _state.update {
537→            it.copy(
538→                connState = ConnState.PAIRED,
539→                paired = true,
540→                pairingPhase = PairingPhase.SUCCESS,
541→                statusText = "配对成功，允许上网",
542→                hint = "打开手机「蓝牙网络共享」后，板子会自动连接并上网"
543→            )
544→        }
545→        log("配对成功")
546→        handler.removeCallbacks(heartbeat)
547→        handler.postDelayed(heartbeat, HEARTBEAT_INTERVAL_MS)
548→        handler.postDelayed({
549→            _state.update {
550→                if (it.pairingPhase == PairingPhase.SUCCESS) it.copy(pairingPhase = PairingPhase.NONE) else it
551→            }
552→        }, 2000L)
553→    }
554→
555→    private fun onPairFailed(reason: String) {
556→        pendingPairAck = false
557→        ackCharUuid = null
558→        handler.removeCallbacks(pairTimeout)
559→        _state.update {
560→            it.copy(
561→                connState = ConnState.READY,
562→                paired = false,
563→                pairingPhase = PairingPhase.FAIL,
564→                statusText = "配对失败",
565→                hint = reason
566→            )
567→        }
568→        log("配对失败：" + reason)
569→        handler.postDelayed({
570→            _state.update {
571→                if (it.pairingPhase == PairingPhase.FAIL) it.copy(pairingPhase = PairingPhase.NONE) else it
572→            }
573→        }, 2500L)
574→    }
575→
576→    private fun onPairTimeout() {
577→        if (_state.value.pairingPhase == PairingPhase.PAIRING && !_state.value.paired) {
578→            onPairFailed("配对超时：没有收到板子的 challenge")
579→        }
580→    }
581→
582→    private fun onDisconnected(status: Int) {
583→        handler.removeCallbacks(pairTimeout)
584→        handler.removeCallbacks(heartbeat)
585→        pendingPairAck = false
586→        ackCharUuid = null
587→        closeGatt()
588→        if (manualDisconnect) {
589→            manualDisconnect = false
590→            return
591→        }
592→        _state.update {
593→            it.copy(
594→                connState = ConnState.IDLE,
595→                statusText = "连接已断开",
596→                hint = "可以重新扫描或连接",
597→                connectedAddress = null,
598→                paired = false,
599→                networkShared = false,
600→                pairingPhase = PairingPhase.NONE
601→            )
602→        }
603→        if (status == BluetoothGatt.GATT_SUCCESS) {
604→            log("连接断开")
605→        } else {
606→            log("连接断开，状态码 " + status)
607→        }
608→    }
