585→/* ---- adapter ---- */
586→
587→static volatile int s_start_pending;
588→
589→static void do_register_and_adv(void)
590→{
591→  if (!s_srv)
592→    {
593→      bt_status_t ret = bt_gatts_register_service(s_ins, &s_srv,
594→                                                 &s_gatts_cbs);
595→      if (ret != BT_STATUS_SUCCESS || !s_srv)
596→        {
597→          syslog(LOG_ERR, "[ble-gatt] register service fail %d\n", (int)ret);
598→          s_srv = NULL;
599→          return;
600→        }
601→      /* start_adv() also fires from on_attr_table_added when ready */
602→      bt_gatts_add_attr_table(s_srv, &s_srv_db);
603→    }
604→  (void)start_adv();
605→}
606→
607→/* Called from the UI tick.  Registration/adv is deferred here instead of
608→   running inside the adapter callback: doing it while the stack is still
609→   in HCI init raced zblue into a kernel oops and no advertisement ever
610→   started.  Keeps retrying every ~2s while starting. */
611→void dm_ble_poll(void)
612→{
613→  static int ticks;
614→
615→  if (!s_start_pending || s_state != DM_BLE_STARTING)
616→    {
617→      ticks = 0;
618→      return;
619→    }
620→  if (++ticks < 8) /* ~2s settle for zblue HCI init */
621→    {
622→      return;
623→    }
624→  ticks = 0;
625→  if (!s_ins || bt_adapter_get_state(s_ins) != BT_ADAPTER_STATE_ON)
626→    {
627→      return;
628→    }
629→  do_register_and_adv();
630→  if (s_adv)
631→    {
632→      s_start_pending = 0;
633→    }
634→}
635→
636→static void adapter_state_cb(void *cookie, bt_adapter_state_t state)
637→{
638→  (void)cookie;
639→  syslog(LOG_INFO, "[ble-gatt] adapter state=%d\n", (int)state);
640→  if (state == BT_ADAPTER_STATE_ON)
641→    {
642→      s_start_pending = 1;
643→    }
644→}
645→
646→static adapter_callbacks_t s_adapter_cbs = {
647→  .on_adapter_state_changed = adapter_state_cb,
648→};
649→
650→int dm_ble_start(void)
651→{
652→  if (s_state != DM_BLE_IDLE && s_state != DM_BLE_ERROR)
653→    {
654→      return 0;
655→    }
656→
657→  set_state(DM_BLE_STARTING);
658→  s_paired = 0;
659→  s_pairing = 0;
660→  s_has_peer = 0;
661→  srand((unsigned int)time(NULL) ^ (unsigned int)(uintptr_t)s_ins);
662→
663→  if (!s_ins)
664→    {
665→      s_ins = bluetooth_create_instance();
666→      if (!s_ins)
667→        {
668→          syslog(LOG_ERR, "[ble-gatt] create instance fail\n");
669→          set_state(DM_BLE_ERROR);
670→          return -1;
671→        }
672→    }
673→
674→  if (!s_adapter_cb)
675→    {
676→      s_adapter_cb = bt_adapter_register_callback(s_ins, &s_adapter_cbs);
677→    }
678→
679→  if (bt_adapter_enable(s_ins) != BT_STATUS_SUCCESS)
680→    {
681→      /* may already be on — verify before registering */
682→      if (bt_adapter_get_state(s_ins) == BT_ADAPTER_STATE_ON)
683→        {
684→          adapter_state_cb(NULL, BT_ADAPTER_STATE_ON);
685→        }
686→      else
687→        {
688→          syslog(LOG_ERR, "[ble-gatt] adapter enable fail\n");
689→          set_state(DM_BLE_ERROR);
690→          return -1;
691→        }
692→    }
693→  return 0;
694→}
