696→void dm_ble_stop(void)
697→{
698→  stop_adv();
699→  if (s_srv)
700→    {
701→      bt_gatts_unregister_service(s_srv);
702→      s_srv = NULL;
703→    }
704→  s_paired = 0;
705→  s_pairing = 0;
706→  s_has_peer = 0;
707→  s_auth_cccd = 0;
708→  s_start_pending = 0;
709→  set_state(DM_BLE_IDLE);
710→}
