120→/* ---- protocol helpers (LE) ---- */
121→
122→static void put_u32_le(uint8_t *p, uint32_t v)
123→{
124→  p[0] = (uint8_t)(v & 0xff);
125→  p[1] = (uint8_t)((v >> 8) & 0xff);
126→  p[2] = (uint8_t)((v >> 16) & 0xff);
127→  p[3] = (uint8_t)((v >> 24) & 0xff);
128→}
129→
130→static uint32_t get_u32_le(const uint8_t *p)
131→{
132→  return (uint32_t)p[0] | ((uint32_t)p[1] << 8) |
133→         ((uint32_t)p[2] << 16) | ((uint32_t)p[3] << 24);
134→}
135→
136→static uint32_t key_hash(void)
137→{
138→  uint32_t h = 0;
139→  int i;
140→  for (i = 0; i < DM_BT_PAIR_KEY_LEN; i++)
141→    {
142→      h = h * 31u + (uint8_t)DM_BT_PAIR_KEY[i];
143→    }
144→  return h;
145→}
146→
147→static int send_notify(uint16_t attr, const uint8_t *data, uint16_t len)
148→{
149→  bt_status_t ret;
150→  if (!s_srv || !s_has_peer)
151→    {
152→      return -1;
153→    }
154→  pthread_mutex_lock(&s_lock);
155→  ret = bt_gatts_notify(s_srv, &s_peer, attr, (uint8_t *)data, len);
156→  pthread_mutex_unlock(&s_lock);
157→  return (ret == BT_STATUS_SUCCESS) ? 0 : -1;
158→}
159→
160→static int send_pair_req(uint32_t challenge)
161→{
162→  uint8_t buf[6];
163→  buf[0] = DM_BT_CMD_PAIR_REQ;
164→  buf[1] = 4;
165→  put_u32_le(buf + 2, challenge);
166→  return send_notify(ATTR_AUTH, buf, 6);
167→}
168→
169→static int send_pair_fail(void)
170→{
171→  uint8_t buf[2] = { DM_BT_CMD_PAIR_FAIL, 0 };
172→  return send_notify(ATTR_AUTH, buf, 2);
173→}
174→
175→static int send_pair_confirm(void)
176→{
177→  uint8_t buf[2] = { DM_BT_CMD_PAIR_ACK, 0 };
178→  return send_notify(ATTR_AUTH, buf, 2);
179→}
180→
181→static void start_pairing(void)
182→{
183→  uint32_t ch = (uint32_t)rand() ^ (uint32_t)(uintptr_t)&s_challenge;
184→  s_challenge = ch;
185→  s_pairing = 1;
186→  s_paired = 0;
187→  set_state(DM_BLE_PAIRING);
188→  if (send_pair_req(ch) != 0)
189→    {
190→      syslog(LOG_WARNING, "[ble-gatt] pair req notify failed\n");
191→    }
192→}
