194→/* ---- attr callbacks ---- */
195→
196→static uint16_t auth_on_read(void *srv, bt_address_t *addr, uint16_t attr,
197→                             uint32_t req)
198→{
199→  uint8_t buf[2] = { 0, 0 };
200→  (void)srv;
201→  (void)addr;
202→  (void)attr;
203→  bt_gatts_response(srv, addr, req, buf, 2);
204→  return 0;
205→}
206→
207→static uint16_t auth_on_write(void *srv, bt_address_t *addr, uint16_t attr,
208→                              const uint8_t *value, uint16_t length,
209→                              uint16_t offset)
210→{
211→  (void)srv;
212→  (void)attr;
213→  (void)offset;
214→
215→  if (length >= 2 && value[0] == DM_BT_CMD_PAIR_ACK && value[1] >= 4 &&
216→      length >= 6)
217→    {
218→      uint32_t resp = get_u32_le(value + 2);
219→      uint32_t expect = s_challenge ^ key_hash();
220→      syslog(LOG_INFO, "[ble-gatt] pair ack resp=0x%x expect=0x%x\n",
221→             (unsigned)resp, (unsigned)expect);
222→      if (s_pairing && resp == expect)
223→        {
224→          s_paired = 1;
225→          s_pairing = 0;
226→          pthread_mutex_lock(&s_lock);
227→          if (addr)
228→            {
229→              s_peer = *addr;
230→              s_paired_peer = *addr;
231→              s_has_peer = 1;
232→              s_has_paired_peer = 1;
233→            }
234→          pthread_mutex_unlock(&s_lock);
235→          set_state(DM_BLE_PAIRED);
236→          /* Confirm the application-level pairing, not just the ATT write. */
237→          if (send_pair_confirm() != 0)
238→            {
239→              syslog(LOG_WARNING, "[ble-gatt] pair confirmation notify failed\n");
240→            }
241→        }
242→      else
243→        {
244→          s_paired = 0;
245→          s_pairing = 0;
246→          send_pair_fail();
247→          set_state(DM_BLE_CONNECTED);
248→        }
249→      return length;
250→    }
251→
252→  if (length >= 2 && value[0] == DM_BT_CMD_PAIR_REQ)
253→    {
254→      start_pairing();
255→      return length;
256→    }
257→
258→  return length;
259→}
260→
261→static uint16_t cmd_on_write(void *srv, bt_address_t *addr, uint16_t attr,
262→                             const uint8_t *value, uint16_t length,
263→                             uint16_t offset)
264→{
265→  (void)srv;
266→  (void)attr;
267→  (void)offset;
268→
269→  if (addr)
270→    {
271→      pthread_mutex_lock(&s_lock);
272→      s_peer = *addr;
273→      s_has_peer = 1;
274→      pthread_mutex_unlock(&s_lock);
275→    }
276→
277→  if (length >= 1)
278→    {
279→      uint8_t cmd = value[0];
280→      if (cmd == DM_BT_CMD_PAIR_REQ)
281→        {
282→          start_pairing();
283→        }
284→      else if (cmd == DM_BT_CMD_HEARTBEAT)
285→        {
286→          /* keep-alive, ignore */
287→        }
288→      else if (cmd == DM_BT_CMD_PAIR_ACK && length >= 6)
289→        {
290→          /* App may write ACK on AUTH or CMD */
291→          auth_on_write(srv, addr, ATTR_AUTH, value, length, offset);
292→        }
293→    }
294→  return length;
295→}
296→
297→static uint16_t status_on_read(void *srv, bt_address_t *addr, uint16_t attr,
298→                               uint32_t req)
299→{
300→  uint8_t buf[2] = { DM_BT_CMD_NET_OFF, 0 };
301→  (void)attr;
302→  bt_gatts_response(srv, addr, req, buf, 2);
303→  return 0;
304→}
305→
306→static uint16_t cccd_on_write(void *srv, bt_address_t *addr, uint16_t attr,
307→                              const uint8_t *value, uint16_t length,
308→                              uint16_t offset)
309→{
310→  (void)srv;
311→  (void)addr;
312→  (void)offset;
313→  if (length < 1)
314→    {
315→      return length;
316→    }
317→  if (attr == ATTR_AUTH_CCCD)
318→    {
319→      s_auth_cccd = value[0];
320→      if (s_auth_cccd)
321→        {
322→          if (s_paired)
323→            {
324→              /* Restore the App state after reconnecting to a known peer. */
325→              if (send_pair_confirm() != 0)
326→                {
327→                  syslog(LOG_WARNING,
328→                         "[ble-gatt] reconnect pair confirmation failed\n");
329→                }
330→            }
331→          else
332→            {
333→              start_pairing();
334→            }
335→        }
336→    }
337→  else if (attr == ATTR_CMD_CCCD)
338→    {
339→      s_cmd_cccd = value[0];
340→    }
341→  else if (attr == ATTR_STATUS_CCCD)
342→    {
343→      s_status_cccd = value[0];
344→    }
345→  return length;
346→}
