701→    private fun enableNotifications(g: BluetoothGatt, c: BluetoothGattCharacteristic?) {
702→        if (c == null) return
703→        val props = c.properties
704→        val notify = (props and BluetoothGattCharacteristic.PROPERTY_NOTIFY) != 0
705→        val indicate = (props and BluetoothGattCharacteristic.PROPERTY_INDICATE) != 0
706→        if (!notify && !indicate) return
707→        try {
708→            g.setCharacteristicNotification(c, true)
709→            val cccd = c.getDescriptor(BleProtocol.CCCD_UUID)
710→            if (cccd == null) {
711→                log("特征 " + c.uuid.toString().takeLast(4) + " 没有 CCCD，无法订阅")
712→                return
713→            }
714→            val value = if (notify) {
715→                BluetoothGattDescriptor.ENABLE_NOTIFICATION_VALUE
716→            } else {
717→                BluetoothGattDescriptor.ENABLE_INDICATION_VALUE
718→            }
719→            queue?.enqueue(GattOp.WriteDescriptor(cccd, value, "订阅 " + c.uuid.toString().takeLast(4)))
720→        } catch (e: SecurityException) {
721→            log("订阅通知失败：蓝牙权限被拒绝")
722→        }
723→    }
