709→    private fun enableNotifications(g: BluetoothGatt, c: BluetoothGattCharacteristic?) {
710→        if (c == null) return
711→        val props = c.properties
712→        val notify = (props and BluetoothGattCharacteristic.PROPERTY_NOTIFY) != 0
713→        val indicate = (props and BluetoothGattCharacteristic.PROPERTY_INDICATE) != 0
714→        if (!notify && !indicate) return
715→        try {
716→            g.setCharacteristicNotification(c, true)
717→            val cccd = c.getDescriptor(BleProtocol.CCCD_UUID)
718→            if (cccd == null) {
719→                log("特征 " + c.uuid.toString().takeLast(4) + " 没有 CCCD，无法订阅")
720→                return
721→            }
722→            val value = if (notify) {
723→                BluetoothGattDescriptor.ENABLE_NOTIFICATION_VALUE
724→            } else {
725→                BluetoothGattDescriptor.ENABLE_INDICATION_VALUE
726→            }
727→            queue?.enqueue(GattOp.WriteDescriptor(cccd, value, "订阅 " + c.uuid.toString().takeLast(4)))
728→        } catch (e: SecurityException) {
729→            log("订阅通知失败：蓝牙权限被拒绝")
