123→static void put_u32_le(uint8_t *p, uint32_t v)
124→{
125→  p[0] = (uint8_t)(v & 0xff);
126→  p[1] = (uint8_t)((v >> 8) & 0xff);
127→  p[2] = (uint8_t)((v >> 16) & 0xff);
128→  p[3] = (uint8_t)((v >> 24) & 0xff);
129→}
