131→static uint32_t get_u32_le(const uint8_t *p)
132→{
133→  return (uint32_t)p[0] | ((uint32_t)p[1] << 8) |
134→         ((uint32_t)p[2] << 16) | ((uint32_t)p[3] << 24);
135→}
