220→      uint32_t expect = s_challenge ^ key_hash();
221→      syslog(LOG_INFO, "[ble-gatt] pair ack resp=0x%x expect=0x%x\n",
222→             (unsigned)resp, (unsigned)expect);
223→      if (s_pairing && resp == expect)
224→        {
225→          s_paired = 1;
226→          s_pairing = 0;
227→          pthread_mutex_lock(&s_lock);
