262→static uint16_t cmd_on_write(void *srv, bt_address_t *addr, uint16_t attr,
263→                             const uint8_t *value, uint16_t length,
264→                             uint16_t offset)
265→{
266→  (void)srv;
267→  (void)attr;
268→  (void)offset;
269→
270→  if (addr)
271→    {
272→      pthread_mutex_lock(&s_lock);
273→      s_peer = *addr;
274→      s_has_peer = 1;
275→      pthread_mutex_unlock(&s_lock);
276→    }
277→
278→  if (length >= 1)
279→    {
280→      uint8_t cmd = value[0];
281→      if (cmd == DM_BT_CMD_PAIR_REQ)
282→        {
283→          start_pairing();
284→        }
285→      else if (cmd == DM_BT_CMD_HEARTBEAT)
286→        {
287→          /* keep-alive, ignore */
288→        }
289→      else if (cmd == DM_BT_CMD_PAIR_ACK && length >= 6)
290→        {
291→          /* App may write ACK on AUTH or CMD */
292→          auth_on_write(srv, addr, ATTR_AUTH, value, length, offset);
293→        }
294→    }
295→  return length;
296→}
