635→
636→/* Called from the UI tick.  Registration/adv is deferred here instead of
637→   running inside the adapter callback: doing it while the stack is still
638→   in HCI init raced zblue into a kernel oops and no advertisement ever
639→   started.  Keeps retrying every ~2s while starting. */
640→void dm_ble_poll(void)
641→{
642→  static int ticks;
643→
644→  if (!s_start_pending || s_state != DM_BLE_STARTING)
645→    {
646→      ticks = 0;
647→      return;
648→    }
649→  if (++ticks < 8) /* ~2s settle for zblue HCI init */
650→    {
651→      return;
652→    }
653→  ticks = 0;
654→  if (!s_ins || bt_adapter_get_state(s_ins) != BT_ADAPTER_STATE_ON)
655→    {
656→      return;
657→    }
658→  do_register_and_adv();
659→  if (s_adv)
660→    {
661→      s_start_pending = 0;
662→    }
663→}
