package com.lrc.flowdesk

import com.lrc.flowdesk.ble.BleProtocol
import org.junit.Assert.assertArrayEquals
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNull
import org.junit.Assert.assertNotNull
import org.junit.Test

class ExampleUnitTest {
    @Test
    fun pairAckUsesExpectedFrameAndLittleEndianPayload() {
        val challenge = 0x12345678
        val response = BleProtocol.computeResponse(challenge)
        val frame = BleProtocol.buildPairAck(challenge)

        assertEquals(BleProtocol.CMD_PAIR_ACK, frame[0].toInt() and 0xFF)
        assertEquals(4, frame[1].toInt() and 0xFF)
        assertArrayEquals(
            byteArrayOf(
                response.toByte(),
                (response ushr 8).toByte(),
                (response ushr 16).toByte(),
                (response ushr 24).toByte()
            ),
            frame.copyOfRange(2, 6)
        )
    }

    @Test
    fun parserAcceptsExactEmptyAndChallengeFrames() {
        val heartbeat = BleProtocol.parse(BleProtocol.buildHeartbeat())
        assertNotNull(heartbeat)
        assertEquals(BleProtocol.CMD_HEARTBEAT, heartbeat!!.cmd)
        assertEquals(0, heartbeat.payload.size)

        val challengeBytes = byteArrayOf(
            BleProtocol.CMD_PAIR_REQ.toByte(), 4, 0x78, 0x56, 0x34, 0x12
        )
        val challenge = BleProtocol.parse(challengeBytes)
        assertNotNull(challenge)
        assertEquals(0x12345678, BleProtocol.readChallenge(challenge!!))
    }

    @Test
    fun parserRejectsTruncatedOversizedAndTrailingBytes() {
        assertNull(BleProtocol.parse(byteArrayOf(1)))
        assertNull(BleProtocol.parse(byteArrayOf(1, 4, 1, 2)))
        assertNull(BleProtocol.parse(byteArrayOf(1, 0, 0)))
        assertNull(BleProtocol.parse(ByteArray(35).also { it[1] = 33 }))
    }
}

