680→            val reason = if (pendingPairAck && ackWriteSucceeded) {
681→                "配对超时：ACK 已写入，但没有收到板端确认"
682→            } else if (pendingPairAck) {
683→                "配对超时：板端 challenge 响应未完成"
684→            } else {
685→                "配对超时：未收到板端 challenge/已配对确认"
686→            }
687→            onPairFailed(reason)
688→        }
689→    }
