723→    private fun enableNotifications(g: BluetoothGatt, c: BluetoothGattCharacteristic?) {
724→        if (c == null) return
725→        val props = c.properties
726→        val notify = (props and BluetoothGattCharacteristic.PROPERTY_NOTIFY) != 0
727→        val indicate = (props and BluetoothGattCharacteristic.PROPERTY_INDICATE) != 0
728→        if (!notify && !indicate) return
729→        try {
730→            g.setCharacteristicNotification(c, true)
731→            val cccd = c.getDescriptor(BleProtocol.CCCD_UUID)
732→            if (cccd == null) {
733→                log("特征 " + c.uuid.toString().takeLast(4) + " 没有 CCCD，无法订阅")
734→                return
735→            }
736→            val value = if (notify) {
737→                BluetoothGattDescriptor.ENABLE_NOTIFICATION_VALUE
738→            } else {
739→                BluetoothGattDescriptor.ENABLE_INDICATION_VALUE
740→            }
741→            queue?.enqueue(GattOp.WriteDescriptor(cccd, value, "订阅 " + c.uuid.toString().takeLast(4)))
742→        } catch (e: SecurityException) {
743→            log("订阅通知失败：蓝牙权限被拒绝")
744→        }
745→    }
746→
747→    private fun writeCharacteristic(c: BluetoothGattCharacteristic, value: ByteArray, label: String) {
748→        if (!hasConnectPermission()) {
749→            log(label + "：缺少蓝牙连接权限")
750→            return
751→        }
752→        val q = queue
753→        if (q == null) {
754→            log(label + "：GATT 队列未就绪")
755→            return
756→        }
757→        q.enqueue(GattOp.WriteCharacteristic(c, value, label))
758→    }
