141→/* ---- protocol helpers (LE) ---- */
142→
143→static void put_u32_le(uint8_t *p, uint32_t v)
144→{
145→  p[0] = (uint8_t)(v & 0xff);
146→  p[1] = (uint8_t)((v >> 8) & 0xff);
147→  p[2] = (uint8_t)((v >> 16) & 0xff);
148→  p[3] = (uint8_t)((v >> 24) & 0xff);
149→}
150→
151→static uint32_t get_u32_le(const uint8_t *p)
152→{
153→  return (uint32_t)p[0] | ((uint32_t)p[1] << 8) |
154→         ((uint32_t)p[2] << 16) | ((uint32_t)p[3] << 24);
155→}
156→
157→static uint32_t key_hash(void)
158→{
159→  uint32_t h = 0;
160→  int i;
161→  for (i = 0; i < DM_BT_PAIR_KEY_LEN; i++)
162→    {
163→      h = h * 31u + (uint8_t)DM_BT_PAIR_KEY[i];
164→    }
165→  return h;
166→}
167→
168→static int send_notify(uint16_t attr, const uint8_t *data, uint16_t len)
169→{
170→  bt_status_t ret;
171→  if (!s_srv || !s_has_peer)
172→    {
173→      return -1;
174→    }
175→  pthread_mutex_lock(&s_lock);
176→  ret = bt_gatts_notify(s_srv, &s_peer, attr, (uint8_t *)data, len);
177→  pthread_mutex_unlock(&s_lock);
178→  return (ret == BT_STATUS_SUCCESS) ? 0 : -1;
179→}
180→
181→static int send_pair_req(uint32_t challenge)
182→{
183→  uint8_t buf[6];
184→  buf[0] = DM_BT_CMD_PAIR_REQ;
185→  buf[1] = 4;
186→  put_u32_le(buf + 2, challenge);
187→  return send_notify(ATTR_AUTH, buf, 6);
188→}
189→
190→static int send_pair_fail(void)
191→{
192→  uint8_t buf[2] = { DM_BT_CMD_PAIR_FAIL, 0 };
193→  return send_notify(ATTR_AUTH, buf, 2);
194→}
195→
196→static int send_pair_confirm(void)
197→{
198→  uint8_t buf[2] = { DM_BT_CMD_PAIR_ACK, 0 };
199→  return send_notify(ATTR_AUTH, buf, 2);
200→}
201→
202→static void start_pairing(void)
203→{
204→  uint32_t ch = (uint32_t)rand() ^ (uint32_t)(uintptr_t)&s_challenge;
205→
206→  pthread_mutex_lock(&s_lock);
207→  s_challenge = ch;
208→  s_pair_ticks = 0;
209→  s_pairing = 1;
210→  s_paired = 0;
211→  pthread_mutex_unlock(&s_lock);
212→  set_state(DM_BLE_PAIRING);
213→  if (send_pair_req(ch) != 0)
214→    {
215→      syslog(LOG_WARNING, "[ble-gatt] pair req notify failed\n");
216→    }
217→}
