219→/* ---- attr callbacks ---- */
220→
221→static uint16_t auth_on_read(void *srv, bt_address_t *addr, uint16_t attr,
222→                             uint32_t req)
223→{
224→  uint8_t buf[2] = { 0, 0 };
225→  (void)srv;
226→  (void)addr;
227→  (void)attr;
228→  bt_gatts_response(srv, addr, req, buf, 2);
229→  return 0;
230→}
231→
232→static uint16_t auth_on_write(void *srv, bt_address_t *addr, uint16_t attr,
233→                              const uint8_t *value, uint16_t length,
234→                              uint16_t offset)
235→{
236→  (void)srv;
237→  (void)attr;
238→  (void)offset;
239→
240→  if (length >= 2 && value[0] == DM_BT_CMD_PAIR_ACK && value[1] >= 4 &&
241→      length >= 6)
242→    {
243→      uint32_t resp = get_u32_le(value + 2);
244→      uint32_t expect;
245→      int accepted;
246→
247→      pthread_mutex_lock(&s_lock);
248→      expect = s_challenge ^ key_hash();
249→      accepted = s_pairing && resp == expect;
250→      s_pair_ticks = 0;
251→      s_challenge = 0;
252→      s_pairing = 0;
253→      s_paired = accepted;
254→      if (accepted && addr)
255→        {
256→          s_peer = *addr;
257→          s_paired_peer = *addr;
258→          s_has_peer = 1;
259→          s_has_paired_peer = 1;
260→        }
261→      pthread_mutex_unlock(&s_lock);
262→
263→      syslog(LOG_INFO, "[ble-gatt] pair ack resp=0x%x expect=0x%x\n",
264→             (unsigned)resp, (unsigned)expect);
265→      if (accepted)
266→        {
267→          set_state(DM_BLE_PAIRED);
268→          /* Confirm the application-level pairing, not just the ATT write. */
269→          if (send_pair_confirm() != 0)
270→            {
271→              syslog(LOG_WARNING, "[ble-gatt] pair confirmation notify failed\n");
272→            }
273→        }
274→      else
275→        {
276→          (void)send_pair_fail();
277→          set_state(DM_BLE_CONNECTED);
278→        }
279→      return length;
280→    }
281→
282→  if (length >= 2 && value[0] == DM_BT_CMD_PAIR_REQ)
283→    {
284→      start_pairing();
285→      return length;
286→    }
287→
288→  return length;
289→}
290→
291→static uint16_t cmd_on_write(void *srv, bt_address_t *addr, uint16_t attr,
292→                             const uint8_t *value, uint16_t length,
293→                             uint16_t offset)
294→{
295→  (void)srv;
296→  (void)attr;
297→  (void)offset;
298→
299→  if (addr)
300→    {
301→      pthread_mutex_lock(&s_lock);
302→      s_peer = *addr;
303→      s_has_peer = 1;
304→      pthread_mutex_unlock(&s_lock);
305→    }
306→
307→  if (length >= 1)
308→    {
309→      uint8_t cmd = value[0];
310→      if (cmd == DM_BT_CMD_PAIR_REQ)
311→        {
312→          start_pairing();
313→        }
314→      else if (cmd == DM_BT_CMD_HEARTBEAT)
315→        {
316→          /* keep-alive, ignore */
317→        }
318→      else if (cmd == DM_BT_CMD_PAIR_ACK && length >= 6)
319→        {
320→          /* App may write ACK on AUTH or CMD */
321→          auth_on_write(srv, addr, ATTR_AUTH, value, length, offset);
322→        }
323→    }
324→  return length;
325→}
326→
327→static uint16_t status_on_read(void *srv, bt_address_t *addr, uint16_t attr,
328→                               uint32_t req)
329→{
330→  uint8_t buf[2] = { DM_BT_CMD_NET_OFF, 0 };
331→  (void)attr;
332→  bt_gatts_response(srv, addr, req, buf, 2);
333→  return 0;
334→}
335→
336→static uint16_t cccd_on_write(void *srv, bt_address_t *addr, uint16_t attr,
337→                              const uint8_t *value, uint16_t length,
338→                              uint16_t offset)
339→{
340→  (void)srv;
341→  (void)addr;
342→  (void)offset;
343→  if (length < 1)
344→    {
345→      return length;
346→    }
347→  if (attr == ATTR_AUTH_CCCD)
348→    {
349→      int notify_enabled = value[0] != 0;
350→      int paired;
351→      pthread_mutex_lock(&s_lock);
352→      s_auth_cccd = value[0];
353→      paired = s_paired;
354→      pthread_mutex_unlock(&s_lock);
355→      if (notify_enabled)
356→        {
357→          if (paired)
358→            {
359→              /* Restore the App state after reconnecting to a known peer. */
360→              if (send_pair_confirm() != 0)
361→                {
362→                  syslog(LOG_WARNING,
363→                         "[ble-gatt] reconnect pair confirmation failed\n");
364→                }
365→            }
366→          else
367→            {
368→              start_pairing();
369→            }
370→        }
371→    }
372→  else if (attr == ATTR_CMD_CCCD)
373→    {
374→      pthread_mutex_lock(&s_lock);
375→      s_cmd_cccd = value[0];
376→      pthread_mutex_unlock(&s_lock);
377→    }
378→  else if (attr == ATTR_STATUS_CCCD)
379→    {
380→      pthread_mutex_lock(&s_lock);
381→      s_status_cccd = value[0];
382→      pthread_mutex_unlock(&s_lock);
383→    }
384→  return length;
385→}
