678→
679→/* Called from the UI tick.  Registration/adv is deferred here instead of
680→   running inside the adapter callback: doing it while the stack is still
681→   in HCI init raced zblue into a kernel oops and no advertisement ever
682→   started.  Keeps retrying every ~2s while starting. */
683→void dm_ble_poll(void)
684→{
685→  static int ticks;
686→  int pairing_timed_out = 0;
687→
688→  pthread_mutex_lock(&s_lock);
689→  if (s_pairing)
690→    {
691→      if (++s_pair_ticks >= DM_BLE_PAIR_TIMEOUT_TICKS)
692→        {
693→          s_pairing = 0;
694→          s_paired = 0;
695→          s_pair_ticks = 0;
696→          s_challenge = 0;
697→          pairing_timed_out = 1;
698→        }
699→    }
700→  else
701→    {
702→      s_pair_ticks = 0;
703→    }
704→  pthread_mutex_unlock(&s_lock);
705→
706→  if (pairing_timed_out)
707→    {
708→      syslog(LOG_WARNING, "[ble-gatt] pairing challenge timed out\n");
709→      (void)send_pair_fail();
710→      set_state(DM_BLE_CONNECTED);
711→    }
712→
713→  if (!s_start_pending || s_state != DM_BLE_STARTING)
714→    {
715→      ticks = 0;
716→      return;
717→    }
718→  if (++ticks < 8) /* ~2s settle for zblue HCI init */
719→    {
