 465→static int cd_save(void)
 466→{
 467→  FILE *f = fopen(COUNTDOWN_PATH, "w");
 468→  int i;
 469→  int ok = 1;
 470→  if (!f)
 471→    {
 472→      return -1;
 473→    }
 474→  for (i = 0; i < s_cd_n; i++)
 475→    {
 476→      int rc;
 477→      if (s_cd[i].has_alarm)
 478→        {
 479→          rc = fprintf(f, "%04d-%02d-%02d %02d:%02d %d %s\n",
 480→                       s_cd[i].y, s_cd[i].m, s_cd[i].d, s_cd[i].hour,
 481→                       s_cd[i].minute, s_cd[i].alarm_fired, s_cd[i].name);
 482→        }
 483→      else
 484→        {
 485→          rc = fprintf(f, "%04d-%02d-%02d %s\n", s_cd[i].y, s_cd[i].m,
 486→                       s_cd[i].d, s_cd[i].name);
 487→        }
 488→      if (rc < 0)
 489→        {
 490→          ok = 0;
 491→          break;
 492→        }
 493→    }
 494→  if (fclose(f) != 0)
 495→    {
 496→      ok = 0;
 497→    }
 498→  return ok ? 0 : -1;
 499→}
