 501→static void cd_load(void)
 502→{
 503→  FILE *f = fopen(COUNTDOWN_PATH, "r");
 504→  char line[128];
 505→  s_cd_n = 0;
 506→  s_cd_sel = 0;
 507→  if (!f)
 508→    {
 509→      /* seed demo */
 510→      time_t t = time(NULL);
 511→      struct tm tmv;
 512→      localtime_r(&t, &tmv);
 513→      memset(s_cd, 0, sizeof(s_cd));
 514→      s_cd[0].y = tmv.tm_year + 1900;
 515→      s_cd[0].m = 10;
 516→      s_cd[0].d = 1;
 517→      snprintf(s_cd[0].name, CD_NAME_MAX, "生日");
 518→      s_cd[1].y = tmv.tm_year + 1900;
 519→      s_cd[1].m = 12;
 520→      s_cd[1].d = 20;
 521→      snprintf(s_cd[1].name, CD_NAME_MAX, "考试");
 522→      s_cd_n = 2;
 523→      return;
 524→    }
 525→  memset(s_cd, 0, sizeof(s_cd));
 526→  while (s_cd_n < CD_MAX && fgets(line, sizeof(line), f))
 527→    {
 528→      int y;
 529→      int m;
 530→      int d;
 531→      int hour;
 532→      int minute;
 533→      int fired;
 534→      char name[CD_NAME_MAX];
 535→      int fields;
 536→
 537→      fields = sscanf(line, "%d-%d-%d %d:%d %d %47[^\r\n]",
 538→                      &y, &m, &d, &hour, &minute, &fired, name);
 539→      if (fields == 7 && m >= 1 && m <= 12 && d >= 1 && d <= 31 &&
 540→          hour >= 0 && hour <= 23 && minute >= 0 && minute <= 59)
 541→        {
 542→          s_cd[s_cd_n].y = y;
 543→          s_cd[s_cd_n].m = m;
 544→          s_cd[s_cd_n].d = d;
 545→          s_cd[s_cd_n].hour = hour;
 546→          s_cd[s_cd_n].minute = minute;
 547→          s_cd[s_cd_n].has_alarm = 1;
 548→          s_cd[s_cd_n].alarm_fired = fired ? 1 : 0;
 549→          snprintf(s_cd[s_cd_n].name, CD_NAME_MAX, "%s", name);
 550→          s_cd_n++;
 551→        }
 552→      else
 553→        {
 554→          fields = sscanf(line, "%d-%d-%d %47[^\r\n]", &y, &m, &d, name);
 555→          if (fields == 4 && m >= 1 && m <= 12 && d >= 1 && d <= 31)
 556→            {
 557→              s_cd[s_cd_n].y = y;
 558→              s_cd[s_cd_n].m = m;
 559→              s_cd[s_cd_n].d = d;
 560→              snprintf(s_cd[s_cd_n].name, CD_NAME_MAX, "%s", name);
 561→              s_cd_n++;
 562→            }
 563→        }
 564→    }
 565→  fclose(f);
 566→}
