 568→static int cd_days(const cd_item_t *it)
 569→{
 570→  time_t now = time(NULL);
 571→  struct tm tmv;
 572→  struct tm t2;
 573→  time_t target;
 574→
 575→  localtime_r(&now, &tmv);
 576→  memset(&t2, 0, sizeof(t2));
 577→  t2.tm_year = it->y - 1900;
 578→  t2.tm_mon = it->m - 1;
 579→  t2.tm_mday = it->d;
 580→  t2.tm_hour = 12;
 581→  target = mktime(&t2);
 582→  if (target == (time_t)-1)
 583→    {
 584→      return 0;
 585→    }
 586→  {
 587→    struct tm a;
 588→    struct tm b;
 589→    localtime_r(&target, &a);
 590→    localtime_r(&now, &b);
 591→    a.tm_hour = a.tm_min = a.tm_sec = 0;
 592→    b.tm_hour = b.tm_min = b.tm_sec = 0;
 593→    return (int)difftime(mktime(&a), mktime(&b)) / 86400;
 594→  }
 595→}
