 599→static time_t cd_alarm_time(const cd_item_t *item)
 600→{
 601→  struct tm tmv;
 602→  struct tm verify;
 603→  time_t target;
 604→
 605→  if (!item || !item->has_alarm || item->m < 1 || item->m > 12 ||
 606→      item->d < 1 || item->d > 31 || item->hour < 0 || item->hour > 23 ||
 607→      item->minute < 0 || item->minute > 59)
 608→    {
 609→      return (time_t)-1;
 610→    }
 611→  memset(&tmv, 0, sizeof(tmv));
 612→  tmv.tm_year = item->y - 1900;
 613→  tmv.tm_mon = item->m - 1;
 614→  tmv.tm_mday = item->d;
 615→  tmv.tm_hour = item->hour;
 616→  tmv.tm_min = item->minute;
 617→  tmv.tm_isdst = -1;
 618→  target = mktime(&tmv);
 619→  if (target == (time_t)-1)
 620→    {
 621→      return (time_t)-1;
 622→    }
 623→  localtime_r(&target, &verify);
 624→  if (verify.tm_year != item->y - 1900 || verify.tm_mon != item->m - 1 ||
 625→      verify.tm_mday != item->d || verify.tm_hour != item->hour ||
 626→      verify.tm_min != item->minute)
 627→    {
 628→      return (time_t)-1;
 629→    }
 630→  return target;
 631→}
 632→
 633→int dm_countdown_add_voice(const char *name, int year, int month, int day,
 634→                           int hour, int minute)
 635→{
 636→  time_t now = time(NULL);
 637→  struct tm current;
 638→  struct tm target_tm;
 639→  struct tm verify;
 640→  time_t target;
 641→  size_t len;
 642→
 643→  if (!name || !name[0] || month < 1 || month > 12 || day < 1 || day > 31 ||
 644→      hour < 0 || hour > 23 || minute < 0 || minute > 59 ||
 645→      year < 2024 || year > 2099)
 646→    {
 647→      return -1;
 648→    }
 649→  if (s_cd_n >= CD_MAX)
 650→    {
 651→      return -2;
 652→    }
 653→  localtime_r(&now, &current);
 654→  if (current.tm_year + 1900 < 2024)
 655→    {
 656→      return -4;
 657→    }
 658→
 659→  memset(&target_tm, 0, sizeof(target_tm));
 660→  target_tm.tm_year = year - 1900;
 661→  target_tm.tm_mon = month - 1;
 662→  target_tm.tm_mday = day;
 663→  target_tm.tm_hour = hour;
 664→  target_tm.tm_min = minute;
 665→  target_tm.tm_isdst = -1;
 666→  target = mktime(&target_tm);
 667→  if (target == (time_t)-1)
 668→    {
 669→      return -1;
 670→    }
 671→  localtime_r(&target, &verify);
 672→  if (verify.tm_year != year - 1900 || verify.tm_mon != month - 1 ||
 673→      verify.tm_mday != day || verify.tm_hour != hour ||
 674→      verify.tm_min != minute || target <= now)
 675→    {
 676→      return -1;
 677→    }
 678→
 679→  len = strlen(name);
 680→  if (len >= CD_NAME_MAX)
 681→    {
 682→      len = CD_NAME_MAX - 1;
 683→      while (len > 0 && ((unsigned char)name[len] & 0xc0u) == 0x80u)
 684→        {
 685→          len--;
 686→        }
 687→    }
 688→  if (len == 0)
 689→    {
 690→      return -1;
 691→    }
 692→
 693→  memset(&s_cd[s_cd_n], 0, sizeof(s_cd[s_cd_n]));
 694→  s_cd[s_cd_n].y = year;
 695→  s_cd[s_cd_n].m = month;
 696→  s_cd[s_cd_n].d = day;
 697→  s_cd[s_cd_n].hour = hour;
 698→  s_cd[s_cd_n].minute = minute;
 699→  s_cd[s_cd_n].has_alarm = 1;
 700→  memcpy(s_cd[s_cd_n].name, name, len);
 701→  s_cd[s_cd_n].name[len] = '\0';
 702→  s_cd_sel = s_cd_n;
 703→  s_cd_n++;
 704→  if (cd_save() != 0)
 705→    {
 706→      s_cd_n--;
 707→      memset(&s_cd[s_cd_n], 0, sizeof(s_cd[s_cd_n]));
 708→      return -3;
 709→    }
 710→  cd_paint();
 711→  dm_show(PAGE_COUNTDOWN);
 712→  return 0;
 713→}
