  1→/*
  2→ * dm_audio_vol.c — volume control for 4R 3W speaker
  3→ * Uses NuttX audio FEATURE/VOLUME ioctl (see nxplayer_setvolume),
  4→ * value range 0..1000 on device, 0..100% in UI.
  5→ * Persist to /data/deskmate_vol.txt
  6→ */
  7→
  8→#include "deskmate.h"
  9→#include "dm_audio_vol.h"
 10→
 11→#ifdef CONFIG_DESKMATE_APP
 12→
 13→#include <stdio.h>
 14→#include <string.h>
 15→#include <unistd.h>
 16→#include <fcntl.h>
 17→#include <errno.h>
 18→#include <syslog.h>
 19→#include <sys/ioctl.h>
 20→#include <nuttx/audio/audio.h>
 21→#include <aw-alsa-lib/control.h>
 22→#include "dm_voice.h"
 23→
 24→#define VOL_PATH "/data/deskmate_vol.txt"
 25→#define VOL_DEFAULT 80
 26→#define CODEC_CARD "audiocodec"
 27→#define DAC_VOL_MAX 160
 28→
 29→static int s_vol = VOL_DEFAULT;
 30→static int s_mute;
 31→
 32→/* Perceptual slider mapping: lift the quiet half of the range, while
 33→ * reserving headroom at the top to avoid the previous full-scale loudness. */
 34→static unsigned int vol_percent_to_reg(int percent)
 35→{
 36→  static const struct
 37→  {
 38→    unsigned char percent;
 39→    unsigned char reg;
 40→  } points[] =
 41→  {
 42→    { 0,   0 },
 43→    { 10, 48 },
 44→    { 25, 88 },
 45→    { 50, 124 },
 46→    { 75, 148 },
 47→    { 100, DAC_VOL_MAX }
 48→  };
 49→  unsigned int i;
 50→
 51→  if (percent <= 0)
 52→    {
 53→      return 0;
 54→    }
 55→  if (percent >= 100)
 56→    {
 57→      return DAC_VOL_MAX;
 58→    }
 59→
 60→  for (i = 1; i < sizeof(points) / sizeof(points[0]); i++)
 61→    {
 62→      if (percent <= points[i].percent)
 63→        {
 64→          unsigned int span = points[i].percent - points[i - 1].percent;
 65→          unsigned int value_span = points[i].reg - points[i - 1].reg;
 66→          unsigned int offset = (unsigned int)percent - points[i - 1].percent;
 67→          return points[i - 1].reg + (value_span * offset + span / 2) / span;
 68→        }
 69→    }
 70→
 71→  return DAC_VOL_MAX;
 72→}
