305→/* ---- player: nxplayer (buffer-queue API) ---- */
306→
307→/* The audio driver owns a small number of DMA channels.  Serialize all
308→ * playback and recording setup/teardown so the app never starts a new stream
309→ * while an earlier stream is still releasing its buffers. */
310→
311→/* Parse a PCM WAV and normalize it to the board's reliable playback format.
312→ * The R528 speaker path is known to work at 16 kHz, 16-bit stereo. In
313→ * particular, do not send 8 kHz mono recorder data or 24 kHz mono preview
314→ * files directly to the speaker endpoint. */
315→#define SPEAKER_RATE 16000
316→#define WAV_INPUT_MAX (4 * 1024 * 1024)
317→
318→static uint16_t voice_get_le16(const uint8_t *p)
319→{
320→  return (uint16_t)p[0] | ((uint16_t)p[1] << 8);
321→}
322→
323→static uint32_t voice_get_le32(const uint8_t *p)
324→{
325→  return (uint32_t)p[0] | ((uint32_t)p[1] << 8) |
326→         ((uint32_t)p[2] << 16) | ((uint32_t)p[3] << 24);
327→}
