329→static int voice_wav_find_data(FILE *f, uint16_t *channels, uint32_t *rate,
330→                               uint16_t *bits, long *data_offset,
331→                               uint32_t *data_size)
332→{
333→  uint8_t riff[12];
334→  uint8_t chunk[8];
335→  uint8_t fmt[16];
336→  long file_size;
337→  long offset = 12;
338→  int have_fmt = 0;
339→  int have_data = 0;
340→
341→  if (fread(riff, 1, sizeof(riff), f) != sizeof(riff) ||
342→      memcmp(riff, "RIFF", 4) != 0 || memcmp(riff + 8, "WAVE", 4) != 0 ||
343→      fseek(f, 0, SEEK_END) != 0 || (file_size = ftell(f)) < 44)
344→    {
345→      return -1;
346→    }
347→
348→  while (offset <= file_size - 8)
349→    {
350→      uint32_t chunk_size;
351→      long payload_offset;
352→
353→      if (fseek(f, offset, SEEK_SET) != 0 ||
354→          fread(chunk, 1, sizeof(chunk), f) != sizeof(chunk))
355→        {
356→          return -1;
357→        }
358→      chunk_size = voice_get_le32(chunk + 4);
359→      payload_offset = offset + 8;
360→      if (payload_offset > file_size ||
361→          chunk_size > (uint32_t)(file_size - payload_offset))
362→        {
363→          return -1;
364→        }
365→
366→      if (memcmp(chunk, "fmt ", 4) == 0)
367→        {
368→          if (chunk_size < sizeof(fmt) ||
369→              fseek(f, payload_offset, SEEK_SET) != 0 ||
370→              fread(fmt, 1, sizeof(fmt), f) != sizeof(fmt) ||
371→              voice_get_le16(fmt) != 1)
372→            {
373→              return -1;
374→            }
375→          *channels = voice_get_le16(fmt + 2);
376→          *rate = voice_get_le32(fmt + 4);
377→          *bits = voice_get_le16(fmt + 14);
378→          have_fmt = 1;
379→        }
