void dm_reminder_tick(void)
{
  time_t now;
  int i;

  if (s_voice_done)
    {
      s_voice_done = 0;
      s_voice_busy = 0;
    }
  if (s_alert_idx >= 0)
    {
      return;
    }
  now = time(NULL);
  if (!reminder_clock_valid(now))
    {
      return;
    }
  for (i = 0; i < s_count; i++)
    {
      reminder_t *item = &s_items[i];
      if (item->fired || item->due > now)
        {
          continue;
        }
      if (item->type == REMINDER_ALARM && item->repeat_daily)
        {
          struct tm next;
          localtime_r(&item->due, &next);
          next.tm_mday++;
          next.tm_hour = item->hour;
          next.tm_min = item->minute;
          next.tm_sec = 0;
          next.tm_isdst = -1;
          item->due = mktime(&next);
          item->fired = 0;
        }
      else
        {
          item->fired = 1;
        }
      reminder_save();
      s_alert_idx = i;
      if (s_alert_title)
        {
          lv_label_set_text(s_alert_title,
                            item->type == REMINDER_ALARM ? "闹钟响了" : "待办提醒");
        }
      if (s_alert_text)
        {
          lv_label_set_text(s_alert_text, item->text);
        }
      if (s_alert)
        {
          lv_obj_clear_flag(s_alert, LV_OBJ_FLAG_HIDDEN);
          lv_obj_move_foreground(s_alert);
        }
      if (g_dm_dock) lv_obj_add_flag(g_dm_dock, LV_OBJ_FLAG_HIDDEN);
      (void)reminder_speak(i);
      reminder_paint();
      return;
    }
  reminder_paint();
}

