414→static void *reminder_speech_worker(void *arg)
415→{
416→  reminder_speech_t *speech = arg;
417→  char line[REMINDER_TEXT_MAX + 48];
418→  int rc = -1;
419→  int attempt;
420→
421→  if (!speech)
422→    {
423→      return NULL;
424→    }
425→  if (speech->is_alarm)
426→    {
427→      snprintf(line, sizeof(line), "闹钟响了：%s。", speech->text);
428→    }
429→  else
430→    {
431→      snprintf(line, sizeof(line), "待办提醒：%s。", speech->text);
432→    }
433→
434→  dm_vol_alarm_begin();
435→  for (attempt = 0; attempt < 3; attempt++)
436→    {
437→      rc = dm_voice_tts_play(line);
438→      if (rc == 0)
439→        {
440→          break;
441→        }
442→      if (attempt < 2)
443→        {
444→          sleep(2);
445→        }
446→    }
447→  if (rc != 0)
448→    {
449→      (void)dm_voice_beep();
450→    }
451→  dm_vol_alarm_end();
452→  free(speech);
453→  s_voice_done = 1;
454→  return NULL;
455→}
