457→static int reminder_speak(int index)
458→{
459→  reminder_speech_t *speech;
460→  pthread_t th;
461→  pthread_attr_t attr;
462→  int rc;
463→
464→  if (index < 0 || index >= s_count || s_voice_busy)
465→    {
466→      return -1;
467→    }
468→  speech = malloc(sizeof(*speech));
469→  if (!speech)
470→    {
471→      return -1;
472→    }
473→  speech->is_alarm = s_items[index].type == REMINDER_ALARM;
474→  snprintf(speech->text, sizeof(speech->text), "%s", s_items[index].text);
475→  s_voice_busy = 1;
476→  s_voice_done = 0;
477→  pthread_attr_init(&attr);
478→  pthread_attr_setstacksize(&attr, DM_VOICE_NET_WORKER_STACK);
479→  rc = pthread_create(&th, &attr, reminder_speech_worker, speech);
480→  pthread_attr_destroy(&attr);
481→  if (rc != 0)
482→    {
483→      s_voice_busy = 0;
484→      free(speech);
485→      return -1;
486→    }
487→  pthread_detach(th);
488→  return 0;
489→}
