int dm_alarm_add_voice(const char *name, int hour, int minute,
                       int day_offset, int repeat_daily)
{
  time_t now = time(NULL);
  struct tm tmv;
  struct tm verify;
  time_t due;

  if (!reminder_clock_valid(now))
    {
      return -4;
    }
  if (hour < 0 || hour > 23 || minute < 0 || minute > 59 ||
      day_offset < 0 || day_offset > 366)
    {
      return -1;
    }
  localtime_r(&now, &tmv);
  tmv.tm_mday += day_offset;
  tmv.tm_hour = hour;
  tmv.tm_min = minute;
  tmv.tm_sec = 0;
  tmv.tm_isdst = -1;
  due = mktime(&tmv);
  if (due == (time_t)-1)
    {
      return -1;
    }
  localtime_r(&due, &verify);
  if (verify.tm_hour != hour || verify.tm_min != minute)
    {
      return -1;
    }
  if (repeat_daily && due <= now)
    {
      verify.tm_mday++;
      verify.tm_hour = hour;
      verify.tm_min = minute;
      verify.tm_sec = 0;
      verify.tm_isdst = -1;
      due = mktime(&verify);
    }
  else if (due <= now)
    {
      return -1;
    }
  return reminder_append(REMINDER_ALARM, name, due, repeat_daily, hour, minute);
}

input.new_string:
int dm_alarm_add_voice(const char *name, int year, int month, int day,
                       int hour, int minute, int repeat_daily)
{
  time_t now = time(NULL);
  struct tm tmv;
  struct tm verify;
  time_t due;

  if (!reminder_clock_valid(now))
    {
      return -4;
    }
  if (year < 2024 || year > 2099 || month < 1 || month > 12 ||
      day < 1 || day > 31 || hour < 0 || hour > 23 || minute < 0 ||
      minute > 59)
    {
      return -1;
    }
  memset(&tmv, 0, sizeof(tmv));
  tmv.tm_year = year - 1900;
  tmv.tm_mon = month - 1;
  tmv.tm_mday = day;
  tmv.tm_hour = hour;
  tmv.tm_min = minute;
  tmv.tm_isdst = -1;
  due = mktime(&tmv);
  if (due == (time_t)-1)
    {
      return -1;
    }
  localtime_r(&due, &verify);
  if (verify.tm_year != year - 1900 || verify.tm_mon != month - 1 ||
      verify.tm_mday != day || verify.tm_hour != hour || verify.tm_min != minute)
    {
      return -1;
    }
  if (repeat_daily && due <= now)
    {
      verify.tm_mday++;
      verify.tm_isdst = -1;
      due = mktime(&verify);
    }
  else if (due <= now)
    {
      return -1;
    }
  return reminder_append(REMINDER_ALARM, name, due, repeat_daily, hour, minute);
}

int dm_alarm_add_after_voice(const char *name, int delay_seconds)
{
  time_t now = time(NULL);
  struct tm tmv;
  if (!reminder_clock_valid(now))
    {
      return -4;
    }
  if (delay_seconds < 1 || delay_seconds > TODO_MAX_SECONDS)
    {
      return -1;
    }
  now += delay_seconds;
  if (!localtime_r(&now, &tmv))
    {
      return -1;
    }
  return reminder_append(REMINDER_ALARM, name, now, 0,
                         tmv.tm_hour, tmv.tm_min);
}

