147→static int reminder_copy_text(const char *in, char *out, size_t cap)
148→{
149→  size_t n;
150→  if (!in || !out || cap < 2)
151→    {
152→      return -1;
153→    }
154→  while (*in == ' ' || *in == '\t')
155→    {
156→      in++;
157→    }
158→  n = strlen(in);
159→  while (n > 0 && (in[n - 1] == ' ' || in[n - 1] == '\t' ||
160→                   in[n - 1] == '\r' || in[n - 1] == '\n'))
161→    {
162→      n--;
163→    }
164→  if (n == 0)
165→    {
166→      return -1;
167→    }
168→  if (n >= cap)
169→    {
170→      n = cap - 1;
171→      while (n > 0 && ((unsigned char)in[n] & 0xc0u) == 0x80u)
172→        {
173→          n--;
174→        }
175→    }
176→  memcpy(out, in, n);
177→  out[n] = '\0';
178→  return n > 0 ? 0 : -1;
179→}
