 37→/* Perceptual slider mapping: lift the quiet half of the range, while
 38→ * reserving headroom at the top to avoid the previous full-scale loudness. */
 39→static unsigned int vol_percent_to_reg(int percent)
 40→{
 41→  static const struct
 42→  {
 43→    unsigned char percent;
 44→    unsigned char reg;
 45→  } points[] =
 46→  {
 47→    { 0,   0 },
 48→    { 10, 48 },
 49→    { 25, 88 },
 50→    { 50, 124 },
 51→    { 75, 148 },
 52→    { 100, DAC_VOL_MAX }
 53→  };
 54→  unsigned int i;
 55→
 56→  if (percent <= 0)
 57→    {
 58→      return 0;
 59→    }
 60→  if (percent >= 100)
 61→    {
 62→      return DAC_VOL_MAX;
 63→    }
 64→
 65→  for (i = 1; i < sizeof(points) / sizeof(points[0]); i++)
 66→    {
 67→      if (percent <= points[i].percent)
 68→        {
 69→          unsigned int span = points[i].percent - points[i - 1].percent;
 70→          unsigned int value_span = points[i].reg - points[i - 1].reg;
 71→          unsigned int offset = (unsigned int)percent - points[i - 1].percent;
 72→          return points[i - 1].reg + (value_span * offset + span / 2) / span;
 73→        }
 74→    }
 75→
 76→  return DAC_VOL_MAX;
 77→}
