576→static int parse_alarm_time(const char *text, assistant_intent_t *intent)
577→{
578→  size_t ds;
579→  size_t de;
580→  size_t ts;
581→  size_t te;
582→  const char *time_mark;
583→  const char *minute_mark;
584→  size_t hour_start;
585→  int hour;
586→  int minute = 0;
587→  int day_offset = 0;
588→  int has_datetime;
589→  time_t now;
590→  struct tm current;
591→  struct tm target;
592→  time_t when;
593→
594→  has_datetime = parse_datetime(text, &intent->year, &intent->month, &intent->day,
595→                                &intent->hour, &intent->minute, &ds, &de,
596→                                &ts, &te);
597→  if (has_datetime == 1)
598→    {
599→      intent->repeat_daily = strstr(text, "每天") || strstr(text, "每日") ||
600→                             strstr(text, "天天") ? 1 : 0;
601→      clean_alarm_name(text, intent->text, sizeof(intent->text));
602→      return 1;
603→    }
604→  if (has_datetime < 0)
605→    {
606→      return -1;
607→    }
608→
609→  time_mark = first_of(text, "点", "时");
610→  if (!time_mark ||
611→      !parse_number_before(text, (size_t)(time_mark - text), &hour_start, &hour) ||
612→      hour < 0 || hour > 23)
613→    {
614→      return 0;
615→    }
616→  minute_mark = strstr(time_mark + 3, "分");
617→  if (minute_mark)
618→    {
619→      size_t minute_start;
620→      int parsed;
621→      if (!parse_number_before(text, (size_t)(minute_mark - text), &minute_start,
622→                               &parsed) ||
623→          minute_start < (size_t)(time_mark + 3 - text) || parsed < 0 || parsed > 59)
624→        {
625→          return 0;
626→        }
627→      minute = parsed;
628→    }
629→  else if (strncmp(time_mark + 3, "半", 3) == 0)
630→    {
631→      minute = 30;
632→    }
633→
634→  if ((strstr(text, "凌晨") || strstr(text, "早上") || strstr(text, "上午")) &&
635→      hour == 12)
636→    {
637→      hour = 0;
638→    }
639→  else if ((strstr(text, "下午") || strstr(text, "晚上") ||
640→            strstr(text, "傍晚")) && hour < 12)
641→    {
642→      hour += 12;
643→    }
644→
645→  now = time(NULL);
646→  if (!localtime_r(&now, &current) || current.tm_year + 1900 < 2024)
647→    {
648→      return -1;
649→    }
650→  if (strstr(text, "后天")) day_offset = 2;
651→  else if (strstr(text, "明天")) day_offset = 1;
652→  memset(&target, 0, sizeof(target));
653→  target.tm_year = current.tm_year;
654→  target.tm_mon = current.tm_mon;
655→  target.tm_mday = current.tm_mday + day_offset;
656→  target.tm_hour = hour;
657→  target.tm_min = minute;
658→  target.tm_isdst = -1;
659→  when = mktime(&target);
660→  if (when == (time_t)-1)
661→    {
662→      return 0;
663→    }
664→  if (day_offset == 0 && when <= now &&
665→      !(strstr(text, "每天") || strstr(text, "每日") || strstr(text, "天天")))
666→    {
667→      target.tm_mday++;
668→      target.tm_isdst = -1;
669→      when = mktime(&target);
670→    }
671→  localtime_r(&when, &target);
672→  intent->year = target.tm_year + 1900;
673→  intent->month = target.tm_mon + 1;
674→  intent->day = target.tm_mday;
675→  intent->hour = hour;
676→  intent->minute = minute;
677→  intent->repeat_daily = strstr(text, "每天") || strstr(text, "每日") ||
678→                         strstr(text, "天天") ? 1 : 0;
679→  clean_alarm_name(text, intent->text, sizeof(intent->text));
680→  return 1;
681→}
