230→int dm_alarm_add_voice(const char *name, int year, int month, int day,
231→                       int hour, int minute, int repeat_daily)
232→{
233→  time_t now = time(NULL);
234→  struct tm tmv;
235→  struct tm verify;
236→  time_t due;
237→
238→  if (!reminder_clock_valid(now))
239→    {
240→      return -4;
241→    }
242→  if (year < 2024 || year > 2099 || month < 1 || month > 12 ||
243→      day < 1 || day > 31 || hour < 0 || hour > 23 || minute < 0 ||
244→      minute > 59)
245→    {
246→      return -1;
247→    }
248→  memset(&tmv, 0, sizeof(tmv));
249→  tmv.tm_year = year - 1900;
250→  tmv.tm_mon = month - 1;
251→  tmv.tm_mday = day;
252→  tmv.tm_hour = hour;
253→  tmv.tm_min = minute;
254→  tmv.tm_isdst = -1;
255→  due = mktime(&tmv);
256→  if (due == (time_t)-1)
257→    {
258→      return -1;
259→    }
260→  localtime_r(&due, &verify);
261→  if (verify.tm_year != year - 1900 || verify.tm_mon != month - 1 ||
262→      verify.tm_mday != day || verify.tm_hour != hour || verify.tm_min != minute)
263→    {
264→      return -1;
265→    }
266→  if (repeat_daily && due <= now)
267→    {
268→      verify.tm_mday++;
269→      verify.tm_isdst = -1;
270→      due = mktime(&verify);
271→    }
272→  else if (due <= now)
273→    {
274→      return -1;
275→    }
276→  return reminder_append(REMINDER_ALARM, name, due, repeat_daily, hour, minute);
277→}
