224→/* ---- attr callbacks ---- */
225→
226→static uint16_t auth_on_read(void *srv, bt_address_t *addr, uint16_t attr,
227→                             uint32_t req)
228→{
229→  uint8_t buf[2] = { 0, 0 };
230→  (void)srv;
231→  (void)addr;
232→  (void)attr;
233→  bt_gatts_response(srv, addr, req, buf, 2);
234→  return 0;
235→}
236→
237→static uint16_t auth_on_write(void *srv, bt_address_t *addr, uint16_t attr,
238→                              const uint8_t *value, uint16_t length,
239→                              uint16_t offset)
240→{
241→  (void)srv;
242→  (void)attr;
243→  (void)offset;
244→
245→  if (length >= 2 && value[0] == DM_BT_CMD_PAIR_ACK && value[1] >= 4 &&
246→      length >= 6)
247→    {
248→      uint32_t resp = get_u32_le(value + 2);
249→      uint32_t expect;
250→      int accepted;
251→
252→      pthread_mutex_lock(&s_lock);
253→      expect = s_challenge ^ key_hash();
254→      accepted = s_pairing && resp == expect;
255→      s_pair_ticks = 0;
256→      s_challenge = 0;
257→      s_pairing = 0;
258→      s_paired = accepted;
259→      if (accepted && addr)
260→        {
261→          s_peer = *addr;
262→          s_paired_peer = *addr;
263→          s_has_peer = 1;
264→          s_has_paired_peer = 1;
265→        }
266→      pthread_mutex_unlock(&s_lock);
267→
268→      syslog(LOG_INFO, "[ble-gatt] pair ack resp=0x%x expect=0x%x\n",
269→             (unsigned)resp, (unsigned)expect);
270→      if (accepted)
271→        {
272→          set_state(DM_BLE_PAIRED);
273→          /* Confirm the application-level pairing, not just the ATT write. */
274→          if (send_pair_confirm() != 0)
275→            {
276→              syslog(LOG_WARNING, "[ble-gatt] pair confirmation notify failed\n");
277→            }
278→        }
279→      else
280→        {
281→          (void)send_pair_fail();
282→          set_state(DM_BLE_CONNECTED);
283→        }
284→      return length;
285→    }
286→
287→  if (length >= 2 && value[0] == DM_BT_CMD_PAIR_REQ)
288→    {
289→      start_pairing();
290→      return length;
291→    }
292→
293→  return length;
294→}
