305→    fun startScan() {
306→        if (scanning) {
307→            stopScan()
308→            return
309→        }
310→        val bt = adapter
311→        if (bt == null) {
312→            fail("此设备不支持 BLE")
313→            return
314→        }
315→        if (!hasScanPermission()) {
316→            fail("缺少蓝牙扫描权限，请授予「附近的设备」权限")
317→            return
318→        }
319→        if (!hasConnectPermission()) {
320→            fail("缺少蓝牙连接权限，请授予「附近的设备」权限")
321→            return
322→        }
323→        if (!bt.isEnabled) {
324→            promptEnableBluetooth()
325→            return
326→        }
327→        val scanner = try {
328→            bt.bluetoothLeScanner
329→        } catch (e: SecurityException) {
330→            null
331→        }
332→        if (scanner == null) {
333→            fail("无法获取 BLE 扫描器，请确认蓝牙已开启")
334→            return
335→        }
336→        scanResults.clear()
337→        scanGeneration++
338→        val generation = scanGeneration
339→        val callback = createScanCallback(generation)
340→        activeScanCallback = callback
341→        scanning = true
342→        _state.update {
343→            it.copy(
344→                connState = ConnState.SCANNING,
345→                devices = emptyList(),
346→                selectedAddress = null,
347→                statusText = "正在扫描…",
348→                hint = "只显示广播专属 Service UUID 的设备（12 秒）"
349→            )
350→        }
351→        val filters = listOf(
352→            ScanFilter.Builder()
353→                .setServiceUuid(ParcelUuid(BleProtocol.SERVICE_UUID))
354→                .build()
355→        )
356→        val settings = ScanSettings.Builder()
357→            .setScanMode(ScanSettings.SCAN_MODE_LOW_LATENCY)
358→            .build()
359→        try {
360→            scanner.startScan(filters, settings, callback)
361→            log("开始扫描：过滤 Service UUID")
362→        } catch (e: SecurityException) {
363→            scanning = false
364→            activeScanCallback = null
365→            scanGeneration++
366→            fail("扫描失败：蓝牙权限被拒绝")
367→            return
368→        }
369→        handler.postDelayed(scanTimeout, SCAN_TIMEOUT_MS)
370→    }
