372→    fun stopScan() {
373→        if (!scanning) return
374→        stopScanInternal()
375→        val count = _state.value.devices.size
376→        _state.update {
377→            it.copy(
378→                connState = if (it.paired) ConnState.PAIRED else ConnState.IDLE,
379→                statusText = "扫描结束，发现 " + count + " 台专属设备",
380→                hint = if (count > 0) {
381→                    "点选设备后点「连接」"
