404→    fun connect(address: String) {
405→        val bt = adapter
406→        if (bt == null) {
407→            fail("此设备不支持 BLE")
408→            return
409→        }
410→        if (!hasConnectPermission()) {
411→            fail("缺少蓝牙连接权限，请授予「附近的设备」权限")
412→            return
413→        }
414→        if (!bt.isEnabled) {
415→            promptEnableBluetooth()
416→            return
417→        }
418→        if (scanning) stopScan()
419→        manualDisconnect = false
420→        val device = try {
421→            bt.getRemoteDevice(address)
422→        } catch (e: SecurityException) {
423→            null
424→        } catch (e: IllegalArgumentException) {
425→            null
426→        }
427→        if (device == null) {
428→            fail("无效的设备地址")
429→            return
430→        }
431→        closeGatt()
432→        _state.update {
433→            it.copy(
434→                connState = ConnState.CONNECTING,
435→                statusText = "正在连接…",
436→                hint = address,
437→                connectedAddress = address,
438→                selectedAddress = address,
439→                paired = false,
440→                networkShared = false,
441→                pairingPhase = PairingPhase.NONE
442→            )
443→        }
444→        log("连接 " + address)
445→        gatt = try {
446→            device.connectGatt(appContext, false, gattCallback, BluetoothDevice.TRANSPORT_LE)
447→        } catch (e: SecurityException) {
448→            null
449→        }
450→        if (gatt == null) {
451→            fail("连接失败：请检查蓝牙权限和设备状态")
452→        } else {
453→            handler.removeCallbacks(connectionTimeout)
454→            handler.postDelayed(connectionTimeout, CONNECT_TIMEOUT_MS)
455→        }
456→    }
