458→    fun requestPair() {
459→        val current = _state.value
460→        if (current.paired) {
461→            log("已经配对，无需重复配对")
462→            return
463→        }
464→        if (current.connState == ConnState.PAIRING) {
465→            log("正在等待板子完成配对，不重复发送请求")
466→            return
467→        }
468→        if (gatt == null || authChar == null || queue == null) {
469→            fail("请先连接设备")
470→            return
471→        }
472→        if (!hasConnectPermission()) {
473→            fail("缺少蓝牙连接权限")
474→            return
475→        }
476→        pendingPairAck = false
477→        ackWriteSucceeded = false
478→        boardPairConfirmed = false
479→        awaitingReconnectConfirmation = false
480→        _state.update {
481→            it.copy(
482→                connState = ConnState.PAIRING,
483→                pairingPhase = PairingPhase.PAIRING,
484→                statusText = "正在配对…",
485→                hint = "已向板子发送 Pair Request，等待 challenge"
486→            )
487→        }
488→        handler.removeCallbacks(pairTimeout)
489→        handler.postDelayed(pairTimeout, PAIR_TIMEOUT_MS)
490→        val target = cmdChar ?: authChar
