537→    private fun handleNotification(value: ByteArray) {
538→        val msg = BleProtocol.parse(value) ?: return
539→        log("收到 " + BleProtocol.commandName(msg.cmd) + " [" + BleProtocol.hex(value) + "]")
540→        when (msg.cmd) {
541→            BleProtocol.CMD_PAIR_REQ -> handlePairRequest(msg)
542→            BleProtocol.CMD_PAIR_ACK -> {
543→                if (msg.payload.isNotEmpty()) {
544→                    log("PairAck 确认帧长度错误，忽略")
545→                } else if (pendingPairAck) {
546→                    boardPairConfirmed = true
547→                    log("收到板端 PairAck 协议确认")
548→                    if (ackWriteSucceeded) onPairSuccess()
549→                } else if (awaitingReconnectConfirmation && gatt != null &&
550→                    _state.value.connState == ConnState.PAIRING) {
551→                    awaitingReconnectConfirmation = false
552→                    log("板端确认此前已配对的设备")
553→                    onPairSuccess()
554→                } else {
555→                    log("收到无待处理事务的 PairAck，忽略")
556→                }
557→            }
558→            BleProtocol.CMD_PAIR_FAIL -> onPairFailed("板子返回配对失败")
559→            BleProtocol.CMD_NET_ON -> {
560→                _state.update {
561→                    it.copy(
562→                        networkShared = true,
563→                        statusText = "网络共享已开启",
564→                        hint = "板子已请求联网，请保持蓝牙网络共享开启"
565→                    )
566→                }
567→                log("板子请求开启网络共享")
568→            }
569→
570→            BleProtocol.CMD_NET_OFF -> {
571→                _state.update {
572→                    it.copy(
573→                        networkShared = false,
574→                        statusText = "网络共享已关闭",
575→                        hint = "可在系统设置中重新开启蓝牙网络共享"
576→                    )
577→                }
578→                log("板子请求关闭网络共享")
579→            }
580→
581→            BleProtocol.CMD_HEARTBEAT -> {
582→                // 板子心跳，保持静默
583→            }
584→
585→            else -> log("未识别命令 " + BleProtocol.commandName(msg.cmd))
586→        }
587→    }
