589→    private fun handlePairRequest(msg: BleProtocol.Message) {
590→        val challenge = BleProtocol.readChallenge(msg)
591→        if (challenge == null) {
592→            log("PairRequest 数据长度不足，忽略")
593→            return
594→        }
595→        if (_state.value.paired) {
596→            log("已经配对，忽略重复 PairRequest")
597→            return
598→        }
599→        awaitingReconnectConfirmation = false
600→        val target = authChar ?: cmdChar ?: statusChar
601→        if (target == null) {
602→            fail("没有可写入的配对特征")
603→            return
604→        }
605→        log("收到 challenge=0x" + String.format(Locale.US, "%08X", challenge))
606→        _state.update {
607→            it.copy(
608→                connState = ConnState.PAIRING,
609→                pairingPhase = PairingPhase.PAIRING,
610→                statusText = "正在配对…",
611→                hint = "已收到 challenge，正在回复 Pair ACK"
612→            )
613→        }
614→        handler.removeCallbacks(pairTimeout)
615→        handler.postDelayed(pairTimeout, PAIR_TIMEOUT_MS)
616→        pendingPairAck = true
617→        ackWriteSucceeded = false
618→        boardPairConfirmed = false
619→        ackCharUuid = target.uuid
620→        writeCharacteristic(target, BleProtocol.buildPairAck(challenge), "PairAck")
621→    }
