604→  params.tx_power = 0;
605→  params.interval = 160; /* 100ms */
606→  params.duration = 0;
607→  params.channel_map = 7;
608→  params.filter_policy = BT_LE_ADV_FILTER_WHITE_LIST_FOR_NONE;
609→
610→  adv_data = advertiser_data_new();
611→  if (!adv_data)
612→    {
613→      return -1;
614→    }
615→  advertiser_data_set_flags(adv_data,
616→                            BT_AD_FLAG_GENERAL_DISCOVERABLE |
617→                            BT_AD_FLAG_BREDR_NOT_SUPPORT);
618→  advertiser_data_add_service_uuid(adv_data, &k_svc_uuid);
619→  p_adv = advertiser_data_build(adv_data, &adv_len);
620→
621→  scan_rsp = advertiser_data_new();
622→  if (scan_rsp)
623→    {
624→      advertiser_data_set_name(scan_rsp, "FlowDesk-S1");
625→      p_rsp = advertiser_data_build(scan_rsp, &rsp_len);
626→    }
627→  else
628→    {
629→      p_rsp = NULL;
630→    }
631→
632→  s_adv = bt_le_start_advertising(s_ins, &params,
633→                                  p_adv, adv_len,
634→                                  p_rsp, rsp_len,
635→                                  &s_adv_cbs);
636→
637→  advertiser_data_free(adv_data);
638→  if (scan_rsp)
639→    {
640→      advertiser_data_free(scan_rsp);
641→    }
642→
643→  if (!s_adv)
644→    {
645→      syslog(LOG_ERR, "[ble-gatt] start advertising failed\n");
646→      set_state(DM_BLE_ERROR);
