662→/* ---- adapter ---- */
663→
664→static volatile int s_start_pending;
665→
666→static void do_register_and_adv(void)
667→{
668→  if (!s_srv)
669→    {
670→      bt_status_t ret = bt_gatts_register_service(s_ins, &s_srv,
671→                                                 &s_gatts_cbs);
672→      if (ret != BT_STATUS_SUCCESS || !s_srv)
673→        {
674→          syslog(LOG_ERR, "[ble-gatt] register service fail %d\n", (int)ret);
675→          s_srv = NULL;
676→          return;
677→        }
678→      /* start_adv() also fires from on_attr_table_added when ready */
679→      bt_gatts_add_attr_table(s_srv, &s_srv_db);
680→    }
681→  (void)start_adv();
682→}
683→
684→/* Called from the UI tick.  Registration/adv is deferred here instead of
685→   running inside the adapter callback: doing it while the stack is still
686→   in HCI init raced zblue into a kernel oops and no advertisement ever
687→   started.  Keeps retrying every ~2s while starting. */
688→void dm_ble_poll(void)
689→{
690→  static int ticks;
691→  int pairing_timed_out = 0;
692→
693→  pthread_mutex_lock(&s_lock);
694→  if (s_pairing)
695→    {
696→      if (++s_pair_ticks >= DM_BLE_PAIR_TIMEOUT_TICKS)
697→        {
698→          s_pairing = 0;
699→          s_paired = 0;
700→          s_pair_ticks = 0;
701→          s_challenge = 0;
702→          pairing_timed_out = 1;
703→        }
704→    }
705→  else
706→    {
707→      s_pair_ticks = 0;
708→    }
709→  pthread_mutex_unlock(&s_lock);
710→
711→  if (pairing_timed_out)
712→    {
713→      syslog(LOG_WARNING, "[ble-gatt] pairing challenge timed out\n");
714→      (void)send_pair_fail();
715→      set_state(DM_BLE_CONNECTED);
716→    }
717→
718→  if (!s_start_pending || s_state != DM_BLE_STARTING)
719→    {
720→      ticks = 0;
721→      return;
722→    }
723→  if (++ticks < 8) /* ~2s settle for zblue HCI init */
724→    {
725→      return;
726→    }
727→  ticks = 0;
728→  if (!s_ins || bt_adapter_get_state(s_ins) != BT_ADAPTER_STATE_ON)
729→    {
730→      return;
731→    }
732→  do_register_and_adv();
733→  if (s_adv)
734→    {
735→      s_start_pending = 0;
736→    }
737→}
