739→static void adapter_state_cb(void *cookie, bt_adapter_state_t state)
740→{
741→  (void)cookie;
742→  syslog(LOG_INFO, "[ble-gatt] adapter state=%d\n", (int)state);
743→  if (state == BT_ADAPTER_STATE_ON)
744→    {
745→      s_start_pending = 1;
746→    }
747→}
748→
749→static adapter_callbacks_t s_adapter_cbs = {
750→  .on_adapter_state_changed = adapter_state_cb,
751→};
752→
753→int dm_ble_start(void)
754→{
755→  if (s_state != DM_BLE_IDLE && s_state != DM_BLE_ERROR)
756→    {
757→      return 0;
758→    }
759→
760→  set_state(DM_BLE_STARTING);
761→  pthread_mutex_lock(&s_lock);
762→  s_paired = 0;
763→  s_pairing = 0;
764→  s_pair_ticks = 0;
765→  s_challenge = 0;
766→  s_has_peer = 0;
767→  pthread_mutex_unlock(&s_lock);
768→  srand((unsigned int)time(NULL) ^ (unsigned int)(uintptr_t)s_ins);
769→
770→  if (!s_ins)
771→    {
772→      s_ins = bluetooth_create_instance();
773→      if (!s_ins)
774→        {
775→          syslog(LOG_ERR, "[ble-gatt] create instance fail\n");
776→          set_state(DM_BLE_ERROR);
777→          return -1;
778→        }
779→    }
780→
781→  if (!s_adapter_cb)
782→    {
783→      s_adapter_cb = bt_adapter_register_callback(s_ins, &s_adapter_cbs);
784→    }
785→
786→  if (bt_adapter_enable(s_ins) != BT_STATUS_SUCCESS)
787→    {
788→      /* may already be on — verify before registering */
789→      if (bt_adapter_get_state(s_ins) == BT_ADAPTER_STATE_ON)
790→        {
791→          adapter_state_cb(NULL, BT_ADAPTER_STATE_ON);
792→        }
793→      else
794→        {
795→          syslog(LOG_ERR, "[ble-gatt] adapter enable fail\n");
796→          set_state(DM_BLE_ERROR);
797→          return -1;
798→        }
799→    }
800→  return 0;
801→}
