747→    private fun writeCharacteristic(c: BluetoothGattCharacteristic, value: ByteArray, label: String) {
748→        if (!hasConnectPermission()) {
749→            log(label + "：缺少蓝牙连接权限")
750→            return
751→        }
752→        val q = queue
753→        if (q == null) {
754→            log(label + "：GATT 队列未就绪")
755→            return
756→        }
757→        q.enqueue(GattOp.WriteCharacteristic(c, value, label))
758→    }
