869→private sealed class GattOp {
870→    abstract val label: String
871→
872→    data class WriteCharacteristic(
873→        val characteristic: BluetoothGattCharacteristic,
874→        val value: ByteArray,
875→        override val label: String,
876→        val writeType: Int = BluetoothGattCharacteristic.WRITE_TYPE_DEFAULT
877→    ) : GattOp()
878→
879→    data class WriteDescriptor(
880→        val descriptor: BluetoothGattDescriptor,
881→        val value: ByteArray,
882→        override val label: String
883→    ) : GattOp()
884→}
885→
886→/** 串行执行 GATT 操作：Android 同一时刻只允许一个 GATT 写操作。 */
887→private class GattQueue(
888→    private val gatt: BluetoothGatt,
889→    private val onMessage: (String?) -> Unit
890→) {
891→    private val pending = ArrayDeque<GattOp>()
892→    private var busy = false
893→
894→    fun enqueue(op: GattOp) {
895→        pending.addLast(op)
896→        pump()
897→    }
898→
899→    fun onOperationFinished(error: String?) {
900→        busy = false
901→        if (error != null) onMessage(error)
902→        pump()
903→    }
904→
905→    private fun pump() {
906→        if (busy) return
907→        val op = pending.removeFirstOrNull() ?: return
908→        busy = true
909→        val ok = when (op) {
910→            is GattOp.WriteCharacteristic -> writeCharacteristic(op)
911→            is GattOp.WriteDescriptor -> writeDescriptor(op)
912→        }
913→        if (!ok) {
914→            busy = false
915→            onMessage(op.label + "：GATT 忙或写入被拒绝")
916→            pump()
917→        }
918→    }
919→
920→    private fun writeCharacteristic(op: GattOp.WriteCharacteristic): Boolean {
921→        return try {
922→            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
923→                gatt.writeCharacteristic(op.characteristic, op.value, op.writeType) == BluetoothStatusCodes.SUCCESS
924→            } else {
925→                @Suppress("DEPRECATION")
926→                op.characteristic.value = op.value
927→                @Suppress("DEPRECATION")
928→                op.characteristic.writeType = op.writeType
929→                @Suppress("DEPRECATION")
930→                gatt.writeCharacteristic(op.characteristic)
931→            }
932→        } catch (e: SecurityException) {
933→            false
934→        }
935→    }
936→
937→    private fun writeDescriptor(op: GattOp.WriteDescriptor): Boolean {
938→        return try {
939→            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
940→                gatt.writeDescriptor(op.descriptor, op.value) == BluetoothStatusCodes.SUCCESS
941→            } else {
942→                @Suppress("DEPRECATION")
943→                op.descriptor.value = op.value
944→                @Suppress("DEPRECATION")
945→                gatt.writeDescriptor(op.descriptor)
946→            }
947→        } catch (e: SecurityException) {
948→            false
949→        }
950→    }
951→}

