720→void dm_ble_poll(void)
721→{
722→  static int ticks;
723→  int pairing_timed_out = 0;
724→
725→  pthread_mutex_lock(&s_lock);
726→  if (s_pairing)
727→    {
728→      if (++s_pair_ticks >= DM_BLE_PAIR_TIMEOUT_TICKS)
729→        {
730→          s_pairing = 0;
731→          s_paired = 0;
732→          s_pair_ticks = 0;
733→          s_challenge = 0;
734→          pairing_timed_out = 1;
735→        }
736→    }
737→  else
738→    {
739→      s_pair_ticks = 0;
740→    }
741→  pthread_mutex_unlock(&s_lock);
742→
743→  if (pairing_timed_out)
744→    {
745→      syslog(LOG_WARNING, "[ble-gatt] pairing challenge timed out\n");
746→      (void)send_pair_fail();
