735→             (int)ret);
736→      s_start_pending = 0;
737→      s_start_ticks = 0;
738→      set_state(DM_BLE_ERROR);
739→      (void)bt_gatts_unregister_service(s_srv);
740→      s_srv = NULL;
741→      return;
742→    }
743→
744→  /* The callback is the single gate for advertising. */
745→  s_start_pending = 0;
