748→/* Called from the UI tick. Registration is deferred until the adapter reports
749→   fully ON. Advertising begins only after this service's attribute-table
750→   callback succeeds. A deadline prevents a failed HCI bring-up from leaving
751→   the app page in STARTING forever. */
752→void dm_ble_poll(void)
753→{
754→  static int ticks;
755→  int pairing_timed_out = 0;
756→
757→  pthread_mutex_lock(&s_lock);
758→  if (s_pairing)
759→    {
760→      if (++s_pair_ticks >= DM_BLE_PAIR_TIMEOUT_TICKS)
761→        {
762→          s_pairing = 0;
763→          s_paired = 0;
764→          s_pair_ticks = 0;
765→          s_challenge = 0;
766→          pairing_timed_out = 1;
767→        }
768→    }
769→  else
770→    {
771→      s_pair_ticks = 0;
772→    }
773→  pthread_mutex_unlock(&s_lock);
774→
775→  if (pairing_timed_out)
776→    {
