 72→bt_status_t bt_le_start_advertising_async(bt_instance_t* ins, ble_adv_params_t* params, uint8_t* adv_data,
 73→    uint16_t adv_len, uint8_t* scan_rsp_data, uint16_t scan_rsp_len,
 74→    advertiser_callback_t* adv_cbs, bt_le_start_adv_callback_cb_t cb, void* userdata)
 75→{
 76→    bt_le_start_advertising_data_t* context;
 77→    bt_message_packet_t packet = { 0 };
 78→    bt_status_t status;
 79→    bt_advertiser_remote_t* adv;
 80→
 81→    BT_SOCKET_INS_VALID(ins, BT_STATUS_PARM_INVALID);
 82→    BT_SOCKET_PTR_VALID(cb, BT_STATUS_PARM_INVALID);
 83→
 84→    adv = malloc(sizeof(*adv));
 85→    if (adv == NULL)
 86→        return BT_STATUS_NOMEM;
 87→
 88→    adv->ins = ins;
 89→    adv->callback = adv_cbs;
 90→    packet.adv_pl._bt_le_start_advertising.adver = PTR2INT(uint64_t) adv;
 91→    memcpy(&packet.adv_pl._bt_le_start_advertising.params, params, sizeof(*params));
 92→    if ((adv_len && (adv_len > sizeof(packet.adv_pl._bt_le_start_advertising.adv_data)))
 93→        || (scan_rsp_len && (scan_rsp_len > sizeof(packet.adv_pl._bt_le_start_advertising.scan_rsp_data)))) {
 94→        free(adv);
 95→        return BT_STATUS_FAIL;
 96→    }
 97→
 98→    if (adv_len)
 99→        memcpy(packet.adv_pl._bt_le_start_advertising.adv_data, adv_data, adv_len);
100→    packet.adv_pl._bt_le_start_advertising.adv_len = adv_len;
101→
102→    if (scan_rsp_len)
103→        memcpy(packet.adv_pl._bt_le_start_advertising.scan_rsp_data, scan_rsp_data, scan_rsp_len);
104→    packet.adv_pl._bt_le_start_advertising.scan_rsp_len = scan_rsp_len;
105→
106→    context = calloc(1, sizeof(bt_le_start_advertising_data_t));
107→    context->userdata = userdata;
108→    context->adv = (void*)adv;
109→
110→    status = bt_socket_client_send_with_reply(ins, &packet, BT_LE_START_ADVERTISING, le_start_advertising_reply, cb, context);
111→
112→    if (status != BT_STATUS_SUCCESS) {
113→        free(adv);
114→        free(context);
115→        return BT_STATUS_FAIL;
116→    }
117→
118→    return status;
119→}
