738→      s_srv = NULL;
739→      return;
740→    }
741→
742→  /* The callback is the single gate for advertising. */
743→  s_start_pending = 0;
744→}
745→
746→/* Called from the UI tick. Registration is deferred until the adapter reports
747→   fully ON. Advertising begins only after this service's attribute-table
748→   callback succeeds. A deadline prevents a failed HCI bring-up from leaving
749→   the app page in STARTING forever. */
750→void dm_ble_poll(void)
751→{
752→  static int ticks;
753→  int pairing_timed_out = 0;
754→  bt_adapter_state_t adapter_state;
755→
756→  pthread_mutex_lock(&s_lock);
757→  if (s_pairing)
758→    {
759→      if (++s_pair_ticks >= DM_BLE_PAIR_TIMEOUT_TICKS)
760→        {
761→          s_pairing = 0;
762→          s_paired = 0;
763→          s_pair_ticks = 0;
764→          s_challenge = 0;
765→          pairing_timed_out = 1;
766→        }
767→    }
768→  else
769→    {
770→      s_pair_ticks = 0;
771→    }
772→  pthread_mutex_unlock(&s_lock);
773→
774→  adapter_state = s_ins ? bt_adapter_get_state(s_ins) : BT_ADAPTER_STATE_OFF;
775→  if (pairing_timed_out)
776→    {
777→      syslog(LOG_WARNING, "[ble-gatt] pairing challenge timed out\n");
778→      (void)send_pair_fail();
779→      set_state(DM_BLE_CONNECTED);
780→    }
781→
782→  if (s_state == DM_BLE_STARTING)
783→    {
784→      /* Recover if the stack was already ready before callback registration,
785→         or if the transition notification was dropped. */
786→      if (adapter_le_ready())
787→        {
788→          s_start_pending = 1;
789→        }
790→      if (++s_start_ticks >= DM_BLE_START_TIMEOUT_TICKS)
791→        {
792→          s_start_ticks = 0;
793→          s_start_pending = 0;
794→          ticks = 0;
795→          syslog(LOG_ERR,
796→                 "[ble-gatt] startup timeout state=%d: adapter did not reach advertising\n",
797→                 (int)adapter_state);
798→          set_state(DM_BLE_ERROR);
799→          stop_adv();
800→          if (s_srv)
801→            {
802→              (void)bt_gatts_unregister_service(s_srv);
803→              s_srv = NULL;
804→            }
805→          return;
806→        }
807→    }
808→  else
809→    {
810→      s_start_ticks = 0;
811→    }
812→
813→  if (!s_start_pending || s_state != DM_BLE_STARTING)
814→    {
815→      ticks = 0;
816→      return;
817→    }
818→  if (++ticks < 8) /* ~2s settle after the fully-ON callback */
819→    {
820→      return;
821→    }
822→  ticks = 0;
823→  if (!adapter_le_ready())
824→    {
825→      s_start_pending = 0;
826→      return;
827→    }
828→  do_register_and_adv();
829→}
