831→static void adapter_state_cb(void *cookie, bt_adapter_state_t state)
832→{
833→  (void)cookie;
834→  syslog(LOG_INFO, "[ble-gatt] adapter state=%d\n", (int)state);
835→  if ((state == BT_ADAPTER_STATE_BLE_ON || state == BT_ADAPTER_STATE_ON) &&
836→      s_state == DM_BLE_STARTING)
837→    {
838→      s_start_pending = 1;
839→    }
840→}
841→
842→static adapter_callbacks_t s_adapter_cbs = {
843→  .on_adapter_state_changed = adapter_state_cb,
844→};
