846→int dm_ble_start(void)
847→{
848→  bt_status_t ret;
849→
850→  if (s_state != DM_BLE_IDLE && s_state != DM_BLE_ERROR)
851→    {
852→      return 0;
853→    }
854→
855→  if (s_state == DM_BLE_ERROR)
856→    {
857→      stop_adv();
858→      if (s_srv)
859→        {
860→          (void)bt_gatts_unregister_service(s_srv);
861→          s_srv = NULL;
862→        }
863→    }
864→  s_start_pending = 0;
865→  s_start_ticks = 0;
866→  set_state(DM_BLE_STARTING);
867→  pthread_mutex_lock(&s_lock);
868→  s_paired = 0;
869→  s_pairing = 0;
870→  s_pair_ticks = 0;
871→  s_challenge = 0;
872→  s_has_peer = 0;
873→  pthread_mutex_unlock(&s_lock);
874→  srand((unsigned int)time(NULL) ^ (unsigned int)(uintptr_t)s_ins);
875→
876→  if (!s_ins)
877→    {
878→      s_ins = bluetooth_create_instance();
879→      if (!s_ins)
880→        {
881→          syslog(LOG_ERR, "[ble-gatt] create instance fail\n");
882→          set_state(DM_BLE_ERROR);
883→          return -1;
884→        }
885→    }
886→
887→  if (!s_adapter_cb)
888→    {
889→      s_adapter_cb = bt_adapter_register_callback(s_ins, &s_adapter_cbs);
890→      if (!s_adapter_cb)
891→        {
892→          /* dm_ble_poll() also checks readiness, so an already-ready adapter
893→             can still proceed without callback delivery. */
894→          syslog(LOG_WARNING, "[ble-gatt] adapter callback registration failed; polling state\n");
895→        }
896→    }
897→
898→  /* GATT is LE-only; do not bring up the unrelated BR/EDR profile stack. */
899→  ret = bt_adapter_enable_le(s_ins);
900→  if (ret != BT_STATUS_SUCCESS && !adapter_le_ready())
901→    {
902→      syslog(LOG_ERR, "[ble-gatt] BLE adapter enable fail %d\n", (int)ret);
903→      set_state(DM_BLE_ERROR);
904→      return -1;
905→    }
906→
907→  /* Covers an already-ready adapter even if no transition callback is emitted. */
908→  if (adapter_le_ready())
909→    {
910→      bt_adapter_state_t state = bt_adapter_get_state(s_ins);
911→      adapter_state_cb(NULL, state);
912→    }
913→  return 0;
914→}
