153→static int reminder_copy_text(const char *in, char *out, size_t cap)
154→{
155→  size_t n;
156→  if (!in || !out || cap < 2)
157→    {
158→      return -1;
159→    }
160→  while (*in == ' ' || *in == '\t')
161→    {
162→      in++;
163→    }
164→  n = strlen(in);
165→  while (n > 0 && (in[n - 1] == ' ' || in[n - 1] == '\t' ||
166→                   in[n - 1] == '\r' || in[n - 1] == '\n'))
167→    {
168→      n--;
169→    }
170→  if (n == 0)
171→    {
172→      return -1;
173→    }
174→  if (n >= cap)
175→    {
176→      n = cap - 1;
177→      while (n > 0 && ((unsigned char)in[n] & 0xc0u) == 0x80u)
178→        {
179→          n--;
180→        }
181→    }
182→  memcpy(out, in, n);
183→  out[n] = '\0';
184→  {
185→    size_t i;
186→    for (i = 0; i < n; i++)
187→      {
188→        if (out[i] == '\r' || out[i] == '\n' || (unsigned char)out[i] < 0x20)
189→          {
190→            out[i] = ' ';
191→          }
192→      }
193→  }
194→  return n > 0 ? 0 : -1;
195→}
