244→int dm_alarm_add_voice(const char *name, int year, int month, int day,
245→                       int hour, int minute, int repeat_daily)
246→{
247→  time_t now = time(NULL);
248→  struct tm tmv;
249→  struct tm verify;
250→  time_t due;
251→
252→  if (!reminder_clock_valid(now))
253→    {
254→      return -4;
255→    }
256→  if (year < 2024 || year > 2099 || month < 1 || month > 12 ||
257→      day < 1 || day > 31 || hour < 0 || hour > 23 || minute < 0 ||
258→      minute > 59)
259→    {
260→      return -1;
261→    }
262→  memset(&tmv, 0, sizeof(tmv));
263→  tmv.tm_year = year - 1900;
264→  tmv.tm_mon = month - 1;
265→  tmv.tm_mday = day;
266→  tmv.tm_hour = hour;
267→  tmv.tm_min = minute;
268→  tmv.tm_isdst = -1;
269→  due = mktime(&tmv);
270→  if (due == (time_t)-1)
271→    {
272→      return -1;
273→    }
274→  localtime_r(&due, &verify);
275→  if (verify.tm_year != year - 1900 || verify.tm_mon != month - 1 ||
276→      verify.tm_mday != day || verify.tm_hour != hour || verify.tm_min != minute)
277→    {
278→      return -1;
279→    }
280→  if (repeat_daily && due <= now)
281→    {
282→      verify.tm_mday++;
283→      verify.tm_isdst = -1;
284→      due = mktime(&verify);
285→    }
286→  else if (due <= now)
287→    {
288→      return -1;
289→    }
290→  return reminder_append(REMINDER_ALARM, name, due, repeat_daily, hour, minute);
291→}
