1354→
1355→  if (has_dt < 0 && !cancel_reminder &&
1356→      contains_any(text, reminder_triggers,
1357→                   sizeof(reminder_triggers) / sizeof(reminder_triggers[0])))
1358→    {
1359→      intent->type = INTENT_TIME_ERROR;
1360→      return 1;
1361→    }
1362→  if (has_dt == 1 && !cancel_reminder &&
1363→      contains_any(text, reminder_triggers,
1364→                   sizeof(reminder_triggers) / sizeof(reminder_triggers[0])))
1365→    {
