1388→      return 1;
1389→    }
1390→
1391→  if (contains_any(text, note_triggers,
1392→                   sizeof(note_triggers) / sizeof(note_triggers[0])))
1393→    {
1394→      const char *trigger = NULL;
1395→      size_t trigger_len = 0;
1396→      size_t i;
1397→      for (i = 0; i < sizeof(note_triggers) / sizeof(note_triggers[0]); i++)
1398→        {
1399→          const char *found = strstr(text, note_triggers[i]);
1400→          if (found && (!trigger || found < trigger))
1401→            {
1402→              trigger = found;
1403→              trigger_len = strlen(note_triggers[i]);
1404→            }
1405→        }
1406→      if (trigger)
1407→        {
1408→          const char *content = trigger + trigger_len;
1409→          while (*content == ' ' || *content == '\t' || *content == ':' ||
1410→                 *content == ',')
1411→            {
1412→              content++;
1413→            }
1414→          while (strncmp(content, "，", 3) == 0 ||
1415→                 strncmp(content, "：", 3) == 0 ||
1416→                 strncmp(content, "、", 3) == 0)
1417→            {
1418→              content += 3;
1419→            }
1420→          while (strncmp(content, "我", 3) == 0 ||
1421→                 strncmp(content, "一下", 6) == 0 ||
1422→                 strncmp(content, "记得", 6) == 0)
1423→            {
1424→              content += strncmp(content, "我", 3) == 0 ? 3 : 6;
1425→            }
1426→          if (!*content)
1427→            {
1428→              return 0;
1429→            }
1430→          intent->type = INTENT_NOTE;
1431→          snprintf(intent->text, sizeof(intent->text), "%s", content);
1432→          return 1;
1433→        }
1434→    }
1435→
1436→  if (!cancel_focus &&
1437→      (strstr(text, "专注") || strstr(text, "计时") || strstr(text, "番茄钟")) &&
1438→      parse_duration_seconds(text, &seconds, 120 * 60))
1439→    {
1440→      intent->type = INTENT_FOCUS;
1441→      intent->seconds = seconds;
1442→      return 1;
1443→    }
1444→
1445→  if (contains_any(text, mood_words, sizeof(mood_words) / sizeof(mood_words[0])))
