382→static const char *relative_marker(const char *text, size_t *bytes)
383→{
384→  const char *p = strstr(text, "之后");
385→  const char *q = strstr(text, "以后");
386→  const char *r = strstr(text, "后");
387→  const char *best = NULL;
388→  *bytes = 0;
