395→static void clean_relative_name(const char *text, char *out, size_t cap)
396→{
397→  const char *marker;
398→  const char *content;
399→  size_t marker_bytes;
400→  size_t len;
401→  static const char *const prefixes[] = {
402→    "提醒我", "提醒一下", "提醒", "叫醒我", "叫我", "帮我", "帮忙",
403→    "安排我", "记得", "请", "在", "我", "一下"
404→  };
405→  size_t i;
406→  if (!out || cap == 0)
407→    {
408→      return;
409→    }
410→  marker = relative_marker(text, &marker_bytes);
411→  content = marker ? marker + marker_bytes : NULL;
412→  if (!content)
413→    {
414→      snprintf(out, cap, "%s", "待办事项");
415→      return;
416→    }
417→  while (*content == ' ' || *content == '\t' || *content == ',' || *content == ':')
418→    {
419→      content++;
420→    }
421→  while (strncmp(content, "，", 3) == 0 || strncmp(content, "：", 3) == 0 ||
422→         strncmp(content, "、", 3) == 0)
423→    {
424→      content += 3;
425→    }
426→  while (*content)
427→    {
428→      int changed = 0;
429→      for (i = 0; i < sizeof(prefixes) / sizeof(prefixes[0]); i++)
430→        {
431→          size_t n = strlen(prefixes[i]);
432→          if (strncmp(content, prefixes[i], n) == 0)
433→            {
434→              content += n;
435→              changed = 1;
436→              break;
437→            }
438→        }
439→      if (!changed)
440→        {
441→          break;
442→        }
443→      while (*content == ' ' || *content == '\t' || *content == ',' || *content == ':')
444→        {
445→          content++;
446→        }
447→      while (strncmp(content, "，", 3) == 0 || strncmp(content, "：", 3) == 0 ||
448→             strncmp(content, "、", 3) == 0)
449→        {
450→          content += 3;
451→        }
452→    }
453→  len = strlen(content);
454→  while (len > 0)
455→    {
456→      if (len >= 3 && (memcmp(content + len - 3, "。", 3) == 0 ||
457→                       memcmp(content + len - 3, "，", 3) == 0 ||
458→                       memcmp(content + len - 3, "！", 3) == 0 ||
459→                       memcmp(content + len - 3, "？", 3) == 0))
460→        {
461→          len -= 3;
462→        }
463→      else if (content[len - 1] == ' ' || content[len - 1] == '\t' ||
464→               content[len - 1] == ',' || content[len - 1] == '.')
465→        {
466→          len--;
467→        }
468→      else
469→        {
470→          break;
471→        }
472→    }
473→  if (len == 0)
474→    {
475→      snprintf(out, cap, "%s", "待办事项");
476→      return;
477→    }
478→  if (len >= cap)
479→    {
480→      len = cap - 1;
481→      while (len > 0 && ((unsigned char)content[len] & 0xc0u) == 0x80u)
482→        {
483→          len--;
484→        }
485→    }
486→  memcpy(out, content, len);
487→  out[len] = '\0';
488→}
