621→static int start_adv(void)
622→{
623→  ble_adv_params_t params;
624→  advertiser_data_t *adv_data;
625→  advertiser_data_t *scan_rsp;
626→  uint8_t *p_adv;
627→  uint8_t *p_rsp;
628→  uint16_t adv_len = 0;
629→  uint16_t rsp_len = 0;
630→
631→  if (!s_ins)
632→    {
633→      return -1;
634→    }
635→  if (s_adv)
636→    {
637→      return 0;
638→    }
639→
640→  memset(&params, 0, sizeof(params));
641→  params.adv_type = BT_LE_ADV_IND;
642→  params.own_addr_type = BT_LE_ADDR_TYPE_PUBLIC;
643→  params.tx_power = 0;
644→  params.interval = 160; /* 100ms */
645→  params.duration = 0;
646→  params.channel_map = 7;
647→  params.filter_policy = BT_LE_ADV_FILTER_WHITE_LIST_FOR_NONE;
648→
649→  adv_data = advertiser_data_new();
650→  if (!adv_data)
651→    {
652→      return -1;
653→    }
654→  advertiser_data_set_flags(adv_data,
655→                            BT_AD_FLAG_GENERAL_DISCOVERABLE |
656→                            BT_AD_FLAG_BREDR_NOT_SUPPORT);
657→  advertiser_data_add_service_uuid(adv_data, &k_svc_uuid);
658→  p_adv = advertiser_data_build(adv_data, &adv_len);
659→
660→  scan_rsp = advertiser_data_new();
661→  if (scan_rsp)
662→    {
663→      advertiser_data_set_name(scan_rsp, "FlowDesk-S1");
664→      p_rsp = advertiser_data_build(scan_rsp, &rsp_len);
665→    }
666→  else
667→    {
668→      p_rsp = NULL;
669→    }
670→
671→  s_adv = bt_le_start_advertising(s_ins, &params,
672→                                  p_adv, adv_len,
673→                                  p_rsp, rsp_len,
674→                                  &s_adv_cbs);
675→
676→  advertiser_data_free(adv_data);
677→  if (scan_rsp)
678→    {
679→      advertiser_data_free(scan_rsp);
680→    }
681→
682→  if (!s_adv)
683→    {
684→      syslog(LOG_ERR, "[ble-gatt] start advertising failed\n");
685→      set_state(DM_BLE_ERROR);
686→      return -1;
687→    }
688→  /* Wait for on_adv_start() to confirm that the controller is advertising. */
689→  return 0;
690→}
