716→static void do_register_and_adv(void)
717→{
718→  bt_status_t ret;
719→
720→  if (s_srv)
721→    {
722→      /* An attribute-table callback is already pending for this service. */
723→      return;
724→    }
725→
726→  ret = bt_gatts_register_service(s_ins, &s_srv, &s_gatts_cbs);
727→  if (ret != BT_STATUS_SUCCESS || !s_srv)
728→    {
729→      syslog(LOG_ERR, "[ble-gatt] register service fail %d\n", (int)ret);
730→      s_srv = NULL;
731→      return;
732→    }
733→
734→  ret = bt_gatts_add_attr_table(s_srv, &s_srv_db);
735→  if (ret != BT_STATUS_SUCCESS)
736→    {
737→      syslog(LOG_ERR, "[ble-gatt] add attr table request failed %d\n",
738→             (int)ret);
739→      s_start_pending = 0;
740→      s_start_ticks = 0;
741→      set_state(DM_BLE_ERROR);
742→      (void)bt_gatts_unregister_service(s_srv);
743→      s_srv = NULL;
744→      return;
745→    }
746→
747→  /* The callback is the single gate for advertising. */
