751→/* Called from the UI tick. Registration is deferred until BLE reports ready
752→   (BLE_ON or ON). Advertising begins only after this service's attribute-table
753→   callback succeeds. A deadline prevents a failed HCI bring-up from leaving
754→   the app page in STARTING forever. */
755→void dm_ble_poll(void)
756→{
757→  static int ticks;
758→  int pairing_timed_out = 0;
759→  bt_adapter_state_t adapter_state;
760→
761→  pthread_mutex_lock(&s_lock);
762→  if (s_pairing)
763→    {
764→      if (++s_pair_ticks >= DM_BLE_PAIR_TIMEOUT_TICKS)
765→        {
766→          s_pairing = 0;
767→          s_paired = 0;
768→          s_pair_ticks = 0;
769→          s_challenge = 0;
770→          pairing_timed_out = 1;
771→        }
772→    }
773→  else
774→    {
775→      s_pair_ticks = 0;
776→    }
777→  pthread_mutex_unlock(&s_lock);
778→
779→  adapter_state = s_ins ? bt_adapter_get_state(s_ins) : BT_ADAPTER_STATE_OFF;
780→  if (pairing_timed_out)
781→    {
782→      syslog(LOG_WARNING, "[ble-gatt] pairing challenge timed out\n");
783→      (void)send_pair_fail();
784→      set_state(DM_BLE_CONNECTED);
785→    }
786→
787→  if (s_state == DM_BLE_STARTING)
788→    {
789→      /* Recover if the stack was already ready before callback registration,
790→         or if the transition notification was dropped. */
791→      if (adapter_le_ready())
792→        {
793→          s_start_pending = 1;
794→        }
795→      if (++s_start_ticks >= DM_BLE_START_TIMEOUT_TICKS)
796→        {
797→          s_start_ticks = 0;
798→          s_start_pending = 0;
799→          ticks = 0;
800→          syslog(LOG_ERR,
801→                 "[ble-gatt] startup timeout state=%d: adapter did not reach advertising\n",
802→                 (int)adapter_state);
803→          set_state(DM_BLE_ERROR);
804→          stop_adv();
805→          if (s_srv)
806→            {
807→              (void)bt_gatts_unregister_service(s_srv);
808→              s_srv = NULL;
809→            }
810→          return;
811→        }
812→    }
813→  else
814→    {
815→      s_start_ticks = 0;
816→    }
817→
818→  if (!s_start_pending || s_state != DM_BLE_STARTING)
819→    {
820→      ticks = 0;
821→      return;
822→    }
823→  if (++ticks < 8) /* ~2s settle after BLE_ON/ON callback */
824→    {
825→      return;
826→    }
827→  ticks = 0;
828→  if (!adapter_le_ready())
829→    {
830→      s_start_pending = 0;
831→      return;
832→    }
833→  do_register_and_adv();
834→}
