836→static const char *adapter_state_name(bt_adapter_state_t state)
837→{
838→  switch (state)
839→    {
840→      case BT_ADAPTER_STATE_OFF: return "OFF";
841→      case BT_ADAPTER_STATE_BLE_TURNING_ON: return "BLE_TURNING_ON";
842→      case BT_ADAPTER_STATE_BLE_ON: return "BLE_ON";
843→      case BT_ADAPTER_STATE_TURNING_ON: return "TURNING_ON";
844→      case BT_ADAPTER_STATE_ON: return "ON";
845→      case BT_ADAPTER_STATE_TURNING_OFF: return "TURNING_OFF";
846→      case BT_ADAPTER_STATE_BLE_TURNING_OFF: return "BLE_TURNING_OFF";
847→      default: return "UNKNOWN";
848→    }
849→}
850→
851→static void adapter_state_cb(void *cookie, bt_adapter_state_t state)
852→{
853→  (void)cookie;
854→  syslog(LOG_INFO, "[ble-gatt] adapter state=%d (%s)\n", (int)state,
855→         adapter_state_name(state));
856→  if ((state == BT_ADAPTER_STATE_BLE_ON || state == BT_ADAPTER_STATE_ON) &&
857→      s_state == DM_BLE_STARTING)
858→    {
859→      s_start_pending = 1;
860→    }
861→}
862→
863→static adapter_callbacks_t s_adapter_cbs = {
864→  .on_adapter_state_changed = adapter_state_cb,
865→};
