867→int dm_ble_start(void)
868→{
869→  bt_status_t ret;
870→
871→  if (s_state != DM_BLE_IDLE && s_state != DM_BLE_ERROR)
872→    {
873→      return 0;
874→    }
875→
876→  if (s_state == DM_BLE_ERROR)
877→    {
878→      stop_adv();
879→      if (s_srv)
880→        {
881→          (void)bt_gatts_unregister_service(s_srv);
882→          s_srv = NULL;
883→        }
884→    }
885→  s_start_pending = 0;
886→  s_start_ticks = 0;
887→  set_state(DM_BLE_STARTING);
888→  pthread_mutex_lock(&s_lock);
889→  s_paired = 0;
890→  s_pairing = 0;
891→  s_pair_ticks = 0;
892→  s_challenge = 0;
893→  s_has_peer = 0;
894→  pthread_mutex_unlock(&s_lock);
895→  srand((unsigned int)time(NULL) ^ (unsigned int)(uintptr_t)s_ins);
896→
897→  if (!s_ins)
898→    {
899→      s_ins = bluetooth_create_instance();
900→      if (!s_ins)
901→        {
902→          syslog(LOG_ERR, "[ble-gatt] create instance fail\n");
903→          set_state(DM_BLE_ERROR);
904→          return -1;
905→        }
906→    }
907→
908→  if (!s_adapter_cb)
909→    {
910→      s_adapter_cb = bt_adapter_register_callback(s_ins, &s_adapter_cbs);
911→      if (!s_adapter_cb)
912→        {
913→          /* dm_ble_poll() also checks readiness, so an already-ready adapter
914→             can still proceed without callback delivery. */
915→          syslog(LOG_WARNING, "[ble-gatt] adapter callback registration failed; polling state\n");
916→        }
917→    }
918→
919→  /* GATT is LE-only; do not bring up the unrelated BR/EDR profile stack. */
920→  ret = bt_adapter_enable_le(s_ins);
921→  if (ret != BT_STATUS_SUCCESS && !adapter_le_ready())
922→    {
923→      syslog(LOG_ERR, "[ble-gatt] BLE adapter enable fail %d\n", (int)ret);
924→      set_state(DM_BLE_ERROR);
925→      return -1;
926→    }
927→
928→  /* Covers an already-ready adapter even if no transition callback is emitted. */
929→  if (adapter_le_ready())
930→    {
931→      bt_adapter_state_t state = bt_adapter_get_state(s_ins);
932→      adapter_state_cb(NULL, state);
933→    }
934→  return 0;
935→}
