 25→#define VOL_PATH "/data/deskmate_vol.txt"
 26→#define VOL_DEFAULT 80
 27→#define CODEC_CARD "audiocodec"
 28→#define DAC_VOL_MAX 160
 29→#define VOL_ALARM_DEFAULT 100
 30→
 31→static pthread_mutex_t s_vol_lock = PTHREAD_MUTEX_INITIALIZER;
 32→static int s_vol = VOL_DEFAULT;
 33→static int s_mute;
 34→static int s_alarm_vol = VOL_ALARM_DEFAULT;
 35→static int s_alarm_active;
 36→
 37→/* Perceptual slider mapping: lift the quiet half of the range, while
 38→ * reserving headroom at the top to avoid the previous full-scale loudness. */
 39→static unsigned int vol_percent_to_reg(int percent)
 40→{
 41→  static const struct
 42→  {
 43→    unsigned char percent;
 44→    unsigned char reg;
 45→  } points[] =
 46→  {
 47→    { 0,   0 },
 48→    { 10, 48 },
 49→    { 25, 88 },
 50→    { 50, 124 },
 51→    { 75, 148 },
 52→    { 100, DAC_VOL_MAX }
 53→  };
 54→  unsigned int i;
 55→
 56→  if (percent <= 0)
 57→    {
 58→      return 0;
 59→    }
 60→  if (percent >= 100)
 61→    {
 62→      return DAC_VOL_MAX;
 63→    }
 64→
 65→  for (i = 1; i < sizeof(points) / sizeof(points[0]); i++)
 66→    {
 67→      if (percent <= points[i].percent)
 68→        {
 69→          unsigned int span = points[i].percent - points[i - 1].percent;
 70→          unsigned int value_span = points[i].reg - points[i - 1].reg;
 71→          unsigned int offset = (unsigned int)percent - points[i - 1].percent;
 72→          return points[i - 1].reg + (value_span * offset + span / 2) / span;
 73→        }
 74→    }
 75→
 76→  return DAC_VOL_MAX;
 77→}
 78→
 79→static void vol_save_locked(void)
 80→{
 81→  FILE *f = fopen(VOL_PATH, "w");
 82→  if (!f)
 83→    {
 84→      return;
 85→    }
 86→  fprintf(f, "%d %d %d\n", s_vol, s_mute, s_alarm_vol);
 87→  fclose(f);
 88→}
 89→
 90→static void vol_apply_locked(void)
 91→{
 92→  unsigned int reg;
 93→  int percent;
 94→  int r1;
 95→  int r2;
 96→
 97→  /* Alarm output temporarily overrides both the media gain and media mute;
 98→   * the saved media controls are restored as soon as the spoken alert ends. */
 99→  if (s_alarm_active > 0)
100→    {
101→      percent = s_alarm_vol;
102→      reg = vol_percent_to_reg(percent);
103→    }
104→  else
105→    {
106→      percent = s_mute ? 0 : s_vol;
107→      reg = vol_percent_to_reg(percent);
108→    }
109→  r1 = snd_ctl_set(CODEC_CARD, "DACL digital volume", reg);
110→  r2 = snd_ctl_set(CODEC_CARD, "DACR digital volume", reg);
111→  syslog(LOG_INFO, "[dm-vol] dac vol reg=%u alarm=%d (dACL=%d dACR=%d)\n",
112→         reg, s_alarm_active > 0, r1, r2);
113→  dm_voice_set_speaker_volume(percent);
114→}
