116→void dm_vol_init(void)
117→{
118→  FILE *f = fopen(VOL_PATH, "r");
119→  int v = VOL_DEFAULT;
120→  int m = 0;
121→  int alarm = VOL_ALARM_DEFAULT;
122→
123→  if (f)
124→    {
125→      int fields = fscanf(f, "%d %d %d", &v, &m, &alarm);
126→      if (fields >= 1)
127→        {
128→          if (v < 0) v = 0;
129→          if (v > 100) v = 100;
130→          if (alarm < 0) alarm = 0;
131→          if (alarm > 100) alarm = 100;
132→          pthread_mutex_lock(&s_vol_lock);
133→          s_vol = v;
134→          s_mute = m ? 1 : 0;
135→          s_alarm_vol = fields >= 3 ? alarm : VOL_ALARM_DEFAULT;
136→          pthread_mutex_unlock(&s_vol_lock);
137→        }
138→      fclose(f);
139→    }
140→  dm_vol_apply();
141→}
