170→int dm_vol_alarm_set(int percent)
171→{
172→  if (percent < 0) percent = 0;
173→  if (percent > 100) percent = 100;
174→  pthread_mutex_lock(&s_vol_lock);
175→  s_alarm_vol = percent;
176→  if (s_alarm_active > 0)
177→    {
178→      vol_apply_locked();
179→    }
180→  vol_save_locked();
181→  pthread_mutex_unlock(&s_vol_lock);
182→  return percent;
183→}
