185→void dm_vol_alarm_begin(void)
186→{
187→  pthread_mutex_lock(&s_vol_lock);
188→  s_alarm_active++;
189→  if (s_alarm_active == 1)
190→    {
191→      vol_apply_locked();
192→    }
193→  pthread_mutex_unlock(&s_vol_lock);
194→}
195→
196→void dm_vol_alarm_end(void)
197→{
198→  pthread_mutex_lock(&s_vol_lock);
199→  if (s_alarm_active > 0)
200→    {
201→      s_alarm_active--;
202→    }
203→  if (s_alarm_active == 0)
204→    {
205→      vol_apply_locked();
206→    }
207→  pthread_mutex_unlock(&s_vol_lock);
208→}
