529→static void *reminder_speech_worker(void *arg)
530→{
531→  reminder_speech_t *speech = arg;
532→  char line[REMINDER_TEXT_MAX + 48];
533→  int rc = -1;
534→  int beep_rc = -EBUSY;
535→  int attempt;
536→
537→  if (!speech)
538→    {
539→      return NULL;
540→    }
541→  if (speech->is_alarm)
542→    {
543→      snprintf(line, sizeof(line), "闹钟响了：%s。", speech->text);
544→    }
545→  else
546→    {
547→      snprintf(line, sizeof(line), "待办提醒：%s。", speech->text);
548→    }
549→
550→  if (speech->is_alarm)
551→    {
552→      dm_vol_alarm_begin();
553→    }
554→  /* Start with an offline-safe alert tone so network TTS latency never
555→   * suppresses the alarm itself. Briefly retry if another audio stream owns
556→   * the speaker, then speak the task name when connectivity exists. */
557→  for (attempt = 0; attempt < 12; attempt++)
558→    {
559→      beep_rc = dm_voice_beep();
560→      if (beep_rc != -EBUSY)
561→        {
562→          break;
563→        }
564→      usleep(250000);
565→    }
566→  if (beep_rc != 0)
567→    {
568→      syslog(LOG_WARNING, "[dm-remind] alert tone playback failed rc=%d\n",
569→             beep_rc);
570→    }
571→  if (dm_wifi_connected())
572→    {
573→      rc = dm_voice_tts_play(line);
574→    }
575→  if (rc != 0)
576→    {
577→      syslog(LOG_WARNING, "[dm-remind] spoken reminder unavailable\n");
578→    }
579→  if (speech->is_alarm)
580→    {
581→      dm_vol_alarm_end();
582→    }
583→  free(speech);
584→  pthread_mutex_lock(&s_voice_lock);
585→  s_voice_done = 1;
586→  pthread_mutex_unlock(&s_voice_lock);
587→  return NULL;
588→}
