590→static int reminder_speak(int index)
591→{
592→  reminder_speech_t *speech;
593→  pthread_t th;
594→  pthread_attr_t attr;
595→  int rc;
596→
597→  if (index < 0 || index >= s_count)
598→    {
599→      return -1;
600→    }
601→  pthread_mutex_lock(&s_voice_lock);
602→  if (s_voice_busy)
603→    {
604→      pthread_mutex_unlock(&s_voice_lock);
605→      return -1;
606→    }
607→  s_voice_busy = 1;
608→  s_voice_done = 0;
609→  pthread_mutex_unlock(&s_voice_lock);
610→  speech = malloc(sizeof(*speech));
611→  if (!speech)
612→    {
613→      pthread_mutex_lock(&s_voice_lock);
614→      s_voice_busy = 0;
615→      pthread_mutex_unlock(&s_voice_lock);
616→      return -1;
617→    }
618→  speech->is_alarm = s_items[index].type == REMINDER_ALARM;
619→  snprintf(speech->text, sizeof(speech->text), "%s", s_items[index].text);
620→  pthread_attr_init(&attr);
621→  pthread_attr_setstacksize(&attr, DM_VOICE_NET_WORKER_STACK);
622→  rc = pthread_create(&th, &attr, reminder_speech_worker, speech);
623→  pthread_attr_destroy(&attr);
624→  if (rc != 0)
625→    {
626→      pthread_mutex_lock(&s_voice_lock);
627→      s_voice_busy = 0;
628→      pthread_mutex_unlock(&s_voice_lock);
629→      free(speech);
630→      return -1;
631→    }
632→  pthread_detach(th);
633→  return 0;
634→}
