858→                          s_alarm_repeat);
859→  if (s_alarm_hint)
860→    {
861→      lv_label_set_text(s_alarm_hint, rc == 0 ? "闹钟已保存" :
862→                        (rc == -2 ? "闹钟数量已满" :
863→                         (rc == -4 ? "请先校准设备时间" : "设置失败")));
864→    }
865→  reminder_paint();
866→}
