868→void dm_reminder_tick(void)
869→{
870→  time_t now;
871→  int i;
872→  int voice_done;
873→  int voice_busy;
874→
875→  pthread_mutex_lock(&s_voice_lock);
876→  voice_done = s_voice_done;
877→  s_voice_done = 0;
878→  if (voice_done)
879→    {
880→      s_voice_busy = 0;
881→    }
882→  voice_busy = s_voice_busy;
883→  pthread_mutex_unlock(&s_voice_lock);
884→  if (s_alert_idx >= 0 || voice_busy)
885→    {
886→      return;
887→    }
888→  now = time(NULL);
889→  if (now < s_speech_retry_after)
890→    {
891→      return;
892→    }
893→  if (!reminder_clock_valid(now))
894→    {
895→      return;
896→    }
897→  for (i = 0; i < s_count; i++)
898→    {
899→      reminder_t *item = &s_items[i];
900→      reminder_t previous;
901→      if (item->fired || item->due > now)
902→        {
903→          continue;
904→        }
905→      previous = *item;
906→      if (item->type == REMINDER_ALARM && item->repeat_daily)
907→        {
908→          struct tm next;
909→          localtime_r(&now, &next);
910→          next.tm_hour = item->hour;
911→          next.tm_min = item->minute;
912→          next.tm_sec = 0;
913→          next.tm_isdst = -1;
914→          if (mktime(&next) <= now)
915→            {
916→              next.tm_mday++;
917→              next.tm_isdst = -1;
918→            }
919→          item->due = mktime(&next);
920→          item->fired = 0;
921→        }
922→      else
923→        {
924→          item->fired = 1;
925→        }
926→      if (reminder_save() != 0)
927→        {
928→          *item = previous;
929→          s_speech_retry_after = now + 5;
930→          syslog(LOG_ERR, "[dm-remind] unable to save due reminder\n");
931→          return;
932→        }
933→      s_alert_idx = i;
934→      if (s_alert_title)
935→        {
936→          lv_label_set_text(s_alert_title,
937→                            item->type == REMINDER_ALARM ? "闹钟响了" : "待办提醒");
938→        }
939→      if (s_alert_text)
940→        {
941→          lv_label_set_text(s_alert_text, item->text);
942→        }
943→      if (s_alert)
944→        {
945→          lv_obj_clear_flag(s_alert, LV_OBJ_FLAG_HIDDEN);
946→          lv_obj_move_foreground(s_alert);
947→        }
948→      if (reminder_speak(i) != 0)
949→        {
950→          *item = previous;
951→          (void)reminder_save();
952→          s_alert_idx = -1;
953→          s_speech_retry_after = now + 5;
954→          if (s_alert)
955→            {
956→              lv_obj_add_flag(s_alert, LV_OBJ_FLAG_HIDDEN);
957→            }
958→          return;
959→        }
960→      reminder_paint();
961→      return;
962→    }
963→  reminder_paint();
964→}
