1324→static int asr_wav(const char *wav, char *text, int cap)
1325→{
1326→  FILE *f;
1327→  unsigned char *raw;
1328→  char *b64;
1329→  char *body;
1330→  size_t body_cap;
1331→  long sz;
1332→  int n;
1333→  cJSON *root;
1334→  cJSON *message;
1335→  cJSON *content;
1336→
1337→  if (!wav || !text || cap < 2)
1338→    {
1339→      return -1;
1340→    }
1341→  text[0] = '\0';
1342→  f = fopen(wav, "rb");
1343→  if (!f)
1344→    {
1345→      return -1;
1346→    }
1347→  if (fseek(f, 0, SEEK_END) != 0 || (sz = ftell(f)) <= 44 ||
1348→      sz > 2 * 1024 * 1024 || fseek(f, 0, SEEK_SET) != 0)
1349→    {
1350→      fclose(f);
1351→      syslog(LOG_ERR, "[dm-voice] ASR WAV size/seek invalid\n");
1352→      return -1;
1353→    }
1354→  syslog(LOG_INFO, "[dm-voice] ASR WAV bytes=%ld\n", sz);
1355→  raw = malloc((size_t)sz);
1356→  b64 = malloc((size_t)sz * 2 + 8);
1357→  body_cap = (size_t)sz * 2 + 512;
1358→  body = malloc(body_cap);
1359→  if (!raw || !b64 || !body)
1360→    {
1361→      free(raw);
1362→      free(b64);
1363→      free(body);
1364→      fclose(f);
1365→      return -1;
1366→    }
1367→  if (fread(raw, 1, (size_t)sz, f) != (size_t)sz)
1368→    {
1369→      free(raw);
1370→      free(b64);
1371→      free(body);
1372→      fclose(f);
1373→      return -1;
1374→    }
1375→  fclose(f);
1376→  if (b64_encode(raw, (size_t)sz, b64, (size_t)sz * 2 + 8) <= 0)
1377→    {
1378→      free(raw);
1379→      free(b64);
1380→      free(body);
1381→      return -1;
1382→    }
1383→  free(raw);
1384→
1385→  /* Official MiMo ASR schema: data URL + one input_audio content part. */
1386→  n = snprintf(body, body_cap,
1387→               "{\"model\":\"%s\",\"messages\":[{\"role\":\"user\",\"content\":"
1388→               "[{\"type\":\"input_audio\",\"input_audio\":{\"data\":"
1389→               "\"data:audio/wav;base64,%s\"}}]}],"
1390→               "\"asr_options\":{\"language\":\"auto\"}}",
1391→               ASR_MODEL, b64);
1392→  free(b64);
1393→  if (n <= 0 || (size_t)n >= body_cap)
1394→    {
1395→      free(body);
1396→      return -1;
1397→    }
1398→  syslog(LOG_INFO, "[dm-voice] ASR request start\n");
1399→  if (http_post_json("/chat/completions", body, TXT_ASR) != 0)
1400→    {
1401→      free(body);
1402→      syslog(LOG_ERR, "[dm-voice] ASR HTTP request failed\n");
1403→      return -1;
1404→    }
1405→  free(body);
1406→
1407→  root = voice_json_load(TXT_ASR, 256 * 1024);
1408→  if (!root)
1409→    {
1410→      syslog(LOG_ERR, "[dm-voice] ASR response is not valid JSON\n");
1411→      return -1;
1412→    }
1413→  message = voice_first_message(root);
1414→  content = message ? cJSON_GetObjectItem(message, "content") : NULL;
1415→  if (content && cJSON_IsString(content) && content->valuestring)
1416→    {
1417→      snprintf(text, (size_t)cap, "%s", content->valuestring);
1418→    }
1419→  cJSON_Delete(root);
1420→  if (!text[0])
1421→    {
1422→      syslog(LOG_ERR,
1423→             "[dm-voice] ASR response has no choices[0].message.content text\n");
1424→      return -1;
1425→    }
1426→  syslog(LOG_INFO, "[dm-voice] ASR success text_bytes=%u\n",
1427→         (unsigned int)strlen(text));
1428→  return 0;
1429→}
