1431→static int chat_reply(const char *user, char *out, int cap)
1432→{
1433→  char esc[400];
1434→  char hist[1400];
1435→  char body[2400];
1436→  int n;
1437→  cJSON *root;
1438→  cJSON *message;
1439→  cJSON *content;
1440→
1441→  if (!user || !out || cap < 2)
1442→    {
1443→      return -1;
1444→    }
1445→  out[0] = '\0';
1446→  if (json_escape(user, esc, sizeof(esc)) < 0)
1447→    {
1448→      return -1;
1449→    }
1450→  dm_chat_hist_json(hist, sizeof(hist));
1451→
1452→  n = snprintf(body, sizeof(body),
