static void *reminder_speech_worker(void *arg)
{
  reminder_speech_t *speech = arg;
  char line[REMINDER_TEXT_MAX + 48];
  int rc = -1;
  int beep_rc;
  int attempt;
  int speech_attempted = 0;

  if (!speech)
    {
      return NULL;
    }
  if (speech->is_alarm)
    {
      snprintf(line, sizeof(line), "闹钟响了：%s。", speech->text);
      dm_vol_alarm_begin();
    }
  else
    {
      snprintf(line, sizeof(line), "待办提醒：%s。", speech->text);
    }

  /* TODOs notify once. Alarms repeat the offline-safe tone until the user
   * dismisses the alert; cloud TTS is attempted only once per alarm event. */
  do
    {
      if (speech->is_alarm && !reminder_alarm_is_ringing())
        {
          break;
        }

      beep_rc = -EBUSY;
      for (attempt = 0; attempt < 12 &&
           (!speech->is_alarm || reminder_alarm_is_ringing()); attempt++)
        {
          beep_rc = dm_voice_beep();
          if (beep_rc != -EBUSY)
            {
              break;
            }
          usleep(250000);
        }
      if (beep_rc != 0 &&
          (!speech->is_alarm || reminder_alarm_is_ringing()))
        {
          syslog(LOG_WARNING, "[dm-remind] alert tone playback failed rc=%d\n",
                 beep_rc);
        }

      if (!speech_attempted)
        {
          speech_attempted = 1;
          if (dm_wifi_connected())
            {
              rc = dm_voice_tts_play(line);
            }
          if (rc != 0)
            {
              syslog(LOG_WARNING, "[dm-remind] spoken reminder unavailable\n");
            }
        }

      if (!speech->is_alarm || !reminder_alarm_is_ringing())
        {
          break;
        }

      /* The tone itself lasts about one second; a short gap keeps the ring
       * persistent without monopolizing the audio device between beeps. */
      for (attempt = 0; attempt < 5 && reminder_alarm_is_ringing(); attempt++)
        {
          usleep(100000);
        }
    }
  while (speech->is_alarm && reminder_alarm_is_ringing());

  if (speech->is_alarm)
    {
      pthread_mutex_lock(&s_voice_lock);
      s_alarm_ring_active = 0;
      pthread_mutex_unlock(&s_voice_lock);
      dm_vol_alarm_end();
    }
  free(speech);
  pthread_mutex_lock(&s_voice_lock);
  s_voice_done = 1;
  pthread_mutex_unlock(&s_voice_lock);
  return NULL;
}

