 46→  } points[] =
 47→  {
 48→    { 0,   0 },
 49→    { 10, 48 },
 50→    { 25, 88 },
 51→    { 50, 124 },
 52→    { 75, 148 },
 53→    { 100, DAC_VOL_MAX }
 54→  };
 55→  unsigned int i;
 56→
 57→  if (percent <= 0)
 58→    {
 59→      return 0;
 60→    }
 61→  if (percent >= 100)
 62→    {
 63→      return DAC_VOL_MAX;
 64→    }
 65→
 66→  for (i = 1; i < sizeof(points) / sizeof(points[0]); i++)
 67→    {
 68→      if (percent <= points[i].percent)
 69→        {
 70→          unsigned int span = points[i].percent - points[i - 1].percent;
 71→          unsigned int value_span = points[i].reg - points[i - 1].reg;
 72→          unsigned int offset = (unsigned int)percent - points[i - 1].percent;
 73→          return points[i - 1].reg + (value_span * offset + span / 2) / span;
 74→        }
 75→    }
 76→
 77→  return DAC_VOL_MAX;
 78→}
