779→/* Called from the UI tick. Registration is deferred until BLE reports ready
780→   (BLE_ON or ON). Advertising begins only after this service's attribute-table
781→   callback succeeds. A deadline prevents a failed HCI bring-up from leaving
782→   the app page in STARTING forever. */
783→void dm_ble_poll(void)
784→{
785→  static int ticks;
786→  int pairing_timed_out = 0;
787→  bt_adapter_state_t adapter_state;
788→
789→  pthread_mutex_lock(&s_lock);
790→  if (s_pairing)
791→    {
792→      if (++s_pair_ticks >= DM_BLE_PAIR_TIMEOUT_TICKS)
793→        {
794→          s_pairing = 0;
795→          s_paired = 0;
796→          s_pair_ticks = 0;
797→          s_challenge = 0;
798→          pairing_timed_out = 1;
799→        }
800→    }
801→  else
802→    {
803→      s_pair_ticks = 0;
804→    }
805→  pthread_mutex_unlock(&s_lock);
806→
807→  adapter_state = s_ins ? bt_adapter_get_state(s_ins) : BT_ADAPTER_STATE_OFF;
808→  if (pairing_timed_out)
809→    {
810→      syslog(LOG_WARNING, "[ble-gatt] pairing challenge timed out\n");
811→      (void)send_pair_fail();
812→      set_state(DM_BLE_CONNECTED);
813→    }
814→
815→  if (s_state == DM_BLE_ADVERTISING && s_adv_restart_pending &&
816→      s_gatt_ready && !s_adv)
817→    {
818→      s_adv_restart_pending = 0;
819→      s_start_pending = 1;
820→      s_start_ticks = 0;
821→      set_state(DM_BLE_STARTING);
822→    }
823→
824→  if (s_state == DM_BLE_STARTING)
825→    {
826→      /* Recover if the stack was already ready before callback registration,
827→         or if the transition notification was dropped. */
828→      if (adapter_le_ready())
829→        {
830→          s_start_pending = 1;
831→        }
832→      if (++s_start_ticks >= DM_BLE_START_TIMEOUT_TICKS)
833→        {
834→          s_start_ticks = 0;
835→          s_start_pending = 0;
836→          s_adv_restart_pending = 0;
837→          ticks = 0;
838→          syslog(LOG_ERR,
839→                 "[ble-gatt] startup timeout state=%d: adapter did not reach advertising\n",
840→                 (int)adapter_state);
841→          set_state(DM_BLE_ERROR);
842→          stop_adv();
843→          if (s_srv)
844→            {
845→              (void)bt_gatts_unregister_service(s_srv);
846→              s_srv = NULL;
847→            }
848→          s_gatt_ready = 0;
849→          return;
850→        }
851→    }
852→  else
853→    {
854→      s_start_ticks = 0;
855→    }
856→
857→  if (!s_start_pending || s_state != DM_BLE_STARTING)
858→    {
859→      ticks = 0;
860→      return;
861→    }
862→  if (++ticks < 8) /* ~2s settle after BLE_ON/ON callback */
863→    {
864→      return;
865→    }
866→  ticks = 0;
867→  if (!adapter_le_ready())
868→    {
869→      s_start_pending = 0;
870→      return;
871→    }
872→  do_register_and_adv();
873→}
