539→static void *reminder_speech_worker(void *arg)
540→{
541→  reminder_speech_t *speech = arg;
542→  char line[REMINDER_TEXT_MAX + 48];
543→  int rc = -1;
544→  int beep_rc;
545→  int attempt;
546→  int speech_attempted = 0;
547→
548→  if (!speech)
549→    {
550→      return NULL;
551→    }
552→  if (speech->is_alarm)
553→    {
554→      snprintf(line, sizeof(line), "闹钟响了：%s。", speech->text);
555→      dm_vol_alarm_begin();
556→    }
557→  else
558→    {
559→      snprintf(line, sizeof(line), "待办提醒：%s。", speech->text);
560→    }
561→
562→  /* TODOs notify once. Alarms repeat the offline-safe tone until the user
563→   * dismisses the alert; cloud TTS is attempted only once per alarm event. */
564→  do
565→    {
566→      if (speech->is_alarm && !reminder_alarm_is_ringing())
567→        {
568→          break;
569→        }
570→
571→      beep_rc = -EBUSY;
572→      for (attempt = 0; attempt < 12 &&
573→           (!speech->is_alarm || reminder_alarm_is_ringing()); attempt++)
574→        {
575→          beep_rc = dm_voice_beep();
576→          if (beep_rc != -EBUSY)
577→            {
578→              break;
579→            }
580→          usleep(250000);
581→        }
582→      if (beep_rc != 0 &&
583→          (!speech->is_alarm || reminder_alarm_is_ringing()))
584→        {
585→          syslog(LOG_WARNING, "[dm-remind] alert tone playback failed rc=%d\n",
586→                 beep_rc);
587→        }
588→
589→      if (!speech_attempted &&
590→          (!speech->is_alarm || reminder_alarm_is_ringing()))
591→        {
592→          speech_attempted = 1;
593→          if (dm_wifi_connected())
594→            {
595→              rc = dm_voice_tts_play(line);
596→            }
597→          if (rc != 0)
598→            {
599→              syslog(LOG_WARNING, "[dm-remind] spoken reminder unavailable\n");
600→            }
601→        }
602→
603→      if (!speech->is_alarm || !reminder_alarm_is_ringing())
604→        {
605→          break;
606→        }
607→
608→      /* The tone itself lasts about one second; a short gap keeps the ring
609→       * persistent without monopolizing the audio device between beeps. */
610→      for (attempt = 0; attempt < 5 && reminder_alarm_is_ringing(); attempt++)
611→        {
612→          usleep(100000);
613→        }
614→    }
615→  while (speech->is_alarm && reminder_alarm_is_ringing());
616→
617→  if (speech->is_alarm)
618→    {
619→      pthread_mutex_lock(&s_voice_lock);
620→      s_alarm_ring_active = 0;
621→      pthread_mutex_unlock(&s_voice_lock);
622→      dm_vol_alarm_end();
623→    }
624→  free(speech);
625→  pthread_mutex_lock(&s_voice_lock);
626→  s_voice_done = 1;
627→  pthread_mutex_unlock(&s_voice_lock);
628→  return NULL;
629→}
