633→  reminder_speech_t *speech;
634→  pthread_t th;
635→  pthread_attr_t attr;
636→  int rc;
637→
638→  if (index < 0 || index >= s_count)
639→    {
640→      return -1;
641→    }
642→  pthread_mutex_lock(&s_voice_lock);
643→  if (s_voice_busy)
644→    {
645→      pthread_mutex_unlock(&s_voice_lock);
646→      return -1;
647→    }
648→  s_voice_busy = 1;
649→  s_voice_done = 0;
650→  pthread_mutex_unlock(&s_voice_lock);
651→  speech = malloc(sizeof(*speech));
652→  if (!speech)
653→    {
654→      pthread_mutex_lock(&s_voice_lock);
655→      s_voice_busy = 0;
656→      pthread_mutex_unlock(&s_voice_lock);
657→      return -1;
658→    }
659→  speech->is_alarm = s_items[index].type == REMINDER_ALARM;
660→  snprintf(speech->text, sizeof(speech->text), "%s", s_items[index].text);
661→  pthread_mutex_lock(&s_voice_lock);
662→  s_alarm_ring_active = speech->is_alarm;
663→  pthread_mutex_unlock(&s_voice_lock);
664→  pthread_attr_init(&attr);
665→  pthread_attr_setstacksize(&attr, DM_VOICE_NET_WORKER_STACK);
666→  rc = pthread_create(&th, &attr, reminder_speech_worker, speech);
667→  pthread_attr_destroy(&attr);
668→  if (rc != 0)
669→    {
670→      pthread_mutex_lock(&s_voice_lock);
671→      s_voice_busy = 0;
672→      s_alarm_ring_active = 0;
673→      pthread_mutex_unlock(&s_voice_lock);
674→      free(speech);
675→      return -1;
676→    }
677→  pthread_detach(th);
678→  return 0;
679→}
