 32→static pthread_mutex_t s_vol_lock = PTHREAD_MUTEX_INITIALIZER;
 33→static int s_vol = VOL_DEFAULT;
 34→static int s_mute;
 35→static int s_alarm_vol = VOL_ALARM_DEFAULT;
 36→static int s_alarm_active;
 37→
 38→/* Perceptual slider mapping: lift the quiet half of the range, while
 39→ * reserving headroom at the top to avoid the previous full-scale loudness. */
 40→static unsigned int vol_percent_to_reg(int percent)
 41→{
 42→  static const struct
 43→  {
 44→    unsigned char percent;
 45→    unsigned char reg;
 46→  } points[] =
 47→  {
 48→    { 0,   0 },
 49→    { 10, 48 },
 50→    { 25, 88 },
 51→    { 50, 124 },
 52→    { 75, 148 },
 53→    { 100, DAC_VOL_MAX }
 54→  };
 55→  unsigned int i;
 56→
 57→  if (percent <= 0)
 58→    {
 59→      return 0;
 60→    }
 61→  if (percent >= 100)
 62→    {
 63→      return DAC_VOL_MAX;
 64→    }
 65→
 66→  for (i = 1; i < sizeof(points) / sizeof(points[0]); i++)
 67→    {
 68→      if (percent <= points[i].percent)
 69→        {
 70→          unsigned int span = points[i].percent - points[i - 1].percent;
 71→          unsigned int value_span = points[i].reg - points[i - 1].reg;
 72→          unsigned int offset = (unsigned int)percent - points[i - 1].percent;
 73→          return points[i - 1].reg + (value_span * offset + span / 2) / span;
 74→        }
 75→    }
 76→
 77→  return DAC_VOL_MAX;
 78→}
 79→
 80→static unsigned int alarm_percent_to_reg(int percent)
 81→{
 82→  unsigned int media_reg = vol_percent_to_reg(percent);
 83→
 84→  /* The codec control accepts 0..255. Keep media at its existing ceiling,
 85→   * but give alarms a modest app-layer boost while retaining headroom. */
 86→  return (media_reg * DAC_ALARM_VOL_MAX + DAC_VOL_MAX / 2) / DAC_VOL_MAX;
 87→}
