100→  dm_create_dock();
101→  dm_show(PAGE_FOCUS_HOME);
102→
103→  /* WiFi is manual-only now: no boot auto-connect.
104→   * The user connects from Settings > Wi-Fi (logic ported from the 9.5 demo). */
105→
106→  lv_timer_create(tick_cb, DM_TICK_MS, NULL);
107→
108→  LV_LOG_USER("FlowDesk " DM_VER " focus-home zh=%d", (int)g_dm.zh);
109→
110→  while (true)
111→    {
