171→void dm_show(dm_page_t p)
172→{
173→  int i;
174→
175→  if (p >= PAGE_COUNT)
176→    {
177→      return;
178→    }
179→
180→  g_dm.page = p;
181→  for (i = 0; i < PAGE_COUNT; i++)
182→    {
183→      if (!g_dm_pages[i])
184→        {
185→          continue;
186→        }
187→
188→      if (i == (int)p)
189→        {
190→          fade_in(g_dm_pages[i]);
191→          /* keep active page on top (later-created pages e.g. 2048) */
192→          lv_obj_move_foreground(g_dm_pages[i]);
193→        }
194→      else
195→        {
196→          lv_obj_add_flag(g_dm_pages[i], LV_OBJ_FLAG_HIDDEN);
197→        }
198→    }
199→
200→  if (g_dm_dock)
201→    {
202→      /* Fix: Hide bottom dock on PAGE_WIFI as well so it does not cover
203→       * the AP list and the "连接所选" (Join) button at y=202..230. */
204→      if (p == PAGE_FOCUS_RUN || p == PAGE_FOCUS_DONE || p == PAGE_MOOD_LOG ||
205→          p == PAGE_SUPERVISE ||
206→          p == PAGE_NOTE || p == PAGE_WIFI || p == PAGE_WIFI_PW ||
207→          p == PAGE_WIFI_KB || p == PAGE_WIFI_CONN ||
208→          p == PAGE_WIFI_DONE ||
209→          p == PAGE_WORD_STUDY || p == PAGE_WORD_RES ||
210→          p == PAGE_WORD_QUIZ || p == PAGE_WORD_WRONG ||
211→          p == PAGE_WORD_LIST || p == PAGE_WORD_WSET || p == PAGE_CALC ||
212→          p == PAGE_SENSORS || p == PAGE_GUESS || p == PAGE_CONVERT ||
213→          p == PAGE_WATER || p == PAGE_COUNTDOWN || p == PAGE_EAT ||
214→          p == PAGE_24 || p == PAGE_DRAW || p == PAGE_BMI || p == PAGE_MED ||
215→          p == PAGE_MED_ADD || p == PAGE_MED_KB || p == PAGE_2048 ||
216→          p == PAGE_MBTI || p == PAGE_MBTI_Q || p == PAGE_MBTI_RESULT ||
217→          p == PAGE_NOTE_ADD || p == PAGE_NOTE_KB ||
218→          p == PAGE_DICT || p == PAGE_DICT_SEARCH || p == PAGE_DICT_DETAIL ||
219→          p == PAGE_RECORDER || p == PAGE_TODO || p == PAGE_ALARM ||
220→          p == PAGE_VOLUME ||
221→          p == PAGE_VOICE_SEL ||
222→          p == PAGE_ABOUT)
223→        {
224→          lv_obj_add_flag(g_dm_dock, LV_OBJ_FLAG_HIDDEN);
225→        }
226→      else
227→        {
228→          lv_obj_clear_flag(g_dm_dock, LV_OBJ_FLAG_HIDDEN);
229→          /* dock must stay above content pages */
230→          lv_obj_move_foreground(g_dm_dock);
231→        }
232→      dm_dock_highlight(p);
233→    }
234→
235→  if (p == PAGE_HEALTH)
236→    {
237→      dm_health_refresh();
238→    }
239→
240→  if (p == PAGE_CHAT && g_dm_pages[PAGE_CHAT])
241→    {
242→      dm_face_attach(g_dm_pages[PAGE_CHAT], (DM_SCR_W - 76) / 2, 32);
243→      if (g_dm_face)
244→        {
245→          lv_obj_set_size(g_dm_face, 76, 76);
246→        }
247→    }
248→  else if (p == PAGE_FOCUS_HOME && g_dm_pages[PAGE_FOCUS_HOME])
249→    {
250→      dm_face_attach(g_dm_pages[PAGE_FOCUS_HOME], (DM_SCR_W - 68) / 2, 24);
251→      if (g_dm_face)
252→        {
253→          lv_obj_set_size(g_dm_face, 68, 68);
254→        }
255→    }
256→  else if (p == PAGE_FOCUS_RUN && g_dm_pages[PAGE_FOCUS_RUN])
257→    {
258→      dm_face_attach(g_dm_pages[PAGE_FOCUS_RUN], (DM_SCR_W - 84) / 2, 24);
259→      if (g_dm_face)
260→        {
261→          lv_obj_set_size(g_dm_face, 84, 84);
262→        }
263→    }
264→  else if (p == PAGE_FOCUS_DONE && g_dm_pages[PAGE_FOCUS_DONE])
265→    {
266→      dm_face_attach(g_dm_pages[PAGE_FOCUS_DONE], (DM_SCR_W - 64) / 2, 22);
267→      if (g_dm_face)
268→        {
269→          lv_obj_set_size(g_dm_face, 64, 64);
270→        }
271→    }
272→
273→  if (p != PAGE_FOCUS_RUN && p != PAGE_FOCUS_DONE && g_dm.focus_run)
274→    {
275→      dm_face_set(FACE_IDLE, EYE_DECOR_NONE, 0);
276→    }
277→}
