868→static void alarm_adjust_cb(lv_event_t *e)
869→{
870→  int code = (int)(intptr_t)lv_event_get_user_data(e);
871→  if (code == 1) s_alarm_hour = (s_alarm_hour + 1) % 24;
872→  else if (code == -1) s_alarm_hour = (s_alarm_hour + 23) % 24;
873→  else if (code == 5) s_alarm_minute = (s_alarm_minute + 5) % 60;
874→  else if (code == -5) s_alarm_minute = (s_alarm_minute + 55) % 60;
875→  alarm_time_paint();
876→}
