885→static void alarm_add_cb(lv_event_t *e)
886→{
887→  int rc;
888→  time_t now = time(NULL);
889→  struct tm tmv;
890→  (void)e;
891→  if (!localtime_r(&now, &tmv))
892→    {
893→      if (s_alarm_hint) lv_label_set_text(s_alarm_hint, "设备时间不可用");
894→      return;
895→    }
896→  if (!s_alarm_repeat &&
897→      (s_alarm_hour < tmv.tm_hour ||
898→       (s_alarm_hour == tmv.tm_hour && s_alarm_minute <= tmv.tm_min)))
899→    {
900→      tmv.tm_mday++;
901→    }
902→  rc = dm_alarm_add_voice("闹钟", tmv.tm_year + 1900, tmv.tm_mon + 1,
903→                          tmv.tm_mday, s_alarm_hour, s_alarm_minute,
904→                          s_alarm_repeat);
905→  if (s_alarm_hint)
906→    {
907→      lv_label_set_text(s_alarm_hint, rc == 0 ? "闹钟已保存" :
908→                        (rc == -2 ? "闹钟数量已满" :
909→                         (rc == -4 ? "请先校准设备时间" : "设置失败")));
910→    }
911→  reminder_paint();
912→}
