 71→void dm_voice_profile_init(void)
 72→{
 73→  FILE *f = fopen(VOICE_CFG, "r");
 74→  int v = 0;
 75→  if (f)
 76→    {
 77→      if (fscanf(f, "%d", &v) == 1)
 78→        {
 79→          if (v >= 0 && v < NPROF)
 80→            {
