245→int dm_todo_add_at_voice(const char *name, int year, int month, int day,
246→                         int hour, int minute)
247→{
248→  time_t now = time(NULL);
249→  time_t due;
250→  struct tm target;
251→  struct tm verify;
252→
253→  if (!reminder_clock_valid(now))
254→    {
255→      return -4;
256→    }
257→  if (year < 2024 || year > 2099 || month < 1 || month > 12 ||
258→      day < 1 || day > 31 || hour < 0 || hour > 23 || minute < 0 ||
259→      minute > 59)
260→    {
261→      return -1;
262→    }
263→
264→  memset(&target, 0, sizeof(target));
265→  target.tm_year = year - 1900;
266→  target.tm_mon = month - 1;
267→  target.tm_mday = day;
268→  target.tm_hour = hour;
269→  target.tm_min = minute;
270→  target.tm_isdst = -1;
271→  due = mktime(&target);
272→  if (due == (time_t)-1 || !localtime_r(&due, &verify) ||
273→      verify.tm_year != year - 1900 || verify.tm_mon != month - 1 ||
274→      verify.tm_mday != day || verify.tm_hour != hour ||
275→      verify.tm_min != minute || due <= now)
276→    {
277→      return -1;
278→    }
279→
280→  return reminder_append(REMINDER_TODO, name, due, 0, 0, 0);
281→}
