283→int dm_alarm_add_voice(const char *name, int year, int month, int day,
284→                       int hour, int minute, int repeat_daily)
285→{
286→  time_t now = time(NULL);
287→  struct tm tmv;
288→  struct tm verify;
289→  time_t due;
290→
291→  if (!reminder_clock_valid(now))
292→    {
293→      return -4;
294→    }
295→  if (year < 2024 || year > 2099 || month < 1 || month > 12 ||
296→      day < 1 || day > 31 || hour < 0 || hour > 23 || minute < 0 ||
297→      minute > 59)
298→    {
299→      return -1;
300→    }
301→  memset(&tmv, 0, sizeof(tmv));
302→  tmv.tm_year = year - 1900;
303→  tmv.tm_mon = month - 1;
304→  tmv.tm_mday = day;
305→  tmv.tm_hour = hour;
306→  tmv.tm_min = minute;
307→  tmv.tm_isdst = -1;
308→  due = mktime(&tmv);
309→  if (due == (time_t)-1)
310→    {
311→      return -1;
312→    }
313→  localtime_r(&due, &verify);
314→  if (verify.tm_year != year - 1900 || verify.tm_mon != month - 1 ||
315→      verify.tm_mday != day || verify.tm_hour != hour || verify.tm_min != minute)
316→    {
317→      return -1;
318→    }
319→  if (repeat_daily && due <= now)
320→    {
321→      verify.tm_mday++;
322→      verify.tm_isdst = -1;
323→      due = mktime(&verify);
324→    }
325→  else if (due <= now)
326→    {
327→      return -1;
328→    }
329→  return reminder_append(REMINDER_ALARM, name, due, repeat_daily, hour, minute);
330→}
