393→static void reminder_delete(int type)
394→{
395→  int index = type == REMINDER_TODO ? s_todo_sel : s_alarm_sel;
396→  int old_count = s_count;
397→  int old_alert = s_alert_idx;
398→  reminder_t removed;
399→  int i;
400→  if (index < 0 || index >= s_count || s_items[index].type != type)
401→    {
402→      return;
403→    }
404→  if (index == s_alert_idx)
405→    {
406→      return;
407→    }
408→  removed = s_items[index];
409→  for (i = index; i + 1 < s_count; i++)
410→    {
411→      s_items[i] = s_items[i + 1];
412→    }
413→  s_count--;
414→  memset(&s_items[s_count], 0, sizeof(s_items[s_count]));
415→  if (reminder_save() != 0)
416→    {
417→      for (i = s_count; i > index; i--)
418→        {
419→          s_items[i] = s_items[i - 1];
420→        }
421→      s_items[index] = removed;
422→      s_count = old_count;
423→      s_alert_idx = old_alert;
424→      return;
425→    }
426→  if (s_alert_idx > index)
427→    {
428→      s_alert_idx--;
429→    }
430→  s_todo_sel = -1;
431→  s_alarm_sel = -1;
432→  reminder_paint();
433→}
