447→static void format_remaining(time_t due, char *out, size_t cap)
448→{
449→  time_t now = time(NULL);
450→  long left = (long)(due - now);
451→  if (left <= 0)
452→    {
453→      snprintf(out, cap, "%s", "到时间了");
454→    }
455→  else if (left >= 86400)
456→    {
457→      snprintf(out, cap, "%ld天后", (left + 86399) / 86400);
458→    }
459→  else if (left >= 3600)
460→    {
461→      snprintf(out, cap, "%ld小时后", (left + 3599) / 3600);
462→    }
463→  else if (left >= 60)
464→    {
465→      snprintf(out, cap, "%ld分钟后", (left + 59) / 60);
466→    }
467→  else
468→    {
469→      snprintf(out, cap, "%ld秒后", left);
470→    }
471→}
