  if (!f)
    {
      syslog(LOG_WARNING, "[dm-simple] unable to save display mode\n");
      return s_simple_mode;
    }

  if (fprintf(f, "%d\n", next) < 0)
    {
      failed = 1;
    }
  if (fclose(f) != 0)
    {
      failed = 1;
    }
  if (failed)
    {
      syslog(LOG_WARNING, "[dm-simple] display mode write failed\n");
      return s_simple_mode;
    }

  s_simple_mode = next;
  return s_simple_mode;
}

