        else if (dir == LV_DIR_TOP) next = PAGE_CONTROL_CENTER;
        break;

      case PAGE_SIMPLE_OVERVIEW:
        if (dir == LV_DIR_RIGHT) next = PAGE_SIMPLE_HOME;
        else if (dir == LV_DIR_TOP) next = PAGE_CONTROL_CENTER;
        else if (dir == LV_DIR_LEFT) next = PAGE_WATCH_CARDS;
        break;

      case PAGE_CONTROL_CENTER:
        if (dir == LV_DIR_BOTTOM) next = PAGE_SIMPLE_HOME;
        else if (dir == LV_DIR_LEFT) next = PAGE_SIMPLE_OVERVIEW;
        else if (dir == LV_DIR_RIGHT) next = PAGE_WATCH_CARDS;
        break;

      case PAGE_WATCH_CARDS:
        if (dir == LV_DIR_LEFT || dir == LV_DIR_BOTTOM)
          next = PAGE_SIMPLE_HOME;
        else if (dir == LV_DIR_TOP)
          next = PAGE_WATCH_APPS;
        break;

      case PAGE_WATCH_APPS:
        if (dir == LV_DIR_BOTTOM) next = PAGE_WATCH_CARDS;
        else if (dir == LV_DIR_LEFT) next = PAGE_SIMPLE_HOME;
        break;

      default:
        break;
    }

  if (next < PAGE_COUNT)
    {
      dm_show(next);
    }
}

