159→    }
160→  if (fclose(out) != 0)
161→    {
162→      write_failed = 1;
163→    }
164→
165→  if (write_failed || !recorder_wav_exists(dst))
166→    {
167→      unlink(dst);
168→      return;
169→    }
170→
171→  s_slot_exists[0] = 1;
172→  s_slot_count = 1;
