 99→/* ---------- recorder: nxrecorder (buffer-queue API) ----------
100→ * plain read() on /dev/audio/pcm0c is a no-op on this driver (no .read
101→ * op), only the nxrecorder buffer-queue path actually captures audio.
102→ */
103→
104→static struct nxrecorder_s *s_rec;
105→static uint32_t s_rec_generation;
106→
107→struct rec_auto_stop_arg_s
108→{
109→  int max_sec;
110→  uint32_t generation;
111→};
112→
113→static int dm_voice_rec_stop_generation(uint32_t generation, int check_generation);
114→
115→static void *rec_auto_stop(void *arg)
116→{
117→  struct rec_auto_stop_arg_s *timer = arg;
118→  int max_sec = timer->max_sec;
119→  uint32_t generation = timer->generation;
120→
121→  free(timer);
122→  sleep(max_sec > 0 ? max_sec : REC_MAX_SEC);
123→  (void)dm_voice_rec_stop_generation(generation, 1);
124→  return NULL;
125→}
126→
127→int dm_voice_rec_start(int max_seconds)
128→{
129→  struct rec_auto_stop_arg_s *timer;
130→  pthread_t th;
131→  pthread_attr_t attr;
132→  uint32_t generation;
133→  int ret;
134→
135→  if (max_seconds <= 0)
136→    {
137→      max_seconds = REC_MAX_SEC;
138→    }
139→  if (max_seconds > 300)
140→    {
141→      max_seconds = 300;
142→    }
143→
144→  pthread_mutex_lock(&s_rec_lock);
145→  if (s_rec_active)
146→    {
147→      pthread_mutex_unlock(&s_rec_lock);
148→      return -EBUSY;
149→    }
150→
151→  /* Do not contend for the audio DMA while playback is active.  Use
152→   * trylock so a UI click never waits behind a long speaker operation. */
153→  if (pthread_mutex_trylock(&s_audio_lock) != 0)
154→    {
155→      pthread_mutex_unlock(&s_rec_lock);
156→      return -EBUSY;
157→    }
158→
159→  unlink(WAV_REC);
160→  s_rec = nxrecorder_create();
161→  if (!s_rec)
162→    {
163→      pthread_mutex_unlock(&s_audio_lock);
164→      pthread_mutex_unlock(&s_rec_lock);
165→      s_st = DM_VOICE_ERR;
166→      return -1;
167→    }
168→  ret = nxrecorder_setdevice(s_rec, "/dev/audio/pcm0c");
169→  if (ret != OK)
170→    {
171→      syslog(LOG_ERR, "[dm-voice] set microphone device failed: %d\n", ret);
172→      nxrecorder_release(s_rec);
173→      s_rec = NULL;
174→      pthread_mutex_unlock(&s_audio_lock);
175→      pthread_mutex_unlock(&s_rec_lock);
176→      s_st = DM_VOICE_ERR;
177→      return ret;
178→    }
179→
180→  ret = nxrecorder_recordinternal(s_rec, WAV_REC, AUDIO_FMT_PCM,
181→                                  REC_CH, REC_BITS, REC_RATE, 1);
182→  if (ret != OK)
183→    {
184→      syslog(LOG_ERR,
185→             "[dm-voice] recorder start failed: %d (rate=%d ch=%d bits=%d)\n",
186→             ret, REC_RATE, REC_CH, REC_BITS);
187→      nxrecorder_release(s_rec);
188→      s_rec = NULL;
189→      pthread_mutex_unlock(&s_audio_lock);
190→      pthread_mutex_unlock(&s_rec_lock);
191→      s_st = DM_VOICE_ERR;
192→      return ret;
193→    }
194→
195→  s_rec_generation++;
196→  if (s_rec_generation == 0)
197→    {
198→      s_rec_generation++;
199→    }
200→  generation = s_rec_generation;
201→  s_rec_active = 1;
202→  s_st = DM_VOICE_REC;
203→  pthread_mutex_unlock(&s_audio_lock);
204→  pthread_mutex_unlock(&s_rec_lock);
205→
206→  timer = malloc(sizeof(*timer));
207→  if (!timer)
208→    {
209→      (void)dm_voice_rec_stop_generation(generation, 1);
210→      return -ENOMEM;
211→    }
212→  timer->max_sec = max_seconds;
213→  timer->generation = generation;
214→
215→  pthread_attr_init(&attr);
216→  pthread_attr_setstacksize(&attr, 16384);
217→  ret = pthread_create(&th, &attr, rec_auto_stop, timer);
218→  pthread_attr_destroy(&attr);
219→  if (ret != 0)
