 27→static int chat_key_load(char *key, size_t key_cap)
 28→{
 29→  FILE *f;
 30→  size_t i;
 31→  size_t n;
 32→  int valid = 0;
 33→
 34→  if (!key || key_cap < 16)
 35→    {
 36→      return 0;
 37→    }
 38→  key[0] = '\0';
 39→  f = fopen(MIMO_KEY_PATH, "rb");
 40→  if (!f)
 41→    {
 42→      snprintf(key, key_cap, "%s", MIMO_EMBEDDED_KEY);
 43→      return key[0] != '\0';
 44→    }
 45→  if (fgets(key, (int)key_cap, f))
 46→    {
 47→      n = strlen(key);
 48→      while (n > 0 && (key[n - 1] == '\r' || key[n - 1] == '\n' ||
 49→                       key[n - 1] == ' ' || key[n - 1] == '\t'))
 50→        {
 51→          key[--n] = '\0';
 52→        }
 53→      valid = n > 8 && n < key_cap - 1;
 54→      for (i = 0; valid && i < n; i++)
 55→        {
 56→          unsigned char ch = (unsigned char)key[i];
 57→          if (!((ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') ||
 58→                (ch >= '0' && ch <= '9') || ch == '-' || ch == '_' ||
 59→                ch == '.'))
 60→            {
 61→              valid = 0;
 62→            }
 63→        }
 64→    }
 65→  fclose(f);
 66→  if (!valid)
 67→    {
 68→      memset(key, 0, key_cap);
 69→      snprintf(key, key_cap, "%s", MIMO_EMBEDDED_KEY);
 70→      valid = key[0] != '\0';
 71→    }
 72→  return valid;
 73→}
 74→
 75→/* Store every curl option in its config file. The NSH command is kept to two
 76→ * arguments (curl and -K config) because this image's argument limit is low. */
 77→static int run_curl_command(const char *url, const char *request_path,
 78→                            const char *out_path, int timeout_sec)
 79→{
 80→  char key[128];
 81→  FILE *kf;
 82→  int config_ok;
 83→  int close_rc;
 84→  int rc;
 85→  int saved_errno;
 86→
 87→  if (!url || !request_path || !out_path || timeout_sec < 1 ||
 88→      timeout_sec > 120 || strchr(url, '"') || strchr(url, '\\') ||
 89→      strchr(url, '\r') || strchr(url, '\n') || strchr(request_path, '"') ||
 90→      strchr(request_path, '\\') || strchr(request_path, '\r') ||
 91→      strchr(request_path, '\n') || strchr(out_path, '"') ||
 92→      strchr(out_path, '\\') || strchr(out_path, '\r') ||
 93→      strchr(out_path, '\n') || !chat_key_load(key, sizeof(key)))
 94→    {
 95→      syslog(LOG_ERR, "[dm-chat] invalid curl request configuration\n");
 96→      return -1;
 97→    }
 98→
 99→  kf = fopen(MIMO_CURL_CONFIG, "w");
100→  if (!kf)
101→    {
102→      syslog(LOG_ERR, "[dm-chat] cannot create curl config errno=%d\n", errno);
103→      memset(key, 0, sizeof(key));
104→      return -1;
105→    }
106→  if (chmod(MIMO_CURL_CONFIG, S_IRUSR | S_IWUSR) != 0)
107→    {
108→      /* chmod is unsupported on this image; that must not block requests. */
109→      syslog(LOG_WARNING,
110→             "[dm-chat] chmod unavailable for curl config errno=%d; continuing\n",
111→             errno);
112→    }
113→
114→  config_ok = fputs("silent\nshow-error\nfail\n",
115→                    kf) != EOF &&
116→              fprintf(kf, "max-time = %d\n", timeout_sec) > 0 &&
117→              fprintf(kf, "url = \"%s\"\n", url) > 0 &&
118→              fputs("cacert = \"/resource/etc/ssl/curl/ca-certificates.crt\"\n"
119→                    "request = \"POST\"\n"
120→                    "header = \"Content-Type: application/json\"\n",
121→                    kf) != EOF &&
122→              fprintf(kf, "header = \"Authorization: Bearer %s\"\n",
123→                      key) > 0 &&
124→              fprintf(kf, "data = \"@%s\"\noutput = \"%s\"\n",
125→                      request_path, out_path) > 0 &&
126→              fputs("write-out = \"HTTP_STATUS:%{http_code}\\n\"\n",
127→                    kf) != EOF;
128→  close_rc = fclose(kf);
129→  memset(key, 0, sizeof(key));
130→  if (!config_ok || close_rc != 0)
131→    {
132→      syslog(LOG_ERR, "[dm-chat] cannot write curl config\n");
133→      unlink(MIMO_CURL_CONFIG);
134→      return -1;
135→    }
136→
137→  errno = 0;
138→  rc = system("curl -K " MIMO_CURL_CONFIG);
139→  saved_errno = errno;
140→  unlink(MIMO_CURL_CONFIG);
141→  if (rc != 0)
142→    {
143→      syslog(LOG_ERR,
144→             "[dm-chat] curl command failed system_status=%d errno=%d\n",
145→             rc, saved_errno);
146→      return -1;
147→    }
148→  return 0;
149→}
