398→static int play_wav(const char *path)
399→{
400→  const char *src = (path && path[0]) ? path : WAV_TTS;
401→  struct nxplayer_s *p = NULL;
402→  FILE *f = NULL;
403→  FILE *o = NULL;
404→  uint8_t in_frame[4];
405→  uint8_t outbuf[4096];
406→  size_t out_used = 0;
407→  uint16_t ch = 0;
408→  uint16_t bits = 0;
409→  uint32_t rate = 0;
410→  uint32_t data_size = 0;
411→  uint64_t phase = 0;
412→  uint64_t out_frames = 0;
413→  uint64_t source_frames;
414→  long data_offset = 0;
415→  uint32_t i;
416→  int rc = -1;
417→  const char *failed_at = "lock";
418→
419→  if (pthread_mutex_trylock(&s_audio_lock) != 0)
420→    {
421→      return -EBUSY;
422→    }
423→  if (s_rec_active)
424→    {
425→      pthread_mutex_unlock(&s_audio_lock);
426→      return -EBUSY;
427→    }
428→
429→  failed_at = "open WAV";
430→  f = fopen(src, "rb");
431→  if (!f)
432→    {
433→      syslog(LOG_ERR, "[dm-voice] playback cannot open WAV errno=%d\n", errno);
434→      goto out;
435→    }
436→  if (voice_wav_find_data(f, &ch, &rate, &bits, &data_offset,
437→                          &data_size) != 0 ||
438→      (ch != 1 && ch != 2) || (bits != 8 && bits != 16) ||
439→      rate < 8000 || rate > 48000)
440→    {
441→      syslog(LOG_ERR, "[dm-voice] playback invalid WAV format\n");
442→      goto out;
443→    }
444→
445→  source_frames = data_size / ((uint32_t)ch * (bits / 8));
446→  if (source_frames == 0 || data_size > WAV_INPUT_MAX ||
447→      fseek(f, data_offset, SEEK_SET) != 0)
448→    {
449→      syslog(LOG_ERR, "[dm-voice] playback invalid WAV payload bytes=%u\n",
450→             data_size);
451→      goto out;
452→    }
453→
454→  failed_at = "create normalized PCM";
455→  o = fopen(PCM_RAW, "wb");
456→  if (!o)
457→    {
458→      syslog(LOG_ERR, "[dm-voice] playback cannot create PCM errno=%d\n",
459→             errno);
460→      goto out;
461→    }
462→
463→  /* Nearest-neighbour resampling is sufficient for speech previews and avoids
464→   * pulling a large resampler into the small embedded app. Mix stereo inputs
465→   * to mono, then duplicate to left/right at a fixed 16 kHz output rate. */
466→  for (i = 0; i < source_frames; i++)
467→    {
468→      int32_t sample;
469→
470→      if (fread(in_frame, 1, (size_t)ch * (bits / 8), f) !=
471→          (size_t)ch * (bits / 8))
472→        {
473→          syslog(LOG_ERR, "[dm-voice] playback WAV read failed frame=%u\n", i);
474→          goto out;
475→        }
476→
477→      if (bits == 16)
478→        {
479→          int32_t left = (int16_t)voice_get_le16(in_frame);
480→          sample = left;
481→          if (ch == 2)
482→            {
483→              int32_t right = (int16_t)voice_get_le16(in_frame + 2);
484→              sample = (left + right) / 2;
485→            }
486→        }
487→      else
488→        {
489→          int32_t left = ((int32_t)in_frame[0] - 128) * 256;
490→          sample = left;
491→          if (ch == 2)
492→            {
493→              int32_t right = ((int32_t)in_frame[1] - 128) * 256;
494→              sample = (left + right) / 2;
495→            }
496→        }
497→
498→      phase += SPEAKER_RATE;
499→      while (phase >= rate)
500→        {
501→          uint16_t encoded = (uint16_t)(int16_t)sample;
502→          if (out_used + 4 > sizeof(outbuf))
503→            {
504→              if (fwrite(outbuf, 1, out_used, o) != out_used)
505→                {
506→                  syslog(LOG_ERR, "[dm-voice] playback PCM write failed\n");
507→                  goto out;
508→                }
509→              out_used = 0;
510→            }
511→          outbuf[out_used++] = (uint8_t)encoded;
512→          outbuf[out_used++] = (uint8_t)(encoded >> 8);
513→          outbuf[out_used++] = (uint8_t)encoded;
514→          outbuf[out_used++] = (uint8_t)(encoded >> 8);
515→          out_frames++;
516→          phase -= rate;
517→        }
518→    }
519→
520→  if (out_used > 0 && fwrite(outbuf, 1, out_used, o) != out_used)
521→    {
522→      syslog(LOG_ERR, "[dm-voice] playback final PCM write failed\n");
523→      goto out;
524→    }
525→  if (fclose(o) != 0)
526→    {
527→      o = NULL;
528→      syslog(LOG_ERR, "[dm-voice] playback PCM close failed\n");
529→      goto out;
530→    }
531→  o = NULL;
532→  fclose(f);
533→  f = NULL;
534→
535→  failed_at = "create player";
536→  p = nxplayer_create();
537→  if (!p)
538→    {
539→      syslog(LOG_ERR, "[dm-voice] playback nxplayer_create failed\n");
540→      goto out;
541→    }
542→  if (nxplayer_setdevice(p, "/dev/audio/pcm0p") != OK)
543→    {
544→      syslog(LOG_ERR, "[dm-voice] playback cannot select speaker device\n");
545→      goto out;
546→    }
547→
548→  /* Re-apply the app's persisted codec gain before starting a new audio
549→   * session. Some board configurations also expose nxplayer's volume ioctl. */
550→  dm_vol_apply();
551→#ifndef CONFIG_AUDIO_EXCLUDE_VOLUME
552→  if (nxplayer_setvolume(p, (uint16_t)(s_speaker_vol * 10)) != OK)
553→    {
554→      syslog(LOG_WARNING, "[dm-voice] nxplayer volume ioctl unavailable\n");
555→    }
556→#endif
557→  syslog(LOG_INFO,
558→         "[dm-voice] playback start source=%uHz/%uch/%ubit output=16000Hz/2ch/16bit bytes=%llu\n",
559→         (unsigned int)rate, (unsigned int)ch, (unsigned int)bits,
560→         (unsigned long long)(out_frames * 4));
561→  failed_at = "start playback";
562→  rc = nxplayer_playraw(p, PCM_RAW, AUDIO_FMT_PCM, 0, 2, 16,
563→                        SPEAKER_RATE, 0);
564→  if (rc != OK)
565→    {
566→      syslog(LOG_ERR, "[dm-voice] nxplayer_playraw failed rc=%d errno=%d\n",
567→             rc, errno);
568→      goto out;
569→    }
570→
571→  /* nxplayer_playraw() returns once its worker starts. Hold the audio gate
572→   * through the normalized PCM duration and join before another stream opens. */
573→  {
574→    uint64_t play_ms = out_frames * 1000 / SPEAKER_RATE + 200;
575→    /* Permit a full 30-second recording plus playback completion margin. */
576→    if (play_ms > 35000)
577→      {
578→        play_ms = 35000;
579→      }
580→    while (play_ms >= 1000)
581→      {
582→        sleep(1);
583→        play_ms -= 1000;
584→      }
585→    if (play_ms > 0)
586→      {
587→        usleep((useconds_t)(play_ms * 1000));
588→      }
589→  }
590→
591→  (void)nxplayer_stop(p);
592→  rc = 0;
593→
594→out:
595→  if (o)
596→    {
597→      fclose(o);
598→    }
599→  if (f)
600→    {
601→      fclose(f);
602→    }
603→  if (p)
604→    {
605→      nxplayer_release(p);
606→    }
607→  if (rc != 0)
608→    {
609→      syslog(LOG_WARNING, "[dm-voice] playback failed at %s\n", failed_at);
610→    }
611→  pthread_mutex_unlock(&s_audio_lock);
612→  return rc;
613→}
