 992→static int http_post_json(const char *path, const char *json_body,
 993→                          const char *out_path)
 994→{
 995→  char url[160];
 996→  FILE *f;
 997→  size_t body_len;
 998→  int write_ok;
 999→  int close_rc;
1000→  int url_len;
1001→  int rc;
1002→
1003→  if (!path || !json_body || !out_path)
1004→    {
1005→      return -1;
1006→    }
1007→
1008→  if (!dm_wifi_connected())
1009→    {
1010→      syslog(LOG_INFO, "[dm-voice] waiting up to %d seconds for Wi-Fi\n",
1011→             VOICE_WIFI_WAIT_SEC);
1012→      if (voice_wait_for_wifi() != 0)
1013→        {
1014→          s_last_failure = DM_VOICE_FAILURE_WIFI;
1015→          syslog(LOG_WARNING, "[dm-voice] Wi-Fi did not become ready\n");
1016→          return -1;
1017→        }
1018→    }
1019→  if (dm_wifi_wait_time_sync(40) != 0)
1020→    {
1021→      s_last_failure = DM_VOICE_FAILURE_TIME;
1022→      syslog(LOG_WARNING, "[dm-voice] secure request deferred: clock not ready\n");
1023→      return -1;
1024→    }
1025→
1026→  f = fopen(JSON_REQ, "w");
1027→  if (!f)
1028→    {
1029→      s_last_failure = DM_VOICE_FAILURE_CHAT;
1030→      syslog(LOG_ERR, "[dm-voice] cannot create HTTP request body\n");
1031→      return -1;
1032→    }
1033→  body_len = strlen(json_body);
1034→  write_ok = fwrite(json_body, 1, body_len, f) == body_len;
1035→  close_rc = fclose(f);
1036→  if (!write_ok || close_rc != 0)
1037→    {
1038→      s_last_failure = DM_VOICE_FAILURE_CHAT;
1039→      syslog(LOG_ERR, "[dm-voice] cannot write HTTP request body\n");
1040→      return -1;
1041→    }
1042→  unlink(out_path);
1043→  url_len = snprintf(url, sizeof(url), "%s%s", VOICE_BASE, path);
1044→  if (url_len <= 0 || url_len >= (int)sizeof(url))
1045→    {
1046→      s_last_failure = DM_VOICE_FAILURE_CHAT;
1047→      syslog(LOG_ERR, "[dm-voice] HTTP URL buffer is too small\n");
1048→      return -1;
1049→    }
1050→
1051→  syslog(LOG_INFO, "[dm-voice] curl request configured; NSH argv kept minimal\n");
1052→  rc = run_curl_command(url, JSON_REQ, out_path, 25);
1053→
1054→  if (rc != 0)
1055→    {
1056→      if (s_last_failure == DM_VOICE_FAILURE_NONE)
1057→        {
1058→          s_last_failure = DM_VOICE_FAILURE_CHAT;
1059→        }
1060→      syslog(LOG_WARNING,
1061→             "[dm-voice] HTTP request failed; curl error/status is above\n");
1062→    }
1063→  else
1064→    {
1065→      syslog(LOG_INFO, "[dm-voice] HTTP request completed\n");
1066→    }
1067→  return rc;
1068→}
