1082→  if (fseek(f, 0, SEEK_END) != 0 || (size = ftell(f)) <= 0 ||
1083→      size > max_size || fseek(f, 0, SEEK_SET) != 0)
1084→    {
1085→      fclose(f);
1086→      return NULL;
1087→    }
1088→  buf = malloc((size_t)size + 1);
1089→  if (!buf)
1090→    {
1091→      fclose(f);
1092→      return NULL;
1093→    }
1094→  if (fread(buf, 1, (size_t)size, f) != (size_t)size)
1095→    {
1096→      free(buf);
1097→      fclose(f);
1098→      return NULL;
1099→    }
1100→  fclose(f);
1101→  buf[size] = '\0';
1102→  root = cJSON_Parse(buf);
1103→  free(buf);
1104→  return root;
1105→}
