1629→static int voice_asr_chat_tts_unlocked(const char *wav_path, char *reply,
1630→                                       int cap)
1631→{
1632→  char text[256];
1633→  const char *asr_path;
1634→  int play_rc = -1;
1635→  int intent_handled;
1636→
1637→  if (!wav_path || !reply || cap < 8)
1638→    {
1639→      return -1;
1640→    }
1641→  s_last_failure = DM_VOICE_FAILURE_NONE;
1642→  reply[0] = '\0';
1643→
1644→  if (voice_prepare_wav(wav_path, &asr_path) != 0)
1645→    {
1646→      s_last_failure = DM_VOICE_FAILURE_ASR;
1647→      s_st = DM_VOICE_ERR;
1648→      return -1;
1649→    }
1650→
1651→  s_st = DM_VOICE_ASR;
1652→  if (asr_wav(asr_path, text, sizeof(text)) != 0)
1653→    {
1654→      if (s_last_failure == DM_VOICE_FAILURE_NONE)
1655→        {
1656→          s_last_failure = DM_VOICE_FAILURE_ASR;
1657→        }
1658→      s_st = DM_VOICE_ERR;
1659→      return -1;
1660→    }
1661→
1662→  s_st = DM_VOICE_CHAT;
1663→  intent_handled = dm_assistant_intent_try(text, reply, cap);
1664→  if (intent_handled > 0)
1665→    {
1666→      dm_chat_hist_push(text, reply);
1667→    }
1668→  else if (chat_reply(text, reply, cap) != 0)
1669→    {
1670→      if (s_last_failure == DM_VOICE_FAILURE_NONE)
1671→        {
1672→          s_last_failure = DM_VOICE_FAILURE_CHAT;
1673→        }
1674→      strncpy(reply, "（网络忙，没听清）", (size_t)cap - 1);
1675→      reply[cap - 1] = '\0';
1676→      s_st = DM_VOICE_ERR;
1677→      return -1;
1678→    }
1679→
1680→  /* Preserve the text answer even if playback fails; the caller can show
1681→   * that the reply is text-only rather than pretending the speaker worked. */
1682→  if (intent_handled == 2)
1683→    {
1684→      /* Wake phrase response demonstrates all three user-provided voices in
1685→       * their existing order; regular profile audition behavior is unchanged. */
1686→      s_st = DM_VOICE_PLAY;
1687→      play_rc = voice_play_wake_samples_unlocked();
1688→      if (play_rc != 0 && s_last_failure == DM_VOICE_FAILURE_NONE)
1689→        {
1690→          s_last_failure = DM_VOICE_FAILURE_TTS;
1691→        }
1692→    }
1693→  else
1694→    {
1695→      s_st = DM_VOICE_TTS;
1696→      if (tts_synth(reply, WAV_TTS, dm_voice_profile_api_id()) == 0)
1697→        {
1698→          s_st = DM_VOICE_PLAY;
1699→          play_rc = play_wav(WAV_TTS);
1700→        }
1701→      else if (s_last_failure == DM_VOICE_FAILURE_NONE)
1702→        {
1703→          s_last_failure = DM_VOICE_FAILURE_TTS;
1704→        }
1705→    }
1706→  s_st = DM_VOICE_IDLE;
1707→  return play_rc == 0 ? 0 : 1;
1708→}
