1758→static int voice_wav_cache_valid(const char *path)
1759→{
1760→  FILE *f = fopen(path, "rb");
1761→  unsigned char hdr[44];
1762→  long size;
1763→  int valid = 0;
1764→
1765→  if (!f)
1766→    {
1767→      return 0;
1768→    }
1769→  if (fseek(f, 0, SEEK_END) == 0 && (size = ftell(f)) > 44 &&
1770→      fseek(f, 0, SEEK_SET) == 0 &&
1771→      fread(hdr, 1, sizeof(hdr), f) == sizeof(hdr) &&
1772→      memcmp(hdr, "RIFF", 4) == 0 && memcmp(hdr + 8, "WAVE", 4) == 0)
1773→    {
1774→      valid = 1;
1775→    }
1776→  fclose(f);
1777→  return valid;
1778→}
