676→void dm_recorder_tick(void)
677→{
678→  int job_done;
679→  int rc = 0;
680→  int completed_slot = -1;
681→  recorder_job_t completed = REC_JOB_NONE;
682→
683→  pthread_mutex_lock(&s_job_lock);
684→  job_done = s_job_done;
685→  if (job_done)
686→    {
687→      completed = s_job;
688→      rc = s_job_result;
689→      completed_slot = s_job_completed_slot;
690→      s_job_done = 0;
691→    }
692→  pthread_mutex_unlock(&s_job_lock);
693→
694→  if (job_done)
695→    {
696→      s_busy = 0;
697→      s_job = REC_JOB_NONE;
698→
699→      if (completed == REC_JOB_START)
700→        {
701→          if (rc == 0)
702→            {
703→              s_recording = 1;
704→              s_record_started_ms = recorder_monotonic_ms();
705→              if (s_elapsed)
706→                {
707→                  char elapsed[48];
708→                  snprintf(elapsed, sizeof(elapsed),
709→                           dm_t("已录 0 / %u 秒", "0 / %u sec"),
710→                           RECORDER_MAX_SEC);
711→                  lv_label_set_text(s_elapsed, elapsed);
712→                }
713→              if (s_status)
714→                {
715→                  char status[48];
716→                  snprintf(status, sizeof(status),
717→                           dm_t("正在录制第 %02d 条…", "Recording #%02d…"),
718→                           s_record_slot + 1);
719→                  lv_label_set_text(s_status, status);
720→                }
721→            }
722→          else if (s_status)
723→            {
724→              lv_label_set_text(s_status,
725→                                dm_t("无法启动录音，请稍后重试",
726→                                     "Could not start recording"));
727→            }
728→        }
729→      else if (completed == REC_JOB_STOP_SAVE)
730→        {
731→          s_recording = 0;
732→          s_record_started_ms = 0;
733→          if (rc == 0 && completed_slot >= 0 &&
734→              completed_slot < RECORDER_SLOT_COUNT)
735→            {
736→              if (!s_slot_exists[completed_slot])
737→                {
738→                  s_slot_count++;
739→                }
740→              s_slot_exists[completed_slot] = 1;
741→              s_selected_slot = completed_slot;
742→              s_next_slot = (completed_slot + 1) % RECORDER_SLOT_COUNT;
743→              if (s_status)
744→                {
745→                  char status[64];
746→                  if (s_will_overwrite)
747→                    {
748→                      snprintf(status, sizeof(status),
749→                               dm_t("已保存第 %02d 条，覆盖循环槽位",
750→                                    "Saved #%02d; oldest slot replaced"),
751→                               completed_slot + 1);
752→                    }
753→                  else
754→                    {
755→                      snprintf(status, sizeof(status),
756→                               dm_t("第 %02d 条录音已保存",
757→                                    "Recording #%02d saved"),
758→                               completed_slot + 1);
759→                    }
760→                  lv_label_set_text(s_status, status);
761→                }
762→            }
763→          else if (s_status)
764→            {
765→              lv_label_set_text(s_status,
766→                                dm_t("录音保存失败，请重新录制",
767→                                     "Save failed; please record again"));
768→            }
769→          s_will_overwrite = 0;
770→        }
771→      else if (completed == REC_JOB_PLAY && s_status)
772→        {
773→          lv_label_set_text(s_status,
774→                            rc == 0
775→                              ? dm_t("录音播放完成", "Playback complete")
776→                              : dm_t("播放失败，请检查喇叭", "Playback failed; check speaker"));
777→        }
778→      recorder_refresh();
779→    }
780→
781→  if (s_recording && !s_busy)
782→    {
783→      uint64_t now_ms = recorder_monotonic_ms();
784→      if (s_record_started_ms != 0 && now_ms >= s_record_started_ms)
