794→                   dm_t("已录 %u / %u 秒", "%u / %u sec"),
795→                   seconds, RECORDER_MAX_SEC);
796→          if (s_elapsed)
797→            {
798→              lv_label_set_text(s_elapsed, elapsed);
799→            }
800→        }
801→
802→      /* nxrecorder stops itself at the configured time limit. Save its
803→       * completed capture instead of leaving it in /tmp. */
