1139→/* nxrecorder's AUDIO_FMT_PCM encoder writes headerless PCM even when the
1140→ * filename ends in .wav.  Wrap that payload in a standards-compliant WAV
1141→ * header before sending `format: wav` to the MiMo chat-completions ASR API. */
1142→static int voice_prepare_wav(const char *src, const char **wav_out)
1143→{
1144→  FILE *in;
1145→  FILE *out;
1146→  uint8_t header[44];
1147→  char buf[1024];
1148→  long size;
1149→  size_t n;
1150→  uint32_t data_size;
1151→  unsigned int byte_rate = REC_RATE * REC_CH * REC_BITS / 8;
1152→  int rc = -1;
1153→
1154→  if (!src || !wav_out)
1155→    {
1156→      return -1;
1157→    }
1158→
1159→  *wav_out = src;
1160→  in = fopen(src, "rb");
1161→  if (!in)
1162→    {
1163→      return -1;
1164→    }
1165→
1166→  if (fread(header, 1, 12, in) == 12 &&
1167→      memcmp(header, "RIFF", 4) == 0 && memcmp(header + 8, "WAVE", 4) == 0)
1168→    {
1169→      fclose(in);
1170→      return 0;
1171→    }
1172→
1173→  if (fseek(in, 0, SEEK_END) != 0 || (size = ftell(in)) <= 0 ||
1174→      size > 2 * 1024 * 1024 - 44 || fseek(in, 0, SEEK_SET) != 0)
1175→    {
1176→      fclose(in);
1177→      return -1;
1178→    }
1179→
1180→  data_size = (uint32_t)size;
1181→  memset(header, 0, sizeof(header));
1182→  memcpy(header, "RIFF", 4);
1183→  put_le32(header + 4, data_size + 36);
1184→  memcpy(header + 8, "WAVEfmt ", 8);
1185→  put_le32(header + 16, 16);
1186→  put_le16(header + 20, 1);
1187→  put_le16(header + 22, REC_CH);
1188→  put_le32(header + 24, REC_RATE);
1189→  put_le32(header + 28, byte_rate);
1190→  put_le16(header + 32, REC_CH * REC_BITS / 8);
1191→  put_le16(header + 34, REC_BITS);
1192→  memcpy(header + 36, "data", 4);
1193→  put_le32(header + 40, data_size);
1194→
1195→  out = fopen(WAV_ASR, "wb");
1196→  if (!out)
1197→    {
1198→      fclose(in);
1199→      return -1;
1200→    }
1201→
1202→  if (fwrite(header, 1, sizeof(header), out) == sizeof(header))
1203→    {
1204→      rc = 0;
1205→      while ((n = fread(buf, 1, sizeof(buf), in)) > 0)
1206→        {
1207→          if (fwrite(buf, 1, n, out) != n)
1208→            {
1209→              rc = -1;
1210→              break;
1211→            }
1212→        }
1213→      if (ferror(in))
1214→        {
1215→          rc = -1;
1216→        }
1217→    }
1218→
1219→  if (fclose(out) != 0)
1220→    {
1221→      rc = -1;
1222→    }
1223→  fclose(in);
1224→  if (rc == 0)
1225→    {
1226→      *wav_out = WAV_ASR;
1227→    }
1228→  else
1229→    {
1230→      unlink(WAV_ASR);
1231→    }
1232→  return rc;
1233→}
