1235→/* Convert the latest microphone capture from raw PCM to a WAV file and persist
1236→ * it on /data.  Use a temporary sibling and rename so an interrupted save does
1237→ * not leave a partial file masquerading as a completed recording. */
1238→int dm_voice_record_save(const char *wav_path)
1239→{
1240→  const char *prepared_path;
1241→  char temp_path[160];
1242→  FILE *in = NULL;
1243→  FILE *out = NULL;
1244→  unsigned char buf[1024];
1245→  size_t n;
1246→  int rc = -1;
1247→  int close_in_rc = 0;
1248→  int close_out_rc = 0;
1249→  int path_len;
1250→
1251→  if (!wav_path || !wav_path[0])
1252→    {
1253→      return -EINVAL;
1254→    }
1255→  path_len = snprintf(temp_path, sizeof(temp_path), "%s.tmp", wav_path);
1256→  if (path_len < 0 || path_len >= (int)sizeof(temp_path))
1257→    {
1258→      return -ENAMETOOLONG;
1259→    }
1260→
1261→  pthread_mutex_lock(&s_voice_api_lock);
1262→  if (voice_prepare_wav(WAV_REC, &prepared_path) != 0)
1263→    {
1264→      syslog(LOG_ERR, "[dm-voice] recorder save: WAV preparation failed\n");
1265→      goto out;
1266→    }
1267→
1268→  in = fopen(prepared_path, "rb");
1269→  out = fopen(temp_path, "wb");
1270→  if (!in || !out)
1271→    {
1272→      syslog(LOG_ERR, "[dm-voice] recorder save: cannot open source/destination\n");
1273→      goto out;
1274→    }
1275→
1276→  rc = 0;
1277→  while ((n = fread(buf, 1, sizeof(buf), in)) > 0)
1278→    {
1279→      if (fwrite(buf, 1, n, out) != n)
1280→        {
1281→          rc = -EIO;
1282→          break;
1283→        }
1284→    }
1285→  if (ferror(in))
1286→    {
1287→      rc = -EIO;
1288→    }
1289→
1290→  close_in_rc = fclose(in);
1291→  in = NULL;
1292→  close_out_rc = fclose(out);
1293→  out = NULL;
1294→  if (close_in_rc != 0 || close_out_rc != 0)
1295→    {
1296→      rc = -EIO;
1297→    }
1298→  if (rc == 0 && rename(temp_path, wav_path) != 0)
1299→    {
1300→      rc = -errno;
1301→    }
1302→
1303→out:
1304→  if (in)
1305→    {
1306→      fclose(in);
1307→    }
1308→  if (out)
1309→    {
1310→      fclose(out);
1311→    }
1312→  if (rc != 0)
1313→    {
1314→      unlink(temp_path);
1315→    }
1316→  else
1317→    {
1318→      syslog(LOG_INFO, "[dm-voice] saved recording to persistent storage\n");
1319→    }
1320→  pthread_mutex_unlock(&s_voice_api_lock);
1321→  return rc;
