229→static int dm_voice_rec_stop_generation(uint32_t generation,
230→                                        int check_generation)
231→{
232→  FILE *f;
233→  long size;
234→
235→  pthread_mutex_lock(&s_rec_lock);
236→  if (check_generation &&
237→      (!s_rec_active || generation != s_rec_generation))
238→    {
239→      pthread_mutex_unlock(&s_rec_lock);
240→      return 0;
241→    }
242→
243→  if (s_rec_active)
244→    {
245→      /* Stop/join can wait for the NuttX audio worker.  Keep this off the
246→       * LVGL event thread and hold the audio gate until the recorder releases
247→       * its DMA/session resources. */
248→      pthread_mutex_lock(&s_audio_lock);
249→      if (s_rec)
250→        {
251→          (void)nxrecorder_stop(s_rec);
252→          nxrecorder_release(s_rec);
253→          s_rec = NULL;
254→        }
255→      s_rec_active = 0;
256→      s_st = DM_VOICE_IDLE;
257→      pthread_mutex_unlock(&s_audio_lock);
258→    }
259→
260→  /* Keep the recorder lock until the completed file has been checked. This
261→   * prevents a new recording from truncating WAV_REC during validation. */
262→  f = fopen(WAV_REC, "rb");
263→  if (!f)
264→    {
265→      pthread_mutex_unlock(&s_rec_lock);
266→      syslog(LOG_ERR, "[dm-voice] recording file missing\n");
267→      s_st = DM_VOICE_ERR;
268→      return -1;
269→    }
270→
271→  if (fseek(f, 0, SEEK_END) != 0)
272→    {
273→      fclose(f);
274→      pthread_mutex_unlock(&s_rec_lock);
275→      s_st = DM_VOICE_ERR;
276→      return -1;
277→    }
278→
279→  size = ftell(f);
280→  fclose(f);
281→  if (size <= 44)
282→    {
283→      pthread_mutex_unlock(&s_rec_lock);
284→      syslog(LOG_ERR, "[dm-voice] recording has no audio payload (bytes=%ld)\n",
285→             size);
286→      s_st = DM_VOICE_ERR;
287→      return -1;
288→    }
289→
290→  /* nxrecorder writes raw PCM for AUDIO_FMT_PCM; report only sizes/format
291→   * metadata so we can distinguish a capture failure from an API failure. */
292→  syslog(LOG_INFO, "[dm-voice] captured PCM bytes=%ld rate=%d ch=%d bits=%d\n",
293→         size, REC_RATE, REC_CH, REC_BITS);
294→  pthread_mutex_unlock(&s_rec_lock);
295→  return 0;
296→}
