514→static int meeting_start_worker(meeting_job_t job, int slot)
515→{
516→  pthread_t thread;
517→  pthread_attr_t attr;
518→  int rc;
519→
520→  if (s_busy) return -EBUSY;
521→  s_busy = 1;
522→  s_job = job;
523→  pthread_mutex_lock(&s_job_lock);
524→  s_job_done = 0;
525→  s_job_result = 0;
526→  s_job_store_result = 0;
527→  s_job_completed_slot = slot;
528→  pthread_mutex_unlock(&s_job_lock);
529→  meeting_refresh();
530→
531→  pthread_attr_init(&attr);
532→  pthread_attr_setstacksize(&attr, DM_VOICE_NET_WORKER_STACK);
533→  rc = pthread_create(&thread, &attr, meeting_worker, (void *)(intptr_t)slot);
534→  pthread_attr_destroy(&attr);
535→  if (rc != 0)
536→    {
537→      s_busy = 0;
538→      s_job = MEETING_JOB_NONE;
539→      meeting_refresh();
540→      return -rc;
541→    }
542→  pthread_detach(thread);
543→  return 0;
544→}
