693→static void meeting_worker_finish(int rc, int store_rc, int slot)
694→{
695→  pthread_mutex_lock(&s_job_lock);
696→  s_job_result = rc;
697→  s_job_store_result = store_rc;
698→  s_job_completed_slot = slot;
699→  s_job_done = 1;
700→  pthread_mutex_unlock(&s_job_lock);
701→}
