703→static void *meeting_worker(void *arg)
704→{
705→  meeting_job_t job = s_job;
706→  int slot = (int)(intptr_t)arg;
707→  char path[80];
708→  int rc = -EINVAL;
709→  int store_rc = 0;
710→
711→  switch (job)
712→    {
713→      case MEETING_JOB_START:
714→        rc = dm_voice_rec_start(MEETING_MAX_SEC);
715→        break;
716→
717→      case MEETING_JOB_STOP_SAVE:
718→        rc = dm_voice_rec_stop();
719→        if (rc == 0 && meeting_store_path(slot, path, sizeof(path)) == 0)
720→          {
721→            rc = dm_voice_record_save(path);
722→            if (rc == 0)
723→              {
724→                char meta[96];
725→                snprintf(meta, sizeof(meta), "/data/flowdesk_meeting_%02d.meta",
726→                         slot + 1);
727→                unlink(meta);
728→                store_rc = meeting_state_save((slot + 1) % MEETING_SLOTS);
729→              }
730→          }
731→        break;
732→
733→      case MEETING_JOB_ANALYZE:
734→        rc = meeting_store_path(slot, path, sizeof(path));
735→        if (rc == 0)
736→          {
737→            rc = dm_voice_meeting_analyze(path, s_result_transcript,
738→                                          sizeof(s_result_transcript),
739→                                          s_result_summary,
740→                                          sizeof(s_result_summary));
741→            if (rc >= 0)
742→              {
743→                int api_rc = rc;
744→                store_rc = meeting_info_save(slot, s_result_transcript,
745→                                             s_result_summary);
746→                rc = api_rc;
747→              }
748→          }
749→        break;
750→
751→      case MEETING_JOB_PLAY:
752→        rc = meeting_store_path(slot, path, sizeof(path));
753→        if (rc == 0) rc = dm_voice_play_file_sync(path);
754→        break;
755→
756→      default:
757→        break;
758→    }
759→
760→  meeting_worker_finish(rc, store_rc, slot);
761→  return NULL;
762→}
