539→static void *reminder_speech_worker(void *arg)
540→{
541→  reminder_speech_t *speech = arg;
542→  char line[REMINDER_TEXT_MAX + 48];
543→  int rc = -1;
544→  int beep_rc;
545→  int attempt;
546→  int speech_attempted = 0;
547→
548→  if (!speech)
549→    {
550→      return NULL;
551→    }
552→  if (speech->is_alarm)
553→    {
554→      snprintf(line, sizeof(line), "闹钟响了：%s。", speech->text);
555→      dm_vol_alarm_begin();
556→    }
557→  else
558→    {
559→      snprintf(line, sizeof(line), "待办提醒：%s。", speech->text);
560→    }
561→
562→  /* TODOs notify once with optional speech. Alarms repeat offline tones
563→   * until dismissed; never block their ringing on a cloud TTS request. */
564→  do
565→    {
566→      if (speech->is_alarm && !reminder_alarm_is_ringing())
567→        {
568→          break;
569→        }
570→
571→      beep_rc = -EBUSY;
572→      for (attempt = 0; attempt < 12 &&
573→           (!speech->is_alarm || reminder_alarm_is_ringing()); attempt++)
574→        {
575→          beep_rc = dm_voice_beep();
576→          if (beep_rc != -EBUSY)
577→            {
578→              break;
579→            }
580→          usleep(250000);
581→        }
582→      if (beep_rc != 0 &&
583→          (!speech->is_alarm || reminder_alarm_is_ringing()))
584→        {
585→          syslog(LOG_WARNING, "[dm-remind] alert tone playback failed rc=%d\n",
586→                 beep_rc);
587→        }
588→
589→      if (!speech->is_alarm && !speech_attempted)
590→        {
591→          speech_attempted = 1;
592→          if (dm_wifi_connected())
593→            {
594→              rc = dm_voice_tts_play(line);
595→            }
596→          if (rc != 0)
597→            {
598→              syslog(LOG_WARNING, "[dm-remind] spoken reminder unavailable\n");
599→            }
600→        }
601→
602→      if (!speech->is_alarm || !reminder_alarm_is_ringing())
603→        {
604→          break;
605→        }
606→
607→      /* Keep only a 100 ms gap between tones and recheck dismissal. */
608→      for (attempt = 0; attempt < 1 && reminder_alarm_is_ringing(); attempt++)
609→        {
610→          usleep(100000);
611→        }
612→    }
613→  while (speech->is_alarm && reminder_alarm_is_ringing());
614→
615→  if (speech->is_alarm)
616→    {
617→      pthread_mutex_lock(&s_voice_lock);
618→      s_alarm_ring_active = 0;
619→      pthread_mutex_unlock(&s_voice_lock);
620→      dm_vol_alarm_end();
621→    }
622→  free(speech);
623→  pthread_mutex_lock(&s_voice_lock);
624→  s_voice_done = 1;
625→  pthread_mutex_unlock(&s_voice_lock);
626→  return NULL;
627→}
