580→  if (n > DM_MOOD_REC_MAX)
581→    {
582→      n = DM_MOOD_REC_MAX;
583→    }
584→
585→  for (i = 0; i < n; i++)
586→    {
587→      list[i] = mood_record_score(&recs[i]);
588→      /* recs[0] is newest → weight = n - i */
589→      {
590→        float w = (float)(n - i);
591→        acc += list[i] * w;
592→        wsum += w;
593→      }
594→    }
595→
596→  final = (wsum > 0.0f) ? (acc / wsum) : 50.0f;
597→
598→  /* stability: last up to 5 records in list order (index 0..min(n,5)-1 = newest first in FlowDesk)
599→   * App used slice(-5) oldest-of-recent on their list order.
600→   * FlowDesk stores newest at [0]; use up to 5 newest = list[0..m-1]. */
601→  if (n >= 3)
602→    {
603→      int m = n < 5 ? n : 5;
604→      float avg = 0.0f;
605→      float var = 0.0f;
606→      float sd;
607→      for (i = 0; i < m; i++)
608→        {
609→          avg += list[i];
610→        }
611→      avg /= (float)m;
612→      for (i = 0; i < m; i++)
613→        {
614→          float d = list[i] - avg;
615→          var += d * d;
616→        }
617→      var /= (float)m;
618→      sd = (float)sqrt((double)var);
619→      if (sd < 10.0f)
620→        {
621→          bonus = 5.0f;
622→        }
623→      else if (sd < 20.0f)
624→        {
625→          bonus = 3.0f;
626→        }
627→      else if (sd < 30.0f)
628→        {
629→          bonus = 1.0f;
630→        }
631→    }
632→
633→  final = final + bonus;
634→  if (final < 0.0f)
635→    {
636→      final = 0.0f;
637→    }
638→  if (final > 100.0f)
639→    {
640→      final = 100.0f;
641→    }
642→  return (int)(final + 0.5f);
643→}
