645→/* behavior multi-factor 0..100 — env/words/focus/med/water/game */
646→static int behavior_score_from_board(int *cov100, int *nf)
647→{
648→  float t = 0.0f;
649→  float h = 0.0f;
650→  int has_env;
651→  float es;
652→  int words_n;
653→  int water;
654→  int sched = 0;
655→  int taken = 0;
656→  float items_s[6];
657→  float items_w[6];
658→  int items_ok[6];
659→  int n = 6;
660→  int i;
661→  float acc = 0.0f;
662→  float wsum = 0.0f;
663→  int cnt = 0;
664→
665→  has_env = (dm_sensor_last_th(&t, &h) == 0) ? 1 : 0;
666→  es = mf_env_score(t, h, has_env, has_env);
667→  words_n = dm_word_today_n();
668→  water = dm_water_today_cups();
669→  (void)dm_med_today_stats(&sched, &taken);
670→
671→  items_w[0] = 0.15f;
672→  items_s[0] = es;
673→  items_ok[0] = (es >= 0.0f) ? 1 : 0;
674→
675→  items_w[1] = 0.15f;
676→  items_s[1] = clampf((float)words_n / MF_WORDS_TARGET, 0.0f, 1.0f);
677→  items_ok[1] = 1;
678→
679→  items_w[2] = 0.25f;
680→  items_s[2] = (g_dm.focus_done_min <= 0)
681→                   ? 0.0f
682→                   : clampf((float)g_dm.focus_done_min / MF_FOCUS_TARGET,
683→                            0.0f, 1.0f);
684→  items_ok[2] = 1;
685→
686→  items_w[3] = 0.20f;
687→  if (sched > 0)
688→    {
689→      items_s[3] = clampf((float)taken / (float)sched, 0.0f, 1.0f);
690→      items_ok[3] = 1;
691→    }
692→  else
693→    {
694→      items_s[3] = 0.0f;
695→      items_ok[3] = 0;
696→    }
697→
698→  items_w[4] = 0.15f;
699→  items_s[4] = clampf((float)water / MF_WATER_TARGET, 0.0f, 1.0f);
700→  items_ok[4] = 1;
701→
702→  items_w[5] = 0.10f;
703→  items_s[5] = mf_game_score(s_game_ms);
704→  items_ok[5] = 1;
705→
706→  for (i = 0; i < n; i++)
707→    {
708→      if (!items_ok[i])
709→        {
710→          continue;
711→        }
712→      acc += items_w[i] * items_s[i];
713→      wsum += items_w[i];
714→      cnt++;
715→    }
716→  if (nf)
717→    {
718→      *nf = cnt;
719→    }
720→  if (cov100)
721→    {
722→      *cov100 = (int)(wsum * 100.0f + 0.5f);
723→    }
724→  if (wsum <= 0.0001f || cnt <= 0)
725→    {
726→      return -1;
727→    }
728→  return (int)((acc / wsum) * 100.0f + 0.5f);
729→}
