365→static void med_paint(void)
366→{
367→  int i;
368→  time_t now = time(NULL);
369→  struct tm tmv;
370→  int hour;
371→
372→  localtime_r(&now, &tmv);
373→  hour = tmv.tm_hour;
374→
375→  for (i = 0; i < MED_MAX; i++)
376→    {
377→      if (!s_med_rows[i])
378→        {
379→          continue;
380→        }
381→      if (i < s_med_n)
382→        {
383→          med_item_t *m = &s_med[i];
384→          char st[48];
385→          int done = 0;
386→          int due = 0;
387→          int k;
388→
389→          for (k = 0; k < m->times; k++)
390→            {
391→              if (m->taken & (1u << k))
392→                {
393→                  done++;
394→                }
395→              else if (hour >= m->hours[k])
396→                {
397→                  due = 1;
398→                }
399→            }
400→
401→          lv_obj_clear_flag(s_med_rows[i], LV_OBJ_FLAG_HIDDEN);
402→          lv_obj_set_style_bg_color(
403→              s_med_rows[i],
404→              lv_color_hex(i == s_med_sel ? 0x0d3a4a : C_BTN), LV_PART_MAIN);
405→          if (s_med_names[i])
406→            {
407→              lv_label_set_text(s_med_names[i], m->name);
408→            }
409→          if (s_med_stat[i])
410→            {
411→              if (done >= m->times)
412→                {
413→                  snprintf(st, sizeof(st), "已服 %d/%d", done, m->times);
414→                  lv_label_set_text(s_med_stat[i], st);
415→                  lv_obj_set_style_text_color(s_med_stat[i],
416→                                              lv_color_hex(C_OK),
417→                                              LV_PART_MAIN);
418→                }
419→              else if (due)
420→                {
421→                  snprintf(st, sizeof(st), "待服 %d/%d", done, m->times);
422→                  lv_label_set_text(s_med_stat[i], st);
423→                  lv_obj_set_style_text_color(s_med_stat[i],
424→                                              lv_color_hex(C_STAR),
425→                                              LV_PART_MAIN);
426→                }
427→              else
428→                {
429→                  size_t n;
430→                  snprintf(st, sizeof(st), "%d/%d ", done, m->times);
