107→static void store_save(void)
108→{
109→  dm_mood_file_t f;
110→  int fd;
111→
112→  memset(&f, 0, sizeof(f));
113→  f.magic = DM_MOOD_MAGIC;
114→  f.count = (uint32_t)s_rec_n;
115→  f.focus_done_min = g_dm.focus_done_min;
116→  f.yday = health_today_key();
117→  f.game_ms = s_game_ms;
118→  if (s_rec_n > 0)
119→    {
120→      memcpy(f.recs, s_recs, sizeof(dm_mood_rec_t) * (size_t)s_rec_n);
121→    }
122→
123→  fd = open(DM_MOOD_PATH, O_WRONLY | O_CREAT | O_TRUNC, 0666);
124→  if (fd < 0)
125→    {
126→      return;
127→    }
128→  (void)write(fd, &f, sizeof(f));
