132→static void health_rollover_if_new_day(void)
133→{
134→  int key = health_today_key();
135→  if (s_health_day_key < 0)
136→    {
137→      s_health_day_key = key;
138→      return;
139→    }
140→  if (s_health_day_key == key)
141→    {
142→      return;
143→    }
144→  /* new calendar day: clear today-scoped stats */
145→  s_rec_n = 0;
146→  g_dm.focus_done_min = 0;
147→  s_game_ms = 0;
148→  s_health_day_key = key;
149→  store_save();
150→}
