152→static void store_load(void)
153→{
154→  dm_mood_file_t f;
155→  int fd;
156→  ssize_t n;
157→  int key = health_today_key();
158→
159→  fd = open(DM_MOOD_PATH, O_RDONLY);
160→  if (fd < 0)
161→    {
162→      s_health_day_key = key;
163→      return;
164→    }
165→  n = read(fd, &f, sizeof(f));
166→  close(fd);
167→
168→  if (n != (ssize_t)sizeof(f) || f.magic != DM_MOOD_MAGIC)
169→    {
170→      /* old/invalid file: start clean today */
171→      s_rec_n = 0;
172→      g_dm.focus_done_min = 0;
173→      s_health_day_key = key;
174→      return;
175→    }
176→
177→  if (f.yday != key)
178→    {
179→      /* data from previous day — do not leak into today's score */
180→      s_rec_n = 0;
181→      g_dm.focus_done_min = 0;
182→      s_health_day_key = key;
183→      store_save();
184→      return;
185→    }
186→
187→  if (f.count > DM_MOOD_REC_MAX)
188→    {
189→      f.count = DM_MOOD_REC_MAX;
190→    }
191→  s_rec_n = (int)f.count;
192→  if (s_rec_n > 0)
193→    {
194→      memcpy(s_recs, f.recs, sizeof(dm_mood_rec_t) * (size_t)s_rec_n);
195→    }
196→  g_dm.focus_done_min = f.focus_done_min;
197→  s_game_ms = f.game_ms;
198→  s_health_day_key = key;
199→}
