203→static int mood_mask_score(uint16_t mask)
204→{
205→  int sum = 0;
206→  int n = 0;
207→  int i;
208→
209→  if (mask == 0)
210→    {
211→      return -1;
212→    }
213→  for (i = 0; i < (int)(sizeof(s_moods) / sizeof(s_moods[0])); i++)
214→    {
215→      if (mask & s_moods[i].bit)
216→        {
217→          sum += s_moods[i].score;
218→          n++;
219→        }
220→    }
221→  return n ? (sum / n) : -1;
222→}
