123→static void med_save(void)
124→{
125→  FILE *f = fopen(MED_PATH, "w");
126→  int i;
127→  if (!f)
128→    {
129→      return;
130→    }
131→  for (i = 0; i < s_med_n; i++)
132→    {
133→      fprintf(f, "%s|%d|%d,%d,%d|%d|%d\n", s_med[i].name, s_med[i].times,
134→              s_med[i].hours[0], s_med[i].hours[1], s_med[i].hours[2],
135→              s_med[i].taken, s_med[i].day);
136→    }
137→  fclose(f);
