140→static void med_load(void)
141→{
142→  FILE *f = fopen(MED_PATH, "r");
143→  char line[96];
144→  int today = med_today();
145→
146→  s_med_n = 0;
147→  s_med_sel = 0;
148→  if (!f)
149→    {
150→      return;
151→    }
152→  while (s_med_n < MED_MAX && fgets(line, sizeof(line), f))
153→    {
154→      med_item_t *m = &s_med[s_med_n];
155→      int t;
156→      int h0;
157→      int h1;
158→      int h2;
159→      int taken;
160→      int day;
161→      char name[MED_NAME_MAX];
162→
163→      if (sscanf(line, "%31[^|]|%d|%d,%d,%d|%d|%d", name, &t, &h0, &h1,
164→                 &h2, &taken, &day) != 7)
165→        {
166→          continue;
167→        }
168→      snprintf(m->name, MED_NAME_MAX, "%s", name);
169→      m->times = (uint8_t)(t > 3 ? 3 : (t < 1 ? 1 : t));
170→      m->hours[0] = (uint8_t)h0;
171→      m->hours[1] = (uint8_t)h1;
172→      m->hours[2] = (uint8_t)h2;
173→      m->taken = (uint8_t)taken;
174→      m->day = (uint16_t)day;
175→      if (day != today)
176→        {
177→          m->taken = 0;
178→          m->day = (uint16_t)today;
179→        }
180→      s_med_n++;
181→    }
182→  fclose(f);
183→}
