 655→  for (i = 0; i < MED_PY_DICT_N && n < maxn; i++)
 656→    {
 657→      if (strcmp(s_med_py[i].py, pin) == 0 ||
 658→          strncmp(s_med_py[i].py, pin, strlen(pin)) == 0)
 659→        {
