 727→static void med_kb_key_cb(lv_event_t *e)
 728→{
 729→  const char *k = (const char *)lv_event_get_user_data(e);
 730→  if (!k || !k[0])
 731→    {
 732→      return;
 733→    }
 734→
 735→  if (strcmp(k, "DEL") == 0)
 736→    {
 737→      if (s_kb_mode == 0 && s_kb_pin_len > 0)
 738→        {
 739→          s_kb_pin_len--;
 740→          s_kb_pin[s_kb_pin_len] = 0;
 741→        }
 742→      else if (s_kb_buf_len > 0)
 743→        {
 744→          /* UTF-8: strip one character (1-3 bytes) */
 745→          s_kb_buf_len--;
 746→          while (s_kb_buf_len > 0 &&
 747→                 (s_kb_buf[s_kb_buf_len] & 0xc0) == 0x80)
 748→            {
 749→              s_kb_buf_len--;
 750→            }
 751→          s_kb_buf[s_kb_buf_len] = 0;
 752→        }
 753→    }
 754→  else if (strcmp(k, "SP") == 0)
 755→    {
 756→      if (s_kb_mode == 0 && s_kb_pin_len > 0)
 757→        {
 758→          const char *cands[MED_KB_CAND_MAX];
 759→          int n = med_py_cands(s_kb_pin, cands, MED_KB_CAND_MAX);
 760→          if (n > 0)
 761→            {
 762→              size_t cur = strlen(s_kb_buf);
 763→              size_t add = strlen(cands[0]);
 764→              if (cur + add < sizeof(s_kb_buf))
 765→                {
 766→                  memcpy(s_kb_buf + cur, cands[0], add + 1);
 767→                  s_kb_buf_len = (int)(cur + add);
 768→                }
 769→              s_kb_pin_len = 0;
 770→              s_kb_pin[0] = 0;
 771→            }
 772→        }
 773→      else if (s_kb_buf_len < MED_NAME_MAX - 1)
 774→        {
 775→          s_kb_buf[s_kb_buf_len++] = ' ';
 776→          s_kb_buf[s_kb_buf_len] = 0;
 777→        }
 778→    }
 779→  else if (strcmp(k, "OK") == 0)
 780→    {
 781→      med_kb_confirm_cb(e);
 782→      return;
 783→    }
 784→  else
 785→    {
 786→      size_t n = strlen(k);
 787→      if (s_kb_mode == 0)
 788→        {
 789→          if (s_kb_pin_len + (int)n < MED_KB_PIN_MAX)
 790→            {
 791→              memcpy(s_kb_pin + s_kb_pin_len, k, n + 1);
 792→              s_kb_pin_len += (int)n;
 793→            }
 794→        }
 795→      else if (s_kb_buf_len + (int)n < MED_NAME_MAX)
 796→        {
 797→          memcpy(s_kb_buf + s_kb_buf_len, k, n + 1);
 798→          s_kb_buf_len += (int)n;
 799→        }
 800→    }
 801→
 802→  med_slot_paint();
 803→  med_kb_paint_cands();
 804→}
