 932→int dm_med_today_stats(int *sched_out, int *taken_out)
 933→{
 934→  int i;
 935→  int sched = 0;
 936→  int taken = 0;
 937→  int today = med_today();
 938→
 939→  for (i = 0; i < s_med_n; i++)
 940→    {
 941→      int k;
 942→      int times = s_med[i].times;
 943→      if (times < 1)
 944→        {
 945→          continue;
 946→        }
 947→      if (times > 3)
 948→        {
 949→          times = 3;
 950→        }
 951→      /* only today's schedule counts as valid factor data */
 952→      if ((int)s_med[i].day != today)
 953→        {
 954→          continue;
 955→        }
 956→      sched += times;
 957→      for (k = 0; k < times; k++)
 958→        {
 959→          if (s_med[i].taken & (1u << k))
 960→            {
 961→              taken++;
 962→            }
 963→        }
 964→    }
 965→  if (sched_out)
 966→    {
 967→      *sched_out = sched;
 968→    }
 969→  if (taken_out)
 970→    {
 971→      *taken_out = taken;
 972→    }
 973→  return sched;
 974→}
