1449→  if (!cancel_reminder && alarm_requested)
1450→    {
1451→      relative_marker(text, &relative_bytes);
1452→      if (relative_bytes &&
1453→          parse_duration_seconds(text, &seconds, ASSISTANT_TODO_MAX_SECONDS))
1454→        {
1455→          intent->type = INTENT_ALARM_AFTER;
1456→          intent->seconds = seconds;
1457→          clean_relative_name(text, intent->text, sizeof(intent->text));
1458→          if (strcmp(intent->text, "待办事项") == 0)
1459→            {
1460→              snprintf(intent->text, sizeof(intent->text), "%s", "闹钟");
1461→            }
1462→          return 1;
1463→        }
1464→      alarm_rc = parse_alarm_time(text, intent);
1465→      if (alarm_rc > 0)
1466→        {
1467→          intent->type = INTENT_ALARM;
1468→          return 1;
1469→        }
1470→      if (alarm_rc < 0)
1471→        {
1472→          intent->type = INTENT_TIME_ERROR;
1473→          return 1;
1474→        }
1475→    }
1476→
1477→  if (!cancel_reminder && !alarm_requested && !cancel_focus &&
1478→      !(strstr(text, "专注") || strstr(text, "计时") || strstr(text, "番茄钟")) &&
1479→      contains_any(text, todo_triggers,
1480→                   sizeof(todo_triggers) / sizeof(todo_triggers[0])))
1481→    {
1482→      const char *clock_mark = first_of(text, "点", "时");
1483→      relative_marker(text, &relative_bytes);
1484→      if (relative_bytes &&
1485→          parse_duration_seconds(text, &seconds, ASSISTANT_TODO_MAX_SECONDS))
1486→        {
1487→          intent->type = INTENT_TODO_AFTER;
1488→          intent->seconds = seconds;
1489→          clean_relative_name(text, intent->text, sizeof(intent->text));
1490→          return 1;
1491→        }
1492→
1493→      /* A clock-only request such as "11点提醒我开会" is a timed TODO,
1494→       * not an alarm. Resolve it to the next occurrence of that local time. */
1495→      if (!relative_bytes && has_dt == 0 && clock_mark)
1496→        {
1497→          alarm_rc = parse_alarm_time(text, intent);
1498→          if (alarm_rc > 0)
1499→            {
1500→              intent->type = INTENT_TODO_AT;
1501→              clean_todo_at_name(text, intent->text, sizeof(intent->text));
1502→              return 1;
1503→            }
1504→          if (alarm_rc <= 0)
1505→            {
1506→              intent->type = INTENT_TIME_ERROR;
1507→              return 1;
1508→            }
1509→        }
1510→    }
1511→
1512→  if (has_dt < 0 && !cancel_reminder &&
1513→      contains_any(text, reminder_triggers,
1514→                   sizeof(reminder_triggers) / sizeof(reminder_triggers[0])))
1515→    {
1516→      intent->type = INTENT_TIME_ERROR;
1517→      return 1;
1518→    }
1519→  if (has_dt == 1 && !cancel_reminder &&
1520→      contains_any(text, reminder_triggers,
1521→                   sizeof(reminder_triggers) / sizeof(reminder_triggers[0])))
1522→    {
1523→      intent->type = INTENT_COUNTDOWN;
1524→      clean_reminder_name(text, date_start, date_end, time_start, time_end,
1525→                          intent->text, sizeof(intent->text));
1526→      return 1;
1527→    }
1528→
1529→  if (is_med_take_request(text))
1530→    {
1531→      intent->type = INTENT_MED_TAKE;
1532→      snprintf(intent->text, sizeof(intent->text), "%s", text);
1533→      return 1;
1534→    }
1535→  if (is_mbti_open_request(text))
1536→    {
1537→      intent->type = INTENT_MBTI_OPEN;
1538→      return 1;
1539→    }
1540→
1541→  game_page = game_page_from_text(text);
1542→  if (game_page != PAGE_COUNT &&
1543→      (is_game_request(text) || strstr(text, "玩") != NULL))
1544→    {
1545→      intent->type = INTENT_GAME;
1546→      intent->game_page = game_page;
1547→      return 1;
1548→    }
1549→  if (is_game_request(text))
1550→    {
1551→      intent->type = INTENT_GAME_ASK;
1552→      return 1;
1553→    }
1554→  if (is_wake_phrase(text))
1555→    {
1556→      intent->type = INTENT_WAKE;
1557→      return 1;
1558→    }
1559→
1560→  if (contains_any(text, mood_record_triggers,
1561→                   sizeof(mood_record_triggers) /
1562→                     sizeof(mood_record_triggers[0])))
1563→    {
1564→      intent->type = INTENT_MOOD_RECORD;
1565→      intent->seconds = 1;
1566→      snprintf(intent->text, sizeof(intent->text), "%s", text);
1567→      return 1;
1568→    }
1569→
1570→  if (contains_any(text, note_triggers,
1571→                   sizeof(note_triggers) / sizeof(note_triggers[0])))
1572→    {
1573→      const char *trigger = NULL;
1574→      size_t trigger_len = 0;
1575→      size_t i;
1576→      for (i = 0; i < sizeof(note_triggers) / sizeof(note_triggers[0]); i++)
1577→        {
1578→          const char *found = strstr(text, note_triggers[i]);
1579→          if (found && (!trigger || found < trigger))
1580→            {
1581→              trigger = found;
1582→              trigger_len = strlen(note_triggers[i]);
1583→            }
1584→        }
1585→      if (trigger)
1586→        {
1587→          const char *content = trigger + trigger_len;
1588→          while (*content == ' ' || *content == '\t' || *content == ':' ||
1589→                 *content == ',')
1590→            {
1591→              content++;
1592→            }
1593→          while (strncmp(content, "，", 3) == 0 ||
1594→                 strncmp(content, "：", 3) == 0 ||
1595→                 strncmp(content, "、", 3) == 0)
1596→            {
1597→              content += 3;
1598→            }
1599→          while (strncmp(content, "我", 3) == 0 ||
1600→                 strncmp(content, "一下", 6) == 0 ||
1601→                 strncmp(content, "记得", 6) == 0)
1602→            {
1603→              content += strncmp(content, "我", 3) == 0 ? 3 : 6;
1604→            }
1605→          if (!*content)
1606→            {
1607→              return 0;
1608→            }
1609→          intent->type = INTENT_NOTE;
1610→          snprintf(intent->text, sizeof(intent->text), "%s", content);
1611→          return 1;
1612→        }
1613→    }
1614→
1615→  if (!cancel_focus &&
1616→      (strstr(text, "专注") || strstr(text, "计时") || strstr(text, "番茄钟")) &&
1617→      parse_duration_seconds(text, &seconds, 120 * 60))
1618→    {
1619→      intent->type = INTENT_FOCUS;
1620→      intent->seconds = seconds;
1621→      return 1;
1622→    }
1623→
1624→  if (contains_any(text, mood_state_words,
1625→                   sizeof(mood_state_words) / sizeof(mood_state_words[0])) &&
1626→      contains_any(text, mood_self_report,
1627→                   sizeof(mood_self_report) / sizeof(mood_self_report[0])))
1628→    {
1629→      intent->type = INTENT_MOOD_RECORD;
1630→      intent->seconds = 0;
1631→      snprintf(intent->text, sizeof(intent->text), "%s", text);
1632→      return 1;
1633→    }
1634→
1635→  if (contains_any(text, mood_words, sizeof(mood_words) / sizeof(mood_words[0])))
1636→    {
1637→      intent->type = INTENT_MOOD;
1638→      snprintf(intent->text, sizeof(intent->text), "%s", text);
1639→      return 1;
1640→    }
1641→
1642→  return 0;
1643→}
